DistributionOperation = Literal["fresh", "update", "init-force", "uninstall"]
JournaledDistributionIntent = Literal["fresh", "update", "init-force", "deprovision", "purge"]
_SUPPORTED_JOURNALED_INTENTS = frozenset({"fresh", "update", "init-force", "deprovision", "purge"})
DistributionActionName = Literal[
    "create",
    "adopt",
    "upgrade",
    "prune",
    "preserve",
    "block",
    "ensure-directory",
    "remove-empty-directory",
]
DistributionProvenance = Literal["missing", "current", "historical", "unknown"]

_FRESH_DISTRIBUTION_ACTIONS = frozenset({"create", "adopt", "preserve", "block", "ensure-directory"})
_DEPROVISION_DISTRIBUTION_ACTIONS = frozenset({"prune", "preserve", "block", "remove-empty-directory"})


def _intent_allows_distribution_action(
    intent: DistributionOperation | JournaledDistributionIntent,
    action: DistributionActionName,
) -> bool:
    """Return whether an action belongs to the mutation grammar for an intent."""

    if intent == "fresh":
        return action in _FRESH_DISTRIBUTION_ACTIONS
    if intent in {"deprovision", "purge", "uninstall"}:
        return action in _DEPROVISION_DISTRIBUTION_ACTIONS
    return True


def _plan_operation_for_intent(intent: JournaledDistributionIntent) -> DistributionOperation:
    """Map an internal journal intent to its read-only classifier operation."""

    if intent in {"deprovision", "purge"}:
        return "uninstall"
    if intent in {"fresh", "update", "init-force"}:
        return cast("DistributionOperation", intent)
    raise DistributionPlanError(f"unsupported journaled intent: {intent!r}")


def _is_destructive_intent(intent: DistributionOperation | JournaledDistributionIntent) -> bool:
    """Return whether an intent uses the uninstall journal/action contract."""

    return intent in {"deprovision", "purge", "uninstall"}


@dataclass(frozen=True)
class DistributionAction:
    """One read-only classification result for a consumer path."""

    path: str
    operation: DistributionOperation
    action: DistributionActionName
    provenance: DistributionProvenance
    reason: str
    blocked: bool = False

    @property
    def classification(self) -> DistributionActionName:
        """Design vocabulary alias for the action kind."""

        return self.action

    @property
    def blocking(self) -> bool:
        """Design vocabulary alias for a preserve-and-block result."""

        return self.blocked

    @property
    def operator_action(self) -> str:
        """Sanitized next step for a human or a later apply phase."""

        if not self.blocked:
            return "no mutation required"
        if self.reason in {"unknown-current-collision", "obsolete-identity-unknown"}:
            return "inspect ownership and resolve the collision before retrying"
        if self.reason == "hard-link-mutation-unsafe":
            return "remove the unexpected hard link before retrying"
        return "inspect the path type and resolve the collision before retrying"

    def diagnostic(self) -> dict[str, object]:
        """Return only repository-relative, non-content diagnostic fields."""

        return {
            "operation": self.operation,
            "path": self.path,
            "classification": self.classification,
            "provenance": self.provenance,
            "reason": self.reason,
            "blocking": self.blocking,
            "operator_action": self.operator_action,
        }


