_SCHEMA_VERSION = 1
_MANIFEST_FIELDS = frozenset({
    "schema_version",
    "recognized_workspace_versions",
    "historical_current_identities",
    "trusted_consumer_manifests",
    "obsolete_exact_files",
    "historical_shortcuts",
})
_SHA256_RE = re.compile(r"^[0-9a-f]{64}$")
_DRIVE_RE = re.compile(r"^[A-Za-z]:")
_GLOB_CHARS = frozenset("*?[]{}")


def _fail(message: str) -> NoReturn:
    raise DistributionManifestError(message)


def _exact_relative_path(value: Any, *, field_name: str) -> PurePosixPath:
    if not isinstance(value, str) or not value:
        _fail(f"{field_name} must be a non-empty repository-relative path")
    if "\\" in value or "\x00" in value or value.startswith("/") or _DRIVE_RE.match(value):
        _fail(f"{field_name} must be a POSIX repository-relative path")
    if value.endswith("/") or any(char in _GLOB_CHARS for char in value):
        _fail(f"{field_name} must identify one exact file")
    parts = value.split("/")
    if any(part in {"", ".", ".."} for part in parts):
        _fail(f"{field_name} must not contain empty, '.', or '..' path components")
    normalized = PurePosixPath(value)
    if normalized.as_posix() != value:
        _fail(f"{field_name} is not normalized")
    return normalized


def _sha256(value: Any, *, field_name: str) -> str:
    if not isinstance(value, str) or _SHA256_RE.fullmatch(value) is None:
        _fail(f"{field_name} must be lowercase hexadecimal SHA-256")
    return value


def _source(value: Any, *, field_name: str) -> dict[str, Any]:
    """Validate trace evidence without exposing it in runtime diagnostics."""

    if not isinstance(value, dict) or not value:
        _fail(f"{field_name} must contain historical trace evidence")
    kind = value.get("kind")
    if not isinstance(kind, str) or not kind.strip():
        _fail(f"{field_name}.kind must be non-empty")
    if "path" in value:
        _exact_relative_path(value["path"], field_name=f"{field_name}.path")
    for key in ("ref", "artifact"):
        if key in value and (not isinstance(value[key], str) or not value[key].strip()):
            _fail(f"{field_name}.{key} must be non-empty when present")
    return dict(value)


def _identity_record(value: Any, *, field_name: str, require_source: bool = True) -> dict[str, Any]:
    if not isinstance(value, dict):
        _fail(f"{field_name} must be an object")
    allowed = {"path", "kind", "sha256", "mode", "target", "source"}
    unknown = set(value) - allowed
    if unknown:
        _fail(f"{field_name} contains unsupported fields: {', '.join(sorted(unknown))}")
    path = _exact_relative_path(value.get("path"), field_name=f"{field_name}.path")
    kind = value.get("kind")
    if kind == "regular":
        digest = _sha256(value.get("sha256"), field_name=f"{field_name}.sha256")
        if "target" in value:
            _fail(f"{field_name}.target is only valid for symlinks")
        result: dict[str, Any] = {"path": path.as_posix(), "kind": kind, "sha256": digest}
        if "mode" in value:
            mode = value["mode"]
            if isinstance(mode, bool) or not isinstance(mode, int) or not 0 <= mode <= 0o777:
                _fail(f"{field_name}.mode must be an integer between 0 and 0o777")
            result["mode"] = mode
    elif kind == "symlink":
        target = value.get("target")
        if not isinstance(target, str) or not target or "\\" in target or target.startswith("/"):
            _fail(f"{field_name}.target must be a normalized relative link target")
        target_path = _exact_relative_path(target, field_name=f"{field_name}.target")
        if "sha256" in value:
            _fail(f"{field_name}.sha256 is not valid for symlinks")
        result = {"path": path.as_posix(), "kind": kind, "target": target_path.as_posix()}
    else:
        _fail(f"{field_name}.kind must be 'regular' or 'symlink'")
    if require_source:
        result["source"] = _source(value.get("source"), field_name=f"{field_name}.source")
    elif "source" in value:
        result["source"] = _source(value["source"], field_name=f"{field_name}.source")
    return result


def _section_list(raw: dict[str, Any], name: str) -> list[Any]:
    value = raw.get(name)
    if not isinstance(value, list):
        _fail(f"manifest.{name} must be an array")
    return value


def _validate_manifest(raw: Any) -> DistributionManifest:
    if not isinstance(raw, dict):
        _fail("manifest top-level value must be an object")
    if set(raw) != _MANIFEST_FIELDS:
        missing = sorted(_MANIFEST_FIELDS - set(raw))
        extra = sorted(set(raw) - _MANIFEST_FIELDS)
        detail = []
        if missing:
            detail.append(f"missing={','.join(missing)}")
        if extra:
            detail.append(f"unsupported={','.join(extra)}")
        _fail("manifest schema fields are invalid (" + "; ".join(detail) + ")")
    if raw["schema_version"] != _SCHEMA_VERSION:
        _fail(f"unsupported manifest schema_version: {raw['schema_version']!r}")

    recognized: list[dict[str, Any]] = []
    for index, item in enumerate(_section_list(raw, "recognized_workspace_versions")):
        if not isinstance(item, dict) or set(item) != {"version", "anchors"}:
            _fail(f"recognized_workspace_versions[{index}] has invalid shape")
        version = item.get("version")
        if (
            not isinstance(version, str)
            or re.fullmatch(r"(?:0|[1-9][0-9]*)\.(?:0|[1-9][0-9]*)\.(?:0|[1-9][0-9]*)", version) is None
        ):
            _fail(f"recognized_workspace_versions[{index}].version must be canonical MAJOR.MINOR.PATCH")
        anchors_raw = item.get("anchors")
        if not isinstance(anchors_raw, list) or not anchors_raw:
            _fail(f"recognized_workspace_versions[{index}].anchors must be non-empty")
        anchors = tuple(
            _identity_record(anchor, field_name=f"recognized_workspace_versions[{index}].anchors[{j}]")
            for j, anchor in enumerate(anchors_raw)
        )
        recognized.append({"version": version, "anchors": anchors})

    historical_current = [
        _identity_record(item, field_name=f"historical_current_identities[{index}]")
        for index, item in enumerate(_section_list(raw, "historical_current_identities"))
    ]

    trusted: list[dict[str, Any]] = []
    for index, item in enumerate(_section_list(raw, "trusted_consumer_manifests")):
        if not isinstance(item, dict) or set(item) != {"path", "kind", "sha256", "source", "claims"}:
            _fail(f"trusted_consumer_manifests[{index}] has invalid shape")
        manifest_identity = _identity_record(
            {key: item[key] for key in ("path", "kind", "sha256", "source")},
            field_name=f"trusted_consumer_manifests[{index}]",
        )
        claims_raw = item.get("claims")
        if not isinstance(claims_raw, list):
            _fail(f"trusted_consumer_manifests[{index}].claims must be an array")
        claims = tuple(
            _identity_record(claim, field_name=f"trusted_consumer_manifests[{index}].claims[{j}]")
            for j, claim in enumerate(claims_raw)
        )
        manifest_identity["claims"] = claims
        trusted.append(manifest_identity)

    obsolete: list[dict[str, Any]] = []
    for index, item in enumerate(_section_list(raw, "obsolete_exact_files")):
        if not isinstance(item, dict) or set(item) != {"path", "surface", "identities", "on_unknown"}:
            _fail(f"obsolete_exact_files[{index}] has invalid shape")
        path = _exact_relative_path(item.get("path"), field_name=f"obsolete_exact_files[{index}].path")
        surface = item.get("surface")
        if not isinstance(surface, str) or not surface.strip():
            _fail(f"obsolete_exact_files[{index}].surface must be non-empty")
        identities_raw = item.get("identities")
        if not isinstance(identities_raw, list):
            _fail(f"obsolete_exact_files[{index}].identities must be an array")
        identities = tuple(
            _identity_record(identity, field_name=f"obsolete_exact_files[{index}].identities[{j}]")
            for j, identity in enumerate(identities_raw)
        )
        if any(identity["path"] != path.as_posix() for identity in identities):
            _fail(f"obsolete_exact_files[{index}] identity path must match record path")
        if item.get("on_unknown") != "preserve-and-block":
            _fail(f"obsolete_exact_files[{index}].on_unknown must be preserve-and-block")
        obsolete.append({
            "path": path.as_posix(),
            "surface": surface,
            "identities": identities,
            "on_unknown": "preserve-and-block",
        })

    shortcuts: list[dict[str, Any]] = []
    for index, item in enumerate(_section_list(raw, "historical_shortcuts")):
        if not isinstance(item, dict) or set(item) != {"path", "kind", "target", "source"}:
            _fail(f"historical_shortcuts[{index}] has invalid shape")
        if item.get("kind") != "symlink":
            _fail(f"historical_shortcuts[{index}].kind must be symlink")
        path = _exact_relative_path(item.get("path"), field_name=f"historical_shortcuts[{index}].path")
        target = _exact_relative_path(item.get("target"), field_name=f"historical_shortcuts[{index}].target")
        shortcuts.append({
            "path": path.as_posix(),
            "kind": "symlink",
            "target": target.as_posix(),
            "source": _source(item.get("source"), field_name=f"historical_shortcuts[{index}].source"),
        })

    return DistributionManifest(
        schema_version=_SCHEMA_VERSION,
        recognized_workspace_versions=tuple(recognized),
        historical_current_identities=tuple(historical_current),
        trusted_consumer_manifests=tuple(trusted),
        obsolete_exact_files=tuple(obsolete),
        historical_shortcuts=tuple(shortcuts),
    )


def _path_overlaps(left: str, right: str) -> bool:
    left_parts = PurePosixPath(left).parts
    right_parts = PurePosixPath(right).parts
    return left_parts[: len(right_parts)] == right_parts or right_parts[: len(left_parts)] == left_parts


def _assert_no_manifest_overlap(
    current_paths: set[str],
    manifest: DistributionManifest,
    *,
    protected_paths: set[str] | frozenset[str] = frozenset(),
) -> None:
    for current_path in current_paths:
        if any(_path_overlaps(current_path, protected_path) for protected_path in protected_paths):
            _fail(f"physical Current path overlaps protected workspace surface: {current_path}")

    seen_historical: set[tuple[str, str, str | None, str | None]] = set()
    for item in manifest.historical_current_identities:
        signature = (item["path"], item["kind"], item.get("sha256"), item.get("target"))
        if signature in seen_historical:
            _fail(f"duplicate historical identity: {item['path']}")
        seen_historical.add(signature)

    records: list[tuple[str, str, bool, bool]] = []
    for version_index, version in enumerate(manifest.recognized_workspace_versions):
        for anchor_index, anchor in enumerate(version["anchors"]):
            records.append((
                anchor["path"],
                f"recognized_workspace_versions[{version_index}].anchors[{anchor_index}]",
                False,
                True,
            ))
    for item in manifest.historical_current_identities:
        # A historical identity is intentionally allowed to describe the same
        # target path as a newly shipped Current asset.  It is the evidence
        # used to classify an existing consumer file for upgrade/prune.
        records.append((item["path"], "historical_current_identities", True, False))
    for item in manifest.obsolete_exact_files:
        records.append((item["path"], "obsolete_exact_files", False, False))
    for manifest_index, item in enumerate(manifest.trusted_consumer_manifests):
        records.append((item["path"], f"trusted_consumer_manifests[{manifest_index}]", False, False))
        for claim_index, claim in enumerate(item["claims"]):
            records.append((
                claim["path"],
                f"trusted_consumer_manifests[{manifest_index}].claims[{claim_index}]",
                True,
                False,
            ))
    for item in manifest.historical_shortcuts:
        # The canonical shortcut is a Current identity even though it is
        # synthesized rather than shipped as a regular file.  Historical
        # shortcut records may therefore share that exact path as evidence;
        # ancestor/descendant overlap remains invalid.
        records.append((item["path"], "historical_shortcuts", True, False))

    for index, (path, section, allows_current_overlap, allows_protected_overlap) in enumerate(records):
        if allows_current_overlap:
            current_overlap = any(
                _path_overlaps(path, current_path) and path != current_path for current_path in current_paths
            )
        else:
            current_overlap = any(_path_overlaps(path, current_path) for current_path in current_paths)
        if current_overlap:
            _fail(f"manifest path overlaps physical Current catalog: {path}")
        if not allows_protected_overlap and any(
            _path_overlaps(path, protected_path) for protected_path in protected_paths
        ):
            _fail(f"manifest path overlaps protected workspace surface: {path}")
        for other_path, other_section, _, _ in records[:index]:
            if section == "historical_current_identities" and other_section == section and path == other_path:
                # Multiple releases may legitimately have different bytes at
                # one reusable Current path; exact duplicates were rejected
                # above by identity signature.
                continue
            # A trusted claim is supplemental evidence for an obsolete exact
            # record at the same path, not a second mutable path declaration.
            trusted_claim = ".claims[" in section and other_section == "obsolete_exact_files"
            obsolete_claim = ".claims[" in other_section and section == "obsolete_exact_files"
            historical_trusted = ".claims[" in section and other_section == "historical_current_identities"
            trusted_historical = ".claims[" in other_section and section == "historical_current_identities"
            if (trusted_claim or obsolete_claim or historical_trusted or trusted_historical) and path == other_path:
                continue
            if _path_overlaps(path, other_path):
                _fail(f"manifest paths overlap: {section}:{path} and {other_section}:{other_path}")


def _load_manifest(path: Path) -> DistributionManifest:
    try:
        raw = json.loads(path.read_text(encoding="utf-8"))
    except (OSError, UnicodeError, json.JSONDecodeError) as exc:
        raise DistributionManifestError(f"unable to load distribution manifest: {path.name}") from exc
    return _validate_manifest(raw)


_CANONICAL_VERSION_RE = re.compile(r"^(0|[1-9][0-9]*)\.(0|[1-9][0-9]*)\.(0|[1-9][0-9]*)\n$")
_DISTRIBUTION_RETRY_MARKER_REL = Path("spec-dock/.distribution-retry.json")
_UNINSTALL_RETRY_MARKER_REL = Path("spec-dock/.uninstall-retry.json")
_DISTRIBUTION_JOURNAL_REL = Path("spec-dock/.distribution-journal.json")
_DISTRIBUTION_JOURNAL_SCHEMA_VERSION = 1
# Fresh journals reuse the existing schema-1 field shape.  The schema-2
# discriminator belongs to the forward guard, not to the journal payload.
_DISTRIBUTION_FRESH_JOURNAL_SCHEMA_VERSION = _DISTRIBUTION_JOURNAL_SCHEMA_VERSION
_DISTRIBUTION_LEGACY_JOURNAL_PROTOCOL_VERSION = 1
_DISTRIBUTION_JOURNAL_PROTOCOL_VERSION = 2
_DISTRIBUTION_SUPPORTED_JOURNAL_PROTOCOL_VERSIONS = frozenset({
    _DISTRIBUTION_LEGACY_JOURNAL_PROTOCOL_VERSION,
    _DISTRIBUTION_JOURNAL_PROTOCOL_VERSION,
})
_DISTRIBUTION_RETRY_SCHEMA_VERSION = 1
_DISTRIBUTION_RETRY_PURPOSE: Literal["distribution-rerun"] = "distribution-rerun"
_DISTRIBUTION_JOURNAL_GUARD_SCHEMA_VERSION = 2
_DISTRIBUTION_JOURNAL_GUARD_PURPOSE: Literal["recognized-journal-forward-only"] = "recognized-journal-forward-only"
_DISTRIBUTION_FRESH_JOURNAL_GUARD_PURPOSE: Literal["fresh-journal-forward-only"] = "fresh-journal-forward-only"
_DISTRIBUTION_DEPROVISION_JOURNAL_GUARD_PURPOSE: Literal["deprovision-journal-forward-only"] = (
    "deprovision-journal-forward-only"
)
_DISTRIBUTION_PURGE_JOURNAL_GUARD_PURPOSE: Literal["purge-journal-forward-only"] = "purge-journal-forward-only"
_DISTRIBUTION_JOURNAL_AUTHORITIES = {
    "recognized-journal-forward-only": "recognized-workspace-reconciliation",
    "fresh-journal-forward-only": "fresh-distribution-provisioning",
    "deprovision-journal-forward-only": "managed-distribution-deprovision",
    "purge-journal-forward-only": "explicit-spec-history-purge",
}
_EXPLICIT_SPEC_HISTORY_ROOT = "spec-dock/initiatives"
_DISTRIBUTION_RETRY_PHASES = frozenset({
    "preflight-complete",
    "managed-scaffold-refreshed",
    "current-external-materialized",
    "obsolete-pruned",
    "post-verified",
    "version-written",
})
_UNINSTALL_RETRY_MARKER_PAYLOAD = {
    "schema_version": 1,
    "managed_by": "spec-dock",
    "purpose": "uninstall-rerun",
}
_VERSION_ANCHOR_PATHS = frozenset({"spec-dock/scripts/spec-dock", "spec-dock/.gitignore"})
_SCAFFOLD_MANAGED_ROOTS = ("docs", "templates", "scripts", "system")
_PROTECTED_WORKSPACE_ROOTS = frozenset({
    *(f"spec-dock/{name}" for name in _SCAFFOLD_MANAGED_ROOTS),
    "spec-dock/initiatives",
    "spec-dock/active",
    "spec-dock/.agent",
    "spec-dock/.workbench",
    "spec-dock/.gitignore",
    "spec-dock/spec-dock.version",
    "spec-dock/.distribution-retry.json",
    "spec-dock/.distribution-journal.json",
    "spec-dock/.uninstall-retry.json",
})


def _protected_workspace_paths(scaffold_assets: tuple[DistributionAsset, ...]) -> frozenset[str]:
    """Return all provider-owned and user-preserve workspace boundaries."""

    return _PROTECTED_WORKSPACE_ROOTS | frozenset(asset.path for asset in scaffold_assets)


def _admission_block(
    reason: str,
    detail: str,
    *,
    recovery_mismatch_kind: DistributionRecoveryMismatchKind | None = None,
) -> NoReturn:
    raise DistributionAdmissionError(
        f"distribution admission blocked ({reason}): {detail}",
        reason=reason,
        recovery_mismatch_kind=recovery_mismatch_kind,
    )


def _parse_canonical_version(value: str, *, source: str) -> tuple[int, int, int]:
    """Parse the deliberately narrow version grammar used by workspace markers."""

    try:
        match = _CANONICAL_VERSION_RE.fullmatch(value)
    except (OverflowError, ValueError):
        match = None
    if match is None:
        _admission_block("invalid-version", f"{source} is not canonical MAJOR.MINOR.PATCH")
    assert match is not None
    try:
        return tuple(int(component) for component in match.groups())  # type: ignore[return-value]
    except (OverflowError, ValueError):
        _admission_block("invalid-version", f"{source} contains an invalid numeric component")


def _parse_package_version(value: str, *, source: str) -> tuple[int, int, int]:
    if "\n" in value or "\r" in value:
        _admission_block("invalid-version", f"{source} must not contain a line break")
    return _parse_canonical_version(value + "\n", source=source)


def _read_no_follow_regular_evidence(
    path: Path,
    *,
    label: str,
    allow_missing: bool = False,
) -> tuple[bytes, os.stat_result] | None:
    """Read one link-count-one regular file and retain its held identity."""

    nofollow = getattr(os, "O_NOFOLLOW", None)
    if not isinstance(nofollow, int):
        _admission_block("platform-unsupported", "no-follow regular-file admission is unavailable")
    if path.is_symlink():
        if label == "uninstall retry marker":
            _admission_block("invalid-file", "symlinked SpecDock uninstall retry marker")
        _admission_block("invalid-file", f"{label} is symlinked")
    flags = os.O_RDONLY | nofollow | getattr(os, "O_CLOEXEC", 0)
    try:
        fd = os.open(path, flags)
    except FileNotFoundError:
        if allow_missing:
            return None
        _admission_block("missing", f"{label} is missing")
    except OSError:
        _admission_block("invalid-file", f"{label} cannot be opened without following links")
    try:
        before = os.fstat(fd)
        if not stat.S_ISREG(before.st_mode):
            _admission_block("invalid-file", f"{label} must be a regular file")
        if before.st_nlink != 1:
            _admission_block("hard-link", f"{label} must have link count 1")
        chunks: list[bytes] = []
        while True:
            chunk = os.read(fd, 1024 * 1024)
            if not chunk:
                break
            chunks.append(chunk)
        content = b"".join(chunks)
        after = os.fstat(fd)
        if (
            before.st_dev,
            before.st_ino,
            before.st_ctime_ns,
            before.st_mode,
            before.st_nlink,
        ) != (
            after.st_dev,
            after.st_ino,
            after.st_ctime_ns,
            after.st_mode,
            after.st_nlink,
        ):
            _admission_block("invalid-file", f"{label} changed while it was read")
        return content, after
    except OSError:
        _admission_block("read-error", f"{label} cannot be read safely")
    finally:
        os.close(fd)


def _read_no_follow_regular(path: Path, *, label: str, allow_missing: bool = False) -> bytes | None:
    """Read one link-count-one regular file without following a symlink."""

    evidence = _read_no_follow_regular_evidence(path, label=label, allow_missing=allow_missing)
    return evidence[0] if evidence is not None else None


def _path_present_no_follow(path: Path) -> bool:
    try:
        os.lstat(path)
    except FileNotFoundError:
        return False
    except OSError:
        _admission_block("marker-invalid", f"cannot inspect {path.name}")
    return True


def _root_identity_for_admission(target_root: Path) -> DistributionRootIdentity:
    try:
        info = os.lstat(target_root)
    except OSError:
        _admission_block("target-root-invalid", "target root cannot be inspected safely")
    if stat.S_ISLNK(info.st_mode) or not stat.S_ISDIR(info.st_mode):
        _admission_block("target-root-invalid", "target root must be a real directory")
    return DistributionRootIdentity(device=info.st_dev, inode=info.st_ino)


def _is_preserved_specs_workspace(target_root: Path) -> bool:
    """Recognize only the exact boundary left by a successful keep-specs uninstall."""

    specdock_path = target_root / "spec-dock"
    try:
        specdock_info = os.lstat(specdock_path)
    except FileNotFoundError:
        return False
    except OSError:
        _admission_block("workspace-invalid", "managed workspace cannot be inspected safely")
    if stat.S_ISLNK(specdock_info.st_mode) or not stat.S_ISDIR(specdock_info.st_mode):
        return False
    try:
        children = list(os.scandir(specdock_path))
    except OSError:
        _admission_block("workspace-invalid", "managed workspace cannot be inspected safely")
    children_by_name = {entry.name: entry for entry in children}
    if "initiatives" not in children_by_name or not set(children_by_name) <= {"initiatives", ".workbench"}:
        return False
    pending = [entry.path for entry in children_by_name.values()]
    while pending:
        current = pending.pop()
        try:
            current_info = os.lstat(current)
        except OSError:
            _admission_block("workspace-invalid", "preserved workspace cannot be inspected safely")
        if not stat.S_ISDIR(current_info.st_mode):
            return False
        try:
            entries = list(os.scandir(current))
        except OSError:
            _admission_block("workspace-invalid", "preserved workspace cannot be inspected safely")
        for entry in entries:
            try:
                entry_info = entry.stat(follow_symlinks=False)
            except OSError:
                _admission_block("workspace-invalid", "preserved workspace cannot be inspected safely")
            if stat.S_ISDIR(entry_info.st_mode):
                pending.append(entry.path)
                continue
            if not (stat.S_ISREG(entry_info.st_mode) or stat.S_ISLNK(entry_info.st_mode)):
                return False
    return True


def _assert_real_parent_chain(target_root: Path, relative_path: str, *, label: str) -> bool:
    current = target_root
    for component in PurePosixPath(relative_path).parts[:-1]:
        current = current / component
        try:
            info = os.lstat(current)
        except FileNotFoundError:
            return False
        except OSError:
            _admission_block("invalid-file", f"{label} parent cannot be inspected")
        if stat.S_ISLNK(info.st_mode) or not stat.S_ISDIR(info.st_mode):
            _admission_block("invalid-file", f"{label} parent must be a real directory")
    return True


def _read_distribution_retry_marker(
    target_root: Path,
    *,
    expected_intent: JournaledDistributionIntent | None = None,
) -> DistributionRetryMarker | None:
    path = target_root / _DISTRIBUTION_RETRY_MARKER_REL
    if not _path_present_no_follow(path):
        return None
    evidence = _read_no_follow_regular_evidence(path, label="distribution retry marker")
    assert evidence is not None
    raw_bytes, source_info = evidence
    try:
        raw = json.loads(raw_bytes.decode("utf-8"))
    except (UnicodeDecodeError, json.JSONDecodeError):
        _admission_block("marker-invalid", "distribution retry marker is not valid UTF-8 JSON")
    if not isinstance(raw, dict):
        _admission_block("marker-invalid", "distribution retry marker must be an object")
    base_fields = {
        "schema_version",
        "operation",
        "package_version",
        "target_root",
        "last_completed_phase",
        "purpose",
    }
    schema_version = raw.get("schema_version")
    purpose = raw.get("purpose")
    supported_guard = (
        schema_version == _DISTRIBUTION_JOURNAL_GUARD_SCHEMA_VERSION
        and isinstance(purpose, str)
        and purpose
        in {
            _DISTRIBUTION_JOURNAL_GUARD_PURPOSE,
            _DISTRIBUTION_FRESH_JOURNAL_GUARD_PURPOSE,
            _DISTRIBUTION_DEPROVISION_JOURNAL_GUARD_PURPOSE,
            _DISTRIBUTION_PURGE_JOURNAL_GUARD_PURPOSE,
        }
    )
    supported_legacy = schema_version == _DISTRIBUTION_RETRY_SCHEMA_VERSION and purpose == _DISTRIBUTION_RETRY_PURPOSE
    operation = raw.get("operation")
    supported_operation = isinstance(operation, str) and operation in {
        "fresh",
        "update",
        "init-force",
        "deprovision",
        "purge",
    }
    if supported_guard and supported_operation:
        purpose_operation_matches = (
            (purpose == _DISTRIBUTION_JOURNAL_GUARD_PURPOSE and operation in {"update", "init-force"})
            or (purpose == _DISTRIBUTION_FRESH_JOURNAL_GUARD_PURPOSE and operation == "fresh")
            or (purpose == _DISTRIBUTION_DEPROVISION_JOURNAL_GUARD_PURPOSE and operation == "deprovision")
            or (purpose == _DISTRIBUTION_PURGE_JOURNAL_GUARD_PURPOSE and operation == "purge")
        )
        expected_intent_supported = isinstance(expected_intent, str) and expected_intent in _SUPPORTED_JOURNALED_INTENTS
        request_operation_matches = not expected_intent_supported or operation == expected_intent
        if not purpose_operation_matches or not request_operation_matches:
            _admission_block(
                "marker-invalid",
                "distribution retry marker purpose and operation do not match",
                recovery_mismatch_kind="intent-authority",
            )
    expected_fields = (
        base_fields | {"operation_id", "contract_identity", "plan_digest"} if supported_guard else base_fields
    )
    anchor_fields = {"journal_digest", "journal_predecessor_digest"}
    created_at_anchor_field = {"journal_created_at_ns"}
    raw_fields = set(raw)
    allowed_field_sets = {
        frozenset(expected_fields),
        frozenset(expected_fields | {"stage_ownership"}),
    }
    if supported_guard:
        legacy_anchor_sets = {fields | anchor_fields for fields in tuple(allowed_field_sets)}
        allowed_field_sets.update(legacy_anchor_sets)
        allowed_field_sets.update({fields | created_at_anchor_field for fields in legacy_anchor_sets})
    if frozenset(raw_fields) not in allowed_field_sets:
        _admission_block("marker-invalid", "distribution retry marker fields are invalid")
    if not supported_guard and not supported_legacy:
        _admission_block("marker-invalid", "distribution retry marker schema is unsupported")
    if not supported_operation:
        _admission_block("marker-invalid", "distribution retry marker operation is unsupported")
    assert isinstance(operation, str)
    operation = cast("Literal['fresh', 'update', 'init-force', 'deprovision', 'purge']", operation)
    if supported_guard and (
        (purpose == _DISTRIBUTION_JOURNAL_GUARD_PURPOSE and operation not in {"update", "init-force"})
        or (purpose == _DISTRIBUTION_FRESH_JOURNAL_GUARD_PURPOSE and operation != "fresh")
        or (purpose == _DISTRIBUTION_DEPROVISION_JOURNAL_GUARD_PURPOSE and operation != "deprovision")
        or (purpose == _DISTRIBUTION_PURGE_JOURNAL_GUARD_PURPOSE and operation != "purge")
    ):
        _admission_block("marker-invalid", "distribution retry marker purpose and operation do not match")
    package_version = raw.get("package_version")
    if not isinstance(package_version, str):
        _admission_block("marker-invalid", "distribution retry marker package_version is invalid")
    _parse_package_version(package_version, source="distribution retry marker package_version")
    root = raw.get("target_root")
    if not isinstance(root, dict) or set(root) != {"device", "inode"}:
        _admission_block("marker-invalid", "distribution retry marker target_root identity is invalid")
    device = root.get("device")
    inode = root.get("inode")
    if (
        isinstance(device, bool)
        or not isinstance(device, int)
        or device <= 0
        or isinstance(inode, bool)
        or not isinstance(inode, int)
        or inode <= 0
    ):
        _admission_block("marker-invalid", "distribution retry marker target_root identity is invalid")
    phase = raw.get("last_completed_phase")
    if not isinstance(phase, str) or phase not in _DISTRIBUTION_RETRY_PHASES:
        _admission_block("marker-invalid", "distribution retry marker phase is invalid")
    operation_id = raw.get("operation_id") if supported_guard else None
    contract_identity = raw.get("contract_identity") if supported_guard else None
    plan_digest = raw.get("plan_digest") if supported_guard else None
    journal_digest = raw.get("journal_digest") if supported_guard else None
    journal_predecessor_digest = raw.get("journal_predecessor_digest") if supported_guard else None
    journal_created_at_ns = raw.get("journal_created_at_ns") if supported_guard else None
    if supported_guard and (
        not isinstance(operation_id, str)
        or not operation_id
        or not isinstance(contract_identity, str)
        or not contract_identity
        or not isinstance(plan_digest, str)
        or not re.fullmatch(r"[0-9a-f]{64}", plan_digest)
    ):
        _admission_block("marker-invalid", "distribution retry marker plan binding is invalid")
    if (
        supported_guard
        and raw_fields & anchor_fields
        and (
            not isinstance(journal_digest, str)
            or not re.fullmatch(r"[0-9a-f]{64}", journal_digest)
            or (
                journal_created_at_ns is not None
                and (
                    isinstance(journal_created_at_ns, bool)
                    or not isinstance(journal_created_at_ns, int)
                    or journal_created_at_ns <= 0
                )
            )
            or (
                journal_predecessor_digest is not None
                and (
                    not isinstance(journal_predecessor_digest, str)
                    or not re.fullmatch(r"[0-9a-f]{64}", journal_predecessor_digest)
                )
            )
        )
    ):
        _admission_block("marker-invalid", "distribution retry marker journal anchor is invalid")
    stage_ownership: list[DistributionStageOwnership] = []
    raw_stage_ownership = raw.get("stage_ownership", [])
    if not isinstance(raw_stage_ownership, list):
        _admission_block("marker-invalid", "distribution retry marker stage ownership is invalid")
    for item in raw_stage_ownership:
        if not isinstance(item, dict) or set(item) != {
            "path",
            "stage_name",
            "device",
            "inode",
            "ctime_ns",
            "file_type",
        }:
            _admission_block("marker-invalid", "distribution retry marker stage ownership is invalid")
        stage_path = item.get("path")
        stage_name = item.get("stage_name")
        file_type = item.get("file_type")
        if (
            not isinstance(stage_path, str)
            or not stage_path
            or PurePosixPath(stage_path).is_absolute()
            or ".." in PurePosixPath(stage_path).parts
            or PurePosixPath(stage_path).as_posix() != stage_path
            or not isinstance(stage_name, str)
            or not stage_name
            or PurePosixPath(stage_name).name != stage_name
            or not isinstance(file_type, str)
            or file_type not in {"regular", "symlink"}
        ):
            _admission_block("marker-invalid", "distribution retry marker stage ownership is invalid")
        stage_device = item.get("device")
        stage_inode = item.get("inode")
        stage_ctime_ns = item.get("ctime_ns")
        if any(
            isinstance(value, bool) or not isinstance(value, int) or value <= 0
            for value in (stage_device, stage_inode, stage_ctime_ns)
        ):
            _admission_block("marker-invalid", "distribution retry marker stage ownership is invalid")
        assert isinstance(stage_device, int)
        assert isinstance(stage_inode, int)
        assert isinstance(stage_ctime_ns, int)
        assert file_type in {"regular", "symlink"}
        stage_file_type: Literal["regular", "symlink"] = "regular" if file_type == "regular" else "symlink"
        stage_ownership.append(
            DistributionStageOwnership(
                path=stage_path,
                stage_name=stage_name,
                device=stage_device,
                inode=stage_inode,
                ctime_ns=stage_ctime_ns,
                file_type=stage_file_type,
            )
        )
    guard_purpose = (
        cast(
            "Literal['recognized-journal-forward-only', 'fresh-journal-forward-only', "
            "'deprovision-journal-forward-only', 'purge-journal-forward-only']",
            purpose,
        )
        if supported_guard
        else _DISTRIBUTION_RETRY_PURPOSE
    )
    return DistributionRetryMarker(
        operation=operation,
        package_version=package_version,
        target_root=DistributionRootIdentity(device=device, inode=inode),
        last_completed_phase=phase,
        purpose=guard_purpose,
        stage_ownership=tuple(stage_ownership),
        operation_id=operation_id,
        contract_identity=contract_identity,
        plan_digest=plan_digest,
        journal_digest=journal_digest,
        journal_predecessor_digest=journal_predecessor_digest,
        journal_created_at_ns=journal_created_at_ns,
        source_snapshot=_snapshot_from_stat(_DISTRIBUTION_RETRY_MARKER_REL.as_posix(), source_info),
        source_sha256=hashlib.sha256(raw_bytes).hexdigest(),
    )


def _read_uninstall_retry_marker_for_admission(target_root: Path) -> bool:
    path = target_root / _UNINSTALL_RETRY_MARKER_REL
    try:
        info = os.lstat(path)
    except FileNotFoundError:
        return False
    except OSError:
        _admission_block("marker-invalid", "uninstall retry marker cannot be inspected safely")
    if stat.S_ISLNK(info.st_mode) or not stat.S_ISREG(info.st_mode):
        _admission_block("marker-invalid", "uninstall retry marker must be a regular file")
    if info.st_nlink != 1:
        _admission_block("marker-invalid", "uninstall retry marker must have link count 1")
    raw_bytes = _read_no_follow_regular(path, label="uninstall retry marker")
    assert raw_bytes is not None
    try:
        raw = json.loads(raw_bytes.decode("utf-8"))
    except (UnicodeDecodeError, json.JSONDecodeError):
        _admission_block("marker-invalid", "uninstall retry marker is not valid UTF-8 JSON")
    if raw != _UNINSTALL_RETRY_MARKER_PAYLOAD:
        _admission_block("marker-invalid", "uninstall retry marker schema is invalid")
    return True


def _anchor_identity_matches(target_root: Path, anchor: dict[str, Any]) -> bool:
    path_text = anchor.get("path")
    if path_text not in _VERSION_ANCHOR_PATHS or anchor.get("kind") != "regular":
        return False
    expected_digest = anchor.get("sha256")
    if not isinstance(expected_digest, str):
        return False
    if not _assert_real_parent_chain(target_root, path_text, label=f"version anchor {path_text}"):
        return False
    actual = _read_no_follow_regular(target_root / path_text, label=f"version anchor {path_text}", allow_missing=True)
    if actual is None:
        return False
    return hashlib.sha256(actual).hexdigest() == expected_digest


def _recognized_version_entry(manifest: DistributionManifest, version: str) -> dict[str, Any]:
    matches = [item for item in manifest.recognized_workspace_versions if item.get("version") == version]
    if len(matches) != 1:
        _admission_block("unknown-version", f"workspace version {version!r} is not an exact recognized entry")
    entry = matches[0]
    anchors = entry.get("anchors")
    if not isinstance(anchors, tuple):
        _admission_block("anchor-mismatch", f"workspace version {version!r} has invalid anchors")
    by_path = {anchor.get("path"): anchor for anchor in anchors if isinstance(anchor, dict)}
    if set(_VERSION_ANCHOR_PATHS) - set(by_path):
        _admission_block("anchor-mismatch", f"workspace version {version!r} is missing required anchors")
    return entry


def _validate_workspace_version(
    target_root: Path,
    *,
    manifest: DistributionManifest,
    package_version: str,
) -> tuple[str, tuple[int, int, int], DistributionIdentity]:
    version_path = target_root / "spec-dock" / "spec-dock.version"
    raw_bytes = _read_no_follow_regular(version_path, label="spec-dock/spec-dock.version", allow_missing=True)
    if raw_bytes is None:
        _admission_block("missing-version", "spec-dock/spec-dock.version is missing")
    try:
        version_text = raw_bytes.decode("ascii")
    except UnicodeDecodeError:
        _admission_block("invalid-version", "spec-dock/spec-dock.version must be ASCII")
    target_tuple = _parse_canonical_version(version_text, source="spec-dock/spec-dock.version")
    try:
        version_info = os.lstat(version_path)
    except OSError:
        _admission_block("invalid-file", "spec-dock/spec-dock.version changed during admission")
    if not stat.S_ISREG(version_info.st_mode) or version_info.st_nlink != 1:
        _admission_block("invalid-file", "spec-dock/spec-dock.version changed during admission")
    version_identity = DistributionIdentity(
        kind="regular",
        sha256=hashlib.sha256(raw_bytes).hexdigest(),
        mode=stat.S_IMODE(version_info.st_mode),
    )
    entry = _recognized_version_entry(manifest, version_text[:-1])
    anchors = entry["anchors"]
    for path_text in _VERSION_ANCHOR_PATHS:
        anchor = next((item for item in anchors if item.get("path") == path_text), None)
        if anchor is None or not _anchor_identity_matches(target_root, anchor):
            _admission_block("anchor-mismatch", f"version anchor does not match: {path_text}")
    package_tuple = _parse_package_version(package_version, source="executing package version")
    if target_tuple > package_tuple:
        _admission_block(
            "downgrade-blocked", f"target version {version_text[:-1]} is newer than package {package_version}"
        )
    return version_text[:-1], target_tuple, version_identity


def _journal_authority_for_intent(intent: JournaledDistributionIntent) -> str:
    if intent == "fresh":
        return "fresh-distribution-provisioning"
    if intent == "deprovision":
        return "managed-distribution-deprovision"
    if intent == "purge":
        return "explicit-spec-history-purge"
    return "recognized-workspace-reconciliation"


def _canonical_journal_authority_intents(authority: object) -> tuple[JournaledDistributionIntent, ...]:
    """Return supported intents whose canonical journal authority matches."""

    if not isinstance(authority, str):
        return ()
    return tuple(
        intent
        for intent in cast("tuple[JournaledDistributionIntent, ...]", tuple(_SUPPORTED_JOURNALED_INTENTS))
        if _journal_authority_for_intent(intent) == authority
    )


def _journal_guard_purpose_for_intent(
    intent: JournaledDistributionIntent,
) -> Literal[
    "recognized-journal-forward-only",
    "fresh-journal-forward-only",
    "deprovision-journal-forward-only",
    "purge-journal-forward-only",
]:
    if intent == "fresh":
        return _DISTRIBUTION_FRESH_JOURNAL_GUARD_PURPOSE
    if intent == "deprovision":
        return _DISTRIBUTION_DEPROVISION_JOURNAL_GUARD_PURPOSE
    if intent == "purge":
        return _DISTRIBUTION_PURGE_JOURNAL_GUARD_PURPOSE
    return _DISTRIBUTION_JOURNAL_GUARD_PURPOSE


def _journal_intent_for_guard_purpose(
    purpose: str,
) -> JournaledDistributionIntent:
    if purpose == _DISTRIBUTION_FRESH_JOURNAL_GUARD_PURPOSE:
        return "fresh"
    if purpose == _DISTRIBUTION_JOURNAL_GUARD_PURPOSE:
        return "update"
    if purpose == _DISTRIBUTION_DEPROVISION_JOURNAL_GUARD_PURPOSE:
        return "deprovision"
    if purpose == _DISTRIBUTION_PURGE_JOURNAL_GUARD_PURPOSE:
        return "purge"
    raise DistributionPlanError("unsupported journal guard purpose")


def admit_distribution_operation(
    target_root: Path,
    *,
    operation: DistributionOperation,
    package_version: str,
    manifest_path: Path,
) -> DistributionAdmission:
    """Admit an installer operation without mutating the consumer tree.

    This is intentionally separate from distribution planning and apply.  It
    validates the package version, workspace marker, version-specific anchors,
    and operation-specific retry markers before any caller performs a write.
    """

    if operation not in _OPERATIONS:
        _admission_block("operation-invalid", f"unsupported operation: {operation!r}")
    _parse_package_version(package_version, source="executing package version")
    target_root = Path(target_root)
    root_identity = _root_identity_for_admission(target_root)
    try:
        manifest = _load_manifest(Path(manifest_path))
    except DistributionManifestError as exc:
        _admission_block("manifest-invalid", str(exc))

    specdock_path = target_root / "spec-dock"
    try:
        specdock_info = os.lstat(specdock_path)
    except FileNotFoundError:
        specdock_info = None
    except OSError:
        _admission_block("workspace-invalid", "managed workspace cannot be inspected safely")
    if (
        specdock_info is not None
        and not stat.S_ISLNK(specdock_info.st_mode)
        and not stat.S_ISDIR(specdock_info.st_mode)
    ):
        _admission_block("workspace-invalid", "spec-dock must be a real directory")
    if specdock_info is not None and stat.S_ISLNK(specdock_info.st_mode):
        _admission_block("workspace-invalid", "spec-dock is a symlink; a real directory is required")

    distribution_marker_present = _path_present_no_follow(target_root / _DISTRIBUTION_RETRY_MARKER_REL)
    journal_present = _path_present_no_follow(target_root / _DISTRIBUTION_JOURNAL_REL)
    uninstall_marker_present = _path_present_no_follow(target_root / _UNINSTALL_RETRY_MARKER_REL)
    if uninstall_marker_present and (distribution_marker_present or journal_present):
        _admission_block("dual-marker", "distribution recovery states cannot coexist")

    if journal_present:
        if operation == "uninstall":
            _admission_block("distribution-retry-present", "recover distribution before this operation")
        distribution_marker = _read_distribution_retry_marker(target_root)
        if distribution_marker is None:
            try:
                terminal_journal = OperationJournalStore(target_root)._read(root_identity)
            except DistributionApplyError:
                _admission_block("dual-marker", "distribution recovery states cannot coexist")
            if (
                terminal_journal.status != "completed"
                or terminal_journal.intent not in {"fresh", "update", "init-force"}
                or terminal_journal.authority != _journal_authority_for_intent(terminal_journal.intent)
                or terminal_journal.protocol_version not in _DISTRIBUTION_SUPPORTED_JOURNAL_PROTOCOL_VERSIONS
                or not _journal_package_is_compatible(terminal_journal.package_version, package_version)
                or terminal_journal.staging_leases
                or any(action.checkpoint != "verified" for action in terminal_journal.actions)
            ):
                _admission_block("dual-marker", "distribution recovery states cannot coexist")
            if terminal_journal.intent != "fresh" and terminal_journal.intent != operation:
                _admission_block("marker-operation-mismatch", "journal belongs to another operation")
            return DistributionAdmission(
                operation=operation,
                intent=terminal_journal.intent,
                status="retry",
                package_version=package_version,
            )
        if distribution_marker is None:
            _admission_block("dual-marker", "distribution recovery states cannot coexist")
        marker_intent = (
            "fresh"
            if (
                distribution_marker.purpose == _DISTRIBUTION_FRESH_JOURNAL_GUARD_PURPOSE
                or distribution_marker.operation == "fresh"
            )
            else operation
        )
        marker_operation_valid = (
            distribution_marker.operation == "fresh"
            if marker_intent == "fresh"
            else distribution_marker.operation == operation
        )
        if distribution_marker is None or (
            distribution_marker.purpose
            not in {
                _DISTRIBUTION_JOURNAL_GUARD_PURPOSE,
                _DISTRIBUTION_FRESH_JOURNAL_GUARD_PURPOSE,
            }
            or distribution_marker.source_snapshot is None
            or distribution_marker.source_sha256 is None
            or not marker_operation_valid
            or distribution_marker.target_root != root_identity
            or distribution_marker.last_completed_phase != "preflight-complete"
            or not _journal_package_is_compatible(distribution_marker.package_version, package_version)
        ):
            _admission_block("dual-marker", "distribution recovery states cannot coexist")
        return DistributionAdmission(
            operation=operation,
            intent=marker_intent,
            status="retry",
            package_version=package_version,
            marker=distribution_marker,
        )

    distribution_marker = _read_distribution_retry_marker(target_root)
    uninstall_marker = _read_uninstall_retry_marker_for_admission(target_root)
    if distribution_marker is not None:
        if operation == "uninstall":
            _admission_block("distribution-retry-present", "recover distribution before uninstall")
        marker_intent = (
            "fresh"
            if (
                distribution_marker.purpose == _DISTRIBUTION_FRESH_JOURNAL_GUARD_PURPOSE
                or distribution_marker.operation == "fresh"
            )
            else operation
        )
        marker_operation_valid = (
            distribution_marker.operation == "fresh"
            if marker_intent == "fresh"
            else distribution_marker.operation == operation
        )
        if not marker_operation_valid:
            _admission_block("marker-operation-mismatch", "retry marker belongs to another operation")
        if not _journal_package_is_compatible(distribution_marker.package_version, package_version):
            _admission_block("marker-package-mismatch", "retry marker belongs to another package version")
        if distribution_marker.target_root != root_identity:
            _admission_block("cross-root-replay", "retry marker belongs to another repository root")
        return DistributionAdmission(
            operation=operation,
            intent=marker_intent,
            status="retry",
            package_version=package_version,
            marker=distribution_marker,
        )
    if uninstall_marker:
        if operation != "uninstall":
            _admission_block("uninstall-retry-present", "recover uninstall before init or update")
        return DistributionAdmission(
            operation=operation,
            intent=None,
            status="uninstall-retry",
            package_version=package_version,
        )

    # A successful uninstall may intentionally leave an empty workspace
    # boundary after the retry marker is finalized.  Treat that exact empty
    # directory as a fresh admission so the documented `init` recovery path
    # can recreate the managed scaffold without requiring `--force`.
    if specdock_info is not None:
        try:
            empty_workspace_boundary = not any(specdock_path.iterdir())
        except OSError:
            _admission_block("workspace-invalid", "managed workspace cannot be inspected safely")
        if empty_workspace_boundary and operation in {"fresh", "init-force", "update"}:
            return DistributionAdmission(
                operation=operation, intent="fresh", status="fresh", package_version=package_version
            )
        if operation in {"fresh", "init-force", "update"} and _is_preserved_specs_workspace(target_root):
            return DistributionAdmission(
                operation=operation, intent="fresh", status="fresh", package_version=package_version
            )

    if specdock_info is None:
        if operation in {"fresh", "init-force", "update"}:
            return DistributionAdmission(
                operation=operation, intent="fresh", status="fresh", package_version=package_version
            )
        if operation == "update":
            _admission_block(
                "workspace-missing",
                "'spec-dock' not found. Run 'spec-dock init' first.",
            )
        _admission_block("workspace-missing", "target is not a managed SpecDock repo")
    if operation == "fresh":
        return DistributionAdmission(
            operation=operation, intent="fresh", status="existing", package_version=package_version
        )
    target_version, _target_tuple, version_identity = _validate_workspace_version(
        target_root,
        manifest=manifest,
        package_version=package_version,
    )
    recognized_intent: JournaledDistributionIntent | None = None
    if operation in {"update", "init-force"}:
        recognized_intent = cast("JournaledDistributionIntent", operation)
    return DistributionAdmission(
        operation=operation,
        intent=recognized_intent,
        status="recognized",
        package_version=package_version,
        target_version=target_version,
        version_identity=version_identity,
    )


def _current_assets(install_root: Path) -> tuple[DistributionAsset, ...]:
    if not install_root.is_dir() or install_root.is_symlink():
        raise DistributionManifestError("physical install-root must be a directory")
    assets: list[DistributionAsset] = []
    for candidate in sorted(install_root.rglob("*"), key=lambda item: item.relative_to(install_root).as_posix()):
        if not candidate.is_file() or candidate.is_symlink():
            continue
        relative_candidate = candidate.relative_to(install_root)
        if "__pycache__" in relative_candidate.parts or relative_candidate.suffix in {".pyc", ".pyo"}:
            continue
        relative = _exact_relative_path(relative_candidate.as_posix(), field_name="Current path")
        try:
            content, source_snapshot = _source_asset_bytes(candidate)
            digest = hashlib.sha256(content).hexdigest()
        except (OSError, DistributionApplyError) as exc:
            raise DistributionManifestError(f"unable to read Current asset: {relative.as_posix()}") from exc
        assets.append(
            DistributionAsset(
                path=relative.as_posix(),
                identity=DistributionIdentity(
                    kind="regular",
                    sha256=digest,
                    mode=source_snapshot.mode,
                ),
                source_snapshot=source_snapshot,
            )
        )
    return tuple(assets)


def _scaffold_assets(scaffold_root: Path, *, operation: DistributionOperation) -> tuple[DistributionAsset, ...]:
    """Build the managed scaffold portion of the shared distribution catalog."""

    def is_pruned_by_scaffold_refresh(relative: Path) -> bool:
        parts = relative.parts
        if parts[0] == "scripts" and parts[-1].startswith("spec-dock-close") and parts[-1].endswith(".sh"):
            return True
        if parts[0] != "templates":
            return False
        if len(parts) == 2 and parts[1] in {"requirement.md", "design.md", "plan.md", "report.md"}:
            return True
        if len(parts) >= 2 and parts[1] in {"current", "completed"}:
            return True
        if (
            len(parts) >= 3
            and parts[1] in {"initiative", "epic", "issue"}
            and (parts[2] == "deps.json" or parts[2] in {"adrs", "artifacts", "current", "completed"})
        ):
            return True
        preserved_readmes = {
            PurePosixPath("templates/README.md"),
            PurePosixPath("templates/root/.workbench/README.md"),
            PurePosixPath("templates/initiative/.workbench/README.md"),
            PurePosixPath("templates/epic/.workbench/README.md"),
            PurePosixPath("templates/issue/.workbench/README.md"),
        }
        return parts[-1] == "README.md" and relative not in preserved_readmes

    if not scaffold_root.is_dir() or scaffold_root.is_symlink():
        raise DistributionManifestError("Missing asset directory: spec_dock")
    if not (scaffold_root / ".gitignore").is_file() or (scaffold_root / ".gitignore").is_symlink():
        raise DistributionManifestError("Missing asset file: spec_dock/.gitignore")
    source_entries: list[tuple[str, Path]] = [(".gitignore", scaffold_root / ".gitignore")]
    for root_name in _SCAFFOLD_MANAGED_ROOTS:
        source_root = scaffold_root / root_name
        if not source_root.is_dir() or source_root.is_symlink():
            raise DistributionManifestError(f"Invalid asset directory: spec_dock/{root_name}")
        for candidate in sorted(source_root.rglob("*"), key=lambda item: item.relative_to(scaffold_root).as_posix()):
            relative = candidate.relative_to(scaffold_root)
            if "__pycache__" in relative.parts or relative.suffix in {".pyc", ".pyo"}:
                continue
            if is_pruned_by_scaffold_refresh(relative):
                continue
            if candidate.is_file() and not candidate.is_symlink():
                source_entries.append((relative.as_posix(), candidate))
    runtime_script = scaffold_root / "scripts" / "spec-dock"
    try:
        runtime_info = os.lstat(runtime_script)
    except OSError as exc:
        raise DistributionManifestError("Missing asset file: spec_dock/scripts/spec-dock") from exc
    if (
        stat.S_ISLNK(runtime_info.st_mode)
        or not stat.S_ISREG(runtime_info.st_mode)
        or runtime_info.st_nlink != 1
        or stat.S_IMODE(runtime_info.st_mode) & 0o111 == 0
    ):
        raise DistributionManifestError("Invalid asset file: spec_dock/scripts/spec-dock")
    seed_readme = scaffold_root / "templates" / "root" / ".workbench" / "README.md"
    if not seed_readme.is_file() or seed_readme.is_symlink():
        raise DistributionManifestError("Missing asset file: spec_dock/templates/root/.workbench/README.md")
    if operation == "fresh" and seed_readme.is_file() and not seed_readme.is_symlink():
        source_entries.append((".workbench/README.md", seed_readme))

    assets: list[DistributionAsset] = []
    for source_path, candidate in sorted(source_entries):
        try:
            content, source_snapshot = _source_asset_bytes(candidate)
            digest = hashlib.sha256(content).hexdigest()
        except (OSError, DistributionApplyError) as exc:
            raise DistributionManifestError(f"unable to read scaffold asset: {source_path}") from exc
        mode = source_snapshot.mode
        if source_path == "scripts/spec-dock":
            mode |= 0o111
        if source_path.startswith("system/active-none/"):
            mode &= ~0o222
        # The fresh root workbench seed is published at the workspace root,
        # while its provider source remains under the root template.  Keep the
        # two paths explicit so the journaled apply phase can read the same
        # no-follow source that preflight inspected.
        target_path = (
            "spec-dock/.workbench/README.md" if source_path == ".workbench/README.md" else f"spec-dock/{source_path}"
        )
        provider_source_path = (
            "templates/root/.workbench/README.md" if source_path == ".workbench/README.md" else source_path
        )
        assets.append(
            DistributionAsset(
                path=target_path,
                source_path=provider_source_path,
                identity=DistributionIdentity(
                    kind="regular",
                    sha256=digest,
                    mode=mode,
                ),
                source_snapshot=source_snapshot,
            )
        )
    return tuple(assets)


def _fresh_required_directory_paths(
    assets: tuple[DistributionAsset, ...],
) -> tuple[DistributionDirectoryRequirement, ...]:
    # These workspace boundaries are part of the fresh contract even when the
    # current provider catalog has no child asset under them.  They are the
    # preserved-specs and runtime-state roots that the installer has always
    # provisioned and that later commands address directly.
    required: set[str] = {
        "spec-dock",
        "spec-dock/initiatives",
        "spec-dock/.agent",
    }
    for asset in assets:
        parts = PurePosixPath(asset.path).parts[:-1]
        required.update("/".join(parts[:index]) for index in range(1, len(parts) + 1))
    return tuple(
        DistributionDirectoryRequirement(path)
        for path in sorted(required, key=lambda path: (len(PurePosixPath(path).parts), path))
    )


_OPERATIONS = frozenset({"fresh", "update", "init-force", "uninstall"})
_CURRENT_SHORTCUTS = {
    "spec": DistributionIdentity(kind="symlink", target="spec-dock/scripts/spec-dock"),
}


@dataclass(frozen=True)
class _TargetObservation:
    state: str
    identity: DistributionIdentity | None = None
    link_count: int | None = None
    snapshot: DistributionTargetSnapshot | None = None


def _identity_matches(
    actual: DistributionIdentity,
    record: dict[str, Any],
    *,
    include_mode: bool = True,
) -> bool:
    if actual.kind != record.get("kind"):
        return False
    if actual.kind == "regular":
        if actual.sha256 != record.get("sha256"):
            return False
        expected_mode = record.get("mode")
        return not include_mode or expected_mode is None or actual.mode == expected_mode
    return actual.target == record.get("target")


def _removal_identity_matches(
    actual: DistributionIdentity,
    record: dict[str, Any],
) -> bool:
    """Require complete regular-file identity before granting removal authority.

    Historical manifests remain schema-compatible when a legacy record omits
    ``mode``.  Such a record can still support update/repair provenance, but
    it is deliberately insufficient to prove ownership for a destructive
    prune.
    """

    if actual.kind == "regular":
        mode = record.get("mode")
        if isinstance(mode, bool) or not isinstance(mode, int) or not 0 <= mode <= 0o777:
            return False
    return _identity_matches(actual, record, include_mode=True)


def _normalized_link_target(value: str) -> str | None:
    if not value or "\\" in value or value.startswith("/") or _DRIVE_RE.match(value):
        return None
    try:
        return _exact_relative_path(value, field_name="target link").as_posix()
    except DistributionManifestError:
        return None


def _generated_link_target_is_within_root(path: str, target: str) -> bool:
    if not target or "\\" in target or target.startswith("/") or _DRIVE_RE.match(target):
        return False
    parts: list[str] = list(PurePosixPath(path).parent.parts)
    for component in PurePosixPath(target).parts:
        if component in {"", "."}:
            continue
        if component == "..":
            if not parts:
                return False
            parts.pop()
            continue
        parts.append(component)
    return bool(parts)


def _normalized_link_target_for_path(path: str, target: str) -> str | None:
    normalized = _normalized_link_target(target)
    if normalized is not None:
        return normalized
    return target if _generated_link_target_is_within_root(path, target) else None


def _file_type(mode: int) -> str:
    if stat.S_ISREG(mode):
        return "regular"
    if stat.S_ISDIR(mode):
        return "directory"
    if stat.S_ISLNK(mode):
        return "symlink"
    return "special"


def _missing_snapshot(relative_path: str) -> PathIdentitySnapshot:
    return PathIdentitySnapshot(relative_path=relative_path, exists=False)


def _snapshot_from_stat(
    relative_path: str,
    info: os.stat_result,
    *,
    identity: DistributionIdentity | None = None,
) -> PathIdentitySnapshot:
    return PathIdentitySnapshot(
        relative_path=relative_path,
        exists=True,
        device=info.st_dev,
        inode=info.st_ino,
        ctime_ns=info.st_ctime_ns,
        file_type=_file_type(info.st_mode),
        link_count=info.st_nlink,
        mode=stat.S_IMODE(info.st_mode),
        size=info.st_size if stat.S_ISREG(info.st_mode) else None,
        identity=identity,
    )


def _target_snapshot(
    root: PathIdentitySnapshot,
    parents: list[PathIdentitySnapshot],
    target: PathIdentitySnapshot,
) -> DistributionTargetSnapshot:
    return DistributionTargetSnapshot(root=root, parents=tuple(parents), target=target)


def _same_observed_node(before: os.stat_result, after: os.stat_result) -> bool:
    return (
        before.st_dev == after.st_dev
        and before.st_ino == after.st_ino
        and before.st_ctime_ns == after.st_ctime_ns
        and stat.S_IFMT(before.st_mode) == stat.S_IFMT(after.st_mode)
        and stat.S_IMODE(before.st_mode) == stat.S_IMODE(after.st_mode)
    )


def _digest_open_file(fd: int) -> str:
    digest = hashlib.sha256()
    while True:
        chunk = os.read(fd, 1024 * 1024)
        if not chunk:
            return digest.hexdigest()
        digest.update(chunk)


def _observe_target(target_root: Path, relative_path: str) -> _TargetObservation:
    """Inspect one target through held directory descriptors without following links."""

    try:
        root_stat = os.lstat(target_root)
    except FileNotFoundError:
        return _TargetObservation(
            "missing",
            snapshot=_target_snapshot(
                _missing_snapshot("."),
                [],
                _missing_snapshot(relative_path),
            ),
        )
    except OSError:
        return _TargetObservation("root-error")
    root_snapshot = _snapshot_from_stat(".", root_stat)
    if stat.S_ISLNK(root_stat.st_mode):
        return _TargetObservation(
            "root-symlink",
            snapshot=_target_snapshot(root_snapshot, [], _missing_snapshot(relative_path)),
        )
    if not stat.S_ISDIR(root_stat.st_mode):
        return _TargetObservation(
            "root-non-directory",
            snapshot=_target_snapshot(root_snapshot, [], _missing_snapshot(relative_path)),
        )

    directory_flags = os.O_RDONLY | getattr(os, "O_DIRECTORY", 0) | getattr(os, "O_NOFOLLOW", 0)
    file_flags = os.O_RDONLY | getattr(os, "O_NOFOLLOW", 0)
    try:
        parent_fd = os.open(target_root, directory_flags)
        opened_root = os.fstat(parent_fd)
    except OSError:
        return _TargetObservation(
            "root-error",
            snapshot=_target_snapshot(root_snapshot, [], _missing_snapshot(relative_path)),
        )
    if not _same_observed_node(root_stat, opened_root):
        os.close(parent_fd)
        return _TargetObservation(
            "root-error",
            snapshot=_target_snapshot(root_snapshot, [], _missing_snapshot(relative_path)),
        )

    parts = PurePosixPath(relative_path).parts
    parents: list[PathIdentitySnapshot] = []
    parent_parts: list[str] = []
    missing_parent = False
    try:
        for component in parts[:-1]:
            parent_parts.append(component)
            parent_relative = "/".join(parent_parts)
            if missing_parent:
                parents.append(_missing_snapshot(parent_relative))
                continue
            try:
                component_stat = os.stat(component, dir_fd=parent_fd, follow_symlinks=False)
            except FileNotFoundError:
                parents.append(_missing_snapshot(parent_relative))
                missing_parent = True
                continue
            except OSError:
                return _TargetObservation(
                    "parent-error",
                    snapshot=_target_snapshot(root_snapshot, parents, _missing_snapshot(relative_path)),
                )
            component_snapshot = _snapshot_from_stat(parent_relative, component_stat)
            parents.append(component_snapshot)
            if stat.S_ISLNK(component_stat.st_mode):
                return _TargetObservation(
                    "symlink-container",
                    snapshot=_target_snapshot(root_snapshot, parents, _missing_snapshot(relative_path)),
                )
            if not stat.S_ISDIR(component_stat.st_mode):
                return _TargetObservation(
                    "non-directory-container",
                    snapshot=_target_snapshot(root_snapshot, parents, _missing_snapshot(relative_path)),
                )
            try:
                next_fd = os.open(component, directory_flags, dir_fd=parent_fd)
                opened_component = os.fstat(next_fd)
            except OSError:
                return _TargetObservation(
                    "parent-error",
                    snapshot=_target_snapshot(root_snapshot, parents, _missing_snapshot(relative_path)),
                )
            if not _same_observed_node(component_stat, opened_component):
                os.close(next_fd)
                return _TargetObservation(
                    "parent-error",
                    snapshot=_target_snapshot(root_snapshot, parents, _missing_snapshot(relative_path)),
                )
            os.close(parent_fd)
            parent_fd = next_fd

        if missing_parent:
            return _TargetObservation(
                "missing",
                snapshot=_target_snapshot(root_snapshot, parents, _missing_snapshot(relative_path)),
            )

        exact_name = parts[-1]
        try:
            exact_stat = os.stat(exact_name, dir_fd=parent_fd, follow_symlinks=False)
        except FileNotFoundError:
            return _TargetObservation(
                "missing",
                snapshot=_target_snapshot(root_snapshot, parents, _missing_snapshot(relative_path)),
            )
        except OSError:
            return _TargetObservation(
                "target-error",
                snapshot=_target_snapshot(root_snapshot, parents, _missing_snapshot(relative_path)),
            )

        if stat.S_ISLNK(exact_stat.st_mode):
            try:
                link_target = _normalized_link_target_for_path(
                    relative_path,
                    str(os.readlink(exact_name, dir_fd=parent_fd)),
                )
                after_link = os.stat(exact_name, dir_fd=parent_fd, follow_symlinks=False)
            except OSError:
                link_target = None
                after_link = exact_stat
            if not _same_observed_node(exact_stat, after_link):
                return _TargetObservation(
                    "target-error",
                    snapshot=_target_snapshot(root_snapshot, parents, _snapshot_from_stat(relative_path, exact_stat)),
                )
            identity = DistributionIdentity(kind="symlink", target=link_target)
            return _TargetObservation(
                "symlink",
                identity,
                exact_stat.st_nlink,
                _target_snapshot(
                    root_snapshot,
                    parents,
                    _snapshot_from_stat(relative_path, exact_stat, identity=identity),
                ),
            )
        if stat.S_ISREG(exact_stat.st_mode):
            file_fd: int | None = None
            try:
                file_fd = os.open(exact_name, file_flags, dir_fd=parent_fd)
                opened_file = os.fstat(file_fd)
                if not _same_observed_node(exact_stat, opened_file) or not stat.S_ISREG(opened_file.st_mode):
                    raise OSError(errno.ESTALE, "managed target identity changed")
                digest = _digest_open_file(file_fd)
                after_read = os.fstat(file_fd)
                if not _same_observed_node(opened_file, after_read):
                    raise OSError(errno.ESTALE, "managed target identity changed")
            except OSError:
                return _TargetObservation(
                    "target-error",
                    snapshot=_target_snapshot(root_snapshot, parents, _snapshot_from_stat(relative_path, exact_stat)),
                )
            finally:
                if file_fd is not None:
                    os.close(file_fd)
            identity = DistributionIdentity(
                kind="regular",
                sha256=digest,
                mode=stat.S_IMODE(opened_file.st_mode),
            )
            return _TargetObservation(
                "regular",
                identity,
                opened_file.st_nlink,
                _target_snapshot(
                    root_snapshot,
                    parents,
                    _snapshot_from_stat(relative_path, opened_file, identity=identity),
                ),
            )
        if stat.S_ISDIR(exact_stat.st_mode):
            return _TargetObservation(
                "directory",
                link_count=exact_stat.st_nlink,
                snapshot=_target_snapshot(root_snapshot, parents, _snapshot_from_stat(relative_path, exact_stat)),
            )
        return _TargetObservation(
            "special",
            link_count=exact_stat.st_nlink,
            snapshot=_target_snapshot(root_snapshot, parents, _snapshot_from_stat(relative_path, exact_stat)),
        )
    finally:
        os.close(parent_fd)


_DEPROVISION_ACTIVE_LAYERS = ("initiative", "epic", "issue")
_DEPROVISION_AGENT_CURRENT_FILES = frozenset({
    "active.json",
    "index-all.json",
    "tree-all.json",
    "index.json",
    "tree.json",
    "deps-issues.json",
})
_DEPROVISION_ACTIVE_LEGACY_FILES = frozenset({"current-runbook.json", "current-runbook.md"})
_DEPROVISION_AGENT_LEGACY_FILES = frozenset({"deps.json", "deps.puml", "deps.todo.puml"})
_DEPROVISION_GENERATED_CURRENT_SLOTS = tuple(
    sorted({
        *(f"spec-dock/active/{layer}" for layer in _DEPROVISION_ACTIVE_LAYERS),
        *(f"spec-dock/active/{layer}.path" for layer in _DEPROVISION_ACTIVE_LAYERS),
        "spec-dock/active/context-pack.md",
        *(f"spec-dock/.agent/{name}" for name in _DEPROVISION_AGENT_CURRENT_FILES),
    })
)
_SECOND_PRECISION_OFFSET_RE = re.compile(
    r"^[0-9]{4}-[0-9]{2}-[0-9]{2}T[0-9]{2}:[0-9]{2}:[0-9]{2}[+-][0-9]{2}:[0-9]{2}$"
)
_ACTIVE_LAYER_ID_RE = {
    "initiative": re.compile(r"^init(?:-local)?-[0-9]+$"),
    "epic": re.compile(r"^epic(?:-local)?-[0-9]+$"),
    "issue": re.compile(r"^iss(?:-local)?-[0-9]+$"),
}


def _render_context_pack(
    *,
    initiative_id: str | None,
    epic_id: str | None,
    issue_id: str | None,
) -> str:
    """Render the provider-side context pack shared by all installer producers."""

    has_init = initiative_id is not None
    has_epic = epic_id is not None
    has_issue = issue_id is not None
    lines = [
        "# Context Pack (generated)",
        "",
        "## Active",
        f"- initiative: {initiative_id if has_init else '(none)'}",
        f"- epic: {epic_id if has_epic else '(none)'}",
        f"- issue: {issue_id if has_issue else '(none)'}",
        "",
        "## Generated state",
        "- entry: `spec-dock/.agent/active.json`",
        "- default working set: `spec-dock/.agent/index.json`",
        "- default dependency view: `spec-dock/.agent/deps-issues.json`",
        "- escalation only: `spec-dock/.agent/index-all.json`",
        "- human-oriented tree: `spec-dock/.agent/tree.json`",
        "",
        "## Read order",
        "- Start with `spec-dock/.agent/active.json`.",
        "- For normal work, read `spec-dock/.agent/index.json` and `spec-dock/.agent/deps-issues.json`.",
        "- Read `spec-dock/.agent/index-all.json` only when full-history context is needed.",
        "- `spec-dock/active/context-pack.md` is human guidance that mirrors this contract; it is not the sole source of truth.",
        "- Then follow the active documents:",
    ]
    if has_init:
        lines.extend([
            "- `spec-dock/active/initiative/requirement.md`",
            "- `spec-dock/active/initiative/design.md`",
            "- `spec-dock/active/initiative/plan.md`",
        ])
    else:
        lines.append("- `spec-dock/active/initiative/README.md`")
    if has_epic:
        lines.extend([
            "- `spec-dock/active/epic/requirement.md`",
            "- `spec-dock/active/epic/design.md`",
            "- `spec-dock/active/epic/plan.md`",
        ])
    else:
        lines.append("- `spec-dock/active/epic/README.md`")
    if has_issue:
        lines.extend([
            "- `spec-dock/active/issue/requirement.md`",
            "- `spec-dock/active/issue/design.md`",
            "- `spec-dock/active/issue/plan.md`",
            "- `spec-dock/active/issue/report.md`",
        ])
    else:
        lines.append("- `spec-dock/active/issue/README.md`")
    lines.extend([
        "",
        "## Commands",
        "- state (github default): `./spec-dock/scripts/spec-dock sync`",
        "- state (cache/local opt-out): `./spec-dock/scripts/spec-dock sync --no-github`",
        "- validate: `./spec-dock/scripts/spec-dock validate`",
        "",
    ])
    return "\n".join(lines) + "\n"


def _generated_state_blocker(path: str, reason: str) -> DistributionAction:
    return DistributionAction(
        path=path,
        operation="uninstall",
        action="block",
        provenance="unknown",
        reason=reason,
        blocked=True,
    )


def _list_generated_root(target_root: Path, relative_root: str) -> tuple[tuple[str, ...] | None, str | None]:
    """List one generated root through a no-follow descriptor."""

    root_path = target_root / relative_root
    try:
        visible = os.lstat(root_path)
    except FileNotFoundError:
        return (), None
    except OSError:
        return None, "generated-state-root-unreadable"
    if stat.S_ISLNK(visible.st_mode) or not stat.S_ISDIR(visible.st_mode):
        return None, "generated-state-root-unsafe"
    nofollow = getattr(os, "O_NOFOLLOW", None)
    directory = getattr(os, "O_DIRECTORY", None)
    if not isinstance(nofollow, int) or not isinstance(directory, int):
        return None, "platform-capability-unavailable"
    fd: int | None = None
    try:
        fd = os.open(root_path, os.O_RDONLY | nofollow | directory | getattr(os, "O_CLOEXEC", 0))
        held = os.fstat(fd)
        if not _same_observed_node(visible, held):
            return None, "generated-state-root-rebound"
        names = tuple(sorted(os.listdir(fd)))  # noqa: PTH208 - descriptor-bound listing
        after = os.fstat(fd)
        if not _same_observed_node(held, after):
            return None, "generated-state-root-rebound"
        return names, None
    except OSError:
        return None, "generated-state-root-unreadable"
    finally:
        if fd is not None:
            os.close(fd)


def _generated_entry(
    target_root: Path,
    path: str,
    *,
    origin: GeneratedStateOrigin,
    expected_kind: Literal["regular", "symlink"],
    semantic_contract: str,
) -> DistributionGeneratedStateEntry | None:
    observation = _observe_target(target_root, path)
    if (
        observation.state != expected_kind
        or observation.identity is None
        or observation.link_count != 1
        or observation.snapshot is None
        or not observation.snapshot.target.exists
    ):
        return None
    return DistributionGeneratedStateEntry(
        path=path,
        origin=origin,
        expected_kind=expected_kind,
        identity=observation.identity,
        observed=observation.snapshot.target,
        semantic_contract=semantic_contract,
    )


def _read_generated_regular_bytes(
    target_root: Path,
    path: str,
) -> tuple[bytes, DistributionGeneratedStateEntry] | None:
    entry = _generated_entry(
        target_root,
        path,
        origin="current-agent-producer" if path.startswith("spec-dock/.agent/") else "current-active-producer",
        expected_kind="regular",
        semantic_contract="generated-regular-v1",
    )
    if entry is None:
        return None
    nofollow = getattr(os, "O_NOFOLLOW", None)
    if not isinstance(nofollow, int):
        return None
    parent_fds: tuple[int, ...] = ()
    file_fd: int | None = None
    try:
        parent_fds = _open_distribution_parent_chain(target_root, path)
        file_fd = os.open(
            PurePosixPath(path).name,
            os.O_RDONLY | nofollow | getattr(os, "O_CLOEXEC", 0),
            dir_fd=parent_fds[-1],
        )
        _assert_regular_fd_safe(file_fd, entry.observed, path, exact=True)
        before = os.fstat(file_fd)
        if stat.S_IMODE(before.st_mode) != entry.observed.mode or before.st_size != entry.observed.size:
            return None
        raw = _read_fd_bytes(file_fd)
        after = os.fstat(file_fd)
        visible = os.stat(
            PurePosixPath(path).name,
            dir_fd=parent_fds[-1],
            follow_symlinks=False,
        )
        if (
            _stat_identity_tuple(before) != _stat_identity_tuple(after)
            or not _same_stat_identity(visible, entry.observed)
            or stat.S_IMODE(visible.st_mode) != entry.observed.mode
            or visible.st_size != entry.observed.size
        ):
            return None
    except (DistributionApplyError, OSError):
        return None
    finally:
        if file_fd is not None:
            os.close(file_fd)
        _close_distribution_parent_chain(parent_fds)
    if hashlib.sha256(raw).hexdigest() != entry.identity.sha256:
        return None
    return raw, entry


def _canonical_active_path(target_root: Path, layer: str, entry: object) -> tuple[str, str] | None:
    if not isinstance(entry, dict) or set(entry) != {"id", "path"}:
        return None
    node_id = entry.get("id")
    path = entry.get("path")
    if (
        not isinstance(node_id, str)
        or _ACTIVE_LAYER_ID_RE[layer].fullmatch(node_id) is None
        or not isinstance(path, str)
    ):
        return None
    try:
        normalized = _exact_relative_path(path, field_name="active manifest path").as_posix()
    except DistributionManifestError:
        return None
    if normalized != path or not path.startswith("spec-dock/initiatives/"):
        return None
    node_path = target_root / path
    try:
        node_info = os.lstat(node_path)
    except OSError:
        return None
    if stat.S_ISLNK(node_info.st_mode) or not stat.S_ISDIR(node_info.st_mode):
        return None
    meta = _read_generated_regular_bytes(target_root, f"{path}/.meta.json")
    if meta is None:
        return None
    try:
        payload = json.loads(meta[0].decode("utf-8"))
    except (UnicodeDecodeError, json.JSONDecodeError):
        return None
    if (
        not isinstance(payload, dict)
        or payload.get("id") != node_id
        or payload.get("type", payload.get("kind")) != layer
    ):
        return None
    return node_id, path


def _active_selection_from_recovery_pointers(
    target_root: Path,
    journal: OperationJournal,
) -> dict[str, tuple[str, str] | None] | None:
    """Reconstruct active selection from immutable journal witnesses.

    A pending target may already be absent after its namespace mutation but
    before its checkpoint.  In that window the journal witness remains the
    only trusted representation of the selection; the current filesystem is
    consulted only for still-pending identities and parent bindings.
    """

    witnesses = journal.active_selection_witnesses
    if tuple(witness.layer for witness in witnesses) != _DEPROVISION_ACTIVE_LAYERS:
        return None
    records = {record.path: record for record in journal.actions}
    selection: dict[str, tuple[str, str] | None] = {}
    for layer, witness in zip(_DEPROVISION_ACTIVE_LAYERS, witnesses, strict=True):
        pointer_path = f"spec-dock/active/{layer}"
        path_path = f"{pointer_path}.path"
        candidate_paths = (pointer_path, path_path)
        action_records = [record for candidate in candidate_paths if (record := records.get(candidate)) is not None]
        if len(action_records) > 1:
            return None
        selected = witness.selection
        if (
            selected is not None
            and _canonical_active_path(
                target_root,
                layer,
                {"id": selected[0], "path": selected[1]},
            )
            != selected
        ):
            return None
        selection[layer] = selected

        if witness.representation == "absent":
            if action_records:
                return None
            for candidate in candidate_paths:
                if _observe_target(target_root, candidate).state != "missing":
                    return None
            continue

        expected_path = pointer_path if witness.representation == "symlink" else path_path
        if len(action_records) != 1 or action_records[0].path != expected_path:
            return None
        record = action_records[0]
        if (
            record.action != "prune"
            or record.provenance != "current"
            or record.reason != "current-identity-match"
            or record.checkpoint not in {"pending", "published", "verified"}
        ):
            return None
        expected_identity = _deprovision_recovery_record_identity(record)
        expected_kind = "symlink" if witness.representation == "symlink" else "regular"
        if expected_identity.kind != expected_kind:
            return None
        expected_target = selected[1] if selected is not None else f"spec-dock/system/active-none/{layer}"
        if witness.target is None or _lexical_generated_target(expected_path, witness.target) != expected_target:
            return None
        if record.checkpoint == "pending":
            observation = _observe_target(target_root, expected_path)
            if observation.snapshot is None:
                return None
            if not observation.snapshot.target.exists:
                if not _deprovision_pending_snapshot_is_exact_absence(observation.snapshot, record):
                    return None
            else:
                if (
                    observation.state != expected_kind
                    or observation.identity is None
                    or not _deprovision_recovery_identity_matches(observation.identity, expected_identity)
                ):
                    return None
                if witness.representation == "symlink":
                    if observation.identity.target != witness.target:
                        return None
                else:
                    loaded = _read_generated_regular_bytes(target_root, expected_path)
                    if loaded is None:
                        return None
                    try:
                        raw = loaded[0].decode("utf-8")
                    except UnicodeDecodeError:
                        return None
                    line_target = raw[:-1] if raw.endswith("\n") and "\n" not in raw[:-1] else None
                    if line_target != witness.target:
                        return None

        # A paired pointer/path slot is never valid.  For published records,
        # do not reopen the counterpart: the checkpoint is the durable proof
        # that this generated subtree was already consumed.
        if record.checkpoint == "pending":
            counterpart = path_path if expected_path == pointer_path else pointer_path
            if _observe_target(target_root, counterpart).state != "missing":
                return None
    if selection["issue"] is not None and (selection["epic"] is None or selection["initiative"] is None):
        return None
    if selection["epic"] is not None and selection["initiative"] is None:
        return None
    if (
        selection["epic"] is not None
        and selection["initiative"] is not None
        and PurePosixPath(selection["epic"][1]).parent.parent != PurePosixPath(selection["initiative"][1])
    ):
        return None
    if (
        selection["issue"] is not None
        and selection["epic"] is not None
        and PurePosixPath(selection["issue"][1]).parent.parent != PurePosixPath(selection["epic"][1])
    ):
        return None
    return selection


def _active_selection_from_manifest(
    target_root: Path,
    *,
    recovery_journal: OperationJournal | None = None,
) -> tuple[dict[str, tuple[str, str] | None] | None, DistributionGeneratedStateEntry | None]:
    path = "spec-dock/.agent/active.json"
    active_record = (
        next(
            (item for item in recovery_journal.actions if item.path == path),
            None,
        )
        if recovery_journal is not None
        else None
    )
    recovered_selection: dict[str, tuple[str, str] | None] | None = None
    if recovery_journal is not None:
        recovered_selection = _active_selection_from_recovery_pointers(target_root, recovery_journal)
        if recovered_selection is None:
            return None, None
    if active_record is not None and active_record.checkpoint in {"published", "verified"}:
        if (
            active_record.action != "prune"
            or active_record.provenance != "current"
            or active_record.reason != "current-identity-match"
            or _deprovision_recovery_record_identity(active_record).kind != "regular"
        ):
            return None, None
        assert recovered_selection is not None
        return recovered_selection, None
    observation = _observe_target(target_root, path)
    if observation.state == "missing":
        if recovered_selection is not None:
            return recovered_selection, None
        return dict.fromkeys(_DEPROVISION_ACTIVE_LAYERS), None
    loaded = _read_generated_regular_bytes(target_root, path)
    if loaded is None:
        return None, None
    raw, entry = loaded
    try:
        payload = json.loads(raw.decode("utf-8"))
    except (UnicodeDecodeError, json.JSONDecodeError):
        return None, None
    if not isinstance(payload, dict) or set(payload) != {
        "schema_version",
        "updated_at",
        "initiative",
        "epic",
        "issue",
    }:
        return None, None
    updated_at = payload.get("updated_at")
    if (
        payload.get("schema_version") != 2
        or not isinstance(updated_at, str)
        or _SECOND_PRECISION_OFFSET_RE.fullmatch(updated_at) is None
    ):
        return None, None
    try:
        if datetime.fromisoformat(updated_at).utcoffset() is None:
            return None, None
    except ValueError:
        return None, None
    selection: dict[str, tuple[str, str] | None] = {}
    for layer in _DEPROVISION_ACTIVE_LAYERS:
        value = payload[layer]
        if value is None:
            selection[layer] = None
            continue
        normalized = _canonical_active_path(target_root, layer, value)
        if normalized is None:
            return None, None
        selection[layer] = normalized
    if selection["issue"] is not None and (selection["epic"] is None or selection["initiative"] is None):
        return None, None
    if selection["epic"] is not None and selection["initiative"] is None:
        return None, None
    if (
        selection["epic"] is not None
        and selection["initiative"] is not None
        and PurePosixPath(selection["epic"][1]).parent.parent != PurePosixPath(selection["initiative"][1])
    ):
        return None, None
    if (
        selection["issue"] is not None
        and selection["epic"] is not None
        and PurePosixPath(selection["issue"][1]).parent.parent != PurePosixPath(selection["epic"][1])
    ):
        return None, None
    if recovered_selection is not None and selection != recovered_selection:
        return None, None
    return selection, replace(entry, semantic_contract="active-manifest-schema-2")


def _lexical_generated_target(path: str, target: str) -> str | None:
    if not target or "\\" in target or target.startswith("/") or _DRIVE_RE.match(target):
        return None
    parts = list(PurePosixPath(path).parent.parts)
    for component in PurePosixPath(target).parts:
        if component in {"", "."}:
            continue
        if component == "..":
            if not parts:
                return None
            parts.pop()
        else:
            parts.append(component)
    if not parts:
        return None
    normalized = PurePosixPath(*parts).as_posix()
    return normalized if not normalized.startswith("../") else None


def _deprovision_recovery_generated_entry(
    record: OperationJournalAction,
) -> DistributionGeneratedStateEntry:
    """Reconstruct one published generated entry from its journal witness."""

    if (
        record.action != "prune"
        or record.provenance != "current"
        or record.reason != "current-identity-match"
        or record.path not in _DEPROVISION_GENERATED_CURRENT_SLOTS
    ):
        raise DistributionApplyError("journal-plan-mismatch")
    if record.path.startswith("spec-dock/active/"):
        name = record.path.removeprefix("spec-dock/active/")
        origin: GeneratedStateOrigin = "current-active-producer"
        if name == "context-pack.md":
            expected_kind: Literal["regular", "symlink"] = "regular"
            semantic_contract = "context-pack-v1"
        elif name in _DEPROVISION_ACTIVE_LAYERS:
            expected_kind = "symlink"
            semantic_contract = f"active-{name}-pointer-v1"
        elif name in {f"{layer}.path" for layer in _DEPROVISION_ACTIVE_LAYERS}:
            expected_kind = "regular"
            semantic_contract = f"active-{name.removesuffix('.path')}-path-v1"
        else:
            raise DistributionApplyError("journal-plan-mismatch")
    else:
        name = record.path.removeprefix("spec-dock/.agent/")
        if name not in _DEPROVISION_AGENT_CURRENT_FILES:
            raise DistributionApplyError("journal-plan-mismatch")
        origin = "current-agent-producer"
        expected_kind = "regular"
        semantic_contract = f"{name}-schema-2" if name != "active.json" else "active-manifest-schema-2"

    precondition = record.precondition
    if precondition.get("exists") is not True or precondition.get("file_type") != expected_kind:
        raise DistributionApplyError("journal-plan-mismatch")
    identity = _deprovision_recovery_record_identity(record)
    if identity.kind != expected_kind:
        raise DistributionApplyError("journal-plan-mismatch")
    structural_fields = ("device", "inode", "ctime_ns", "link_count", "mode")
    if any(
        not isinstance(precondition.get(field), int) or isinstance(precondition.get(field), bool)
        for field in structural_fields
    ):
        raise DistributionApplyError("journal-plan-mismatch")
    size = precondition.get("size")
    if expected_kind == "regular":
        if not isinstance(size, int) or isinstance(size, bool) or size < 0:
            raise DistributionApplyError("journal-plan-mismatch")
        if identity.mode != precondition.get("mode"):
            raise DistributionApplyError("journal-plan-mismatch")
    elif size is not None:
        raise DistributionApplyError("journal-plan-mismatch")
    observed = PathIdentitySnapshot(
        relative_path=record.path,
        exists=True,
        device=cast("int", precondition["device"]),
        inode=cast("int", precondition["inode"]),
        ctime_ns=cast("int", precondition["ctime_ns"]),
        file_type=expected_kind,
        link_count=cast("int", precondition["link_count"]),
        mode=cast("int", precondition["mode"]),
        size=cast("int | None", size),
        identity=identity,
    )
    return DistributionGeneratedStateEntry(
        path=record.path,
        origin=origin,
        expected_kind=expected_kind,
        identity=identity,
        observed=observed,
        semantic_contract=semantic_contract,
    )


def _generated_contract_digest(
    entries: tuple[DistributionGeneratedStateEntry, ...],
    legacy_paths: tuple[str, ...],
    blockers: tuple[DistributionAction, ...],
    active_selection_witnesses: tuple[DistributionActiveSelectionWitness, ...] = (),
) -> str:
    payload = {
        "format_version": 1,
        "entries": [
            {
                "path": entry.path,
                "origin": entry.origin,
                "expected_kind": entry.expected_kind,
                "identity": _distribution_identity_payload(entry.identity),
                "observed": _path_snapshot_condition(entry.observed),
                "semantic_contract": entry.semantic_contract,
            }
            for entry in entries
        ],
        "current_slots": list(_DEPROVISION_GENERATED_CURRENT_SLOTS),
        "legacy_unproven_paths": list(legacy_paths),
        "blockers": [action.diagnostic() for action in blockers],
        "active_selection_witnesses": [
            _active_selection_witness_payload(witness) for witness in active_selection_witnesses
        ],
    }
    return hashlib.sha256(json.dumps(payload, sort_keys=True, separators=(",", ":")).encode("utf-8")).hexdigest()


def _valid_generated_timestamp(value: object) -> bool:
    if not isinstance(value, str) or _SECOND_PRECISION_OFFSET_RE.fullmatch(value) is None:
        return False
    try:
        return datetime.fromisoformat(value).utcoffset() is not None
    except ValueError:
        return False


def _artifact_active_selection(
    selection: dict[str, tuple[str, str] | None],
) -> dict[str, object] | None:
    if all(selection[layer] is None for layer in _DEPROVISION_ACTIVE_LAYERS):
        return None
    active: dict[str, object] = {}
    for layer in _DEPROVISION_ACTIVE_LAYERS:
        selected = selection[layer]
        active[layer] = {"id": selected[0]} if selected is not None else None
    return active


def _flatten_tree_node_ids(tree: object) -> frozenset[str] | None:
    if not isinstance(tree, list):
        return None
    node_ids: set[str] = set()

    def add(item: object) -> bool:
        if not isinstance(item, dict) or not isinstance(item.get("id"), str) or not item["id"]:
            return False
        node_id = cast("str", item["id"])
        if node_id in node_ids:
            return False
        node_ids.add(node_id)
        return True

    for initiative in tree:
        if not add(initiative):
            return None
        assert isinstance(initiative, dict)
        epics = initiative.get("epics")
        if not isinstance(epics, list):
            return None
        for epic in epics:
            if not add(epic):
                return None
            assert isinstance(epic, dict)
            issues = epic.get("issues")
            if not isinstance(issues, list):
                return None
            if not all(add(issue) for issue in issues):
                return None
    return frozenset(node_ids)


_GENERATED_NODE_BASE_FIELDS = frozenset({
    "id",
    "type",
    "title",
    "path",
    "document_surfaces",
    "parent_id",
    "initiative_id",
    "epic_id",
    "children",
})
_GENERATED_ISSUE_FIELDS = frozenset({
    "status",
    "authority",
    "effective_status",
    "source",
    "stale",
    "last_sync_at",
    "deps",
})
_GENERATED_DEPENDENCY_SUMMARY_FIELDS = frozenset({
    "valid",
    "error",
    "issue_edges",
    "edge_direction",
})
_GENERATED_DEPENDENCY_EDGE_DIRECTION = "depends_on (dependent -> prerequisite)"
_GENERATED_NODE_KINDS = frozenset({"initiative", "epic", "issue"})


def _valid_generated_relative_path(value: object, *, prefix: str = "spec-dock/") -> bool:
    if not isinstance(value, str) or not value.startswith(prefix) or value.startswith("/"):
        return False
    parts = PurePosixPath(value).parts
    return bool(parts) and all(part not in {"", ".", ".."} for part in parts)


def _valid_generated_active(value: object) -> bool:
    if value is None:
        return True
    if not isinstance(value, dict) or set(value) != set(_DEPROVISION_ACTIVE_LAYERS):
        return False
    for layer in _DEPROVISION_ACTIVE_LAYERS:
        selected = value[layer]
        if selected is None:
            continue
        if not isinstance(selected, dict) or set(selected) != {"id"} or not isinstance(selected["id"], str):
            return False
        if _ACTIVE_LAYER_ID_RE[layer].fullmatch(selected["id"]) is None:
            return False
    return True


def _valid_generated_document_surfaces(value: object) -> bool:
    if not isinstance(value, dict) or set(value) != {"canonical_docs", "future_artifacts", "legacy_discussions"}:
        return False
    canonical_docs = value["canonical_docs"]
    if not isinstance(canonical_docs, list) or len(canonical_docs) != 4:
        return False
    expected_kinds = ("requirement", "design", "plan", "report")
    for document, expected_kind in zip(canonical_docs, expected_kinds, strict=True):
        if not isinstance(document, dict) or set(document) != {"kind", "path", "present"}:
            return False
        if document["kind"] != expected_kind:
            return False
        if not _valid_generated_relative_path(document["path"]):
            return False
        if not isinstance(document["present"], bool):
            return False
    for name in ("future_artifacts", "legacy_discussions"):
        surface = value[name]
        if not isinstance(surface, dict) or set(surface) != {"path", "present"}:
            return False
        if not _valid_generated_relative_path(surface["path"]):
            return False
        if not isinstance(surface["present"], bool):
            return False
    return True


def _valid_generated_progress(value: object) -> bool:
    if not isinstance(value, dict) or set(value) != {"total", "done", "open", "unknown"}:
        return False
    return all(isinstance(value[key], int) and not isinstance(value[key], bool) and value[key] >= 0 for key in value)


def _valid_generated_github(value: object) -> bool:
    if not isinstance(value, dict) or "issue_number" not in value:
        return False
    allowed = {"issue_number", "repo_owner", "repo_name", "state", "url", "updated_at", "labels"}
    if set(value) - allowed:
        return False
    if not isinstance(value["issue_number"], int) or isinstance(value["issue_number"], bool):
        return False
    for key in ("repo_owner", "repo_name", "state", "url", "updated_at"):
        if key in value and not isinstance(value[key], str):
            return False
    return "labels" not in value or (
        isinstance(value["labels"], list) and all(isinstance(label, str) for label in value["labels"])
    )


def _valid_generated_issue_deps(value: object, node_ids: set[str]) -> bool:
    if value is None:
        return True
    if not isinstance(value, dict) or set(value) != {"ready", "depends_on", "blockers_top"}:
        return False
    if not isinstance(value["ready"], bool):
        return False
    for key in ("depends_on", "blockers_top"):
        values = value[key]
        if not isinstance(values, list) or not all(isinstance(item, str) and item in node_ids for item in values):
            return False
    return len(set(value["depends_on"])) == len(value["depends_on"])


def _valid_generated_node_payload(
    node_id: str,
    payload: object,
    *,
    include_dependency_audit: bool,
    node_ids: set[str],
) -> bool:
    if not isinstance(payload, dict) or payload.get("id") != node_id:
        return False
    kind = payload.get("type")
    if kind not in _GENERATED_NODE_KINDS or not isinstance(kind, str):
        return False
    required = set(_GENERATED_NODE_BASE_FIELDS)
    allowed = set(required) | {"github"}
    if kind == "issue":
        required.update(_GENERATED_ISSUE_FIELDS)
        allowed.update(_GENERATED_ISSUE_FIELDS)
    else:
        allowed.add("progress")
    if include_dependency_audit:
        required.add("depends_on")
        allowed.add("depends_on")
    if set(payload) - allowed or required - set(payload):
        return False
    if not isinstance(payload["title"], str) or not _valid_generated_relative_path(
        payload["path"], prefix="spec-dock/"
    ):
        return False
    if not _valid_generated_document_surfaces(payload["document_surfaces"]):
        return False
    parent_id = payload["parent_id"]
    initiative_id = payload["initiative_id"]
    epic_id = payload["epic_id"]
    if any(
        value is not None and (not isinstance(value, str) or value not in node_ids)
        for value in (parent_id, initiative_id, epic_id)
    ):
        return False
    children = payload["children"]
    if not isinstance(children, list) or not all(isinstance(child, str) and child in node_ids for child in children):
        return False
    if len(set(children)) != len(children):
        return False
    if "github" in payload and not _valid_generated_github(payload["github"]):
        return False
    if kind == "issue":
        if any(not isinstance(payload[key], str) for key in ("status", "authority", "effective_status", "source")):
            return False
        if payload["status"] != payload["effective_status"]:
            return False
        if not isinstance(payload["stale"], bool) or (
            payload["last_sync_at"] is not None and not isinstance(payload["last_sync_at"], str)
        ):
            return False
        if not _valid_generated_issue_deps(payload["deps"], node_ids):
            return False
    elif "progress" in payload and not _valid_generated_progress(payload["progress"]):
        return False
    if include_dependency_audit:
        depends_on = payload["depends_on"]
        if not isinstance(depends_on, list) or not all(
            isinstance(item, str) and item in node_ids for item in depends_on
        ):
            return False
        if len(set(depends_on)) != len(depends_on):
            return False
    return True


def _valid_generated_dependency_summary(value: object, *, allow_issue_edges: bool = True) -> bool:
    if not isinstance(value, dict) or set(value) != _GENERATED_DEPENDENCY_SUMMARY_FIELDS:
        return False
    if not isinstance(value["valid"], bool) or (value["error"] is not None and not isinstance(value["error"], str)):
        return False
    if value["edge_direction"] != _GENERATED_DEPENDENCY_EDGE_DIRECTION:
        return False
    edges = value["issue_edges"]
    if not allow_issue_edges and edges != []:
        return False
    if not isinstance(edges, list):
        return False
    for edge in edges:
        if not isinstance(edge, dict) or set(edge) not in ({"from", "to"}, {"from", "to", "kind"}):
            return False
        if not isinstance(edge["from"], str) or not isinstance(edge["to"], str):
            return False
        if "kind" in edge and edge["kind"] != "depends_on":
            return False
    return True


def _valid_generated_projection_base(
    payload: dict[str, object],
    *,
    expected_fields: frozenset[str],
    projection: str | None,
) -> bool:
    if set(payload) != expected_fields:
        return False
    if payload.get("schema_version") != 2 or not _valid_generated_timestamp(payload.get("generated_at")):
        return False
    if not _valid_generated_active(payload.get("active")):
        return False
    warnings = payload.get("warnings")
    if not isinstance(warnings, list) or not all(isinstance(item, str) for item in warnings):
        return False
    if payload.get("root") != "spec-dock/initiatives":
        return False
    if projection is not None and payload.get("projection") != projection:
        return False
    if projection is None and "projection" in payload:
        return False
    return _valid_generated_dependency_summary(payload.get("deps"))


def _validate_generated_node_graph(nodes: Mapping[str, object], *, include_dependency_audit: bool) -> bool:
    node_ids = set(nodes)
    if not all(isinstance(node_id, str) for node_id in node_ids):
        return False
    if not all(
        _valid_generated_node_payload(
            node_id,
            payload,
            include_dependency_audit=include_dependency_audit,
            node_ids=node_ids,
        )
        for node_id, payload in nodes.items()
    ):
        return False
    child_parent: dict[str, str] = {}
    for node_id, payload in nodes.items():
        assert isinstance(payload, dict)
        kind = cast("str", payload["type"])
        parent_id = payload["parent_id"]
        if kind == "initiative" and (
            parent_id is not None or payload["initiative_id"] is not None or payload["epic_id"] is not None
        ):
            return False
        if kind == "epic" and (
            not isinstance(parent_id, str) or payload["initiative_id"] != parent_id or payload["epic_id"] is not None
        ):
            return False
        if kind == "issue" and (not isinstance(parent_id, str) or payload["epic_id"] != parent_id):
            return False
        for child_id in payload["children"]:
            if child_id == node_id or child_id in child_parent:
                return False
            child_parent[child_id] = node_id
    for node_id, payload in nodes.items():
        assert isinstance(payload, dict)
        if payload["parent_id"] != child_parent.get(node_id):
            return False
        if payload["type"] == "issue":
            parent_id = cast("str", payload["parent_id"])
            parent = nodes.get(parent_id)
            if not isinstance(parent, dict) or parent.get("type") != "epic":
                return False
            if payload["initiative_id"] != parent.get("initiative_id"):
                return False
        elif payload["type"] == "epic":
            parent_id = cast("str", payload["parent_id"])
            parent = nodes.get(parent_id)
            if not isinstance(parent, dict) or parent.get("type") != "initiative":
                return False
    return all(
        set(payload["children"]) == {child_id for child_id, parent_id in child_parent.items() if parent_id == node_id}
        for node_id, payload in nodes.items()
        if isinstance(payload, dict)
    )


def _validate_generated_tree(
    tree: object,
    nodes: dict[str, object] | None,
) -> frozenset[str] | None:
    if not isinstance(tree, list):
        return None
    flattened: dict[str, dict[str, object]] = {}

    def visit(item: object, expected_kind: str) -> bool:
        if not isinstance(item, dict) or not isinstance(item.get("id"), str):
            return False
        node_id = cast("str", item["id"])
        if node_id in flattened:
            return False
        nested_name = "epics" if expected_kind == "initiative" else "issues" if expected_kind == "epic" else None
        nested = item.get(nested_name) if nested_name is not None else None
        if expected_kind != "issue" and not isinstance(nested, list):
            return False
        if expected_kind == "issue" and ("epics" in item or "issues" in item):
            return False
        base = dict(item)
        if nested_name is not None:
            base.pop(nested_name, None)
        if base.get("type") != expected_kind or set(base) - (
            _GENERATED_NODE_BASE_FIELDS | _GENERATED_ISSUE_FIELDS | {"github", "progress"}
        ):
            return False
        if not isinstance(base.get("title"), str) or not _valid_generated_relative_path(base.get("path")):
            return False
        if not _valid_generated_document_surfaces(base.get("document_surfaces")):
            return False
        if not isinstance(base.get("parent_id"), (str, type(None))) or not isinstance(base.get("children"), list):
            return False
        flattened[node_id] = base
        if nested_name is not None:
            assert isinstance(nested, list)
            nested_items = cast("list[object]", nested)
            child_kind = "epic" if expected_kind == "initiative" else "issue"
            for child in nested_items:
                if not visit(child, child_kind):
                    return False
            child_ids = [cast("dict[str, object]", child)["id"] for child in nested_items if isinstance(child, dict)]
            if base.get("children") != child_ids:
                return False
        elif base.get("children") != []:
            return False
        return True

    if not all(visit(item, "initiative") for item in tree):
        return None
    if not all(
        _valid_generated_node_payload(
            node_id,
            payload,
            include_dependency_audit=False,
            node_ids=set(flattened),
        )
        for node_id, payload in flattened.items()
    ) or not _validate_generated_node_graph(flattened, include_dependency_audit=False):
        return None
    if nodes is None:
        return frozenset(flattened)
    include_dependency_audit = any(
        isinstance(expected, dict) and "depends_on" in expected for expected in nodes.values()
    )
    if set(flattened) != set(nodes) or not _validate_generated_node_graph(
        nodes,
        include_dependency_audit=include_dependency_audit,
    ):
        return None
    for node_id, expected in nodes.items():
        actual = flattened.get(node_id)
        if not isinstance(expected, dict) or actual is None:
            return None
        expected_without_audit = {key: value for key, value in expected.items() if key != "depends_on"}
        if actual != expected_without_audit:
            return None
    return frozenset(flattened)


def _validate_generated_projection_payload(
    name: str,
    payload: dict[str, object],
    *,
    expected_fields: frozenset[str],
    projection: str | None,
) -> frozenset[str] | None:
    if not _valid_generated_projection_base(payload, expected_fields=expected_fields, projection=projection):
        return None
    if name in {"index-all.json", "index.json"}:
        nodes = payload.get("nodes")
        if not isinstance(nodes, dict) or not _validate_generated_node_graph(
            nodes,
            include_dependency_audit=name == "index-all.json",
        ):
            return None
        if name == "index.json" and any(
            isinstance(node, dict)
            and node.get("type") == "issue"
            and isinstance(node.get("status"), str)
            and node["status"].lower() == "done"
            for node in nodes.values()
        ):
            return None
        edges = cast("dict[str, object]", payload["deps"])["issue_edges"]
        if not all(
            isinstance(edge, dict) and edge["from"] in nodes and edge["to"] in nodes
            for edge in cast("list[object]", edges)
        ):
            return None
        return frozenset(nodes)
    if name in {"tree-all.json", "tree.json"}:
        return _validate_generated_tree(payload.get("tree"), None)
    return None


def _generated_current_future_matches_full_history(
    full_history: dict[str, object],
    current_future: dict[str, object],
) -> bool:
    """Verify the current/future index is exactly the runtime producer view."""

    full_nodes = full_history.get("nodes")
    current_nodes = current_future.get("nodes")
    full_deps = full_history.get("deps")
    current_deps = current_future.get("deps")
    if (
        not isinstance(full_nodes, dict)
        or not isinstance(current_nodes, dict)
        or not isinstance(full_deps, dict)
        or not isinstance(current_deps, dict)
    ):
        return False
    todo_issue_ids = {
        node_id
        for node_id, payload in full_nodes.items()
        if isinstance(node_id, str)
        and isinstance(payload, dict)
        and payload.get("type") == "issue"
        and isinstance(payload.get("status"), str)
        and payload["status"].lower() != "done"
    }
    expected_ids = set(todo_issue_ids)
    pending = list(todo_issue_ids)
    while pending:
        node_id = pending.pop()
        payload = full_nodes.get(node_id)
        if not isinstance(payload, dict):
            return False
        parent_id = payload.get("parent_id")
        if parent_id is None:
            continue
        if not isinstance(parent_id, str) or parent_id not in full_nodes:
            return False
        if parent_id not in expected_ids:
            expected_ids.add(parent_id)
            pending.append(parent_id)
    if set(current_nodes) != expected_ids:
        return False
    for node_id in expected_ids:
        full_payload = full_nodes.get(node_id)
        current_payload = current_nodes.get(node_id)
        if not isinstance(full_payload, dict) or not isinstance(current_payload, dict):
            return False
        expected_payload = {key: value for key, value in full_payload.items() if key != "depends_on"}
        expected_payload["children"] = [
            child_id for child_id in cast("list[object]", full_payload.get("children", [])) if child_id in expected_ids
        ]
        if current_payload != expected_payload:
            return False
    full_edges = full_deps.get("issue_edges")
    current_edges = current_deps.get("issue_edges")
    if not isinstance(full_edges, list) or not isinstance(current_edges, list):
        return False
    expected_edges = [
        edge
        for edge in full_edges
        if isinstance(edge, dict) and edge.get("from") in todo_issue_ids and edge.get("to") in todo_issue_ids
    ]
    return current_deps == {**full_deps, "issue_edges": expected_edges}


def _generated_tree_matches_index(
    index_payload: dict[str, object],
    tree_payload: dict[str, object],
) -> bool:
    nodes = index_payload.get("nodes")
    if not isinstance(nodes, dict):
        return False
    if any(
        tree_payload.get(field) != index_payload.get(field)
        for field in ("schema_version", "generated_at", "active", "warnings", "root", "deps")
    ):
        return False
    return _validate_generated_tree(tree_payload.get("tree"), nodes) is not None


def _valid_deps_issue_context(value: object) -> bool:
    fields = {
        "source_node_id",
        "source_issue_id",
        "target_node_id",
        "target_node_kind",
        "target_issue_ids",
        "expansion",
        "lifecycle_state",
        "lifecycle_source",
        "dependency_disposition",
        "disposition_basis",
    }
    if not isinstance(value, dict) or set(value) != fields:
        return False
    if not all(
        isinstance(value[key], str)
        for key in ("source_node_id", "source_issue_id", "target_node_id", "target_node_kind", "expansion")
    ):
        return False
    if value["target_node_kind"] not in (*_GENERATED_NODE_KINDS, "unknown") or value["expansion"] not in {
        "issue",
        "expanded",
        "empty",
    }:
        return False
    if not isinstance(value["target_issue_ids"], list) or not all(
        isinstance(item, str) for item in value["target_issue_ids"]
    ):
        return False
    return all(
        value[key] is None or isinstance(value[key], str)
        for key in ("lifecycle_state", "lifecycle_source", "dependency_disposition", "disposition_basis")
    )


def _valid_deps_issue_node_blocker(value: object) -> bool:
    fields = {
        "node_id",
        "reason",
        "state",
        "state_source",
        "source_issue_id",
        "lifecycle_state",
        "lifecycle_source",
        "dependency_disposition",
        "disposition_basis",
    }
    if not isinstance(value, dict) or set(value) != fields:
        return False
    if not all(
        isinstance(value[key], str) for key in ("node_id", "reason", "state", "state_source", "source_issue_id")
    ):
        return False
    return all(
        value[key] is None or isinstance(value[key], str)
        for key in ("lifecycle_state", "lifecycle_source", "dependency_disposition", "disposition_basis")
    )


def _validate_deps_issues_payload(payload: dict[str, object]) -> bool:
    expected_fields = {
        "schema_version",
        "generated_at",
        "projection",
        "source",
        "deps",
        "nodes",
        "edges",
        "dependency_contexts",
        "edge_direction",
    }
    if set(payload) != expected_fields or payload.get("schema_version") != 2:
        return False
    if not _valid_generated_timestamp(payload.get("generated_at")):
        return False
    if payload.get("projection") != "issue-readiness-with-dependency-context":
        return False
    if payload.get("source") != {"sync_state": "readiness_evaluation", "schema_version": 2}:
        return False
    if payload.get("edge_direction") != _GENERATED_DEPENDENCY_EDGE_DIRECTION:
        return False
    deps = payload.get("deps")
    if not isinstance(deps, dict) or set(deps) != {"valid", "error"} or not isinstance(deps.get("valid"), bool):
        return False
    if deps["valid"]:
        if deps.get("error") is not None:
            return False
    elif (
        not isinstance(deps.get("error"), str)
        or payload.get("nodes") != {}
        or payload.get("edges") != []
        or payload.get("dependency_contexts") != []
    ):
        return False
    nodes = payload.get("nodes")
    if not isinstance(nodes, dict):
        return False
    for node_id, node in nodes.items():
        if not isinstance(node_id, str) or not isinstance(node, dict) or node.get("id") != node_id:
            return False
        kind = node.get("type")
        common = {"id", "type", "title", "parent_id", "initiative_id", "epic_id"}
        required = common | (
            {"state", "state_source", "ready"}
            if kind != "issue"
            else {
                "status",
                "authority",
                "effective_status",
                "source",
                "stale",
                "last_sync_at",
                "ready",
                "depends_on",
                "issue_blockers",
                "node_blockers",
                "state",
            }
        )
        if kind not in _GENERATED_NODE_KINDS or set(node) != required:
            return False
        if not isinstance(node["title"], str) or any(
            value is not None and not isinstance(value, str)
            for value in (node["parent_id"], node["initiative_id"], node["epic_id"])
        ):
            return False
        if not isinstance(node["ready"], bool) or not isinstance(node["state"], str):
            return False
        if kind == "issue":
            if any(not isinstance(node[key], str) for key in ("status", "authority", "effective_status", "source")):
                return False
            if node["status"] != node["effective_status"]:
                return False
            if not isinstance(node["stale"], bool) or (
                node["last_sync_at"] is not None and not isinstance(node["last_sync_at"], str)
            ):
                return False
            if not all(
                isinstance(node[key], list) and all(isinstance(item, str) for item in node[key])
                for key in ("depends_on", "issue_blockers")
            ):
                return False
            if not isinstance(node["node_blockers"], list) or not all(
                _valid_deps_issue_node_blocker(item) for item in node["node_blockers"]
            ):
                return False
        elif not isinstance(node["state_source"], str):
            return False
    edges = payload.get("edges")
    if not isinstance(edges, list) or not all(
        isinstance(edge, dict)
        and set(edge) == {"from", "to", "state", "relation", "source"}
        and all(isinstance(edge[key], str) for key in edge)
        and edge["from"] in nodes
        and edge["to"] in nodes
        for edge in edges
    ):
        return False
    contexts = payload.get("dependency_contexts")
    return isinstance(contexts, list) and all(_valid_deps_issue_context(item) for item in contexts)


def _deprovision_recovery_directory_is_published(
    journal: OperationJournal | None,
    path: str,
) -> bool:
    return journal is not None and any(
        record.path == path
        and record.action == "remove-empty-directory"
        and record.checkpoint in {"published", "verified"}
        for record in journal.actions
    )


def _deprovision_zero_predecessor_reservation_state(
    target_root: Path,
    journal: OperationJournal,
    lease: DistributionStageOwnership,
) -> Literal["owned", "reusable", "unknown"]:
    """Classify a zero-identity predecessor reservation conservatively.

    A zero-identity lease is a write-ahead reservation, not ownership of the
    pathname.  It is operation-owned only after the canonical target has been
    durably renamed away and the private entry matches the pending prune
    action's immutable physical and semantic precondition.  A reservation
    published immediately before that rename is reusable only when the
    canonical target is still the exact pending precondition and its reserved
    stage pathname is absent.
    """

    if lease.role != "predecessor-quarantine" or lease.device != 0 or lease.inode != 0 or lease.ctime_ns != 0:
        return "unknown"
    records = tuple(item for item in journal.actions if item.path == lease.path)
    if len(records) != 1:
        return "unknown"
    record = records[0]
    if record.action != "prune" or record.checkpoint != "pending":
        return "unknown"
    if lease.file_type != record.precondition.get("file_type"):
        return "unknown"
    try:
        canonical = _assert_deprovision_pending_record_matches(target_root, record)
    except DistributionApplyError:
        return "unknown"
    stage_path = (PurePosixPath(lease.path).parent / lease.stage_name).as_posix()
    stage = _observe_target(target_root, stage_path)
    if canonical.target.exists:
        if stage.state == "missing" and stage.snapshot is not None and not stage.snapshot.target.exists:
            return "reusable"
        return "unknown"
    if stage.snapshot is None or not stage.snapshot.target.exists or stage.state != lease.file_type:
        return "unknown"
    stage_target = stage.snapshot.target
    precondition = record.precondition
    if (
        stage_target.device != precondition.get("device")
        or stage_target.inode != precondition.get("inode")
        or stage_target.file_type != precondition.get("file_type")
        or stage_target.link_count != precondition.get("link_count")
        or stage_target.mode != precondition.get("mode")
        or stage.identity is None
        or precondition.get("identity") != _distribution_identity_payload(stage.identity)
    ):
        return "unknown"
    return "owned"


def _deprovision_zero_predecessor_reservation_is_owned(
    target_root: Path,
    journal: OperationJournal,
    lease: DistributionStageOwnership,
) -> bool:
    return _deprovision_zero_predecessor_reservation_state(target_root, journal, lease) == "owned"


def _assert_deprovision_zero_predecessor_reservations(
    target_root: Path,
    journal: OperationJournal,
) -> None:
    """Reject an unresolved zero lease before any recovery checkpoint write."""

    for lease in journal.staging_leases:
        if (
            lease.role == "predecessor-quarantine"
            and lease.device == 0
            and lease.inode == 0
            and lease.ctime_ns == 0
            and _deprovision_zero_predecessor_reservation_state(target_root, journal, lease) == "unknown"
        ):
            raise DistributionApplyError("journal-precondition-mismatch")


def _deprovision_recovery_stage_names(
    target_root: Path,
    journal: OperationJournal | None,
    relative_root: str,
    names: tuple[str, ...],
) -> tuple[str, ...]:
    """Return only exact journal-owned transition entries under one root."""

    if journal is None:
        return names
    owned: set[str] = set()
    for lease in journal.staging_leases:
        parent = PurePosixPath(lease.path).parent.as_posix()
        if parent != relative_root or lease.stage_name not in names:
            continue
        observation = _observe_target(target_root, f"{relative_root}/{lease.stage_name}")
        snapshot = observation.snapshot
        if snapshot is None or not snapshot.target.exists or observation.state != lease.file_type:
            continue
        target = snapshot.target
        if lease.device == lease.inode == lease.ctime_ns == 0:
            if _deprovision_zero_predecessor_reservation_is_owned(target_root, journal, lease):
                owned.add(lease.stage_name)
            continue
        if (
            target.device == lease.device
            and target.inode == lease.inode
            and target.ctime_ns == lease.ctime_ns
            and target.file_type == lease.file_type
            and target.link_count == 1
        ):
            owned.add(lease.stage_name)
    return tuple(name for name in names if name not in owned)


def build_deprovision_generated_state_contract(
    target_root: Path,
    *,
    expected_root_identity: DistributionRootIdentity,
    recovery_journal: OperationJournal | None = None,
) -> DistributionGeneratedStateContract:
    """Build the only generated-state ownership contract for deprovision."""

    target_root = Path(target_root)
    if _root_identity_for_assessment(target_root) != expected_root_identity:
        raise DistributionPlanError("deprovision generated state root binding mismatch")
    entries: list[DistributionGeneratedStateEntry] = []
    blockers: list[DistributionAction] = []
    legacy_paths: list[str] = []
    active_selection_witnesses: dict[str, DistributionActiveSelectionWitness] = {}

    selection, active_manifest_entry = _active_selection_from_manifest(
        target_root,
        recovery_journal=recovery_journal,
    )
    if selection is None:
        blockers.append(_generated_state_blocker("spec-dock/.agent/active.json", "generated-state-invalid"))
        selection = dict.fromkeys(_DEPROVISION_ACTIVE_LAYERS)
    elif active_manifest_entry is not None:
        entries.append(active_manifest_entry)

    active_names: tuple[str, ...] | None
    active_error: str | None
    if _deprovision_recovery_directory_is_published(recovery_journal, "spec-dock/active"):
        active_names, active_error = (), None
    else:
        active_names, active_error = _list_generated_root(target_root, "spec-dock/active")
    if active_error is not None:
        blockers.append(_generated_state_blocker("spec-dock/active", active_error))
        active_names = ()
    assert active_names is not None
    active_names = _deprovision_recovery_stage_names(
        target_root,
        recovery_journal,
        "spec-dock/active",
        active_names,
    )
    allowed_active_names = {
        *(layer for layer in _DEPROVISION_ACTIVE_LAYERS),
        *(f"{layer}.path" for layer in _DEPROVISION_ACTIVE_LAYERS),
        "context-pack.md",
        *_DEPROVISION_ACTIVE_LEGACY_FILES,
    }
    for name in active_names:
        if name not in allowed_active_names:
            blockers.append(_generated_state_blocker(f"spec-dock/active/{name}", "unknown-generated-state-entry"))
    for name in sorted(_DEPROVISION_ACTIVE_LEGACY_FILES & set(active_names)):
        path = f"spec-dock/active/{name}"
        legacy_paths.append(path)
        blockers.append(_generated_state_blocker(path, "legacy-generated-identity-unproven"))

    for layer in _DEPROVISION_ACTIVE_LAYERS:
        pointer_name = layer
        path_name = f"{layer}.path"
        pointer_present = pointer_name in active_names
        path_present = path_name in active_names
        selected = selection[layer]
        if pointer_present and path_present:
            blockers.append(_generated_state_blocker(f"spec-dock/active/{layer}", "generated-state-slot-conflict"))
            active_selection_witnesses[layer] = DistributionActiveSelectionWitness(
                layer=cast("ActiveSelectionLayer", layer),
                selection=selected,
                representation="absent",
                target=None,
            )
            continue
        if not pointer_present and not path_present:
            active_selection_witnesses[layer] = DistributionActiveSelectionWitness(
                layer=cast("ActiveSelectionLayer", layer),
                selection=selected,
                representation="absent",
                target=None,
            )
            continue
        expected_target = selected[1] if selected is not None else f"spec-dock/system/active-none/{layer}"
        if pointer_present:
            path = f"spec-dock/active/{layer}"
            entry = _generated_entry(
                target_root,
                path,
                origin="current-active-producer",
                expected_kind="symlink",
                semantic_contract=f"active-{layer}-pointer-v1",
            )
            actual_target = _lexical_generated_target(path, entry.identity.target or "") if entry is not None else None
            if entry is None or actual_target != expected_target:
                blockers.append(_generated_state_blocker(path, "generated-state-invalid"))
                active_selection_witnesses[layer] = DistributionActiveSelectionWitness(
                    layer=cast("ActiveSelectionLayer", layer),
                    selection=selected,
                    representation="symlink",
                    target=entry.identity.target if entry is not None else None,
                )
            else:
                entries.append(entry)
                assert entry.identity.target is not None
                active_selection_witnesses[layer] = DistributionActiveSelectionWitness(
                    layer=cast("ActiveSelectionLayer", layer),
                    selection=selected,
                    representation="symlink",
                    target=entry.identity.target,
                )
        else:
            path = f"spec-dock/active/{layer}.path"
            loaded = _read_generated_regular_bytes(target_root, path)
            try:
                raw_target = loaded[0].decode("utf-8") if loaded is not None else ""
            except UnicodeDecodeError:
                raw_target = ""
            line_target = raw_target[:-1] if raw_target.endswith("\n") and "\n" not in raw_target[:-1] else ""
            actual_target = _lexical_generated_target(path, line_target)
            if loaded is None or not line_target or actual_target != expected_target:
                blockers.append(_generated_state_blocker(path, "generated-state-invalid"))
                active_selection_witnesses[layer] = DistributionActiveSelectionWitness(
                    layer=cast("ActiveSelectionLayer", layer),
                    selection=selected,
                    representation="path",
                    target=line_target or None,
                )
            else:
                entries.append(replace(loaded[1], semantic_contract=f"active-{layer}-path-v1"))
                active_selection_witnesses[layer] = DistributionActiveSelectionWitness(
                    layer=cast("ActiveSelectionLayer", layer),
                    selection=selected,
                    representation="path",
                    target=line_target,
                )

    if "context-pack.md" in active_names:
        path = "spec-dock/active/context-pack.md"
        loaded = _read_generated_regular_bytes(target_root, path)
        expected = _render_context_pack(
            initiative_id=selection["initiative"][0] if selection["initiative"] is not None else None,
            epic_id=selection["epic"][0] if selection["epic"] is not None else None,
            issue_id=selection["issue"][0] if selection["issue"] is not None else None,
        ).encode("utf-8")
        if loaded is None or loaded[0] != expected:
            blockers.append(_generated_state_blocker(path, "generated-state-invalid"))
        else:
            entries.append(replace(loaded[1], semantic_contract="context-pack-v1"))

    agent_names: tuple[str, ...] | None
    agent_error: str | None
    if _deprovision_recovery_directory_is_published(recovery_journal, "spec-dock/.agent"):
        agent_names, agent_error = (), None
    else:
        agent_names, agent_error = _list_generated_root(target_root, "spec-dock/.agent")
    if agent_error is not None:
        blockers.append(_generated_state_blocker("spec-dock/.agent", agent_error))
        agent_names = ()
    assert agent_names is not None
    agent_names = _deprovision_recovery_stage_names(
        target_root,
        recovery_journal,
        "spec-dock/.agent",
        agent_names,
    )
    allowed_agent_names = _DEPROVISION_AGENT_CURRENT_FILES | _DEPROVISION_AGENT_LEGACY_FILES
    for name in agent_names:
        if name not in allowed_agent_names:
            blockers.append(_generated_state_blocker(f"spec-dock/.agent/{name}", "unknown-generated-state-entry"))
    for name in sorted(_DEPROVISION_AGENT_LEGACY_FILES & set(agent_names)):
        path = f"spec-dock/.agent/{name}"
        legacy_paths.append(path)
        blockers.append(_generated_state_blocker(path, "legacy-generated-identity-unproven"))

    # The active manifest was validated before the active pointers so it is
    # already present in ``entries``.  Remaining projections are added only
    # after their exact schema/discriminator is proved.
    projection_specs: dict[str, tuple[frozenset[str], str | None]] = {
        "index-all.json": (
            frozenset({"schema_version", "generated_at", "active", "warnings", "root", "projection", "deps", "nodes"}),
            "full-history",
        ),
        "index.json": (
            frozenset({"schema_version", "generated_at", "active", "warnings", "root", "projection", "deps", "nodes"}),
            "current-future",
        ),
        "tree-all.json": (
            frozenset({"schema_version", "generated_at", "active", "warnings", "root", "deps", "tree"}),
            None,
        ),
        "tree.json": (
            frozenset({"schema_version", "generated_at", "active", "warnings", "root", "deps", "tree"}),
            None,
        ),
        "deps-issues.json": (
            frozenset({
                "schema_version",
                "generated_at",
                "projection",
                "source",
                "deps",
                "nodes",
                "edges",
                "dependency_contexts",
                "edge_direction",
            }),
            "issue-readiness-with-dependency-context",
        ),
    }
    projection_payloads: dict[str, dict[str, object]] = {}
    for name in sorted(_DEPROVISION_AGENT_CURRENT_FILES - {"active.json"}):
        if name not in agent_names:
            continue
        path = f"spec-dock/.agent/{name}"
        loaded = _read_generated_regular_bytes(target_root, path)
        valid = loaded is not None
        payload: object = None
        if loaded is not None:
            try:
                payload = json.loads(loaded[0].decode("utf-8"))
            except (UnicodeDecodeError, json.JSONDecodeError):
                valid = False
        expected_fields, projection = projection_specs[name]
        if (
            not isinstance(payload, dict)
            or (name == "deps-issues.json" and not _validate_deps_issues_payload(payload))
            or (
                name != "deps-issues.json"
                and (
                    not _valid_generated_projection_base(
                        payload,
                        expected_fields=expected_fields,
                        projection=projection,
                    )
                    or payload.get("active") != _artifact_active_selection(selection)
                    or _validate_generated_projection_payload(
                        name,
                        payload,
                        expected_fields=expected_fields,
                        projection=projection,
                    )
                    is None
                )
            )
        ):
            valid = False
        if not valid or loaded is None or not isinstance(payload, dict):
            blockers.append(_generated_state_blocker(path, "generated-state-invalid"))
        else:
            entries.append(replace(loaded[1], semantic_contract=f"{name}-schema-2"))
            projection_payloads[name] = payload

    def invalidate_projection(name: str) -> None:
        blockers.append(_generated_state_blocker(f"spec-dock/.agent/{name}", "generated-state-invalid"))
        entries[:] = [entry for entry in entries if entry.path != f"spec-dock/.agent/{name}"]
        projection_payloads.pop(name, None)

    current_index = projection_payloads.get("index.json")
    full_index = projection_payloads.get("index-all.json")
    if (
        current_index is not None
        and full_index is not None
        and not _generated_current_future_matches_full_history(
            full_index,
            current_index,
        )
    ):
        invalidate_projection("index.json")
        current_index = None

    if current_index is not None:
        current_tree = projection_payloads.get("tree.json")
        if current_tree is not None and not _generated_tree_matches_index(current_index, current_tree):
            invalidate_projection("tree.json")

    generated_batches: dict[object, list[str]] = {}
    for name, payload in projection_payloads.items():
        generated_batches.setdefault(payload.get("generated_at"), []).append(name)
    if len(generated_batches) > 1:
        for name in sorted(projection_payloads):
            blockers.append(
                _generated_state_blocker(
                    f"spec-dock/.agent/{name}",
                    "generated-state-batch-conflict",
                )
            )

    for index_name, tree_name in (
        ("index-all.json", "tree-all.json"),
        ("index.json", "tree.json"),
    ):
        index_payload = projection_payloads.get(index_name)
        tree_payload = projection_payloads.get(tree_name)
        if index_payload is None or tree_payload is None:
            continue
        index_nodes = index_payload.get("nodes")
        if not isinstance(index_nodes, dict):
            continue
        tree_ids = _validate_generated_tree(tree_payload.get("tree"), None)
        if tree_ids is None:
            for name in (index_name, tree_name):
                blockers.append(_generated_state_blocker(f"spec-dock/.agent/{name}", "generated-state-invalid"))
            continue
        if tree_ids != frozenset(index_nodes):
            for name in (index_name, tree_name):
                blockers.append(
                    _generated_state_blocker(
                        f"spec-dock/.agent/{name}",
                        "generated-state-node-set-conflict",
                    )
                )
            continue
        if _validate_generated_tree(tree_payload.get("tree"), index_nodes) is None:
            for name in (index_name, tree_name):
                blockers.append(_generated_state_blocker(f"spec-dock/.agent/{name}", "generated-state-invalid"))

    if recovery_journal is not None:
        if (
            tuple(witness.layer for witness in recovery_journal.active_selection_witnesses)
            != _DEPROVISION_ACTIVE_LAYERS
        ):
            blockers.append(_generated_state_blocker("spec-dock/.agent/active.json", "journal-protocol-incompatible"))
            recovery_active_selection_witnesses: tuple[DistributionActiveSelectionWitness, ...] = ()
        else:
            recovery_active_selection_witnesses = recovery_journal.active_selection_witnesses
        entry_paths = {entry.path for entry in entries}
        for record in recovery_journal.actions:
            if record.path not in _DEPROVISION_GENERATED_CURRENT_SLOTS or record.path in entry_paths:
                continue
            if record.checkpoint == "pending" and not _deprovision_recovery_pending_target_is_exact_absent(
                target_root,
                record,
            ):
                continue
            entries.append(_deprovision_recovery_generated_entry(record))
            entry_paths.add(record.path)
    else:
        recovery_active_selection_witnesses = tuple(
            active_selection_witnesses[layer] for layer in _DEPROVISION_ACTIVE_LAYERS
        )

    ordered_entries = tuple(sorted(entries, key=lambda entry: entry.path))
    ordered_legacy = tuple(sorted(set(legacy_paths)))
    ordered_blockers = tuple(sorted(blockers, key=lambda action: (action.path, action.reason)))
    return DistributionGeneratedStateContract(
        entries=ordered_entries,
        current_slots=_DEPROVISION_GENERATED_CURRENT_SLOTS,
        legacy_unproven_paths=ordered_legacy,
        blockers=ordered_blockers,
        contract_digest=_generated_contract_digest(
            ordered_entries,
            ordered_legacy,
            ordered_blockers,
            recovery_active_selection_witnesses,
        ),
        active_selection_witnesses=recovery_active_selection_witnesses,
    )


def _source_semantic_identity(
    asset: DistributionAsset,
    *,
    source_namespace: Literal["install-root", "spec-dock-scaffold"],
) -> DistributionSourceSemanticIdentity:
    """Project a physical provider source into its durable package identity."""

    source_relative = asset.source_path or asset.path
    normalized_source = _exact_relative_path(
        source_relative,
        field_name="deprovision canonical source path",
    ).as_posix()
    canonical_source_path = f"{source_namespace}/{normalized_source}"
    identity = asset.identity
    if identity.kind == "regular":
        if identity.sha256 is None or identity.mode is None or identity.target is not None:
            raise DistributionManifestError("regular provider source has an incomplete semantic identity")
        return DistributionSourceSemanticIdentity(
            canonical_source_path=canonical_source_path,
            kind="regular",
            sha256=identity.sha256,
            mode=identity.mode,
        )
    if identity.kind == "symlink":
        normalized_target = _normalized_link_target(identity.target or "")
        if normalized_target is None or identity.sha256 is not None:
            raise DistributionManifestError("symlink provider source has an incomplete semantic identity")
        return DistributionSourceSemanticIdentity(
            canonical_source_path=canonical_source_path,
            kind="symlink",
            mode=identity.mode,
            link_target=normalized_target,
        )
    raise DistributionManifestError("provider source kind is not supported by deprovision")


def _deprovision_current_assets(install_root: Path) -> tuple[DistributionAsset, ...]:
    """Capture regular and symlink provider assets for deprovision identity."""

    regular_assets = list(_current_assets(install_root))
    occupied = {asset.path for asset in regular_assets}
    for candidate in sorted(
        install_root.rglob("*"),
        key=lambda item: item.relative_to(install_root).as_posix(),
    ):
        try:
            visible = os.lstat(candidate)
        except OSError as exc:
            raise DistributionManifestError("unable to inspect Current provider source") from exc
        if not stat.S_ISLNK(visible.st_mode):
            continue
        relative_candidate = candidate.relative_to(install_root)
        if "__pycache__" in relative_candidate.parts or relative_candidate.suffix in {".pyc", ".pyo"}:
            continue
        relative = _exact_relative_path(relative_candidate.as_posix(), field_name="Current path").as_posix()
        if relative in occupied or visible.st_nlink != 1:
            raise DistributionManifestError("Current symlink source is duplicated or hard-linked")
        try:
            link_target = str(candidate.readlink())
            after = os.lstat(candidate)
        except OSError as exc:
            raise DistributionManifestError("unable to read Current symlink source") from exc
        if _source_snapshot(visible) != _source_snapshot(after):
            raise DistributionManifestError("Current symlink source changed during capture")
        if _normalized_link_target(link_target) is None:
            raise DistributionManifestError("Current symlink source target is not canonical")
        regular_assets.append(
            DistributionAsset(
                path=relative,
                identity=DistributionIdentity(
                    kind="symlink",
                    mode=stat.S_IMODE(after.st_mode),
                    target=link_target,
                ),
                source_snapshot=_source_snapshot(after),
            )
        )
        occupied.add(relative)
    return tuple(sorted(regular_assets, key=lambda asset: asset.path))


def _source_semantic_payload(identity: DistributionSourceSemanticIdentity) -> dict[str, object]:
    return {
        "canonical_source_path": identity.canonical_source_path,
        "kind": identity.kind,
        "sha256": identity.sha256,
        "mode": identity.mode,
        "link_target": identity.link_target,
        "contract_schema_version": identity.contract_schema_version,
    }


def _deprovision_managed_roots(
    assets: tuple[DistributionAsset, ...],
    manifest: DistributionManifest,
) -> tuple[str, ...]:
    roots: set[str] = {
        "spec",
        "spec-dock/active",
        "spec-dock/.agent",
        *(f"spec-dock/{name}" for name in _SCAFFOLD_MANAGED_ROOTS),
    }
    declared_paths = {asset.path for asset in assets}
    declared_paths.update(item["path"] for item in manifest.historical_current_identities)
    declared_paths.update(item["path"] for item in manifest.obsolete_exact_files)
    declared_paths.update(item["path"] for item in manifest.historical_shortcuts)
    for item in manifest.trusted_consumer_manifests:
        declared_paths.update(claim["path"] for claim in item["claims"])
    for path in declared_paths:
        parts = PurePosixPath(path).parts
        roots.update("/".join(parts[:index]) for index in range(1, len(parts)))
    return tuple(sorted(roots, key=lambda path: (len(PurePosixPath(path).parts), path)))


def _historical_generated_records(
    manifest: DistributionManifest,
    path: str,
) -> tuple[dict[str, Any], ...]:
    records: list[dict[str, Any]] = [item for item in manifest.historical_current_identities if item["path"] == path]
    for item in manifest.obsolete_exact_files:
        if item["path"] == path:
            records.extend(item["identities"])
    records.extend(item for item in manifest.historical_shortcuts if item["path"] == path)
    return tuple(records)


def _adopt_historical_generated_entries(
    target_root: Path,
    manifest: DistributionManifest,
    generated: DistributionGeneratedStateContract,
) -> DistributionGeneratedStateContract:
    entries = list(generated.entries)
    blockers: list[DistributionAction] = []
    for blocker in generated.blockers:
        if blocker.reason not in {
            "legacy-generated-identity-unproven",
            "unknown-generated-state-entry",
        }:
            blockers.append(blocker)
            continue
        observation = _observe_target(target_root, blocker.path)
        records = _historical_generated_records(manifest, blocker.path)
        matched = next(
            (
                record
                for record in records
                if observation.identity is not None
                and observation.link_count == 1
                and _removal_identity_matches(observation.identity, record)
            ),
            None,
        )
        trusted_match = observation.identity is not None and _trusted_manifest_matches(
            target_root,
            blocker.path,
            observation.identity,
            manifest,
            require_mode=True,
        )
        if (
            (matched is None and not trusted_match)
            or observation.snapshot is None
            or observation.state not in {"regular", "symlink"}
        ):
            blockers.append(blocker)
            continue
        expected_kind: Literal["regular", "symlink"] = "regular" if observation.state == "regular" else "symlink"
        entries.append(
            DistributionGeneratedStateEntry(
                path=blocker.path,
                origin="historical-exact",
                expected_kind=expected_kind,
                identity=cast("DistributionIdentity", observation.identity),
                observed=observation.snapshot.target,
                semantic_contract="historical-manifest-exact-v1",
            )
        )
    ordered_entries = tuple(sorted(entries, key=lambda entry: entry.path))
    ordered_blockers = tuple(sorted(blockers, key=lambda action: (action.path, action.reason)))
    return replace(
        generated,
        entries=ordered_entries,
        blockers=ordered_blockers,
        contract_digest=_generated_contract_digest(
            ordered_entries,
            generated.legacy_unproven_paths,
            ordered_blockers,
            generated.active_selection_witnesses,
        ),
    )


def _read_target_regular_bytes(
    target_root: Path,
    relative_path: str,
) -> tuple[bytes, DistributionIdentity] | None:
    """Read one target regular file while keeping identity and bytes descriptor-bound."""

    path = target_root / relative_path
    try:
        visible = os.lstat(path)
    except FileNotFoundError:
        return None
    except OSError as exc:
        raise DistributionPlanError("managed workspace version identity is unsafe") from exc
    if stat.S_ISLNK(visible.st_mode) or not stat.S_ISREG(visible.st_mode) or visible.st_nlink != 1:
        raise DistributionPlanError("managed workspace version identity is unsafe")
    nofollow = getattr(os, "O_NOFOLLOW", None)
    if not isinstance(nofollow, int):
        raise DistributionPlanError("managed workspace version identity is unsafe")
    parent_fds: tuple[int, ...] = ()
    file_fd: int | None = None
    try:
        parent_fds = _open_distribution_parent_chain(target_root, relative_path)
        file_fd = os.open(
            PurePosixPath(relative_path).name,
            os.O_RDONLY | nofollow | getattr(os, "O_CLOEXEC", 0),
            dir_fd=parent_fds[-1],
        )
        before = os.fstat(file_fd)
        visible_before = os.stat(
            PurePosixPath(relative_path).name,
            dir_fd=parent_fds[-1],
            follow_symlinks=False,
        )
        if not stat.S_ISREG(before.st_mode) or before.st_nlink != 1 or not _same_observed_node(visible_before, before):
            raise DistributionPlanError("managed workspace version identity changed during admission")
        raw = _read_fd_bytes(file_fd)
        after = os.fstat(file_fd)
        visible_after = os.stat(
            PurePosixPath(relative_path).name,
            dir_fd=parent_fds[-1],
            follow_symlinks=False,
        )
        if (
            not _same_observed_node(before, after)
            or before.st_nlink != after.st_nlink
            or not _same_observed_node(after, visible_after)
            or stat.S_IMODE(before.st_mode) != stat.S_IMODE(after.st_mode)
            or before.st_size != after.st_size
        ):
            raise DistributionPlanError("managed workspace version identity changed during admission")
        identity = DistributionIdentity(
            kind="regular",
            sha256=hashlib.sha256(raw).hexdigest(),
            mode=stat.S_IMODE(after.st_mode),
        )
        return raw, identity
    except DistributionPlanError:
        raise
    except (DistributionApplyError, OSError) as exc:
        raise DistributionPlanError("managed workspace version identity is unsafe") from exc
    finally:
        if file_fd is not None:
            os.close(file_fd)
        _close_distribution_parent_chain(parent_fds)


def _deprovision_version_asset(
    target_root: Path,
    manifest: DistributionManifest,
) -> tuple[DistributionAsset, ...]:
    path = "spec-dock/spec-dock.version"
    loaded = _read_target_regular_bytes(target_root, path)
    if loaded is None:
        return ()
    raw, identity = loaded
    try:
        version_text = raw.decode("ascii")
    except (OSError, UnicodeDecodeError) as exc:
        raise DistributionPlanError("managed workspace version identity is invalid") from exc
    if _CANONICAL_VERSION_RE.fullmatch(version_text) is None:
        raise DistributionPlanError("managed workspace version identity is invalid")
    recognized = [item for item in manifest.recognized_workspace_versions if item["version"] == version_text[:-1]]
    if len(recognized) != 1:
        raise DistributionPlanError("managed workspace version is not recognized")
    return (DistributionAsset(path=path, identity=identity),)


def _deprovision_contract_digest(
    *,
    physical_assets: tuple[DistributionAsset, ...],
    shortcuts: tuple[DistributionAsset, ...],
    target_only_assets: tuple[DistributionAsset, ...],
    managed_roots: tuple[str, ...],
    preserved_roots: tuple[str, ...],
    generated_state_digest: str,
    manifest: DistributionManifest,
) -> str:
    """Hash the static ownership catalog plus a bound generated-state digest."""

    payload = {
        "format_version": 1,
        "journal_schema_version": 2,
        "journal_protocol_version": 2,
        "managed_roots": list(managed_roots),
        "preserved_roots": list(preserved_roots),
        "assets": [
            {
                "path": asset.path,
                "identity": _distribution_identity_payload(asset.identity),
                "source": _source_semantic_payload(
                    cast("DistributionSourceSemanticIdentity", asset.source_semantic_identity)
                ),
            }
            for asset in physical_assets
        ],
        "shortcuts": [
            {"path": asset.path, "identity": _distribution_identity_payload(asset.identity)} for asset in shortcuts
        ],
        "target_only_assets": [
            {"path": asset.path, "identity": _distribution_identity_payload(asset.identity)}
            for asset in target_only_assets
        ],
        "generated_state_digest": generated_state_digest,
        "manifest": {
            "schema_version": manifest.schema_version,
            "recognized_workspace_versions": manifest.recognized_workspace_versions,
            "historical_current_identities": manifest.historical_current_identities,
            "trusted_consumer_manifests": manifest.trusted_consumer_manifests,
            "obsolete_exact_files": manifest.obsolete_exact_files,
            "historical_shortcuts": manifest.historical_shortcuts,
        },
    }
    return hashlib.sha256(json.dumps(payload, sort_keys=True, separators=(",", ":")).encode("utf-8")).hexdigest()


def _build_deprovision_contract(
    install_root: Path,
    *,
    manifest_path: Path,
    scaffold_root: Path,
    target_root: Path,
    expected_root_identity: DistributionRootIdentity,
    recovery_journal: OperationJournal | None = None,
    preserved_roots: tuple[str, ...] = ("spec-dock/initiatives", "spec-dock/.workbench"),
    additional_managed_roots: tuple[str, ...] = (),
) -> DistributionDeprovisionContract:
    """Capture one physical/generated deprovision contract without target mutation."""

    target_root = Path(target_root)
    if _root_identity_for_assessment(target_root) != expected_root_identity:
        raise DistributionPlanError("deprovision contract root binding mismatch")
    manifest = _load_manifest(Path(manifest_path))
    current_assets = tuple(
        replace(
            asset,
            source_semantic_identity=_source_semantic_identity(
                asset,
                source_namespace="install-root",
            ),
        )
        for asset in _deprovision_current_assets(Path(install_root))
    )
    scaffold_assets = tuple(
        replace(
            asset,
            source_semantic_identity=_source_semantic_identity(
                asset,
                source_namespace="spec-dock-scaffold",
            ),
        )
        for asset in _scaffold_assets(Path(scaffold_root), operation="update")
    )
    physical_assets = tuple(sorted((*current_assets, *scaffold_assets), key=lambda asset: asset.path))
    if len({asset.path for asset in physical_assets}) != len(physical_assets):
        raise DistributionPlanError("deprovision physical contract contains duplicate target paths")
    deprovision_protected_paths = frozenset(
        path
        for path in _protected_workspace_paths(scaffold_assets)
        if not _is_same_or_descendant(path, "spec-dock/active") and not _is_same_or_descendant(path, "spec-dock/.agent")
    )
    _assert_no_manifest_overlap(
        {asset.path for asset in current_assets} | set(_CURRENT_SHORTCUTS),
        manifest,
        protected_paths=deprovision_protected_paths,
    )
    generated_state = build_deprovision_generated_state_contract(
        target_root,
        expected_root_identity=expected_root_identity,
        recovery_journal=recovery_journal,
    )
    generated_state = _adopt_historical_generated_entries(target_root, manifest, generated_state)
    target_only_assets = _deprovision_version_asset(target_root, manifest)
    shortcuts = tuple(
        DistributionAsset(path=path, identity=identity) for path, identity in sorted(_CURRENT_SHORTCUTS.items())
    )
    sources = tuple(
        sorted(
            (asset.source_semantic_identity for asset in physical_assets if asset.source_semantic_identity is not None),
            key=lambda identity: identity.canonical_source_path,
        )
    )
    source_snapshots = tuple(asset.source_snapshot for asset in physical_assets if asset.source_snapshot is not None)
    managed_roots = _deprovision_managed_roots(
        (*physical_assets, *shortcuts, *target_only_assets),
        manifest,
    )
    managed_roots = tuple(
        sorted(
            {*managed_roots, *additional_managed_roots},
            key=lambda path: (len(PurePosixPath(path).parts), path),
        )
    )
    contract_digest = _deprovision_contract_digest(
        physical_assets=physical_assets,
        shortcuts=shortcuts,
        target_only_assets=target_only_assets,
        managed_roots=managed_roots,
        preserved_roots=preserved_roots,
        generated_state_digest=generated_state.contract_digest,
        manifest=manifest,
    )
    return DistributionDeprovisionContract(
        managed_roots=managed_roots,
        preserved_roots=preserved_roots,
        removable_shortcuts=shortcuts,
        generated_state=generated_state,
        contract_digest=contract_digest,
        source_semantic_identities=sources,
        source_snapshots=source_snapshots,
        managed_assets=physical_assets,
        target_only_assets=target_only_assets,
        manifest=manifest,
    )


def build_deprovision_contract(
    install_root: Path,
    *,
    manifest_path: Path,
    scaffold_root: Path,
    target_root: Path,
    expected_root_identity: DistributionRootIdentity,
    recovery_journal: OperationJournal | None = None,
) -> DistributionDeprovisionContract:
    """Capture one physical/generated deprovision contract without target mutation."""

    return _build_deprovision_contract(
        install_root,
        manifest_path=manifest_path,
        scaffold_root=scaffold_root,
        target_root=target_root,
        expected_root_identity=expected_root_identity,
        recovery_journal=recovery_journal,
    )


class _PreservationCaptureError(RuntimeError):
    def __init__(self, path: str, reason: str) -> None:
        super().__init__(reason)
        self.path = path
        self.reason = reason


def _tree_entry_payload(entry: DistributionTreeEntrySnapshot) -> dict[str, object]:
    return {
        "format_version": 1,
        "relative_path": entry.relative_path,
        "kind": entry.kind,
        "device": entry.device,
        "inode": entry.inode,
        "ctime_ns": entry.ctime_ns,
        "mode": entry.mode,
        "link_count": entry.link_count,
        "size": entry.size,
        "sha256": entry.sha256,
        "link_target": entry.link_target,
    }


def _preservation_tree_digest(
    relative_root: str,
    root_binding: PathIdentitySnapshot,
    entries: tuple[DistributionTreeEntrySnapshot, ...],
) -> str:
    payload = {
        "format_version": 1,
        "relative_root": relative_root,
        "root_binding": {
            **_path_snapshot_condition(root_binding),
            "mode": root_binding.mode,
        },
        "entries": [_tree_entry_payload(entry) for entry in entries],
    }
    return hashlib.sha256(json.dumps(payload, sort_keys=True, separators=(",", ":")).encode("utf-8")).hexdigest()


def _capture_preservation_witness(
    target_root: Path,
    relative_root: str,
) -> tuple[DistributionPreservationWitness | None, tuple[DistributionAction, ...]]:
    """Capture one explicit preserved tree without following links."""

    try:
        root_binding, entries, _tree_digest = _capture_distribution_tree(
            target_root,
            relative_root,
            reject_symlinks=False,
            require_single_link_regulars=True,
        )
    except _PreservationCaptureError as exc:
        reason = exc.reason.replace("history-", "preservation-")
        return None, (_generated_state_blocker(exc.path, reason),)
    except DistributionApplyError:
        return None, (_generated_state_blocker(relative_root, "platform-capability-unavailable"),)
    return (
        DistributionPreservationWitness(
            relative_root=relative_root,
            root_binding=root_binding,
            entries=entries,
            tree_digest=_preservation_tree_digest(relative_root, root_binding, entries),
            reason="preserved-root",
        ),
        (),
    )


def _distribution_tree_digest(
    relative_root: str,
    root_binding: PathIdentitySnapshot,
    entries: tuple[DistributionTreeEntrySnapshot, ...],
) -> str:
    """Hash a no-follow tree inventory without embedding absolute paths."""

    payload = {
        "format_version": 1,
        "relative_root": relative_root,
        "root_binding": _path_snapshot_condition(root_binding, include_mode=True),
        "entries": [_tree_entry_payload(entry) for entry in entries],
    }
    return hashlib.sha256(json.dumps(payload, sort_keys=True, separators=(",", ":")).encode("utf-8")).hexdigest()


def _capture_distribution_tree(
    target_root: Path,
    relative_root: str,
    *,
    reject_symlinks: bool,
    require_single_link_regulars: bool,
) -> tuple[PathIdentitySnapshot, tuple[DistributionTreeEntrySnapshot, ...], str]:
    """Capture one descriptor-bound repository tree without following links."""

    capture = _capture_distribution_tree_details(
        target_root,
        relative_root,
        reject_symlinks=reject_symlinks,
        require_single_link_regulars=require_single_link_regulars,
    )
    return capture.root_binding, capture.entries, capture.tree_digest


def _tree_entry_target_snapshot(
    entry: DistributionTreeEntrySnapshot,
    *,
    root_snapshot: PathIdentitySnapshot,
    parents: tuple[PathIdentitySnapshot, ...],
) -> DistributionTargetSnapshot:
    identity: DistributionIdentity | None = None
    if entry.kind == "regular":
        identity = DistributionIdentity(kind="regular", sha256=entry.sha256, mode=entry.mode)
    elif entry.kind == "symlink":
        identity = DistributionIdentity(kind="symlink", target=entry.link_target)
    target = PathIdentitySnapshot(
        relative_path=entry.relative_path,
        exists=True,
        device=entry.device,
        inode=entry.inode,
        ctime_ns=entry.ctime_ns,
        file_type=entry.kind,
        link_count=entry.link_count,
        mode=entry.mode,
        size=entry.size,
        identity=identity,
    )
    return _target_snapshot(root_snapshot, list(parents), target)


def _capture_distribution_tree_details(
    target_root: Path,
    relative_root: str,
    *,
    reject_symlinks: bool,
    require_single_link_regulars: bool,
) -> _DistributionTreeCapture:
    """Capture a tree and all mutation-bound evidence from one descriptor walk."""

    observation = _observe_target(target_root, relative_root)
    if observation.snapshot is None:
        raise _PreservationCaptureError(relative_root, "history-root-unreadable")
    root_binding = observation.snapshot.target
    if observation.state == "missing":
        entries: tuple[DistributionTreeEntrySnapshot, ...] = ()
        return _DistributionTreeCapture(
            root_binding=root_binding,
            entries=entries,
            tree_digest=_distribution_tree_digest(relative_root, root_binding, entries),
            target_snapshots=((relative_root, observation.snapshot),),
            directory_captures=(),
        )
    if observation.state != "directory":
        reason = (
            "history-root-symlink"
            if observation.state in {"symlink", "symlink-container", "root-symlink"}
            else "history-root-unsafe"
        )
        raise _PreservationCaptureError(relative_root, reason)

    directory_flags = _distribution_directory_flags()
    regular_flags = os.O_RDONLY | getattr(os, "O_NOFOLLOW", 0) | getattr(os, "O_CLOEXEC", 0)
    captured: list[DistributionTreeEntrySnapshot] = []
    target_snapshots: dict[str, DistributionTargetSnapshot] = {relative_root: observation.snapshot}
    directory_captures: dict[str, tuple[PathIdentitySnapshot, tuple[DistributionTreeEntrySnapshot, ...]]] = {}
    root_snapshot = observation.snapshot.root
    root_parents = (*observation.snapshot.parents, root_binding)

    def walk(
        directory_fd: int,
        current_path: str,
        current_binding: PathIdentitySnapshot,
        parent_bindings: tuple[PathIdentitySnapshot, ...],
    ) -> None:
        before = os.fstat(directory_fd)
        immediate_entries: list[DistributionTreeEntrySnapshot] = []
        for name in sorted(os.listdir(directory_fd), key=os.fsencode):
            child_path = f"{current_path}/{name}"
            try:
                visible = os.stat(name, dir_fd=directory_fd, follow_symlinks=False)
            except OSError as exc:
                raise _PreservationCaptureError(child_path, "history-entry-unreadable") from exc
            mode = stat.S_IMODE(visible.st_mode)
            if stat.S_ISDIR(visible.st_mode):
                try:
                    child_fd = os.open(name, directory_flags, dir_fd=directory_fd)
                except OSError as exc:
                    raise _PreservationCaptureError(child_path, "history-directory-unsafe") from exc
                try:
                    opened = os.fstat(child_fd)
                    if not _same_observed_node(visible, opened) or not stat.S_ISDIR(opened.st_mode):
                        raise _PreservationCaptureError(child_path, "history-entry-rebound")
                    entry = DistributionTreeEntrySnapshot(
                        relative_path=child_path,
                        kind="directory",
                        device=opened.st_dev,
                        inode=opened.st_ino,
                        ctime_ns=opened.st_ctime_ns,
                        mode=stat.S_IMODE(opened.st_mode),
                        link_count=opened.st_nlink,
                    )
                    captured.append(entry)
                    immediate_entries.append(entry)
                    child_snapshot = _tree_entry_target_snapshot(
                        entry,
                        root_snapshot=root_snapshot,
                        parents=parent_bindings,
                    )
                    target_snapshots[child_path] = child_snapshot
                    walk(
                        child_fd,
                        child_path,
                        child_snapshot.target,
                        (*parent_bindings, child_snapshot.target),
                    )
                    after = os.fstat(child_fd)
                    if not _same_observed_node(opened, after):
                        raise _PreservationCaptureError(child_path, "history-directory-rebound")
                finally:
                    os.close(child_fd)
                continue
            if stat.S_ISREG(visible.st_mode):
                if require_single_link_regulars and visible.st_nlink != 1:
                    raise _PreservationCaptureError(child_path, "history-hardlink-unsafe")
                try:
                    child_fd = os.open(name, regular_flags, dir_fd=directory_fd)
                except OSError as exc:
                    raise _PreservationCaptureError(child_path, "history-entry-unreadable") from exc
                try:
                    opened = os.fstat(child_fd)
                    if (
                        not _same_observed_node(visible, opened)
                        or not stat.S_ISREG(opened.st_mode)
                        or (require_single_link_regulars and opened.st_nlink != 1)
                    ):
                        raise _PreservationCaptureError(child_path, "history-entry-rebound")
                    sha256 = _digest_open_file(child_fd)
                    after = os.fstat(child_fd)
                    if not _same_observed_node(opened, after) or after.st_size != opened.st_size:
                        raise _PreservationCaptureError(child_path, "history-entry-rebound")
                    entry = DistributionTreeEntrySnapshot(
                        relative_path=child_path,
                        kind="regular",
                        device=after.st_dev,
                        inode=after.st_ino,
                        ctime_ns=after.st_ctime_ns,
                        mode=stat.S_IMODE(after.st_mode),
                        link_count=after.st_nlink,
                        size=after.st_size,
                        sha256=sha256,
                    )
                    captured.append(entry)
                    immediate_entries.append(entry)
                    target_snapshots[child_path] = _tree_entry_target_snapshot(
                        entry,
                        root_snapshot=root_snapshot,
                        parents=parent_bindings,
                    )
                finally:
                    os.close(child_fd)
                continue
            if stat.S_ISLNK(visible.st_mode):
                if reject_symlinks:
                    raise _PreservationCaptureError(child_path, "history-symlink-unsafe")
                try:
                    link_target = str(os.readlink(name, dir_fd=directory_fd))
                    after = os.stat(name, dir_fd=directory_fd, follow_symlinks=False)
                except OSError as exc:
                    raise _PreservationCaptureError(child_path, "history-entry-unreadable") from exc
                if not _same_observed_node(visible, after) or not stat.S_ISLNK(after.st_mode):
                    raise _PreservationCaptureError(child_path, "history-entry-rebound")
                entry = DistributionTreeEntrySnapshot(
                    relative_path=child_path,
                    kind="symlink",
                    device=after.st_dev,
                    inode=after.st_ino,
                    ctime_ns=after.st_ctime_ns,
                    mode=mode,
                    link_count=after.st_nlink,
                    link_target=link_target,
                )
                captured.append(entry)
                immediate_entries.append(entry)
                target_snapshots[child_path] = _tree_entry_target_snapshot(
                    entry,
                    root_snapshot=root_snapshot,
                    parents=parent_bindings,
                )
                continue
            raise _PreservationCaptureError(child_path, "history-special-file-unsafe")
        after = os.fstat(directory_fd)
        if not _same_observed_node(before, after):
            raise _PreservationCaptureError(current_path, "history-directory-rebound")
        directory_captures[current_path] = (current_binding, tuple(immediate_entries))

    root_fd: int | None = None
    try:
        root_fd = _open_deprovision_directory(target_root, relative_root)
        opened_root = os.fstat(root_fd)
        if not _same_stat_identity(opened_root, root_binding):
            # The held root is already bound by _open_deprovision_directory;
            # this branch only guards an implementation race in the helper.
            raise _PreservationCaptureError(relative_root, "history-root-rebound")
        walk(root_fd, relative_root, root_binding, root_parents)
    except _PreservationCaptureError:
        raise
    except (OSError, DistributionPlanError) as exc:
        raise _PreservationCaptureError(relative_root, "history-root-unreadable") from exc
    finally:
        if root_fd is not None:
            os.close(root_fd)
    ordered = tuple(sorted(captured, key=lambda entry: os.fsencode(entry.relative_path)))
    return _DistributionTreeCapture(
        root_binding=root_binding,
        entries=ordered,
        tree_digest=_distribution_tree_digest(relative_root, root_binding, ordered),
        target_snapshots=tuple(sorted(target_snapshots.items(), key=lambda item: os.fsencode(item[0]))),
        directory_captures=tuple(sorted(directory_captures.items(), key=lambda item: os.fsencode(item[0]))),
    )


def _open_deprovision_directory(target_root: Path, relative_path: str) -> int:
    nofollow = getattr(os, "O_NOFOLLOW", None)
    directory = getattr(os, "O_DIRECTORY", None)
    if not isinstance(nofollow, int) or not isinstance(directory, int):
        raise DistributionPlanError("platform lacks required no-follow directory support")
    flags = os.O_RDONLY | nofollow | directory | getattr(os, "O_CLOEXEC", 0)
    try:
        current_fd = os.open(target_root, flags)
    except OSError as exc:
        raise DistributionPlanError("deprovision target root cannot be opened safely") from exc
    try:
        for component in () if relative_path == "." else PurePosixPath(relative_path).parts:
            visible = os.stat(component, dir_fd=current_fd, follow_symlinks=False)
            if stat.S_ISLNK(visible.st_mode) or not stat.S_ISDIR(visible.st_mode):
                raise DistributionPlanError("deprovision directory path is not a real directory")
            next_fd = os.open(component, flags, dir_fd=current_fd)
            opened = os.fstat(next_fd)
            if not _same_observed_node(visible, opened) or not stat.S_ISDIR(opened.st_mode):
                os.close(next_fd)
                raise DistributionPlanError("deprovision directory binding changed during observation")
            os.close(current_fd)
            current_fd = next_fd
        return current_fd
    except (OSError, DistributionPlanError):
        os.close(current_fd)
        raise


def _capture_immediate_directory_entries_from_fd(
    directory_fd: int,
    relative_path: str,
) -> tuple[PathIdentitySnapshot, tuple[DistributionTreeEntrySnapshot, ...]]:
    """Capture one held directory's lossless immediate child inventory."""

    entries: list[DistributionTreeEntrySnapshot] = []
    regular_flags = os.O_RDONLY | getattr(os, "O_NOFOLLOW", 0) | getattr(os, "O_CLOEXEC", 0)
    before = os.fstat(directory_fd)
    for name in sorted(
        os.listdir(directory_fd),
        key=os.fsencode,
    ):
        child_path = name if relative_path == "." else f"{relative_path}/{name}"
        visible = os.stat(name, dir_fd=directory_fd, follow_symlinks=False)
        if stat.S_ISDIR(visible.st_mode):
            entries.append(
                DistributionTreeEntrySnapshot(
                    relative_path=child_path,
                    kind="directory",
                    device=visible.st_dev,
                    inode=visible.st_ino,
                    ctime_ns=visible.st_ctime_ns,
                    mode=stat.S_IMODE(visible.st_mode),
                    link_count=visible.st_nlink,
                )
            )
            continue
        if stat.S_ISREG(visible.st_mode):
            child_fd = os.open(name, regular_flags, dir_fd=directory_fd)
            try:
                opened = os.fstat(child_fd)
                if not _same_observed_node(visible, opened) or not stat.S_ISREG(opened.st_mode):
                    raise DistributionPlanError("deprovision child binding changed during observation")
                digest = _digest_open_file(child_fd)
                after = os.fstat(child_fd)
                if _source_snapshot(opened) != _source_snapshot(after):
                    raise DistributionPlanError("deprovision child changed during observation")
                entries.append(
                    DistributionTreeEntrySnapshot(
                        relative_path=child_path,
                        kind="regular",
                        device=after.st_dev,
                        inode=after.st_ino,
                        ctime_ns=after.st_ctime_ns,
                        mode=stat.S_IMODE(after.st_mode),
                        link_count=after.st_nlink,
                        size=after.st_size,
                        sha256=digest,
                    )
                )
            finally:
                os.close(child_fd)
            continue
        if stat.S_ISLNK(visible.st_mode):
            link_target = str(os.readlink(name, dir_fd=directory_fd))
            after = os.stat(name, dir_fd=directory_fd, follow_symlinks=False)
            if not _same_observed_node(visible, after) or not stat.S_ISLNK(after.st_mode):
                raise DistributionPlanError("deprovision child changed during observation")
            entries.append(
                DistributionTreeEntrySnapshot(
                    relative_path=child_path,
                    kind="symlink",
                    device=after.st_dev,
                    inode=after.st_ino,
                    ctime_ns=after.st_ctime_ns,
                    mode=stat.S_IMODE(after.st_mode),
                    link_count=after.st_nlink,
                    link_target=link_target,
                )
            )
            continue
        raise _PreservationCaptureError(child_path, "special-managed-entry-unsafe")
    after_directory = os.fstat(directory_fd)
    if not _same_observed_node(before, after_directory):
        raise DistributionPlanError("deprovision directory changed during observation")
    binding = _snapshot_from_stat(relative_path, after_directory)
    return binding, tuple(entries)


def _capture_immediate_directory_entries(
    target_root: Path,
    relative_path: str,
) -> tuple[PathIdentitySnapshot, tuple[DistributionTreeEntrySnapshot, ...]]:
    """Capture one directory through the shared descriptor-bound observer."""

    directory_fd = _open_deprovision_directory(target_root, relative_path)
    try:
        return _capture_immediate_directory_entries_from_fd(directory_fd, relative_path)
    finally:
        os.close(directory_fd)


def _is_same_or_descendant(path: str, root: str) -> bool:
    return path == root or path.startswith(f"{root}/")


def _directory_child_semantic_payload(
    entry: DistributionTreeEntrySnapshot,
    *,
    classification: str,
    owner_source: str,
) -> dict[str, object]:
    payload: dict[str, object] = {
        "format_version": 1,
        "relative_path": entry.relative_path,
        "kind": entry.kind,
        "device": entry.device,
        "inode": entry.inode,
        "mode": entry.mode,
        "classification": classification,
        "owner_source": owner_source,
    }
    if entry.kind == "directory":
        return payload
    payload.update({"ctime_ns": entry.ctime_ns, "link_count": entry.link_count})
    if entry.kind == "regular":
        payload.update({"size": entry.size, "sha256": entry.sha256})
    else:
        payload["link_target"] = entry.link_target
    return payload


def _directory_child_digest(
    records: tuple[tuple[DistributionTreeEntrySnapshot, str, str], ...],
) -> str:
    payload = [
        _directory_child_semantic_payload(entry, classification=classification, owner_source=owner_source)
        for entry, classification, owner_source in sorted(records, key=lambda item: os.fsencode(item[0].relative_path))
    ]
    return hashlib.sha256(json.dumps(payload, sort_keys=True, separators=(",", ":")).encode("utf-8")).hexdigest()


def _leaf_parent_namespace_digest(
    entries: tuple[DistributionTreeEntrySnapshot, ...],
) -> str:
    """Hash a lossless immediate namespace using type-specific semantics."""

    payload = [
        _directory_child_semantic_payload(
            entry,
            classification="namespace",
            owner_source="leaf-parent-namespace",
        )
        for entry in sorted(entries, key=lambda item: os.fsencode(item.relative_path))
    ]
    return hashlib.sha256(json.dumps(payload, sort_keys=True, separators=(",", ":")).encode("utf-8")).hexdigest()


def _owned_descendant_digest(
    contract: DistributionDeprovisionContract,
    relative_root: str,
    known_directories: set[str],
) -> str:
    physical_by_path = {asset.path: asset for asset in contract.managed_assets}
    records: list[dict[str, object]] = []
    for path in sorted(known_directories):
        if _is_same_or_descendant(path, relative_root):
            records.append({"path": path, "expected_kind": "directory", "owner_source": "directory-closure"})
    for path, asset in sorted(physical_by_path.items()):
        if _is_same_or_descendant(path, relative_root):
            records.append({
                "path": path,
                "expected_kind": asset.identity.kind,
                "owner_source": "physical-provider",
                "source": (
                    _source_semantic_payload(asset.source_semantic_identity)
                    if asset.source_semantic_identity is not None
                    else None
                ),
            })
    for entry in contract.generated_state.entries:
        if _is_same_or_descendant(entry.path, relative_root):
            records.append({
                "path": entry.path,
                "expected_kind": entry.expected_kind,
                "owner_source": entry.origin,
                "semantic_contract": entry.semantic_contract,
            })
    for path in contract.generated_state.current_slots:
        if _is_same_or_descendant(path, relative_root):
            records.append({"path": path, "expected_kind": "generated-slot", "owner_source": "generated-producer"})
    for asset in contract.removable_shortcuts:
        if _is_same_or_descendant(asset.path, relative_root):
            records.append({"path": asset.path, "expected_kind": asset.identity.kind, "owner_source": "root-shortcut"})
    for asset in contract.target_only_assets:
        if _is_same_or_descendant(asset.path, relative_root):
            records.append({
                "path": asset.path,
                "expected_kind": asset.identity.kind,
                "owner_source": "workspace-marker",
            })
    if contract.manifest is not None:
        for item in contract.manifest.obsolete_exact_files:
            path = item["path"]
            if _is_same_or_descendant(path, relative_root):
                records.append({
                    "path": path,
                    "expected_kind": "historical-exact-catalog",
                    "owner_source": "historical-exact",
                    "catalog": item,
                })
        for item in contract.manifest.historical_shortcuts:
            path = item["path"]
            if _is_same_or_descendant(path, relative_root):
                records.append({
                    "path": path,
                    "expected_kind": item["kind"],
                    "owner_source": "historical-exact",
                    "catalog": item,
                })
    return hashlib.sha256(json.dumps(records, sort_keys=True, separators=(",", ":")).encode("utf-8")).hexdigest()


def _augment_deprovision_tree(
    target_root: Path,
    contract: DistributionDeprovisionContract,
    classified_actions: tuple[DistributionAction, ...],
    target_snapshots: tuple[tuple[str, DistributionTargetSnapshot], ...],
    *,
    directory_action_provenance: DistributionProvenance = "current",
    directory_action_reason: str = "owned-directory-empty-after-prune",
    additional_owner_sources: Mapping[str, str] | None = None,
    additional_managed_roots: tuple[str, ...] = (),
    additional_directory_captures: Mapping[
        str,
        tuple[PathIdentitySnapshot, tuple[DistributionTreeEntrySnapshot, ...]],
    ]
    | None = None,
) -> tuple[
    tuple[DistributionAction, ...],
    tuple[tuple[str, DistributionTargetSnapshot], ...],
    tuple[DistributionDirectoryMutationSnapshot, ...],
    tuple[DistributionLeafParentNamespaceWitness, ...],
    tuple[DistributionCollapsedAbsenceWitness, ...],
]:
    """Complete bounded classification, directory evidence, and absence collapse."""

    actions_by_path = {action.path: action for action in classified_actions}
    owned_leaf_paths = set(actions_by_path)
    owned_leaf_paths.update(entry.path for entry in contract.generated_state.entries)
    owned_leaf_paths.update(asset.path for asset in contract.removable_shortcuts)
    owned_leaf_paths.update(asset.path for asset in contract.target_only_assets)
    known_directories: set[str] = {
        root for root in contract.managed_roots if root not in owned_leaf_paths and root != "spec"
    }
    known_directories.update(additional_managed_roots)
    for path in owned_leaf_paths:
        parts = PurePosixPath(path).parts[:-1]
        known_directories.update("/".join(parts[:index]) for index in range(1, len(parts) + 1))
    known_directories.discard("")
    preserved_roots = set(contract.preserved_roots)
    generated_blocker_paths = {action.path for action in contract.generated_state.blockers}
    collapsed_roots: list[str] = []
    existing_directories: list[str] = []
    tree_blockers: list[DistributionAction] = []
    captured_directory_evidence = additional_directory_captures or {}
    for path in sorted(known_directories, key=lambda item: (len(PurePosixPath(item).parts), item)):
        if any(_is_same_or_descendant(path, root) for root in collapsed_roots):
            continue
        captured = captured_directory_evidence.get(path)
        if captured is not None:
            binding, _entries = captured
            if binding.exists and binding.file_type == "directory":
                existing_directories.append(path)
            elif not binding.exists:
                collapsed_roots.append(path)
            else:
                tree_blockers.append(_generated_state_blocker(path, "managed-directory-boundary-unsafe"))
            continue
        observation = _observe_target(target_root, path)
        if observation.state == "missing":
            collapsed_roots.append(path)
        elif observation.state == "directory":
            existing_directories.append(path)
        else:
            tree_blockers.append(_generated_state_blocker(path, "managed-directory-boundary-unsafe"))

    # A missing owned leaf is still part of the assessed namespace.  Keep a
    # durable witness for it even when it has no directory subtree to
    # collapse; otherwise an assessment-time absence at the repository root
    # could reappear between mutation and post-verification unnoticed.
    classified_snapshots = dict(target_snapshots)
    classified_missing_leaf_paths = {
        path
        for path, snapshot in classified_snapshots.items()
        if path in owned_leaf_paths
        and not snapshot.target.exists
        and (action := actions_by_path.get(path)) is not None
        and action.action == "prune"
        and action.provenance == "missing"
    }
    collapsed_leaf_paths = [
        path
        for path in sorted(owned_leaf_paths)
        if path in classified_missing_leaf_paths
        and not any(_is_same_or_descendant(path, root) for root in collapsed_roots)
    ]

    filtered_actions = tuple(
        action
        for action in classified_actions
        if not any(_is_same_or_descendant(action.path, root) and action.path != root for root in collapsed_roots)
    )
    actions_by_path = {action.path: action for action in filtered_actions}
    captured_by_directory: dict[str, tuple[PathIdentitySnapshot, tuple[DistributionTreeEntrySnapshot, ...]]] = {}
    if additional_directory_captures:
        captured_by_directory.update({
            path: capture for path, capture in additional_directory_captures.items() if path in known_directories
        })
    owner_by_path: dict[str, str] = {asset.path: "physical-provider" for asset in contract.managed_assets}
    owner_by_path.update({asset.path: "root-shortcut" for asset in contract.removable_shortcuts})
    owner_by_path.update({asset.path: "workspace-marker" for asset in contract.target_only_assets})
    owner_by_path.update({entry.path: entry.origin for entry in contract.generated_state.entries})
    if contract.manifest is not None:
        for item in (*contract.manifest.obsolete_exact_files, *contract.manifest.historical_shortcuts):
            owner_by_path.setdefault(item["path"], "historical-exact")
    if additional_owner_sources:
        owner_by_path.update(additional_owner_sources)
    for path in existing_directories:
        if path in captured_by_directory:
            continue
        try:
            captured_by_directory[path] = _capture_immediate_directory_entries(target_root, path)
        except _PreservationCaptureError as exc:
            tree_blockers.append(_generated_state_blocker(exc.path, exc.reason))
        except (OSError, DistributionPlanError):
            tree_blockers.append(_generated_state_blocker(path, "managed-directory-observation-unsafe"))

    leaf_parent_paths = {
        PurePosixPath(action.path).parent.as_posix()
        for action in filtered_actions
        if action.action == "prune"
        and not action.blocked
        and classified_snapshots.get(action.path) is not None
        and classified_snapshots[action.path].target.exists
    }
    leaf_parent_paths.discard(".")
    protocol_paths = {
        _DISTRIBUTION_RETRY_MARKER_REL.as_posix(),
        _DISTRIBUTION_JOURNAL_REL.as_posix(),
        _UNINSTALL_RETRY_MARKER_REL.as_posix(),
    }
    leaf_parent_namespace_witnesses: list[DistributionLeafParentNamespaceWitness] = []
    for parent_path in sorted(leaf_parent_paths, key=os.fsencode):
        captured = captured_by_directory.get(parent_path)
        if captured is None:
            tree_blockers.append(_generated_state_blocker(parent_path, "leaf-parent-namespace-unavailable"))
            continue
        binding, captured_entries = captured
        entries = tuple(entry for entry in captured_entries if entry.relative_path not in protocol_paths)
        leaf_parent_namespace_witnesses.append(
            DistributionLeafParentNamespaceWitness(
                relative_path=parent_path,
                binding=binding,
                initial_entries=entries,
                initial_namespace_digest=_leaf_parent_namespace_digest(entries),
            )
        )

    explained_protocol_paths = {
        "spec-dock/.distribution-retry.json",
        "spec-dock/.distribution-journal.json",
        "spec-dock/.uninstall-retry.json",
    }
    for _directory_path, (_binding, entries) in captured_by_directory.items():
        for entry in entries:
            child_path = entry.relative_path
            explained = (
                child_path in known_directories
                or child_path in actions_by_path
                or child_path in preserved_roots
                or child_path in generated_blocker_paths
                or child_path in explained_protocol_paths
            )
            if explained:
                continue
            reason = (
                "legacy-generated-identity-unproven"
                if _is_same_or_descendant(child_path, "spec-dock/.work")
                else "unknown-managed-entry"
            )
            tree_blockers.append(_generated_state_blocker(child_path, reason))

    removable_directories: set[str] = set()
    directory_actions: list[DistributionAction] = []
    directory_snapshots: list[DistributionDirectoryMutationSnapshot] = []
    snapshots_by_path = dict(target_snapshots)
    empty_digest = _directory_child_digest(())
    for path in sorted(existing_directories, key=lambda item: (-len(PurePosixPath(item).parts), item)):
        captured = captured_by_directory.get(path)
        if captured is None or path == "spec-dock" or path in preserved_roots:
            continue
        binding, entries = captured
        evidence: list[DistributionImmediateChildEvidence] = []
        semantic_records: list[tuple[DistributionTreeEntrySnapshot, str, str]] = []
        removable = True
        for entry in entries:
            child_path = entry.relative_path
            if child_path in preserved_roots or child_path in generated_blocker_paths:
                removable = False
                classification = "preserve"
                owner_source = "preservation-policy"
            elif child_path in known_directories:
                classification = "remove-empty-directory"
                owner_source = "directory-closure"
                if child_path not in removable_directories:
                    removable = False
                else:
                    evidence.append(
                        DistributionImmediateChildEvidence(
                            child_path=child_path,
                            child_kind="directory",
                            action_path=child_path,
                            required_checkpoint="published",
                            expected_postcondition={"path": child_path, "exists": False},
                        )
                    )
            else:
                action = actions_by_path.get(child_path)
                classification = action.action if action is not None else "block"
                owner_source = owner_by_path.get(child_path, "unknown")
                if (
                    action is None
                    or action.blocked
                    or action.action != "prune"
                    or (entry.kind == "regular" and entry.link_count != 1)
                ):
                    removable = False
                else:
                    evidence.append(
                        DistributionImmediateChildEvidence(
                            child_path=child_path,
                            child_kind="leaf",
                            action_path=child_path,
                            required_checkpoint="published",
                            expected_postcondition={"path": child_path, "exists": False},
                        )
                    )
            semantic_records.append((entry, classification, owner_source))
        if not removable:
            continue
        action = DistributionAction(
            path=path,
            operation="uninstall",
            action="remove-empty-directory",
            provenance=directory_action_provenance,
            reason=directory_action_reason,
        )
        directory_actions.append(action)
        removable_directories.add(path)
        snapshot = snapshots_by_path.get(path)
        if snapshot is None:
            observation = _observe_target(target_root, path)
            if observation.snapshot is None:
                raise DistributionPlanError("deprovision directory action is missing its target snapshot")
            snapshot = observation.snapshot
        snapshots_by_path[path] = snapshot
        directory_snapshots.append(
            DistributionDirectoryMutationSnapshot(
                relative_path=path,
                binding=binding,
                initial_entries=entries,
                initial_child_digest=_directory_child_digest(tuple(semantic_records)),
                immediate_child_evidence=tuple(sorted(evidence, key=lambda item: os.fsencode(item.child_path))),
                expected_remaining_child_digest=empty_digest,
            )
        )

    absence_witnesses: list[DistributionCollapsedAbsenceWitness] = []
    root_info = os.lstat(target_root)
    for relative_root in sorted({*collapsed_roots, *collapsed_leaf_paths}):
        parent = PurePosixPath(relative_root).parent
        anchor_path = "." if parent == PurePosixPath() else parent.as_posix()
        while anchor_path in removable_directories:
            parent = PurePosixPath(anchor_path).parent
            anchor_path = "." if parent == PurePosixPath() else parent.as_posix()
        if anchor_path == ".":
            surviving_anchor = _snapshot_from_stat(".", root_info)
            anchor_parts: tuple[str, ...] = ()
        else:
            anchor_observation = _observe_target(target_root, anchor_path)
            if anchor_observation.state != "directory" or anchor_observation.snapshot is None:
                tree_blockers.append(_generated_state_blocker(relative_root, "unproven-parent-gap"))
                continue
            surviving_anchor = anchor_observation.snapshot.target
            anchor_parts = PurePosixPath(anchor_path).parts
        root_parts = PurePosixPath(relative_root).parts
        missing_suffix = tuple(root_parts[len(anchor_parts) :])
        if not missing_suffix:
            tree_blockers.append(_generated_state_blocker(relative_root, "unproven-parent-gap"))
            continue
        absence_witnesses.append(
            DistributionCollapsedAbsenceWitness(
                relative_root=relative_root,
                anchor_path=anchor_path,
                surviving_anchor=surviving_anchor,
                missing_suffix=missing_suffix,
                owned_descendant_paths_digest=_owned_descendant_digest(
                    contract,
                    relative_root,
                    known_directories,
                ),
                reason="owned-subtree-already-absent",
            )
        )

    actions = (*filtered_actions, *directory_actions, *tree_blockers)
    return (
        actions,
        tuple(sorted(snapshots_by_path.items())),
        tuple(
            sorted(
                directory_snapshots,
                key=lambda item: (-len(PurePosixPath(item.relative_path).parts), item.relative_path),
            )
        ),
        tuple(
            sorted(
                leaf_parent_namespace_witnesses,
                key=lambda item: os.fsencode(item.relative_path),
            )
        ),
        tuple(sorted(absence_witnesses, key=lambda item: item.relative_root)),
    )


def build_deprovision_workspace_assessment(
    install_root: Path,
    *,
    manifest_path: Path,
    scaffold_root: Path,
    target_root: Path,
    expected_root_identity: DistributionRootIdentity,
) -> WorkspaceAssessment:
    """Build the single-contract, read-only deprovision assessment."""

    contract = build_deprovision_contract(
        install_root,
        manifest_path=manifest_path,
        scaffold_root=scaffold_root,
        target_root=target_root,
        expected_root_identity=expected_root_identity,
    )
    if contract.manifest is None:
        raise DistributionPlanError("deprovision contract is missing its validated manifest")
    current_assets = tuple(
        asset
        for asset in contract.managed_assets
        if asset.source_semantic_identity is not None
        and asset.source_semantic_identity.canonical_source_path.startswith("install-root/")
    )
    scaffold_assets = tuple(
        asset
        for asset in contract.managed_assets
        if asset.source_semantic_identity is not None
        and asset.source_semantic_identity.canonical_source_path.startswith("spec-dock-scaffold/")
    )
    generated_assets = (
        tuple(
            DistributionAsset(
                path=entry.path,
                identity=entry.identity,
                generated_observed_target=entry.observed,
            )
            for entry in contract.generated_state.entries
        )
        + contract.target_only_assets
    )
    classified_actions, target_snapshots = _classify_target(
        target_root=Path(target_root),
        current_assets=current_assets,
        operation="uninstall",
        manifest=contract.manifest,
        scaffold_assets=(*scaffold_assets, *generated_assets),
    )
    (
        tree_actions,
        target_snapshots,
        directory_snapshots,
        leaf_parent_namespace_witnesses,
        absence_witnesses,
    ) = _augment_deprovision_tree(
        Path(target_root),
        contract,
        classified_actions,
        target_snapshots,
    )
    preservation_witnesses: list[DistributionPreservationWitness] = []
    preservation_blockers: list[DistributionAction] = []
    for relative_root in sorted(contract.preserved_roots):
        witness, blockers = _capture_preservation_witness(Path(target_root), relative_root)
        if witness is not None:
            preservation_witnesses.append(witness)
        preservation_blockers.extend(blockers)
    actions = tuple(
        sorted(
            (*tree_actions, *contract.generated_state.blockers, *preservation_blockers),
            key=lambda action: (
                -len(PurePosixPath(action.path).parts) if action.action == "remove-empty-directory" else 0,
                action.path,
                action.action,
                action.reason,
            ),
        )
    )
    plan = DistributionPlan(
        current_assets=current_assets,
        actions=actions,
        manifest=contract.manifest,
        scaffold_root=Path(scaffold_root),
        install_root=Path(install_root),
        manifest_path=Path(manifest_path),
        target_root=Path(target_root),
        operation="uninstall",
        target_snapshots=target_snapshots,
        scaffold_assets=(*scaffold_assets, *generated_assets),
    )
    return WorkspaceAssessment(
        intent="deprovision",
        root_identity=expected_root_identity,
        contract_identity=contract.contract_digest,
        distribution_plan=plan,
        actions=actions,
        blockers=tuple(action for action in actions if action.blocked),
        directory_snapshots=directory_snapshots,
        leaf_parent_namespace_witnesses=leaf_parent_namespace_witnesses,
        preservation_witnesses=tuple(preservation_witnesses),
        absence_witnesses=absence_witnesses,
        deprovision_contract=contract,
    )


def _explicit_spec_history_purge_contract_digest(
    *,
    deprovision_contract: DistributionDeprovisionContract,
    history_root: str,
    history_tree_digest: str,
) -> str:
    payload = {
        "format_version": 1,
        "intent": "purge",
        "authority": "explicit-spec-history-purge",
        "history_root": history_root,
        "history_tree_digest": history_tree_digest,
        "deprovision_contract_digest": deprovision_contract.contract_digest,
        "preserved_roots": list(deprovision_contract.preserved_roots),
        "journal_protocol_version": _DISTRIBUTION_JOURNAL_PROTOCOL_VERSION,
    }
    return hashlib.sha256(json.dumps(payload, sort_keys=True, separators=(",", ":")).encode("utf-8")).hexdigest()


def _history_tree_entry_from_journal_record(
    record: OperationJournalAction,
) -> DistributionTreeEntrySnapshot:
    """Reconstruct one purge tree entry solely from its journal precondition."""

    precondition = record.precondition
    kind = precondition.get("file_type")
    if kind not in {"regular", "directory"}:
        raise DistributionApplyError("journal-plan-mismatch")
    identity = precondition.get("identity")
    if kind == "regular":
        if (
            not isinstance(identity, dict)
            or identity.get("kind") != "regular"
            or not isinstance(identity.get("sha256"), str)
            or _SHA256_RE.fullmatch(identity["sha256"]) is None
        ):
            raise DistributionApplyError("journal-plan-mismatch")
        size = precondition.get("size")
        if isinstance(size, bool) or not isinstance(size, int) or size < 0:
            raise DistributionApplyError("journal-plan-mismatch")
        sha256 = identity["sha256"]
    else:
        if identity is not None or precondition.get("size") is not None:
            raise DistributionApplyError("journal-plan-mismatch")
        size = None
        sha256 = None
    values = (
        precondition.get("device"),
        precondition.get("inode"),
        precondition.get("ctime_ns"),
        precondition.get("link_count"),
        precondition.get("mode"),
    )
    if any(isinstance(value, bool) or not isinstance(value, int) or value <= 0 for value in values[:4]):
        raise DistributionApplyError("journal-plan-mismatch")
    if isinstance(values[4], bool) or not isinstance(values[4], int) or not 0 <= values[4] <= 0o777:
        raise DistributionApplyError("journal-plan-mismatch")
    return DistributionTreeEntrySnapshot(
        relative_path=record.path,
        kind=cast("DistributionTreeEntryKind", kind),
        device=cast("int", values[0]),
        inode=cast("int", values[1]),
        ctime_ns=cast("int", values[2]),
        mode=cast("int", values[4]),
        link_count=cast("int", values[3]),
        size=size,
        sha256=sha256,
    )


def _reconstruct_explicit_spec_history_purge_tree(
    journal: OperationJournal,
) -> tuple[PathIdentitySnapshot, tuple[DistributionTreeEntrySnapshot, ...], str]:
    if journal.intent != "purge" or journal.authority != _journal_authority_for_intent("purge"):
        raise DistributionApplyError("journal-contract-mismatch")
    records = tuple(
        record for record in journal.actions if _is_same_or_descendant(record.path, _EXPLICIT_SPEC_HISTORY_ROOT)
    )
    if len({record.path for record in records}) != len(records):
        raise DistributionApplyError("journal-plan-mismatch")
    if not records:
        empty_root_binding = _missing_snapshot(_EXPLICIT_SPEC_HISTORY_ROOT)
        empty_entries: tuple[DistributionTreeEntrySnapshot, ...] = ()
        return (
            empty_root_binding,
            empty_entries,
            _distribution_tree_digest(_EXPLICIT_SPEC_HISTORY_ROOT, empty_root_binding, empty_entries),
        )
    entries: list[DistributionTreeEntrySnapshot] = []
    root_binding: PathIdentitySnapshot | None = None
    for record in records:
        if record.action == "prune":
            if record.provenance != "unknown" or record.reason != "explicit-spec-history-purge":
                raise DistributionApplyError("journal-plan-mismatch")
            entry = _history_tree_entry_from_journal_record(record)
        elif record.action == "remove-empty-directory":
            if record.provenance != "unknown" or record.reason != "explicit-spec-history-purge-directory":
                raise DistributionApplyError("journal-plan-mismatch")
            entry = _history_tree_entry_from_journal_record(record)
            if entry.kind != "directory":
                raise DistributionApplyError("journal-plan-mismatch")
        else:
            raise DistributionApplyError("journal-plan-mismatch")
        if entry.relative_path == _EXPLICIT_SPEC_HISTORY_ROOT:
            root_binding = PathIdentitySnapshot(
                relative_path=entry.relative_path,
                exists=True,
                device=entry.device,
                inode=entry.inode,
                ctime_ns=entry.ctime_ns,
                file_type="directory",
                link_count=entry.link_count,
                mode=entry.mode,
            )
            continue
        entries.append(entry)
    if root_binding is None:
        # A valid purge with no root directory action represents an absent
        # history root and therefore cannot contain descendant entries.
        if entries:
            raise DistributionApplyError("journal-plan-mismatch")
        root_binding = _missing_snapshot(_EXPLICIT_SPEC_HISTORY_ROOT)
    ordered = tuple(sorted(entries, key=lambda entry: os.fsencode(entry.relative_path)))
    return root_binding, ordered, _distribution_tree_digest(_EXPLICIT_SPEC_HISTORY_ROOT, root_binding, ordered)


def _reconstruct_explicit_spec_history_purge_contract(
    target_root: Path,
    *,
    deprovision_contract: DistributionDeprovisionContract,
    journal: OperationJournal,
) -> DistributionExplicitSpecHistoryPurgeContract:
    """Reconstruct purge authority from journal evidence after partial removal."""

    if _root_identity_for_assessment(Path(target_root)) != journal.root_identity:
        raise DistributionApplyError("journal-root-mismatch")
    root_binding, entries, tree_digest = _reconstruct_explicit_spec_history_purge_tree(journal)
    contract_digest = _explicit_spec_history_purge_contract_digest(
        deprovision_contract=deprovision_contract,
        history_root=_EXPLICIT_SPEC_HISTORY_ROOT,
        history_tree_digest=tree_digest,
    )
    if journal.contract_identity != contract_digest:
        raise DistributionApplyError("journal-contract-mismatch")
    return DistributionExplicitSpecHistoryPurgeContract(
        deprovision_contract=deprovision_contract,
        history_root=_EXPLICIT_SPEC_HISTORY_ROOT,
        history_root_binding=root_binding,
        history_entries=entries,
        history_tree_digest=tree_digest,
        authority=_journal_authority_for_intent("purge"),
        contract_digest=contract_digest,
    )


def _build_explicit_spec_history_purge_contract_and_capture(
    install_root: Path,
    *,
    manifest_path: Path,
    scaffold_root: Path,
    target_root: Path,
    expected_root_identity: DistributionRootIdentity,
    recovery_journal: OperationJournal | None = None,
) -> tuple[DistributionExplicitSpecHistoryPurgeContract, _DistributionTreeCapture]:
    """Build purge authority and retain its single descriptor-bound capture."""

    component = _build_deprovision_contract(
        install_root,
        manifest_path=manifest_path,
        scaffold_root=scaffold_root,
        target_root=target_root,
        expected_root_identity=expected_root_identity,
        recovery_journal=recovery_journal,
        preserved_roots=("spec-dock/.workbench",),
        additional_managed_roots=(_EXPLICIT_SPEC_HISTORY_ROOT,),
    )
    if recovery_journal is not None:
        recovered_target_only_assets = _deprovision_recovery_target_only_assets(recovery_journal)
        if recovered_target_only_assets != component.target_only_assets:
            if component.manifest is None:
                raise DistributionApplyError("journal-contract-mismatch")
            component = replace(
                component,
                target_only_assets=recovered_target_only_assets,
                contract_digest=_deprovision_contract_digest(
                    physical_assets=component.managed_assets,
                    shortcuts=component.removable_shortcuts,
                    target_only_assets=recovered_target_only_assets,
                    managed_roots=component.managed_roots,
                    preserved_roots=component.preserved_roots,
                    generated_state_digest=component.generated_state.contract_digest,
                    manifest=component.manifest,
                ),
            )
        contract = _reconstruct_explicit_spec_history_purge_contract(
            target_root,
            deprovision_contract=component,
            journal=recovery_journal,
        )
        return (
            contract,
            _DistributionTreeCapture(
                root_binding=contract.history_root_binding,
                entries=contract.history_entries,
                tree_digest=contract.history_tree_digest,
                target_snapshots=(),
                directory_captures=(),
            ),
        )
    else:
        try:
            capture = _capture_distribution_tree_details(
                Path(target_root),
                _EXPLICIT_SPEC_HISTORY_ROOT,
                reject_symlinks=True,
                require_single_link_regulars=True,
            )
        except _PreservationCaptureError as exc:
            observation = _observe_target(Path(target_root), _EXPLICIT_SPEC_HISTORY_ROOT)
            if observation.snapshot is None:
                root_binding = _missing_snapshot(_EXPLICIT_SPEC_HISTORY_ROOT)
            else:
                root_binding = observation.snapshot.target
            entries: tuple[DistributionTreeEntrySnapshot, ...] = ()
            tree_digest = _distribution_tree_digest(_EXPLICIT_SPEC_HISTORY_ROOT, root_binding, entries)
            capture = _DistributionTreeCapture(
                root_binding=root_binding,
                entries=entries,
                tree_digest=tree_digest,
                target_snapshots=((_EXPLICIT_SPEC_HISTORY_ROOT, observation.snapshot),)
                if observation.snapshot is not None
                else (),
                directory_captures=(),
                blockers=(_generated_state_blocker(exc.path, exc.reason),),
            )
    root_binding = capture.root_binding
    entries = capture.entries
    tree_digest = capture.tree_digest
    contract_digest = _explicit_spec_history_purge_contract_digest(
        deprovision_contract=component,
        history_root=_EXPLICIT_SPEC_HISTORY_ROOT,
        history_tree_digest=tree_digest,
    )
    return (
        DistributionExplicitSpecHistoryPurgeContract(
            deprovision_contract=component,
            history_root=_EXPLICIT_SPEC_HISTORY_ROOT,
            history_root_binding=root_binding,
            history_entries=entries,
            history_tree_digest=tree_digest,
            authority=_journal_authority_for_intent("purge"),
            contract_digest=contract_digest,
        ),
        capture,
    )


def build_explicit_spec_history_purge_contract(
    install_root: Path,
    *,
    manifest_path: Path,
    scaffold_root: Path,
    target_root: Path,
    expected_root_identity: DistributionRootIdentity,
    recovery_journal: OperationJournal | None = None,
) -> DistributionExplicitSpecHistoryPurgeContract:
    """Build the fixed-root explicit history purge contract."""

    contract, _capture = _build_explicit_spec_history_purge_contract_and_capture(
        install_root,
        manifest_path=manifest_path,
        scaffold_root=scaffold_root,
        target_root=target_root,
        expected_root_identity=expected_root_identity,
        recovery_journal=recovery_journal,
    )
    return contract


def build_explicit_spec_history_purge_assessment(
    install_root: Path,
    *,
    manifest_path: Path,
    scaffold_root: Path,
    target_root: Path,
    expected_root_identity: DistributionRootIdentity,
    recovery_journal: OperationJournal | None = None,
) -> WorkspaceAssessment:
    """Build a complete read-only purge assessment for the fixed history root."""

    purge_contract, history_capture = _build_explicit_spec_history_purge_contract_and_capture(
        install_root,
        manifest_path=manifest_path,
        scaffold_root=scaffold_root,
        target_root=target_root,
        expected_root_identity=expected_root_identity,
        recovery_journal=recovery_journal,
    )
    contract = purge_contract.deprovision_contract
    if contract.manifest is None:
        raise DistributionPlanError("deprovision contract is missing its validated manifest")
    current_assets = tuple(
        asset
        for asset in contract.managed_assets
        if asset.source_semantic_identity is not None
        and asset.source_semantic_identity.canonical_source_path.startswith("install-root/")
    )
    scaffold_assets = tuple(
        asset
        for asset in contract.managed_assets
        if asset.source_semantic_identity is not None
        and asset.source_semantic_identity.canonical_source_path.startswith("spec-dock-scaffold/")
    )
    generated_assets = (
        tuple(
            DistributionAsset(path=entry.path, identity=entry.identity, generated_observed_target=entry.observed)
            for entry in contract.generated_state.entries
        )
        + contract.target_only_assets
    )
    classified_actions, target_snapshots = _classify_target(
        target_root=Path(target_root),
        current_assets=current_assets,
        operation="uninstall",
        manifest=contract.manifest,
        scaffold_assets=(*scaffold_assets, *generated_assets),
    )
    history_actions: list[DistributionAction] = []
    history_snapshots = dict(target_snapshots)
    history_blockers: list[DistributionAction] = list(history_capture.blockers)
    history_entries = purge_contract.history_entries
    if recovery_journal is None:
        captured_history_snapshots = dict(history_capture.target_snapshots)
        history_snapshots.update(captured_history_snapshots)
        for entry in history_entries:
            if entry.kind == "regular":
                history_actions.append(
                    DistributionAction(
                        path=entry.relative_path,
                        operation="uninstall",
                        action="prune",
                        provenance="unknown",
                        reason="explicit-spec-history-purge",
                    )
                )
                if entry.relative_path not in captured_history_snapshots:
                    history_blockers.append(_generated_state_blocker(entry.relative_path, "history-entry-unreadable"))
    else:
        for record in recovery_journal.actions:
            if not _is_same_or_descendant(record.path, _EXPLICIT_SPEC_HISTORY_ROOT):
                continue
            history_actions.append(
                DistributionAction(
                    path=record.path,
                    operation="uninstall",
                    action=record.action,
                    provenance=record.provenance,
                    reason=record.reason,
                )
            )
            observed = _observe_target(Path(target_root), record.path)
            if observed.snapshot is not None:
                history_snapshots[record.path] = observed.snapshot
    combined = (*classified_actions, *history_actions, *history_blockers)
    additional_owner_sources = {entry.relative_path: "explicit-spec-history-purge" for entry in history_entries}
    (
        tree_actions,
        combined_snapshots,
        directory_snapshots,
        leaf_parent_namespace_witnesses,
        absence_witnesses,
    ) = _augment_deprovision_tree(
        Path(target_root),
        contract,
        combined,
        tuple(history_snapshots.items()),
        additional_owner_sources=additional_owner_sources,
        additional_managed_roots=tuple(
            sorted(
                {entry.relative_path for entry in history_entries if entry.kind == "directory"}
                | ({_EXPLICIT_SPEC_HISTORY_ROOT} if purge_contract.history_root_binding.exists else set())
            )
        ),
        additional_directory_captures=dict(history_capture.directory_captures),
    )
    history_directory_paths = {entry.relative_path for entry in history_entries if entry.kind == "directory"}
    if purge_contract.history_root_binding.exists:
        history_directory_paths.add(_EXPLICIT_SPEC_HISTORY_ROOT)
    tree_actions = tuple(
        replace(
            action,
            provenance="unknown",
            reason="explicit-spec-history-purge-directory",
        )
        if (action.action == "remove-empty-directory" and action.path in history_directory_paths)
        else action
        for action in tree_actions
    )
    preservation_witnesses: list[DistributionPreservationWitness] = []
    preservation_blockers: list[DistributionAction] = []
    for relative_root in sorted(contract.preserved_roots):
        witness, blockers = _capture_preservation_witness(Path(target_root), relative_root)
        if witness is not None:
            preservation_witnesses.append(witness)
        preservation_blockers.extend(blockers)
    actions = tuple(
        sorted(
            (*tree_actions, *contract.generated_state.blockers, *preservation_blockers),
            key=lambda action: (
                -len(PurePosixPath(action.path).parts) if action.action == "remove-empty-directory" else 0,
                action.path,
                action.action,
                action.reason,
            ),
        )
    )
    plan = DistributionPlan(
        current_assets=current_assets,
        actions=actions,
        manifest=contract.manifest,
        scaffold_root=Path(scaffold_root),
        install_root=Path(install_root),
        manifest_path=Path(manifest_path),
        target_root=Path(target_root),
        operation="uninstall",
        target_snapshots=combined_snapshots,
        scaffold_assets=(*scaffold_assets, *generated_assets),
    )
    return WorkspaceAssessment(
        intent="purge",
        root_identity=expected_root_identity,
        contract_identity=purge_contract.contract_digest,
        distribution_plan=plan,
        actions=actions,
        blockers=tuple(action for action in actions if action.blocked),
        directory_snapshots=directory_snapshots,
        leaf_parent_namespace_witnesses=leaf_parent_namespace_witnesses,
        preservation_witnesses=tuple(preservation_witnesses),
        absence_witnesses=absence_witnesses,
        deprovision_contract=contract,
        explicit_spec_history_purge_contract=purge_contract,
    )


def _historical_records(manifest: DistributionManifest) -> tuple[dict[str, Any], ...]:
    records: list[dict[str, Any]] = list(manifest.historical_current_identities)
    for version in manifest.recognized_workspace_versions:
        records.extend(version["anchors"])
        version_bytes = f"{version['version']}\n".encode()
        records.append({
            "path": "spec-dock/spec-dock.version",
            "kind": "regular",
            "sha256": hashlib.sha256(version_bytes).hexdigest(),
        })
    for item in manifest.obsolete_exact_files:
        records.extend(item["identities"])
    records.extend(manifest.historical_shortcuts)
    return tuple(records)


def _trusted_manifest_matches(
    target_root: Path,
    path: str,
    actual: DistributionIdentity,
    manifest: DistributionManifest,
    *,
    require_mode: bool = False,
) -> bool:
    for trusted in manifest.trusted_consumer_manifests:
        manifest_observation = _observe_target(target_root, trusted["path"])
        manifest_identity = manifest_observation.identity
        envelope_matches = (
            (
                _removal_identity_matches(manifest_identity, trusted)
                if require_mode
                else _identity_matches(manifest_identity, trusted, include_mode=False)
            )
            if manifest_identity is not None
            else False
        )
        if not envelope_matches:
            continue
        for claim in trusted["claims"]:
            if claim["path"] != path:
                continue
            matches = (
                _removal_identity_matches(actual, claim)
                if require_mode
                else _identity_matches(actual, claim, include_mode=False)
            )
            if matches:
                return True
    return False


def _historical_provenance(
    target_root: Path,
    path: str,
    actual: DistributionIdentity,
    manifest: DistributionManifest,
    *,
    require_mode: bool = False,
) -> str | None:
    for record in _historical_records(manifest):
        if record["path"] != path:
            continue
        matches = (
            _removal_identity_matches(actual, record)
            if require_mode
            else _identity_matches(actual, record, include_mode=False)
        )
        if matches:
            return "direct"
    if _trusted_manifest_matches(target_root, path, actual, manifest, require_mode=require_mode):
        return "trusted-manifest"
    return None


def _target_identity_specs(
    current_assets: tuple[DistributionAsset, ...],
    scaffold_assets: tuple[DistributionAsset, ...] = (),
) -> dict[str, DistributionIdentity]:
    # Historical shortcut records are evidence only.  They must never create
    # a new Fresh target; the shipped canonical shortcut is the sole Current
    # shortcut and is represented by the synthetic rule above.
    return {
        **_CURRENT_SHORTCUTS,
        **{asset.path: asset.identity for asset in current_assets},
        **{asset.path: asset.identity for asset in scaffold_assets},
    }


def _blocked_action(
    path: str,
    operation: DistributionOperation,
    reason: str,
    *,
    provenance: DistributionProvenance = "unknown",
    action: DistributionActionName = "block",
) -> DistributionAction:
    return DistributionAction(path, operation, action, provenance, reason, blocked=True)


def _classify_current_target(
    *,
    target_root: Path,
    path: str,
    expected: DistributionIdentity,
    operation: DistributionOperation,
    manifest: DistributionManifest,
    generated_path: bool = False,
    refreshable_existing_identities: tuple[DistributionIdentity, ...] | None = None,
    observation: _TargetObservation | None = None,
) -> DistributionAction:
    if observation is None:
        observation = _observe_target(target_root, path)
    if observation.state == "missing":
        if operation == "uninstall":
            return DistributionAction(path, operation, "prune", "missing", "already-absent")
        return DistributionAction(path, operation, "create", "missing", "target-missing")
    if observation.state == "directory":
        return _blocked_action(path, operation, "exact-path-directory")
    if observation.state == "symlink-container":
        return _blocked_action(path, operation, "symlink-container")
    if observation.state == "non-directory-container":
        return _blocked_action(path, operation, "non-directory-container")
    if observation.state in {
        "root-symlink",
        "root-non-directory",
        "root-error",
        "parent-error",
        "target-error",
        "special",
    }:
        return _blocked_action(path, operation, "unsafe-target-path")

    actual = observation.identity
    if actual is None:
        return _blocked_action(path, operation, "unsafe-target-path")
    generated_refresh_allowed = generated_path and (
        refreshable_existing_identities is None or actual in refreshable_existing_identities
    )
    if actual.kind != expected.kind:
        if (
            generated_refresh_allowed
            and operation in {"update", "init-force"}
            and {actual.kind, expected.kind} <= {"regular", "symlink"}
        ):
            if observation.link_count is not None and observation.link_count > 1:
                return _blocked_action(path, operation, "hard-link-mutation-unsafe", provenance="current")
            return DistributionAction(path, operation, "upgrade", "current", "generated-state-refresh")
        return _blocked_action(path, operation, "exact-path-symlink" if actual.kind == "symlink" else "exact-path-type")
    if actual.kind == "symlink" and actual.target != expected.target:
        if generated_refresh_allowed and operation in {"update", "init-force"}:
            if observation.link_count is not None and observation.link_count > 1:
                return _blocked_action(path, operation, "hard-link-mutation-unsafe", provenance="current")
            return DistributionAction(path, operation, "upgrade", "current", "generated-state-refresh")
        provenance = _historical_provenance(
            target_root,
            path,
            actual,
            manifest,
            require_mode=operation == "uninstall",
        )
        if provenance is not None and operation in {"update", "init-force"}:
            if observation.link_count is not None and observation.link_count > 1:
                return _blocked_action(
                    path,
                    operation,
                    "hard-link-mutation-unsafe",
                    provenance="historical",
                )
            return DistributionAction(path, operation, "upgrade", "historical", "direct-historical-identity-match")
        if provenance is not None and operation == "uninstall":
            if observation.link_count is not None and observation.link_count > 1:
                return _blocked_action(
                    path,
                    operation,
                    "hard-link-mutation-unsafe",
                    provenance="historical",
                )
            return DistributionAction(path, operation, "prune", "historical", "historical-identity-match")
        if provenance is not None:
            return _blocked_action(
                path,
                operation,
                "historical-identity-fresh-preserve",
                provenance="historical",
                action="preserve",
            )
        return _blocked_action(path, operation, "unknown-current-collision", action="preserve")
    if actual.kind == "regular" and actual.sha256 != expected.sha256:
        if generated_refresh_allowed and operation in {"update", "init-force"}:
            if observation.link_count is not None and observation.link_count > 1:
                return _blocked_action(path, operation, "hard-link-mutation-unsafe", provenance="current")
            return DistributionAction(path, operation, "upgrade", "current", "generated-state-refresh")
        provenance = _historical_provenance(
            target_root,
            path,
            actual,
            manifest,
            require_mode=operation == "uninstall",
        )
        if provenance is None:
            return _blocked_action(path, operation, "unknown-current-collision", action="preserve")
        if observation.link_count is not None and observation.link_count > 1:
            return _blocked_action(
                path,
                operation,
                "hard-link-mutation-unsafe",
                provenance="historical",
            )
        if operation == "uninstall":
            return DistributionAction(path, operation, "prune", "historical", "historical-identity-match")
        if operation in {"update", "init-force"}:
            reason = (
                "trusted-manifest-identity-match"
                if provenance == "trusted-manifest"
                else "direct-historical-identity-match"
            )
            return DistributionAction(path, operation, "upgrade", "historical", reason)
        return _blocked_action(
            path,
            operation,
            "historical-identity-fresh-preserve",
            provenance="historical",
            action="preserve",
        )

    if (
        actual.kind == "regular"
        and actual.sha256 == expected.sha256
        and expected.mode is not None
        and actual.mode != expected.mode
    ):
        if operation in {"fresh", "uninstall"}:
            return _blocked_action(
                path,
                operation,
                "current-mode-mismatch",
                provenance="current",
                action="preserve",
            )
        if operation in {"update", "init-force"} and observation.link_count is not None and observation.link_count > 1:
            return _blocked_action(
                path,
                operation,
                "hard-link-mutation-unsafe",
                provenance="current",
            )
        if operation in {"update", "init-force"}:
            return DistributionAction(path, operation, "upgrade", "current", "current-mode-mismatch")

    if (
        actual.kind == "symlink"
        and observation.link_count is not None
        and observation.link_count > 1
        and operation in {"fresh", "uninstall"}
    ):
        return _blocked_action(
            path,
            operation,
            "hard-link-mutation-unsafe",
            provenance="current",
        )

    if (
        actual.kind == "regular"
        and observation.link_count is not None
        and observation.link_count > 1
        and operation in {"fresh", "update", "init-force", "uninstall"}
        and not (operation == "fresh" and path == "spec-dock/.workbench/README.md")
    ):
        return _blocked_action(
            path,
            operation,
            "hard-link-mutation-unsafe",
            provenance="current",
        )

    if operation == "uninstall":
        return DistributionAction(path, operation, "prune", "current", "current-identity-match")
    return DistributionAction(path, operation, "adopt", "current", "current-identity-match")


def _classify_obsolete_target(
    *,
    target_root: Path,
    item: dict[str, Any],
    operation: DistributionOperation,
    manifest: DistributionManifest,
    observation: _TargetObservation | None = None,
) -> DistributionAction | None:
    path = item["path"]
    if observation is None:
        observation = _observe_target(target_root, path)
    if observation.state == "missing":
        return None
    if observation.state == "directory":
        return _blocked_action(path, operation, "exact-path-directory")
    if observation.state == "symlink-container":
        return _blocked_action(path, operation, "symlink-container")
    if observation.state != "regular" and observation.state != "symlink":
        return _blocked_action(path, operation, "unsafe-target-path")
    actual = observation.identity
    if actual is None:
        return _blocked_action(path, operation, "unsafe-target-path")
    require_mode = operation == "uninstall"
    direct = any(
        (
            _removal_identity_matches(actual, identity)
            if require_mode
            else _identity_matches(actual, identity, include_mode=False)
        )
        for identity in item["identities"]
    )
    trusted = _trusted_manifest_matches(target_root, path, actual, manifest, require_mode=require_mode)
    if not direct and not trusted:
        return _blocked_action(path, operation, "obsolete-identity-unknown", action="preserve")
    if actual.kind == "regular" and observation.link_count is not None and observation.link_count > 1:
        return _blocked_action(path, operation, "hard-link-mutation-unsafe", provenance="historical")
    if actual.kind == "symlink" and observation.link_count is not None and observation.link_count > 1:
        return _blocked_action(path, operation, "hard-link-mutation-unsafe", provenance="historical")
    reason = "trusted-manifest-identity-match" if trusted and not direct else "direct-obsolete-identity-match"
    return DistributionAction(path, operation, "prune", "historical", reason)


def _classify_required_directory(
    *,
    target_root: Path,
    path: str,
    operation: DistributionOperation,
    observation: _TargetObservation | None = None,
) -> DistributionAction:
    if observation is None:
        observation = _observe_target(target_root, path)
    if observation.state == "missing":
        return DistributionAction(
            path,
            operation,
            "ensure-directory",
            "missing",
            "required-directory-missing",
        )
    if observation.state == "directory":
        return DistributionAction(path, operation, "adopt", "current", "required-directory-present")
    reason = {
        "symlink-container": "required-directory-symlink",
        "special": "required-directory-unsafe",
    }.get(observation.state, "required-directory-file")
    return _blocked_action(path, operation, reason, action="preserve")


def _same_exact_path_snapshot(
    actual: PathIdentitySnapshot,
    expected: PathIdentitySnapshot,
) -> bool:
    return (
        actual.relative_path == expected.relative_path
        and actual.exists == expected.exists
        and actual.device == expected.device
        and actual.inode == expected.inode
        and actual.ctime_ns == expected.ctime_ns
        and actual.file_type == expected.file_type
        and actual.link_count == expected.link_count
        and actual.mode == expected.mode
        and actual.size == expected.size
        and actual.identity == expected.identity
    )


def _classify_target(
    *,
    target_root: Path,
    current_assets: tuple[DistributionAsset, ...],
    operation: DistributionOperation,
    manifest: DistributionManifest,
    scaffold_assets: tuple[DistributionAsset, ...] = (),
    required_directories: tuple[DistributionDirectoryRequirement, ...] = (),
) -> tuple[tuple[DistributionAction, ...], tuple[tuple[str, DistributionTargetSnapshot], ...]]:
    specs = _target_identity_specs(current_assets, scaffold_assets)
    generated_assets = {asset.path: asset for asset in scaffold_assets if asset.source_path is None}
    actions: list[DistributionAction] = []
    observations: dict[str, _TargetObservation] = {}
    for requirement in required_directories:
        path = requirement.path
        observation = _observe_target(target_root, path)
        observations[path] = observation
        actions.append(
            _classify_required_directory(
                target_root=target_root,
                path=path,
                operation=operation,
                observation=observation,
            )
        )
    for path, expected in sorted(specs.items()):
        observation = _observe_target(target_root, path)
        observations[path] = observation
        generated_asset = generated_assets.get(path)
        producer_observation = generated_asset.generated_observed_target if generated_asset is not None else None
        classified_observation = observation.snapshot.target if observation.snapshot is not None else None
        if producer_observation is not None and (
            classified_observation is None
            or not _same_exact_path_snapshot(classified_observation, producer_observation)
        ):
            actions.append(
                _blocked_action(
                    path,
                    operation,
                    "generated-state-invalid",
                    action="preserve",
                )
            )
            continue
        actions.append(
            _classify_current_target(
                target_root=target_root,
                path=path,
                expected=expected,
                operation=operation,
                manifest=manifest,
                generated_path=path in generated_assets,
                refreshable_existing_identities=(
                    generated_assets[path].refreshable_existing_identities if path in generated_assets else None
                ),
                observation=observation,
            )
        )
    if operation in {"update", "init-force", "uninstall"}:
        current_paths = set(specs)
        for item in manifest.obsolete_exact_files:
            if item["path"] in current_paths:
                continue
            observation = _observe_target(target_root, item["path"])
            observations[item["path"]] = observation
            action = _classify_obsolete_target(
                target_root=target_root,
                item=item,
                operation=operation,
                manifest=manifest,
                observation=observation,
            )
            if action is not None:
                actions.append(action)
    snapshots: list[tuple[str, DistributionTargetSnapshot]] = []
    for path in sorted(observations):
        snapshot = observations[path].snapshot
        if snapshot is not None:
            snapshots.append((path, snapshot))
    return tuple(actions), tuple(snapshots)


def build_distribution_plan(
    install_root: Path,
    *,
    manifest_path: Path,
    scaffold_root: Path | None = None,
    target_root: Path | None = None,
    operation: DistributionOperation = "fresh",
    generated_assets: tuple[DistributionAsset, ...] = (),
) -> DistributionPlan:
    """Build a read-only Current/historical distribution plan.

    ``install_root`` is the provider physical source.  It is never modified;
    ``scaffold_root`` is retained only as context for later steps.  When
    ``target_root`` is supplied, S25 classifies exact consumer paths without
    writing them.  The target tree is never used as a source catalog.
    """

    install_root = Path(install_root)
    manifest_path = Path(manifest_path)
    if operation not in _OPERATIONS:
        raise DistributionManifestError(f"unsupported distribution operation: {operation!r}")
    current_assets = _current_assets(install_root)
    scaffold_assets = (
        _scaffold_assets(Path(scaffold_root), operation=operation)
        if scaffold_root is not None and operation != "uninstall"
        else ()
    )
    normalized_generated_assets: list[DistributionAsset] = []
    occupied_paths = {asset.path for asset in (*current_assets, *scaffold_assets)} | set(_CURRENT_SHORTCUTS)
    for asset in generated_assets:
        try:
            normalized_path = _exact_relative_path(asset.path, field_name="generated asset path").as_posix()
        except DistributionManifestError as exc:
            raise DistributionPlanError("generated asset path is not repository-relative") from exc
        if normalized_path != asset.path or normalized_path in occupied_paths:
            raise DistributionPlanError("generated asset path is duplicated or not canonical")
        if asset.source_path is not None or asset.source_snapshot is not None:
            raise DistributionPlanError("generated asset cannot reference a provider source path")
        if asset.identity.kind == "regular":
            if (
                asset.generated_content is None
                or asset.identity.sha256 != hashlib.sha256(asset.generated_content).hexdigest()
            ):
                raise DistributionPlanError("generated regular asset identity does not match its content")
        elif asset.identity.kind == "symlink":
            if asset.generated_content is not None or not _generated_link_target_is_within_root(
                normalized_path, asset.identity.target or ""
            ):
                raise DistributionPlanError("generated symlink asset has an invalid target")
        else:
            raise DistributionPlanError("generated asset kind is unsupported")
        occupied_paths.add(normalized_path)
        normalized_generated_assets.append(asset)
    scaffold_assets = (*scaffold_assets, *normalized_generated_assets)
    required_directories = (
        _fresh_required_directory_paths((*current_assets, *scaffold_assets)) if operation == "fresh" else ()
    )
    manifest = _load_manifest(manifest_path)
    _assert_no_manifest_overlap(
        {asset.path for asset in current_assets} | set(_CURRENT_SHORTCUTS),
        manifest,
        protected_paths=_protected_workspace_paths(scaffold_assets),
    )
    actions: tuple[DistributionAction, ...] = ()
    target_snapshots: tuple[tuple[str, DistributionTargetSnapshot], ...] = ()
    if target_root is not None:
        actions, target_snapshots = _classify_target(
            target_root=Path(target_root),
            current_assets=current_assets,
            operation=operation,
            manifest=manifest,
            scaffold_assets=scaffold_assets,
            required_directories=required_directories,
        )
    return DistributionPlan(
        current_assets=current_assets,
        actions=actions,
        manifest=manifest,
        scaffold_root=Path(scaffold_root) if scaffold_root is not None else None,
        install_root=install_root,
        manifest_path=manifest_path,
        target_root=Path(target_root) if target_root is not None else None,
        operation=operation,
        target_snapshots=target_snapshots,
        scaffold_assets=scaffold_assets,
        required_directories=required_directories,
    )


def _distribution_identity_payload(identity: DistributionIdentity | None) -> dict[str, object] | None:
    if identity is None:
        return None
    return {
        "kind": identity.kind,
        "sha256": identity.sha256,
        "mode": identity.mode,
        "target": identity.target,
    }


def _contract_identity(plan: DistributionPlan) -> str:
    assets = sorted((*plan.current_assets, *plan.scaffold_assets), key=lambda asset: asset.path)
    payload = {
        "schema_version": plan.manifest.schema_version,
        "required_directories": [item.path for item in plan.required_directories],
        "assets": [
            {
                "path": asset.path,
                "identity": _distribution_identity_payload(asset.identity),
            }
            for asset in assets
        ],
        "recognized_workspace_versions": plan.manifest.recognized_workspace_versions,
        "historical_current_identities": plan.manifest.historical_current_identities,
        "trusted_consumer_manifests": plan.manifest.trusted_consumer_manifests,
        "obsolete_exact_files": plan.manifest.obsolete_exact_files,
        "historical_shortcuts": plan.manifest.historical_shortcuts,
    }
    encoded = json.dumps(payload, sort_keys=True, separators=(",", ":")).encode("utf-8")
    return hashlib.sha256(encoded).hexdigest()


def _root_identity_for_assessment(target_root: Path) -> DistributionRootIdentity:
    try:
        info = os.lstat(target_root)
    except OSError as exc:
        raise DistributionPlanError("recognized target root cannot be inspected safely") from exc
    if stat.S_ISLNK(info.st_mode) or not stat.S_ISDIR(info.st_mode):
        raise DistributionPlanError("recognized target root is not a real directory")
    return DistributionRootIdentity(device=info.st_dev, inode=info.st_ino)


def build_workspace_assessment(
    install_root: Path,
    *,
    manifest_path: Path,
    target_root: Path,
    intent: JournaledDistributionIntent,
    scaffold_root: Path | None = None,
    generated_assets: tuple[DistributionAsset, ...] = (),
) -> WorkspaceAssessment:
    """Assess one journaled operation without creating execution authority."""

    if intent == "deprovision":
        raise DistributionPlanError("deprovision requires the dedicated deprovision assessment")
    if intent == "purge":
        raise DistributionPlanError("purge requires the dedicated explicit history assessment")
    if intent not in {"fresh", "update", "init-force"}:
        raise DistributionPlanError(f"unsupported journaled intent: {intent!r}")
    operation = _plan_operation_for_intent(intent)
    plan = build_distribution_plan(
        install_root,
        manifest_path=manifest_path,
        scaffold_root=scaffold_root,
        target_root=target_root,
        operation=operation,
        generated_assets=generated_assets,
    )
    blockers = tuple(action for action in plan.actions if action.blocked)
    return WorkspaceAssessment(
        intent=intent,
        root_identity=_root_identity_for_assessment(target_root),
        contract_identity=_contract_identity(plan),
        distribution_plan=plan,
        actions=plan.actions,
        blockers=blockers,
    )


def _required_directory_identity(plan: DistributionPlan, path: str) -> DistributionIdentity | None:
    if any(item.path == path for item in plan.required_directories):
        return DistributionIdentity(kind="directory")
    return None


def _action_precondition_payload(plan: DistributionPlan, action: DistributionAction) -> dict[str, object]:
    snapshots = dict(plan.target_snapshots)
    snapshot = snapshots.get(action.path)
    if snapshot is None:
        raise DistributionPlanError(f"assessment is missing a precondition for '{action.path}'")
    target = snapshot.target
    return {
        "root": _path_snapshot_condition(snapshot.root, include_mode=plan.operation == "uninstall"),
        "parents": [
            _path_snapshot_condition(parent, include_mode=plan.operation == "uninstall") for parent in snapshot.parents
        ],
        "exists": target.exists,
        "device": target.device,
        "inode": target.inode,
        "ctime_ns": target.ctime_ns,
        "file_type": target.file_type,
        "link_count": target.link_count,
        "identity": _distribution_identity_payload(target.identity),
    }


def _action_postcondition_payload(plan: DistributionPlan, action: DistributionAction) -> dict[str, object]:
    snapshot = dict(plan.target_snapshots).get(action.path)
    if snapshot is None:
        raise DistributionPlanError(f"assessment is missing a postcondition for '{action.path}'")
    boundary = {
        "root": _path_snapshot_condition(snapshot.root, include_mode=plan.operation == "uninstall"),
        "parents": [
            _path_snapshot_condition(parent, include_mode=plan.operation == "uninstall") for parent in snapshot.parents
        ],
    }
    expected = _expected_target_identity(plan, action.path)
    if action.action in {"prune", "remove-empty-directory"}:
        return {**boundary, "exists": False, "identity": None}
    if expected is None:
        expected = snapshot.target.identity
    expected_type = expected.kind if expected is not None else snapshot.target.file_type
    if expected_type == "directory":
        if action.action == "adopt" and snapshot.target.exists and snapshot.target.file_type == "directory":
            return {
                **boundary,
                "exists": True,
                # An adopted directory is not mutated by the action, but
                # publishing children below it may change ctime/link-count.
                # Keep the captured device/inode as the exact recovery
                # identity while treating those metadata fields as wildcards.
                "device": snapshot.target.device,
                "inode": snapshot.target.inode,
                "ctime_ns": 0,
                "file_type": "directory",
                "link_count": 0,
                "identity": _distribution_identity_payload(expected),
            }
        return {
            **boundary,
            "exists": True,
            # Directory metadata changes when child entries are published.  The
            # directory identity itself is the stable postcondition; zeroed
            # structural fields intentionally make the condition metadata-free.
            "device": 0,
            "inode": 0,
            "ctime_ns": 0,
            "file_type": "directory",
            "link_count": 0,
            "identity": _distribution_identity_payload(expected),
        }
    if action.action == "adopt" and snapshot.target.exists and snapshot.target.file_type != "directory":
        if (
            snapshot.target.device is None
            or snapshot.target.inode is None
            or snapshot.target.ctime_ns is None
            or snapshot.target.link_count is None
        ):
            raise DistributionPlanError(f"assessment is missing structural identity for '{action.path}'")
        return {
            **boundary,
            "exists": True,
            # Adoption does not mutate a non-directory target.  Preserve the
            # observed node identity and link topology so an interrupted
            # checkpoint cannot resume against an external replacement.
            "device": snapshot.target.device,
            "inode": snapshot.target.inode,
            "ctime_ns": snapshot.target.ctime_ns,
            "file_type": snapshot.target.file_type,
            "link_count": snapshot.target.link_count,
            "identity": _distribution_identity_payload(expected),
        }
    return {
        **boundary,
        "exists": True,
        "file_type": expected_type,
        "link_count": 1,
        "identity": _distribution_identity_payload(expected),
    }


def _destructive_action_conditions(
    plan: ExecutableMutationPlan,
    action: DistributionAction,
) -> tuple[dict[str, object], dict[str, object]]:
    precondition = _action_precondition_payload(plan.distribution_plan, action)
    postcondition = _action_postcondition_payload(plan.distribution_plan, action)
    target = dict(plan.distribution_plan.target_snapshots)[action.path].target
    precondition = {
        **precondition,
        "mode": target.mode,
        "size": target.size,
    }
    if action.action == "remove-empty-directory":
        snapshot = next(
            (item for item in plan.directory_snapshots if item.relative_path == action.path),
            None,
        )
        if snapshot is None:
            raise DistributionPlanError("deprovision directory action is missing its evidence")
        precondition.update({
            "initial_child_digest": snapshot.initial_child_digest,
            "immediate_child_evidence": [
                {
                    "child_path": evidence.child_path,
                    "child_kind": evidence.child_kind,
                    "action_path": evidence.action_path,
                    "required_checkpoint": evidence.required_checkpoint,
                    "expected_postcondition": evidence.expected_postcondition,
                }
                for evidence in snapshot.immediate_child_evidence
            ],
            "expected_remaining_child_digest": snapshot.expected_remaining_child_digest,
        })
    return precondition, postcondition


def _deprovision_action_conditions(
    plan: ExecutableMutationPlan,
    action: DistributionAction,
) -> tuple[dict[str, object], dict[str, object]]:
    return _destructive_action_conditions(plan, action)


def _purge_action_conditions(
    plan: ExecutableMutationPlan,
    action: DistributionAction,
) -> tuple[dict[str, object], dict[str, object]]:
    return _destructive_action_conditions(plan, action)


def _legacy_action_postcondition_payload(
    plan: DistributionPlan,
    action: DistributionAction,
    *,
    fixed_link_count: bool = False,
) -> dict[str, object]:
    """Reconstruct the schema-1/protocol-1 adopt condition shape.

    The journal protocol remains version 1 even though current adopt
    postconditions now retain structural identity.  Older journals therefore
    legitimately omit device/inode/ctime for an existing non-directory adopt.
    Keep the old wire shape available for plan-digest compatibility checks.
    """

    payload = _action_postcondition_payload(plan, action)
    if action.action != "adopt" or payload.get("file_type") == "directory":
        return payload
    if fixed_link_count:
        payload = {**payload, "link_count": 1}
    return {key: value for key, value in payload.items() if key not in {"device", "inode", "ctime_ns"}}


def _legacy_fixed_link_count_create_upgrade_postcondition_payload(
    plan: DistributionPlan,
    action: DistributionAction,
) -> dict[str, object]:
    """Reconstruct the pre-identity create/upgrade digest postcondition.

    The Issue 368 writer hashed non-directory create/upgrade postconditions
    with a fixed ``link_count: 1``.  Current journals retain the observed
    successor identity, so that runtime metadata is excluded from the
    canonical digest; this helper keeps the old digest candidate bounded to
    the historical fixed-link-count shape.
    """

    payload = _action_postcondition_payload(plan, action)
    if action.action not in {"create", "upgrade"} or payload.get("file_type") == "directory":
        return payload
    return {
        **{key: value for key, value in payload.items() if key not in {"device", "inode", "ctime_ns", "link_count"}},
        "link_count": 1,
    }


def _path_snapshot_condition(
    snapshot: PathIdentitySnapshot,
    *,
    include_mode: bool = False,
) -> dict[str, object]:
    payload: dict[str, object] = {
        "relative_path": snapshot.relative_path,
        "exists": snapshot.exists,
        "device": snapshot.device,
        "inode": snapshot.inode,
        "ctime_ns": snapshot.ctime_ns,
        "file_type": snapshot.file_type,
        "link_count": snapshot.link_count,
    }
    if include_mode:
        payload["mode"] = snapshot.mode
    return payload


def _plan_digest_condition(condition: dict[str, object]) -> dict[str, object]:
    """Exclude directory ctime noise that recovery metadata itself changes."""

    normalized = dict(condition)
    if normalized.get("file_type") == "directory":
        normalized.pop("ctime_ns", None)
        normalized.pop("link_count", None)
    root = normalized.get("root")
    if isinstance(root, dict):
        normalized["root"] = {key: value for key, value in root.items() if key not in {"ctime_ns", "link_count"}}
    parents = normalized.get("parents")
    if isinstance(parents, list):
        normalized["parents"] = [
            {key: value for key, value in parent.items() if key not in {"ctime_ns", "link_count"}}
            if isinstance(parent, dict)
            else parent
            for parent in parents
        ]
    return normalized


def _semantic_path_binding_payload(snapshot: PathIdentitySnapshot) -> dict[str, object]:
    payload = {
        "relative_path": snapshot.relative_path,
        "exists": snapshot.exists,
        "device": snapshot.device,
        "inode": snapshot.inode,
        "file_type": snapshot.file_type,
        "mode": snapshot.mode,
    }
    if snapshot.file_type != "directory":
        payload.update({
            "ctime_ns": snapshot.ctime_ns,
            "link_count": snapshot.link_count,
            "size": snapshot.size,
            "identity": _distribution_identity_payload(snapshot.identity),
        })
    return payload


def _directory_snapshot_digest_payload(
    snapshot: DistributionDirectoryMutationSnapshot,
) -> dict[str, object]:
    return {
        "relative_path": snapshot.relative_path,
        "binding": _semantic_path_binding_payload(snapshot.binding),
        "initial_entries": [
            _directory_child_semantic_payload(
                entry,
                classification="authorized-child",
                owner_source="deprovision-contract",
            )
            for entry in snapshot.initial_entries
        ],
        "initial_child_digest": snapshot.initial_child_digest,
        "immediate_child_evidence": [
            {
                "child_path": evidence.child_path,
                "child_kind": evidence.child_kind,
                "action_path": evidence.action_path,
                "required_checkpoint": evidence.required_checkpoint,
                "expected_postcondition": evidence.expected_postcondition,
            }
            for evidence in snapshot.immediate_child_evidence
        ],
        "expected_remaining_child_digest": snapshot.expected_remaining_child_digest,
    }


def _leaf_parent_namespace_witness_payload(
    witness: DistributionLeafParentNamespaceWitness,
) -> dict[str, object]:
    return {
        "relative_path": witness.relative_path,
        "binding": _semantic_path_binding_payload(witness.binding),
        "initial_entries": [_tree_entry_payload(entry) for entry in witness.initial_entries],
        "initial_namespace_digest": witness.initial_namespace_digest,
    }


def _durable_leaf_parent_namespace_witness(
    witness: DistributionLeafParentNamespaceWitness,
) -> DistributionLeafParentNamespaceWitness:
    """Drop mutable directory metadata from persisted parent evidence."""

    return replace(
        witness,
        binding=replace(
            witness.binding,
            ctime_ns=None,
            link_count=None,
            size=None,
            identity=None,
        ),
    )


def _preservation_witness_payload(
    witness: DistributionPreservationWitness,
) -> dict[str, object]:
    return {
        "relative_root": witness.relative_root,
        "root_binding": {
            **_path_snapshot_condition(witness.root_binding),
            "mode": witness.root_binding.mode,
        },
        "entries": [_tree_entry_payload(entry) for entry in witness.entries],
        "tree_digest": witness.tree_digest,
        "reason": witness.reason,
    }


def _absence_witness_payload(
    witness: DistributionCollapsedAbsenceWitness,
) -> dict[str, object]:
    return {
        "relative_root": witness.relative_root,
        "anchor_path": witness.anchor_path,
        "surviving_anchor": _semantic_path_binding_payload(witness.surviving_anchor),
        "missing_suffix": list(witness.missing_suffix),
        "owned_descendant_paths_digest": witness.owned_descendant_paths_digest,
        "reason": witness.reason,
    }


def _active_selection_witness_payload(
    witness: DistributionActiveSelectionWitness,
) -> dict[str, object]:
    selection: dict[str, str] | None = None
    if witness.selection is not None:
        selection = {"id": witness.selection[0], "path": witness.selection[1]}
    return {
        "layer": witness.layer,
        "selection": selection,
        "representation": witness.representation,
        "target": witness.target,
    }


def _durable_absence_witness(
    witness: DistributionCollapsedAbsenceWitness,
) -> DistributionCollapsedAbsenceWitness:
    """Drop mutable directory metadata from a persisted surviving anchor."""

    return replace(
        witness,
        surviving_anchor=replace(
            witness.surviving_anchor,
            ctime_ns=None,
            link_count=None,
            size=None,
            identity=None,
        ),
    )


def _distribution_plan_digest(
    *,
    intent: JournaledDistributionIntent,
    root_identity: DistributionRootIdentity,
    contract_identity: str,
    plan: DistributionPlan,
    actions: tuple[DistributionAction, ...],
    directory_snapshots: tuple[DistributionDirectoryMutationSnapshot, ...] = (),
    leaf_parent_namespace_witnesses: tuple[DistributionLeafParentNamespaceWitness, ...] = (),
    preservation_witnesses: tuple[DistributionPreservationWitness, ...] = (),
    absence_witnesses: tuple[DistributionCollapsedAbsenceWitness, ...] = (),
    source_semantic_identities: tuple[DistributionSourceSemanticIdentity, ...] = (),
    generated_state_contract_digest: str | None = None,
    active_selection_witnesses: tuple[DistributionActiveSelectionWitness, ...] = (),
    legacy_adopt_postconditions: bool = False,
    legacy_adopt_fixed_link_count: bool = False,
    legacy_create_upgrade_fixed_link_count: bool = False,
) -> str:
    ordered_actions = (
        list(actions)
        if _is_destructive_intent(intent)
        else sorted(actions, key=lambda action: (action.path, action.action, action.reason))
    )

    def digest_postcondition(action: DistributionAction) -> dict[str, object]:
        postcondition = (
            _legacy_action_postcondition_payload(
                plan,
                action,
                fixed_link_count=legacy_adopt_fixed_link_count,
            )
            if legacy_adopt_postconditions
            else _action_postcondition_payload(plan, action)
        )
        if legacy_create_upgrade_fixed_link_count and action.action in {"create", "upgrade"}:
            postcondition = _legacy_fixed_link_count_create_upgrade_postcondition_payload(plan, action)
        if action.action in {"create", "upgrade"} and postcondition.get("file_type") != "directory":
            if legacy_create_upgrade_fixed_link_count:
                return postcondition
            return {
                key: value
                for key, value in postcondition.items()
                if key not in {"device", "inode", "ctime_ns", "link_count"}
            }
        return postcondition

    payload: dict[str, object] = {
        "schema_version": (
            _DISTRIBUTION_FRESH_JOURNAL_SCHEMA_VERSION if intent == "fresh" else _DISTRIBUTION_JOURNAL_SCHEMA_VERSION
        ),
        "intent": intent,
        "root_binding": {
            "device": root_identity.device,
            "inode": root_identity.inode,
        },
        "contract_identity": contract_identity,
        "actions": [
            {
                "path": action.path,
                "action": action.action,
                "provenance": action.provenance,
                "reason": action.reason,
                "precondition": _plan_digest_condition(_action_precondition_payload(plan, action)),
                "postcondition": _plan_digest_condition(digest_postcondition(action)),
            }
            for action in ordered_actions
        ],
    }
    if intent == "fresh":
        payload["required_directories"] = sorted(item.path for item in plan.required_directories)
    elif _is_destructive_intent(intent):
        if generated_state_contract_digest is None:
            raise DistributionPlanError("destructive plan digest is missing generated state authority")
        payload.update({
            "digest_format_version": 3,
            "authority": _journal_authority_for_intent(intent),
            "generated_state_contract_digest": generated_state_contract_digest,
            "active_selection_witnesses": [
                _active_selection_witness_payload(witness) for witness in active_selection_witnesses
            ],
            "directory_snapshots": [_directory_snapshot_digest_payload(snapshot) for snapshot in directory_snapshots],
            "leaf_parent_namespace_witnesses": [
                _leaf_parent_namespace_witness_payload(witness) for witness in leaf_parent_namespace_witnesses
            ],
            "preservation_witnesses": [_preservation_witness_payload(witness) for witness in preservation_witnesses],
            "absence_witnesses": [_absence_witness_payload(witness) for witness in absence_witnesses],
            "source_semantic_identities": [
                _source_semantic_payload(identity) for identity in source_semantic_identities
            ],
        })
    encoded = json.dumps(payload, sort_keys=True, separators=(",", ":")).encode("utf-8")
    return hashlib.sha256(encoded).hexdigest()


def _mutation_plan_digest(
    assessment: WorkspaceAssessment,
    *,
    legacy_adopt_postconditions: bool = False,
    legacy_adopt_fixed_link_count: bool = False,
    legacy_create_upgrade_fixed_link_count: bool = False,
) -> str:
    return _distribution_plan_digest(
        intent=assessment.intent,
        root_identity=assessment.root_identity,
        contract_identity=assessment.contract_identity,
        plan=assessment.distribution_plan,
        actions=assessment.actions,
        directory_snapshots=assessment.directory_snapshots,
        leaf_parent_namespace_witnesses=assessment.leaf_parent_namespace_witnesses,
        preservation_witnesses=assessment.preservation_witnesses,
        absence_witnesses=assessment.absence_witnesses,
        source_semantic_identities=(
            assessment.deprovision_contract.source_semantic_identities
            if assessment.deprovision_contract is not None
            else ()
        ),
        generated_state_contract_digest=(
            assessment.deprovision_contract.generated_state.contract_digest
            if assessment.deprovision_contract is not None
            else None
        ),
        active_selection_witnesses=(
            assessment.deprovision_contract.generated_state.active_selection_witnesses
            if assessment.deprovision_contract is not None
            else ()
        ),
        legacy_adopt_postconditions=legacy_adopt_postconditions,
        legacy_adopt_fixed_link_count=legacy_adopt_fixed_link_count,
        legacy_create_upgrade_fixed_link_count=legacy_create_upgrade_fixed_link_count,
    )


def _executable_plan_digest(
    plan: ExecutableMutationPlan,
    *,
    legacy_adopt_postconditions: bool = False,
    legacy_adopt_fixed_link_count: bool = False,
    legacy_create_upgrade_fixed_link_count: bool = False,
) -> str:
    return _distribution_plan_digest(
        intent=plan.intent,
        root_identity=plan.root_identity,
        contract_identity=plan.contract_identity,
        plan=plan.distribution_plan,
        actions=plan.actions,
        directory_snapshots=plan.directory_snapshots,
        leaf_parent_namespace_witnesses=plan.leaf_parent_namespace_witnesses,
        preservation_witnesses=plan.preservation_witnesses,
        absence_witnesses=plan.absence_witnesses,
        source_semantic_identities=plan.source_semantic_identities,
        generated_state_contract_digest=plan.generated_state_contract_digest,
        active_selection_witnesses=plan.active_selection_witnesses,
        legacy_adopt_postconditions=legacy_adopt_postconditions,
        legacy_adopt_fixed_link_count=legacy_adopt_fixed_link_count,
        legacy_create_upgrade_fixed_link_count=legacy_create_upgrade_fixed_link_count,
    )


def _deprovision_journal_plan_digest(
    journal: OperationJournal,
    *,
    digest_format_version: int = 3,
) -> str:
    """Recompute a deprovision digest from the immutable journal plan fields."""

    action_by_path = {action.path: action for action in journal.actions}
    directory_snapshots: list[dict[str, object]] = []
    for action in journal.actions:
        if action.action != "remove-empty-directory":
            continue
        precondition = action.precondition
        raw_evidence = precondition.get("immediate_child_evidence")
        if not isinstance(raw_evidence, list):
            raise DistributionApplyError("journal-plan-mismatch")
        initial_entries: list[dict[str, object]] = []
        for raw_item in raw_evidence:
            if not isinstance(raw_item, dict):
                raise DistributionApplyError("journal-plan-mismatch")
            child_path = raw_item.get("action_path")
            if not isinstance(child_path, str):
                raise DistributionApplyError("journal-plan-mismatch")
            child = action_by_path.get(child_path)
            if child is None:
                raise DistributionApplyError("journal-plan-mismatch")
            child_precondition = child.precondition
            kind = child_precondition.get("file_type")
            if kind not in {"regular", "symlink", "directory"}:
                raise DistributionApplyError("journal-plan-mismatch")
            entry: dict[str, object] = {
                "format_version": 1,
                "relative_path": child.path,
                "kind": kind,
                "device": child_precondition.get("device"),
                "inode": child_precondition.get("inode"),
                "mode": child_precondition.get("mode"),
                "classification": "authorized-child",
                "owner_source": "deprovision-contract",
            }
            if kind != "directory":
                entry.update({
                    "ctime_ns": child_precondition.get("ctime_ns"),
                    "link_count": child_precondition.get("link_count"),
                })
                identity = child_precondition.get("identity")
                if not isinstance(identity, dict):
                    raise DistributionApplyError("journal-plan-mismatch")
                if kind == "regular":
                    entry.update({
                        "size": child_precondition.get("size"),
                        "sha256": identity.get("sha256"),
                    })
                else:
                    entry["link_target"] = identity.get("target")
            initial_entries.append(entry)
        directory_snapshots.append({
            "relative_path": action.path,
            "binding": {
                "relative_path": action.path,
                "exists": True,
                "device": precondition.get("device"),
                "inode": precondition.get("inode"),
                "file_type": "directory",
                "mode": precondition.get("mode"),
            },
            "initial_entries": initial_entries,
            "initial_child_digest": precondition.get("initial_child_digest"),
            "immediate_child_evidence": [
                {
                    "child_path": item.get("child_path"),
                    "child_kind": item.get("child_kind"),
                    "action_path": item.get("action_path"),
                    "required_checkpoint": item.get("required_checkpoint"),
                    "expected_postcondition": item.get("expected_postcondition"),
                }
                for item in raw_evidence
                if isinstance(item, dict)
            ],
            "expected_remaining_child_digest": precondition.get("expected_remaining_child_digest"),
        })

    payload: dict[str, object] = {
        "schema_version": _DISTRIBUTION_JOURNAL_SCHEMA_VERSION,
        "intent": journal.intent,
        "root_binding": {
            "device": journal.root_identity.device,
            "inode": journal.root_identity.inode,
        },
        "contract_identity": journal.contract_identity,
        "actions": [
            {
                "path": action.path,
                "action": action.action,
                "provenance": action.provenance,
                "reason": action.reason,
                "precondition": _plan_digest_condition({
                    key: value
                    for key, value in action.precondition.items()
                    if key
                    not in {
                        "mode",
                        "size",
                        "initial_child_digest",
                        "immediate_child_evidence",
                        "expected_remaining_child_digest",
                    }
                }),
                "postcondition": _plan_digest_condition(action.postcondition),
            }
            for action in journal.actions
        ],
        "digest_format_version": digest_format_version,
        "authority": _journal_authority_for_intent(journal.intent),
        "generated_state_contract_digest": journal.generated_state_contract_digest,
        "active_selection_witnesses": [
            _active_selection_witness_payload(witness) for witness in journal.active_selection_witnesses
        ],
        "directory_snapshots": directory_snapshots,
        "preservation_witnesses": [
            _preservation_witness_payload(witness) for witness in journal.preservation_witnesses
        ],
        "absence_witnesses": [_absence_witness_payload(witness) for witness in journal.absence_witnesses],
        "source_semantic_identities": [
            _source_semantic_payload(identity) for identity in journal.source_semantic_identities
        ],
    }
    if digest_format_version >= 3:
        payload["leaf_parent_namespace_witnesses"] = [
            _leaf_parent_namespace_witness_payload(witness) for witness in journal.leaf_parent_namespace_witnesses
        ]
    encoded = json.dumps(payload, sort_keys=True, separators=(",", ":")).encode("utf-8")
    return hashlib.sha256(encoded).hexdigest()


def _mutation_plan_digest_candidates(assessment: WorkspaceAssessment) -> frozenset[str]:
    return frozenset({
        _mutation_plan_digest(assessment),
        _mutation_plan_digest(assessment, legacy_adopt_postconditions=True),
        _mutation_plan_digest(
            assessment,
            legacy_adopt_postconditions=True,
            legacy_adopt_fixed_link_count=True,
        ),
        _mutation_plan_digest(assessment, legacy_create_upgrade_fixed_link_count=True),
        _mutation_plan_digest(
            assessment,
            legacy_adopt_postconditions=True,
            legacy_create_upgrade_fixed_link_count=True,
        ),
        _mutation_plan_digest(
            assessment,
            legacy_adopt_postconditions=True,
            legacy_adopt_fixed_link_count=True,
            legacy_create_upgrade_fixed_link_count=True,
        ),
    })


def _executable_plan_digest_candidates(plan: ExecutableMutationPlan) -> frozenset[str]:
    return frozenset({
        plan.plan_digest,
        _executable_plan_digest(plan, legacy_adopt_postconditions=True),
        _executable_plan_digest(
            plan,
            legacy_adopt_postconditions=True,
            legacy_adopt_fixed_link_count=True,
        ),
        _executable_plan_digest(plan, legacy_create_upgrade_fixed_link_count=True),
        _executable_plan_digest(
            plan,
            legacy_adopt_postconditions=True,
            legacy_create_upgrade_fixed_link_count=True,
        ),
        _executable_plan_digest(
            plan,
            legacy_adopt_postconditions=True,
            legacy_adopt_fixed_link_count=True,
            legacy_create_upgrade_fixed_link_count=True,
        ),
    })


def _plan_digest_matches(plan: ExecutableMutationPlan, stored_digest: str | None) -> bool:
    return stored_digest in _executable_plan_digest_candidates(plan)


def _revalidate_deprovision_source_snapshots(assessment: WorkspaceAssessment) -> None:
    """Keep physical provider identity invocation-local and exact until authority issuance."""

    contract = assessment.deprovision_contract
    plan = assessment.distribution_plan
    if contract is None or plan.install_root is None or plan.scaffold_root is None:
        raise DistributionPlanError("deprovision source contract is incomplete")
    for asset in contract.managed_assets:
        semantic = asset.source_semantic_identity
        expected_snapshot = asset.source_snapshot
        if semantic is None or expected_snapshot is None:
            raise DistributionPlanError("deprovision source contract is incomplete")
        if semantic.canonical_source_path.startswith("install-root/"):
            source_path = plan.install_root / asset.path
        elif semantic.canonical_source_path.startswith("spec-dock-scaffold/"):
            source_path = plan.scaffold_root / (asset.source_path or asset.path.removeprefix("spec-dock/"))
        else:
            raise DistributionPlanError("deprovision source contract has an unknown namespace")
        if semantic.kind == "symlink":
            try:
                visible = os.lstat(source_path)
                link_target = str(source_path.readlink())
                after = os.lstat(source_path)
            except OSError as exc:
                raise DistributionPlanError("deprovision source snapshot changed") from exc
            if (
                not stat.S_ISLNK(after.st_mode)
                or _source_snapshot(visible) != _source_snapshot(after)
                or _source_snapshot(after) != expected_snapshot
                or link_target != semantic.link_target
            ):
                raise DistributionPlanError("deprovision source snapshot changed")
            continue
        try:
            _content, current_snapshot = _source_asset_bytes(source_path)
        except (OSError, DistributionApplyError) as exc:
            raise DistributionPlanError("deprovision source snapshot changed") from exc
        if current_snapshot != expected_snapshot:
            raise DistributionPlanError("deprovision source snapshot changed")


def _ordered_deprovision_actions(
    actions: tuple[DistributionAction, ...],
) -> tuple[DistributionAction, ...]:
    prunes = sorted(
        (action for action in actions if action.action == "prune"),
        key=lambda action: (-len(PurePosixPath(action.path).parts), action.path),
    )
    directories = sorted(
        (action for action in actions if action.action == "remove-empty-directory"),
        key=lambda action: (-len(PurePosixPath(action.path).parts), action.path),
    )
    return (*prunes, *directories)


def _validate_deprovision_plan_metadata(
    assessment: WorkspaceAssessment,
    actions: tuple[DistributionAction, ...],
) -> None:
    contract = assessment.deprovision_contract
    if contract is None or not contract.generated_state.contract_digest:
        raise DistributionPlanError("deprovision plan is missing its generated contract")
    action_by_path = {action.path: action for action in actions}
    if len(action_by_path) != len(actions):
        raise DistributionPlanError("deprovision plan contains duplicate mutating paths")
    if any(action.action not in {"prune", "remove-empty-directory"} for action in actions):
        raise DistributionPlanError("deprovision executable plan contains a non-mutating disposition")
    if actions != _ordered_deprovision_actions(actions):
        raise DistributionPlanError("deprovision executable action order is not canonical")
    try:
        _validate_leaf_parent_namespace_witness_coverage(
            actions,
            assessment.leaf_parent_namespace_witnesses,
            target_snapshots=dict(assessment.distribution_plan.target_snapshots),
        )
    except DistributionApplyError as exc:
        raise DistributionPlanError("deprovision leaf-parent namespace witness is not canonical") from exc
    if assessment.preservation_witnesses != tuple(
        sorted(assessment.preservation_witnesses, key=lambda witness: witness.relative_root)
    ):
        raise DistributionPlanError("deprovision preservation witness order is not canonical")
    if assessment.absence_witnesses != tuple(
        sorted(assessment.absence_witnesses, key=lambda witness: witness.relative_root)
    ):
        raise DistributionPlanError("deprovision absence witness order is not canonical")
    if contract.source_semantic_identities != tuple(
        sorted(contract.source_semantic_identities, key=lambda identity: identity.canonical_source_path)
    ):
        raise DistributionPlanError("deprovision semantic source order is not canonical")
    try:
        parsed_preservation = _parse_preservation_witnesses([
            _preservation_witness_payload(witness) for witness in assessment.preservation_witnesses
        ])
    except DistributionApplyError as exc:
        raise DistributionPlanError("deprovision preservation witness is not canonical") from exc
    if [_preservation_witness_payload(witness) for witness in parsed_preservation] != [
        _preservation_witness_payload(witness) for witness in assessment.preservation_witnesses
    ]:
        raise DistributionPlanError("deprovision preservation witness is not canonical")
    try:
        parsed_absence = _parse_absence_witnesses([
            _absence_witness_payload(witness) for witness in assessment.absence_witnesses
        ])
    except DistributionApplyError as exc:
        raise DistributionPlanError("deprovision absence witness is not canonical") from exc
    if [_absence_witness_payload(witness) for witness in parsed_absence] != [
        _absence_witness_payload(witness) for witness in assessment.absence_witnesses
    ]:
        raise DistributionPlanError("deprovision absence witness is not canonical")
    try:
        parsed_sources = _parse_source_semantic_identities([
            _source_semantic_payload(identity) for identity in contract.source_semantic_identities
        ])
        _journal_sha256(contract.generated_state.contract_digest)
    except DistributionApplyError as exc:
        raise DistributionPlanError("deprovision semantic source is not canonical") from exc
    if parsed_sources != contract.source_semantic_identities:
        raise DistributionPlanError("deprovision semantic source is not canonical")
    owner_by_path: dict[str, str] = {asset.path: "physical-provider" for asset in contract.managed_assets}
    owner_by_path.update({asset.path: "root-shortcut" for asset in contract.removable_shortcuts})
    owner_by_path.update({asset.path: "workspace-marker" for asset in contract.target_only_assets})
    owner_by_path.update({entry.path: entry.origin for entry in contract.generated_state.entries})
    purge_contract = assessment.explicit_spec_history_purge_contract
    if purge_contract is not None:
        owner_by_path.update({
            entry.relative_path: "explicit-spec-history-purge" for entry in purge_contract.history_entries
        })
    if contract.manifest is not None:
        for item in (*contract.manifest.obsolete_exact_files, *contract.manifest.historical_shortcuts):
            owner_by_path.setdefault(item["path"], "historical-exact")
    snapshots = {item.relative_path: item for item in assessment.directory_snapshots}
    directory_paths = {action.path for action in actions if action.action == "remove-empty-directory"}
    if len(snapshots) != len(assessment.directory_snapshots) or set(snapshots) != directory_paths:
        raise DistributionPlanError("deprovision directory snapshots do not match directory actions")
    action_index = {action.path: index for index, action in enumerate(actions)}
    for path in sorted(directory_paths):
        snapshot = snapshots[path]
        target_binding = dict(assessment.distribution_plan.target_snapshots)[path].target
        if (
            snapshot.binding.relative_path != path
            or snapshot.binding.file_type != "directory"
            or snapshot.binding != target_binding
            or snapshot.binding.mode != target_binding.mode
        ):
            raise DistributionPlanError("deprovision directory binding is incomplete")
        if (
            snapshot.initial_entries
            != tuple(sorted(snapshot.initial_entries, key=lambda entry: os.fsencode(entry.relative_path)))
            or len({entry.relative_path for entry in snapshot.initial_entries}) != len(snapshot.initial_entries)
            or any(PurePosixPath(entry.relative_path).parent.as_posix() != path for entry in snapshot.initial_entries)
        ):
            raise DistributionPlanError("deprovision directory semantic digest is not canonical")
        if snapshot.immediate_child_evidence != tuple(
            sorted(
                snapshot.immediate_child_evidence,
                key=lambda evidence: os.fsencode(evidence.child_path),
            )
        ):
            raise DistributionPlanError("deprovision immediate child evidence order is not canonical")
        evidence_by_child = {item.child_path: item for item in snapshot.immediate_child_evidence}
        if len(evidence_by_child) != len(snapshot.immediate_child_evidence):
            raise DistributionPlanError("deprovision immediate child evidence is duplicated")
        initial_by_path = {entry.relative_path: entry for entry in snapshot.initial_entries}
        if set(evidence_by_child) != set(initial_by_path):
            raise DistributionPlanError("deprovision immediate child evidence is incomplete")
        for child_path, evidence in evidence_by_child.items():
            if (
                PurePosixPath(child_path).parent.as_posix() != path
                or evidence.action_path != child_path
                or evidence.required_checkpoint != "published"
                or evidence.expected_postcondition != {"path": child_path, "exists": False}
            ):
                raise DistributionPlanError("deprovision immediate child evidence is not canonical")
            child_action = action_by_path.get(child_path)
            child_entry = initial_by_path[child_path]
            expected_kind = "directory" if child_entry.kind == "directory" else "leaf"
            expected_action = "remove-empty-directory" if expected_kind == "directory" else "prune"
            if (
                evidence.child_kind != expected_kind
                or child_action is None
                or child_action.action != expected_action
                or action_index[child_path] >= action_index[path]
            ):
                raise DistributionPlanError("deprovision immediate child evidence action mismatch")
        semantic_records: list[tuple[DistributionTreeEntrySnapshot, str, str]] = []
        for child_path, child_entry in initial_by_path.items():
            child_action = action_by_path[child_path]
            owner_source = (
                "directory-closure"
                if child_action.action == "remove-empty-directory"
                else owner_by_path.get(child_path)
            )
            if owner_source is None:
                raise DistributionPlanError("deprovision directory semantic owner is not canonical")
            semantic_records.append((child_entry, child_action.action, owner_source))
        if snapshot.initial_child_digest != _directory_child_digest(tuple(semantic_records)):
            raise DistributionPlanError("deprovision directory semantic digest is not canonical")
        if snapshot.expected_remaining_child_digest != _directory_child_digest(()) or path in {
            witness.relative_root for witness in assessment.preservation_witnesses
        }:
            raise DistributionPlanError("deprovision directory postcondition is not canonical")
    for absence_witness in assessment.absence_witnesses:
        if any(_is_same_or_descendant(action.path, absence_witness.relative_root) for action in actions):
            raise DistributionPlanError("deprovision absence witness overlaps a mutating action")
    for preservation_witness in assessment.preservation_witnesses:
        if any(_is_same_or_descendant(action.path, preservation_witness.relative_root) for action in actions):
            raise DistributionPlanError("deprovision preservation witness overlaps a mutating action")


def _validate_explicit_spec_history_purge_plan_metadata(
    assessment: WorkspaceAssessment,
    actions: tuple[DistributionAction, ...],
) -> None:
    contract = assessment.explicit_spec_history_purge_contract
    if (
        contract is None
        or contract.history_root != _EXPLICIT_SPEC_HISTORY_ROOT
        or contract.authority != _journal_authority_for_intent("purge")
        or contract.deprovision_contract.preserved_roots != ("spec-dock/.workbench",)
        or contract.history_tree_digest
        != _distribution_tree_digest(
            contract.history_root,
            contract.history_root_binding,
            contract.history_entries,
        )
        or contract.contract_digest
        != _explicit_spec_history_purge_contract_digest(
            deprovision_contract=contract.deprovision_contract,
            history_root=contract.history_root,
            history_tree_digest=contract.history_tree_digest,
        )
    ):
        raise DistributionPlanError("explicit purge contract is not canonical")
    history_entries = {entry.relative_path: entry for entry in contract.history_entries}
    history_actions = {
        action.path: action for action in actions if _is_same_or_descendant(action.path, contract.history_root)
    }
    if len(history_actions) != sum(
        1 for action in actions if _is_same_or_descendant(action.path, contract.history_root)
    ):
        raise DistributionPlanError("explicit purge action paths are duplicated")
    for action in history_actions.values():
        if action.path == contract.history_root:
            expected_kind = "directory"
        else:
            entry = history_entries.get(action.path)
            if entry is None:
                raise DistributionPlanError("explicit purge action is outside captured history")
            expected_kind = entry.kind
        if action.provenance != "unknown":
            raise DistributionPlanError("explicit purge action provenance is not canonical")
        expected_reason = (
            "explicit-spec-history-purge-directory"
            if action.action == "remove-empty-directory"
            else "explicit-spec-history-purge"
        )
        if (
            action.reason != expected_reason
            or (expected_kind == "directory" and action.action != "remove-empty-directory")
            or (expected_kind == "regular" and action.action != "prune")
        ):
            raise DistributionPlanError("explicit purge action semantics are not canonical")


def build_executable_mutation_plan(assessment: WorkspaceAssessment) -> ExecutableMutationPlan:
    """Issue mutation authority only for a complete blocker-free assessment."""

    plan = assessment.distribution_plan
    plan_operation = _plan_operation_for_intent(assessment.intent)
    if plan.operation != plan_operation:
        raise DistributionPlanError("workspace assessment intent does not match its distribution plan")
    if assessment.intent == "deprovision":
        if (
            assessment.deprovision_contract is None
            or assessment.contract_identity != assessment.deprovision_contract.contract_digest
        ):
            raise DistributionPlanError(
                "workspace assessment contract identity does not match its deprovision contract"
            )
        _revalidate_deprovision_source_snapshots(assessment)
    elif assessment.intent == "purge":
        purge_contract = assessment.explicit_spec_history_purge_contract
        if (
            purge_contract is None
            or assessment.deprovision_contract is None
            or purge_contract.deprovision_contract != assessment.deprovision_contract
            or assessment.contract_identity != purge_contract.contract_digest
            or purge_contract.history_root != _EXPLICIT_SPEC_HISTORY_ROOT
            or purge_contract.authority != _journal_authority_for_intent("purge")
        ):
            raise DistributionPlanError(
                "workspace assessment contract identity does not match its explicit purge contract"
            )
        _revalidate_deprovision_source_snapshots(assessment)
    elif assessment.contract_identity != _contract_identity(plan):
        raise DistributionPlanError("workspace assessment contract identity does not match its distribution plan")
    if assessment.actions != plan.actions:
        raise DistributionPlanError("workspace assessment actions do not match its distribution plan")
    expected_blockers = tuple(action for action in plan.actions if action.blocked)
    if assessment.blockers != expected_blockers:
        raise DistributionPlanError("workspace assessment blockers do not match its distribution plan")
    if assessment.blockers:
        raise DistributionPlanError("workspace assessment contains blocker dispositions")
    if not assessment.actions:
        raise DistributionPlanError("workspace assessment contains no managed actions")
    actions_by_path = {action.path: action for action in assessment.actions}
    snapshots = dict(plan.target_snapshots)
    if len(actions_by_path) != len(assessment.actions) or len(snapshots) != len(plan.target_snapshots):
        raise DistributionPlanError("workspace assessment contains duplicate managed paths")
    if not set(actions_by_path).issubset(snapshots):
        raise DistributionPlanError("workspace assessment is missing snapshots for managed actions")
    current_specs = {
        **_target_identity_specs(plan.current_assets, plan.scaffold_assets),
        **{item.path: DistributionIdentity(kind="directory") for item in plan.required_directories},
    }
    obsolete_paths = {item["path"] for item in plan.manifest.obsolete_exact_files} - set(current_specs)
    for action in assessment.actions:
        try:
            _exact_relative_path(action.path, field_name="workspace assessment action path")
        except DistributionManifestError as exc:
            raise DistributionPlanError("workspace assessment contains an unsafe managed path") from exc
        if action.operation != plan_operation:
            raise DistributionPlanError("workspace assessment action intent mismatch")
        if not _intent_allows_distribution_action(assessment.intent, action.action):
            raise DistributionPlanError("workspace assessment action is not allowed for its intent")
        if action.action == "ensure-directory":
            if not any(item.path == action.path for item in plan.required_directories):
                raise DistributionPlanError("workspace assessment ensure-directory is outside directory authority")
        elif action.action == "prune":
            purge_history_action = (
                assessment.intent == "purge"
                and _is_same_or_descendant(action.path, _EXPLICIT_SPEC_HISTORY_ROOT)
                and action.provenance == "unknown"
                and action.reason == "explicit-spec-history-purge"
            )
            if (
                action.path not in obsolete_paths
                and not (assessment.intent in {"deprovision", "purge"} and action.path in current_specs)
                and not purge_history_action
            ):
                raise DistributionPlanError("workspace assessment prune is outside obsolete authority")
        elif action.action == "remove-empty-directory":
            if assessment.intent not in {"deprovision", "purge"} or not any(
                item.relative_path == action.path for item in assessment.directory_snapshots
            ):
                raise DistributionPlanError("workspace assessment directory removal is outside directory authority")
        elif action.path not in current_specs:
            raise DistributionPlanError("workspace assessment action is outside current authority")
        snapshot = snapshots[action.path]
        if (
            not snapshot.root.exists
            or snapshot.root.file_type != "directory"
            or (snapshot.root.device, snapshot.root.inode)
            != (assessment.root_identity.device, assessment.root_identity.inode)
        ):
            raise DistributionPlanError("workspace assessment root snapshot does not match its root binding")
        _action_precondition_payload(plan, action)
        _action_postcondition_payload(plan, action)
    executable_actions = assessment.actions
    if assessment.intent in {"deprovision", "purge"}:
        executable_actions = _ordered_deprovision_actions(
            tuple(
                action
                for action in assessment.actions
                if action.action in {"prune", "remove-empty-directory"} and snapshots[action.path].target.exists
            )
        )
        _validate_deprovision_plan_metadata(assessment, executable_actions)
        if assessment.intent == "purge":
            _validate_explicit_spec_history_purge_plan_metadata(assessment, executable_actions)
    return ExecutableMutationPlan(
        intent=assessment.intent,
        root_identity=assessment.root_identity,
        contract_identity=assessment.contract_identity,
        plan_digest=_distribution_plan_digest(
            intent=assessment.intent,
            root_identity=assessment.root_identity,
            contract_identity=assessment.contract_identity,
            plan=assessment.distribution_plan,
            actions=executable_actions,
            directory_snapshots=assessment.directory_snapshots,
            leaf_parent_namespace_witnesses=assessment.leaf_parent_namespace_witnesses,
            preservation_witnesses=assessment.preservation_witnesses,
            absence_witnesses=assessment.absence_witnesses,
            source_semantic_identities=(
                assessment.deprovision_contract.source_semantic_identities
                if assessment.deprovision_contract is not None
                else ()
            ),
            generated_state_contract_digest=(
                assessment.deprovision_contract.generated_state.contract_digest
                if assessment.deprovision_contract is not None
                else None
            ),
            active_selection_witnesses=(
                assessment.deprovision_contract.generated_state.active_selection_witnesses
                if assessment.deprovision_contract is not None
                else ()
            ),
        ),
        distribution_plan=assessment.distribution_plan,
        actions=executable_actions,
        directory_snapshots=assessment.directory_snapshots,
        leaf_parent_namespace_witnesses=assessment.leaf_parent_namespace_witnesses,
        preservation_witnesses=assessment.preservation_witnesses,
        absence_witnesses=assessment.absence_witnesses,
        source_semantic_identities=(
            assessment.deprovision_contract.source_semantic_identities
            if assessment.deprovision_contract is not None
            else ()
        ),
        generated_state_contract_digest=(
            assessment.deprovision_contract.generated_state.contract_digest
            if assessment.deprovision_contract is not None
            else None
        ),
        active_selection_witnesses=(
            assessment.deprovision_contract.generated_state.active_selection_witnesses
            if assessment.deprovision_contract is not None
            else ()
        ),
    )


def _staging_leases_payload(journal: OperationJournal) -> list[dict[str, object]]:
    return [
        {
            "path": lease.path,
            "stage_name": lease.stage_name,
            "device": lease.device,
            "inode": lease.inode,
            "ctime_ns": lease.ctime_ns,
            "file_type": lease.file_type,
            **({"role": lease.role} if lease.role != "stage" else {}),
            **(
                {
                    "gc_predecessor_name": lease.gc_predecessor_name,
                    "gc_ordinal": lease.gc_ordinal,
                }
                if lease.gc_predecessor_name is not None
                else {}
            ),
        }
        for lease in journal.staging_leases
    ]


def _staging_leases_digest(
    *,
    operation_id: str,
    leases: list[dict[str, object]],
) -> str:
    payload = {
        "operation_id": operation_id,
        "staging_leases": leases,
    }
    encoded = json.dumps(payload, sort_keys=True, separators=(",", ":")).encode("utf-8")
    return hashlib.sha256(encoded).hexdigest()


def _created_parent_bindings_payload(journal: OperationJournal) -> list[dict[str, object]]:
    # Fresh/update journals retain their legacy binding schema. Deprovision
    # journals have no created-parent inventory; their action/workspace
    # bindings are strict mode-bearing conditions instead.
    return [
        _path_snapshot_condition(binding, include_mode=_is_destructive_intent(journal.intent))
        for binding in journal.created_parent_bindings
    ]


def _created_parent_bindings_digest(
    *,
    operation_id: str,
    bindings: list[dict[str, object]],
) -> str:
    encoded = json.dumps(
        {"operation_id": operation_id, "created_parent_bindings": bindings},
        sort_keys=True,
        separators=(",", ":"),
    ).encode("utf-8")
    return hashlib.sha256(encoded).hexdigest()


def _journal_payload(journal: OperationJournal) -> dict[str, object]:
    leases = _staging_leases_payload(journal)
    created_parent_bindings = _created_parent_bindings_payload(journal)
    payload: dict[str, object] = {
        "schema_version": journal.schema_version,
        "protocol_version": journal.protocol_version,
        "operation_id": journal.operation_id,
        "root_binding": {
            "device": journal.root_identity.device,
            "inode": journal.root_identity.inode,
        },
        "workspace_binding": _path_snapshot_condition(
            journal.workspace_identity,
            include_mode=_is_destructive_intent(journal.intent),
        ),
        "intent": journal.intent,
        "authority": journal.authority,
        "package_version": journal.package_version,
        "contract_identity": journal.contract_identity,
        "plan_digest": journal.plan_digest,
        "created_at_ns": journal.created_at_ns,
        "status": journal.status,
        "actions": [
            {
                "path": action.path,
                "action": action.action,
                "provenance": action.provenance,
                "reason": action.reason,
                "precondition": action.precondition,
                "postcondition": action.postcondition,
                "checkpoint": action.checkpoint,
            }
            for action in (
                journal.actions
                if _is_destructive_intent(journal.intent)
                else sorted(journal.actions, key=lambda item: (item.path, item.action, item.reason))
            )
        ],
        "staging_leases": leases,
        "staging_leases_digest": _staging_leases_digest(
            operation_id=journal.operation_id,
            leases=leases,
        ),
        "created_parent_bindings": created_parent_bindings,
        "created_parent_bindings_digest": _created_parent_bindings_digest(
            operation_id=journal.operation_id,
            bindings=created_parent_bindings,
        ),
    }
    if _is_destructive_intent(journal.intent):
        payload.update({
            "leaf_parent_namespace_witnesses": [
                _leaf_parent_namespace_witness_payload(witness) for witness in journal.leaf_parent_namespace_witnesses
            ],
            "preservation_witnesses": [
                _preservation_witness_payload(witness) for witness in journal.preservation_witnesses
            ],
            "absence_witnesses": [_absence_witness_payload(witness) for witness in journal.absence_witnesses],
            "source_semantic_identities": [
                _source_semantic_payload(identity) for identity in journal.source_semantic_identities
            ],
            "generated_state_contract_digest": journal.generated_state_contract_digest,
            "active_selection_witnesses": [
                _active_selection_witness_payload(witness) for witness in journal.active_selection_witnesses
            ],
        })
    return payload


def _journal_bytes(journal: OperationJournal) -> bytes:
    return (json.dumps(_journal_payload(journal), sort_keys=True, separators=(",", ":")) + "\n").encode("utf-8")


def _journal_relative_path(value: object, *, allow_root: bool = False) -> str:
    if allow_root and value == ".":
        return "."
    try:
        return _exact_relative_path(value, field_name="journal path").as_posix()
    except DistributionManifestError as exc:
        raise DistributionApplyError("journal-protocol-incompatible") from exc


def _journal_sha256(value: object) -> str:
    if not isinstance(value, str) or _SHA256_RE.fullmatch(value) is None:
        raise DistributionApplyError("journal-protocol-incompatible")
    return value


def _journal_integer(value: object, *, minimum: int = 0) -> int:
    if isinstance(value, bool) or not isinstance(value, int) or value < minimum:
        raise DistributionApplyError("journal-protocol-incompatible")
    return value


def _journal_mode(value: object) -> int:
    mode = _journal_integer(value)
    if mode > 0o777:
        raise DistributionApplyError("journal-protocol-incompatible")
    return mode


def _parse_source_semantic_identities(
    raw_identities: object,
) -> tuple[DistributionSourceSemanticIdentity, ...]:
    if not isinstance(raw_identities, list):
        raise DistributionApplyError("journal-protocol-incompatible")
    identities: list[DistributionSourceSemanticIdentity] = []
    for raw_identity in raw_identities:
        if not isinstance(raw_identity, dict) or set(raw_identity) != {
            "canonical_source_path",
            "kind",
            "sha256",
            "mode",
            "link_target",
            "contract_schema_version",
        }:
            raise DistributionApplyError("journal-protocol-incompatible")
        canonical_path = _journal_relative_path(raw_identity["canonical_source_path"])
        kind = raw_identity["kind"]
        mode = _journal_integer(raw_identity["mode"])
        if (
            raw_identity["contract_schema_version"] != 1
            or kind not in {"regular", "symlink"}
            or not canonical_path.startswith(("install-root/", "spec-dock-scaffold/"))
        ):
            raise DistributionApplyError("journal-protocol-incompatible")
        if kind == "regular":
            sha256 = _journal_sha256(raw_identity["sha256"])
            if raw_identity["link_target"] is not None:
                raise DistributionApplyError("journal-protocol-incompatible")
            link_target = None
        else:
            sha256 = None
            link_target = raw_identity["link_target"]
            if (
                raw_identity["sha256"] is not None
                or not isinstance(link_target, str)
                or _normalized_link_target(link_target) != link_target
            ):
                raise DistributionApplyError("journal-protocol-incompatible")
        identities.append(
            DistributionSourceSemanticIdentity(
                canonical_source_path=canonical_path,
                kind=kind,
                sha256=sha256,
                mode=mode,
                link_target=link_target,
                contract_schema_version=1,
            )
        )
    canonical = tuple(sorted(identities, key=lambda item: item.canonical_source_path))
    if tuple(identities) != canonical or len({item.canonical_source_path for item in identities}) != len(identities):
        raise DistributionApplyError("journal-protocol-incompatible")
    return canonical


def _parse_tree_entry_snapshot(raw_entry: object) -> DistributionTreeEntrySnapshot:
    if (
        not isinstance(raw_entry, dict)
        or set(raw_entry)
        != {
            "format_version",
            "relative_path",
            "kind",
            "device",
            "inode",
            "ctime_ns",
            "mode",
            "link_count",
            "size",
            "sha256",
            "link_target",
        }
        or raw_entry["format_version"] != 1
        or raw_entry["kind"] not in {"regular", "directory", "symlink"}
    ):
        raise DistributionApplyError("journal-protocol-incompatible")
    relative_path = _journal_relative_path(raw_entry["relative_path"])
    device = _journal_integer(raw_entry["device"])
    inode = _journal_integer(raw_entry["inode"], minimum=1)
    ctime_ns = _journal_integer(raw_entry["ctime_ns"], minimum=1)
    mode = _journal_integer(raw_entry["mode"])
    link_count = _journal_integer(raw_entry["link_count"], minimum=1)
    kind = raw_entry["kind"]
    size: int | None = None
    sha256: str | None = None
    link_target: str | None = None
    if kind == "regular":
        size = _journal_integer(raw_entry["size"])
        sha256 = _journal_sha256(raw_entry["sha256"])
        if raw_entry["link_target"] is not None or link_count != 1:
            raise DistributionApplyError("journal-protocol-incompatible")
    elif kind == "symlink":
        link_target = raw_entry["link_target"]
        if (
            raw_entry["size"] is not None
            or raw_entry["sha256"] is not None
            or not isinstance(link_target, str)
            or "\x00" in link_target
            or link_count != 1
        ):
            raise DistributionApplyError("journal-protocol-incompatible")
    elif any(raw_entry[field] is not None for field in ("size", "sha256", "link_target")):
        raise DistributionApplyError("journal-protocol-incompatible")
    return DistributionTreeEntrySnapshot(
        relative_path=relative_path,
        kind=kind,
        device=device,
        inode=inode,
        ctime_ns=ctime_ns,
        mode=mode,
        link_count=link_count,
        size=size,
        sha256=sha256,
        link_target=link_target,
    )


def _parse_leaf_parent_namespace_witnesses(
    raw_witnesses: object,
) -> tuple[DistributionLeafParentNamespaceWitness, ...]:
    if not isinstance(raw_witnesses, list):
        raise DistributionApplyError("journal-protocol-incompatible")
    witnesses: list[DistributionLeafParentNamespaceWitness] = []
    binding_fields = {"relative_path", "exists", "device", "inode", "file_type", "mode"}
    protocol_paths = {
        _DISTRIBUTION_RETRY_MARKER_REL.as_posix(),
        _DISTRIBUTION_JOURNAL_REL.as_posix(),
        _UNINSTALL_RETRY_MARKER_REL.as_posix(),
    }
    for raw_witness in raw_witnesses:
        if (
            not isinstance(raw_witness, dict)
            or set(raw_witness) != {"relative_path", "binding", "initial_entries", "initial_namespace_digest"}
            or not isinstance(raw_witness["binding"], dict)
            or set(raw_witness["binding"]) != binding_fields
            or not isinstance(raw_witness["initial_entries"], list)
        ):
            raise DistributionApplyError("journal-protocol-incompatible")
        relative_path = _journal_relative_path(raw_witness["relative_path"])
        if relative_path == ".":
            raise DistributionApplyError("journal-protocol-incompatible")
        binding = raw_witness["binding"]
        if (
            binding["relative_path"] != relative_path
            or binding["exists"] is not True
            or binding["file_type"] != "directory"
            or any(
                isinstance(binding[field], bool) or not isinstance(binding[field], int)
                for field in ("device", "inode", "mode")
            )
        ):
            raise DistributionApplyError("journal-protocol-incompatible")
        entries = tuple(_parse_tree_entry_snapshot(item) for item in raw_witness["initial_entries"])
        if (
            entries != tuple(sorted(entries, key=lambda item: os.fsencode(item.relative_path)))
            or len({entry.relative_path for entry in entries}) != len(entries)
            or any(PurePosixPath(entry.relative_path).parent.as_posix() != relative_path for entry in entries)
            or any(entry.relative_path in protocol_paths for entry in entries)
        ):
            raise DistributionApplyError("journal-protocol-incompatible")
        namespace_digest = _journal_sha256(raw_witness["initial_namespace_digest"])
        if namespace_digest != _leaf_parent_namespace_digest(entries):
            raise DistributionApplyError("journal-protocol-incompatible")
        witnesses.append(
            DistributionLeafParentNamespaceWitness(
                relative_path=relative_path,
                binding=PathIdentitySnapshot(
                    relative_path=relative_path,
                    exists=True,
                    device=binding["device"],
                    inode=binding["inode"],
                    file_type="directory",
                    mode=binding["mode"],
                ),
                initial_entries=entries,
                initial_namespace_digest=namespace_digest,
            )
        )
    canonical = tuple(sorted(witnesses, key=lambda item: os.fsencode(item.relative_path)))
    if tuple(witnesses) != canonical or len({item.relative_path for item in witnesses}) != len(witnesses):
        raise DistributionApplyError("journal-protocol-incompatible")
    return canonical


def _parse_preservation_witnesses(
    raw_witnesses: object,
) -> tuple[DistributionPreservationWitness, ...]:
    if not isinstance(raw_witnesses, list):
        raise DistributionApplyError("journal-protocol-incompatible")
    witnesses: list[DistributionPreservationWitness] = []
    binding_fields = {
        "relative_path",
        "exists",
        "device",
        "inode",
        "ctime_ns",
        "file_type",
        "link_count",
        "mode",
    }
    for raw_witness in raw_witnesses:
        if (
            not isinstance(raw_witness, dict)
            or set(raw_witness) != {"relative_root", "root_binding", "entries", "tree_digest", "reason"}
            or raw_witness["reason"] != "preserved-root"
            or not isinstance(raw_witness["root_binding"], dict)
            or set(raw_witness["root_binding"]) != binding_fields
            or not isinstance(raw_witness["entries"], list)
        ):
            raise DistributionApplyError("journal-protocol-incompatible")
        relative_root = _journal_relative_path(raw_witness["relative_root"])
        binding = raw_witness["root_binding"]
        if binding["relative_path"] != relative_root or not isinstance(binding["exists"], bool):
            raise DistributionApplyError("journal-protocol-incompatible")
        if binding["exists"]:
            if binding["file_type"] != "directory" or any(
                binding[field] is None for field in ("device", "inode", "ctime_ns", "link_count", "mode")
            ):
                raise DistributionApplyError("journal-protocol-incompatible")
            root_binding = PathIdentitySnapshot(
                relative_path=relative_root,
                exists=True,
                device=_journal_integer(binding["device"]),
                inode=_journal_integer(binding["inode"], minimum=1),
                ctime_ns=_journal_integer(binding["ctime_ns"], minimum=1),
                file_type="directory",
                link_count=_journal_integer(binding["link_count"], minimum=1),
                mode=_journal_integer(binding["mode"]),
            )
        else:
            if any(
                binding[field] is not None
                for field in ("device", "inode", "ctime_ns", "file_type", "link_count", "mode")
            ):
                raise DistributionApplyError("journal-protocol-incompatible")
            root_binding = _missing_snapshot(relative_root)
        entries = tuple(_parse_tree_entry_snapshot(item) for item in raw_witness["entries"])
        if (
            tuple(sorted(entries, key=lambda item: os.fsencode(item.relative_path))) != entries
            or len({entry.relative_path for entry in entries}) != len(entries)
            or any(not _is_same_or_descendant(entry.relative_path, relative_root) for entry in entries)
            or (not root_binding.exists and entries)
        ):
            raise DistributionApplyError("journal-protocol-incompatible")
        tree_digest = _journal_sha256(raw_witness["tree_digest"])
        if tree_digest != _preservation_tree_digest(relative_root, root_binding, entries):
            raise DistributionApplyError("journal-protocol-incompatible")
        witnesses.append(
            DistributionPreservationWitness(
                relative_root=relative_root,
                root_binding=root_binding,
                entries=entries,
                tree_digest=tree_digest,
                reason="preserved-root",
            )
        )
    canonical = tuple(sorted(witnesses, key=lambda item: item.relative_root))
    if tuple(witnesses) != canonical or len({item.relative_root for item in witnesses}) != len(witnesses):
        raise DistributionApplyError("journal-protocol-incompatible")
    return canonical


def _parse_absence_witnesses(
    raw_witnesses: object,
) -> tuple[DistributionCollapsedAbsenceWitness, ...]:
    if not isinstance(raw_witnesses, list):
        raise DistributionApplyError("journal-protocol-incompatible")
    witnesses: list[DistributionCollapsedAbsenceWitness] = []
    anchor_fields = {"relative_path", "exists", "device", "inode", "file_type", "mode"}
    for raw_witness in raw_witnesses:
        if (
            not isinstance(raw_witness, dict)
            or set(raw_witness)
            != {
                "relative_root",
                "anchor_path",
                "surviving_anchor",
                "missing_suffix",
                "owned_descendant_paths_digest",
                "reason",
            }
            or raw_witness["reason"] != "owned-subtree-already-absent"
            or not isinstance(raw_witness["surviving_anchor"], dict)
            or set(raw_witness["surviving_anchor"]) != anchor_fields
            or not isinstance(raw_witness["missing_suffix"], list)
            or not raw_witness["missing_suffix"]
        ):
            raise DistributionApplyError("journal-protocol-incompatible")
        relative_root = _journal_relative_path(raw_witness["relative_root"])
        anchor_path = _journal_relative_path(raw_witness["anchor_path"], allow_root=True)
        anchor = raw_witness["surviving_anchor"]
        if anchor["relative_path"] != anchor_path or anchor["exists"] is not True or anchor["file_type"] != "directory":
            raise DistributionApplyError("journal-protocol-incompatible")
        suffix: list[str] = []
        for component in raw_witness["missing_suffix"]:
            if not isinstance(component, str) or _journal_relative_path(component) != component or "/" in component:
                raise DistributionApplyError("journal-protocol-incompatible")
            suffix.append(component)
        anchor_parts = () if anchor_path == "." else PurePosixPath(anchor_path).parts
        if PurePosixPath(*anchor_parts, *suffix).as_posix() != relative_root:
            raise DistributionApplyError("journal-protocol-incompatible")
        surviving_anchor = PathIdentitySnapshot(
            relative_path=anchor_path,
            exists=True,
            device=_journal_integer(anchor["device"]),
            inode=_journal_integer(anchor["inode"], minimum=1),
            file_type="directory",
            mode=_journal_integer(anchor["mode"]),
        )
        witnesses.append(
            DistributionCollapsedAbsenceWitness(
                relative_root=relative_root,
                anchor_path=anchor_path,
                surviving_anchor=surviving_anchor,
                missing_suffix=tuple(suffix),
                owned_descendant_paths_digest=_journal_sha256(raw_witness["owned_descendant_paths_digest"]),
                reason="owned-subtree-already-absent",
            )
        )
    canonical = tuple(sorted(witnesses, key=lambda item: item.relative_root))
    if tuple(witnesses) != canonical or len({item.relative_root for item in witnesses}) != len(witnesses):
        raise DistributionApplyError("journal-protocol-incompatible")
    return canonical


def _parse_active_selection_witnesses(
    raw_witnesses: object,
) -> tuple[DistributionActiveSelectionWitness, ...]:
    if not isinstance(raw_witnesses, list) or len(raw_witnesses) != len(_DEPROVISION_ACTIVE_LAYERS):
        raise DistributionApplyError("journal-protocol-incompatible")
    witnesses: list[DistributionActiveSelectionWitness] = []
    for raw_witness, expected_layer in zip(raw_witnesses, _DEPROVISION_ACTIVE_LAYERS, strict=True):
        if (
            not isinstance(raw_witness, dict)
            or set(raw_witness) != {"layer", "selection", "representation", "target"}
            or raw_witness["layer"] != expected_layer
            or raw_witness["representation"] not in {"symlink", "path", "absent"}
        ):
            raise DistributionApplyError("journal-protocol-incompatible")
        raw_selection = raw_witness["selection"]
        selection: tuple[str, str] | None
        if raw_selection is None:
            selection = None
        else:
            if (
                not isinstance(raw_selection, dict)
                or set(raw_selection) != {"id", "path"}
                or not isinstance(raw_selection["id"], str)
                or _ACTIVE_LAYER_ID_RE[expected_layer].fullmatch(raw_selection["id"]) is None
                or not isinstance(raw_selection["path"], str)
            ):
                raise DistributionApplyError("journal-protocol-incompatible")
            try:
                normalized_path = _exact_relative_path(
                    raw_selection["path"],
                    field_name="journal active selection path",
                ).as_posix()
            except DistributionManifestError as exc:
                raise DistributionApplyError("journal-protocol-incompatible") from exc
            if normalized_path != raw_selection["path"] or not normalized_path.startswith("spec-dock/initiatives/"):
                raise DistributionApplyError("journal-protocol-incompatible")
            selection = (raw_selection["id"], normalized_path)

        representation = cast("ActiveSelectionRepresentation", raw_witness["representation"])
        target = raw_witness["target"]
        if representation == "absent":
            if target is not None:
                raise DistributionApplyError("journal-protocol-incompatible")
        else:
            if (
                not isinstance(target, str)
                or not target
                or "\x00" in target
                or "\n" in target
                or "\r" in target
                or "\\" in target
                or target.startswith("/")
                or _DRIVE_RE.match(target)
                or PurePosixPath(target).as_posix() != target
            ):
                raise DistributionApplyError("journal-protocol-incompatible")
            pointer_path = f"spec-dock/active/{expected_layer}"
            expected_target = (
                selection[1] if selection is not None else f"spec-dock/system/active-none/{expected_layer}"
            )
            if (
                _lexical_generated_target(
                    pointer_path if representation == "symlink" else f"{pointer_path}.path", target
                )
                != expected_target
            ):
                raise DistributionApplyError("journal-protocol-incompatible")
        witnesses.append(
            DistributionActiveSelectionWitness(
                layer=cast("ActiveSelectionLayer", expected_layer),
                selection=selection,
                representation=representation,
                target=target if isinstance(target, str) else None,
            )
        )
    return tuple(witnesses)


def _valid_journal_identity_payload(value: object, *, expected_kind: str) -> bool:
    if not isinstance(value, dict) or set(value) != {"kind", "sha256", "mode", "target"}:
        return False
    if value["kind"] != expected_kind:
        return False
    if expected_kind == "regular":
        return (
            isinstance(value["sha256"], str)
            and _SHA256_RE.fullmatch(value["sha256"]) is not None
            and isinstance(value["mode"], int)
            and not isinstance(value["mode"], bool)
            and value["mode"] >= 0
            and value["target"] is None
        )
    if expected_kind == "symlink":
        return (
            value["sha256"] is None
            and value["mode"] is None
            and isinstance(value["target"], str)
            and "\x00" not in value["target"]
        )
    return False


def _validate_journal_path_condition(
    value: object,
    *,
    expected_path: str,
    require_directory: bool,
    require_mode: bool = False,
) -> None:
    base_fields = {"relative_path", "exists", "device", "inode", "ctime_ns", "file_type", "link_count"}
    allowed_fields = base_fields | ({"mode"} if require_mode else set())
    if (
        not isinstance(value, dict)
        or set(value) != allowed_fields
        or value["relative_path"] != expected_path
        or value["exists"] is not True
        or (require_directory and value["file_type"] != "directory")
        or value["file_type"] not in {"regular", "directory", "symlink"}
    ):
        raise DistributionApplyError("journal-protocol-incompatible")
    _journal_integer(value["device"])
    _journal_integer(value["inode"], minimum=1)
    _journal_integer(value["ctime_ns"], minimum=0)
    _journal_integer(value["link_count"], minimum=0)
    if require_mode:
        _journal_mode(value["mode"])


def _validate_leaf_parent_namespace_witness_shape(
    witnesses: tuple[DistributionLeafParentNamespaceWitness, ...],
) -> dict[str, DistributionLeafParentNamespaceWitness]:
    """Validate canonical, immutable shape of leaf-parent namespace evidence."""

    canonical = tuple(sorted(witnesses, key=lambda item: os.fsencode(item.relative_path)))
    if witnesses != canonical or len({item.relative_path for item in witnesses}) != len(witnesses):
        raise DistributionApplyError("journal-protocol-incompatible")
    result: dict[str, DistributionLeafParentNamespaceWitness] = {}
    protocol_paths = {
        _DISTRIBUTION_RETRY_MARKER_REL.as_posix(),
        _DISTRIBUTION_JOURNAL_REL.as_posix(),
        _UNINSTALL_RETRY_MARKER_REL.as_posix(),
    }
    for witness in witnesses:
        relative_path = _journal_relative_path(witness.relative_path)
        binding_device = witness.binding.device
        binding_inode = witness.binding.inode
        binding_mode = witness.binding.mode
        if (
            relative_path == "."
            or witness.binding.relative_path != relative_path
            or not witness.binding.exists
            or witness.binding.file_type != "directory"
            or any(
                value is None or isinstance(value, bool) or not isinstance(value, int)
                for value in (binding_device, binding_inode, binding_mode)
            )
        ):
            raise DistributionApplyError("journal-protocol-incompatible")
        assert binding_inode is not None
        assert binding_mode is not None
        if binding_inode < 1 or binding_mode < 0 or binding_mode > 0o777:
            raise DistributionApplyError("journal-protocol-incompatible")
        entries = witness.initial_entries
        if entries != tuple(sorted(entries, key=lambda item: os.fsencode(item.relative_path))) or len({
            entry.relative_path for entry in entries
        }) != len(entries):
            raise DistributionApplyError("journal-protocol-incompatible")
        for entry in entries:
            if (
                _journal_relative_path(entry.relative_path) == "."
                or PurePosixPath(entry.relative_path).parent.as_posix() != relative_path
                or entry.relative_path in protocol_paths
                or entry.device < 0
                or entry.inode < 1
                or entry.ctime_ns < 1
                or entry.mode < 0
                or entry.mode > 0o777
                or entry.link_count < 1
            ):
                raise DistributionApplyError("journal-protocol-incompatible")
            if entry.kind == "regular":
                if (
                    entry.size is None
                    or entry.size < 0
                    or not isinstance(entry.sha256, str)
                    or _SHA256_RE.fullmatch(entry.sha256) is None
                    or entry.link_target is not None
                    or entry.link_count != 1
                ):
                    raise DistributionApplyError("journal-protocol-incompatible")
            elif entry.kind == "symlink":
                if (
                    entry.size is not None
                    or entry.sha256 is not None
                    or not isinstance(entry.link_target, str)
                    or "\x00" in entry.link_target
                    or entry.link_count != 1
                ):
                    raise DistributionApplyError("journal-protocol-incompatible")
            elif entry.kind == "directory":
                if entry.size is not None or entry.sha256 is not None or entry.link_target is not None:
                    raise DistributionApplyError("journal-protocol-incompatible")
            else:
                raise DistributionApplyError("journal-protocol-incompatible")
        if _journal_sha256(witness.initial_namespace_digest) != _leaf_parent_namespace_digest(entries):
            raise DistributionApplyError("journal-protocol-incompatible")
        result[relative_path] = witness
    return result


def _leaf_namespace_entry_matches_snapshot(
    entry: DistributionTreeEntrySnapshot,
    snapshot: PathIdentitySnapshot,
) -> bool:
    if (
        not snapshot.exists
        or entry.relative_path != snapshot.relative_path
        or entry.kind != snapshot.file_type
        or entry.device != snapshot.device
        or entry.inode != snapshot.inode
        or entry.ctime_ns != snapshot.ctime_ns
        or entry.mode != snapshot.mode
        or entry.link_count != snapshot.link_count
    ):
        return False
    if entry.kind == "regular":
        return (
            entry.size == snapshot.size
            and snapshot.identity is not None
            and snapshot.identity.kind == "regular"
            and entry.sha256 == snapshot.identity.sha256
            and entry.link_target is None
        )
    if entry.kind == "symlink":
        return (
            entry.size is None
            and entry.sha256 is None
            and snapshot.identity is not None
            and snapshot.identity.kind == "symlink"
            and entry.link_target == snapshot.identity.target
        )
    return entry.size is None and entry.sha256 is None and entry.link_target is None


def _same_structure_identity_snapshot(
    left: PathIdentitySnapshot,
    right: PathIdentitySnapshot,
) -> bool:
    return (
        left.exists
        and right.exists
        and left.file_type == right.file_type == "directory"
        and left.device == right.device
        and left.inode == right.inode
        and left.mode == right.mode
    )


def _leaf_namespace_entry_matches_precondition(
    entry: DistributionTreeEntrySnapshot,
    precondition: dict[str, object],
) -> bool:
    kind = precondition.get("file_type")
    identity = precondition.get("identity")
    if (
        precondition.get("exists") is not True
        or not isinstance(kind, str)
        or entry.kind != kind
        or entry.device != precondition.get("device")
        or entry.inode != precondition.get("inode")
        or entry.ctime_ns != precondition.get("ctime_ns")
        or entry.mode != precondition.get("mode")
        or entry.link_count != precondition.get("link_count")
        or not isinstance(identity, dict)
    ):
        return False
    if kind == "regular":
        return (
            entry.size == precondition.get("size")
            and entry.sha256 == identity.get("sha256")
            and entry.link_target is None
        )
    if kind == "symlink":
        return entry.size is None and entry.sha256 is None and entry.link_target == identity.get("target")
    return entry.size is None and entry.sha256 is None and entry.link_target is None


def _leaf_namespace_entry_matches_precondition_semantic(
    entry: DistributionTreeEntrySnapshot,
    precondition: dict[str, object],
) -> bool:
    """Match a renamed predecessor while ignoring rename-mutated ctime."""

    kind = precondition.get("file_type")
    identity = precondition.get("identity")
    if (
        precondition.get("exists") is not True
        or not isinstance(kind, str)
        or entry.kind != kind
        or entry.device != precondition.get("device")
        or entry.inode != precondition.get("inode")
        or entry.mode != precondition.get("mode")
        or entry.link_count != precondition.get("link_count")
        or not isinstance(identity, dict)
    ):
        return False
    if kind == "regular":
        return (
            entry.size == precondition.get("size")
            and entry.sha256 == identity.get("sha256")
            and entry.link_target is None
        )
    if kind == "symlink":
        return entry.size is None and entry.sha256 is None and entry.link_target == identity.get("target")
    return entry.size is None and entry.sha256 is None and entry.link_target is None


def _validate_leaf_parent_namespace_witness_coverage(
    actions: tuple[OperationJournalAction, ...] | tuple[DistributionAction, ...],
    witnesses: tuple[DistributionLeafParentNamespaceWitness, ...],
    *,
    target_snapshots: Mapping[str, DistributionTargetSnapshot] | None = None,
) -> None:
    witness_by_parent = _validate_leaf_parent_namespace_witness_shape(witnesses)
    covered_parents: set[str] = set()
    for action in actions:
        if action.action != "prune":
            continue
        path = action.path
        parent_path = PurePosixPath(path).parent.as_posix()
        if parent_path == ".":
            continue
        witness = witness_by_parent.get(parent_path)
        if target_snapshots is not None:
            target_snapshot = target_snapshots.get(path)
            if target_snapshot is None or not target_snapshot.target.exists:
                continue
            snapshot = target_snapshot
        elif isinstance(action, OperationJournalAction) and action.precondition.get("exists") is not True:
            continue
        if witness is None:
            raise DistributionApplyError("journal-plan-mismatch")
        covered_parents.add(parent_path)
        entries = {entry.relative_path: entry for entry in witness.initial_entries}
        entry = entries.get(path)
        if entry is None:
            raise DistributionApplyError("journal-plan-mismatch")
        if target_snapshots is not None:
            if not _leaf_namespace_entry_matches_snapshot(entry, snapshot.target):
                raise DistributionApplyError("journal-plan-mismatch")
            parent_binding = next(
                (parent for parent in snapshot.parents if parent.relative_path == parent_path),
                None,
            )
            if parent_binding is None or not _same_structure_identity_snapshot(witness.binding, parent_binding):
                raise DistributionApplyError("journal-plan-mismatch")
        else:
            assert isinstance(action, OperationJournalAction)
            if not _leaf_namespace_entry_matches_precondition(entry, action.precondition):
                raise DistributionApplyError("journal-plan-mismatch")
            raw_parents = action.precondition.get("parents")
            parent_condition = (
                next(
                    (
                        item
                        for item in raw_parents
                        if isinstance(item, dict) and item.get("relative_path") == parent_path
                    ),
                    None,
                )
                if isinstance(raw_parents, list)
                else None
            )
            if (
                parent_condition is None
                or parent_condition.get("file_type") != "directory"
                or parent_condition.get("device") != witness.binding.device
                or parent_condition.get("inode") != witness.binding.inode
                or parent_condition.get("mode") != witness.binding.mode
            ):
                raise DistributionApplyError("journal-plan-mismatch")
    if set(witness_by_parent) != covered_parents:
        raise DistributionApplyError("journal-plan-mismatch")


def _validate_deprovision_journal_actions(
    actions: tuple[OperationJournalAction, ...],
    *,
    intent: Literal["deprovision", "purge"] = "deprovision",
    status: JournalStatus,
    leaf_parent_namespace_witnesses: tuple[DistributionLeafParentNamespaceWitness, ...],
    preservation_witnesses: tuple[DistributionPreservationWitness, ...],
    absence_witnesses: tuple[DistributionCollapsedAbsenceWitness, ...],
    allow_witnessless_completed: bool = False,
) -> None:
    if not actions or len({action.path for action in actions}) != len(actions):
        raise DistributionApplyError("journal-protocol-incompatible")
    expected_order = tuple(
        sorted(
            (action for action in actions if action.action == "prune"),
            key=lambda action: (-len(PurePosixPath(action.path).parts), action.path),
        )
        + sorted(
            (action for action in actions if action.action == "remove-empty-directory"),
            key=lambda action: (-len(PurePosixPath(action.path).parts), action.path),
        )
    )
    allowed_provenance = {"current", "historical"} | ({"unknown"} if intent == "purge" else set())
    if actions != expected_order or any(
        action.action not in {"prune", "remove-empty-directory"} or action.provenance not in allowed_provenance
        for action in actions
    ):
        raise DistributionApplyError("journal-protocol-incompatible")
    if allow_witnessless_completed:
        if status != "completed" or leaf_parent_namespace_witnesses:
            raise DistributionApplyError("journal-protocol-incompatible")
    else:
        _validate_leaf_parent_namespace_witness_coverage(actions, leaf_parent_namespace_witnesses)
    action_by_path = {action.path: action for action in actions}
    action_index = {action.path: index for index, action in enumerate(actions)}
    children_by_parent: dict[str, list[str]] = {}
    for candidate in actions:
        parent = PurePosixPath(candidate.path).parent.as_posix()
        children_by_parent.setdefault(parent, []).append(candidate.path)
    for children in children_by_parent.values():
        children.sort(key=os.fsencode)
    empty_digest = _directory_child_digest(())
    for action in actions:
        path = _journal_relative_path(action.path)
        if path != action.path:
            raise DistributionApplyError("journal-protocol-incompatible")
        precondition = action.precondition
        postcondition = action.postcondition
        if (
            intent == "purge"
            and action.provenance == "unknown"
            and not _is_same_or_descendant(
                path,
                _EXPLICIT_SPEC_HISTORY_ROOT,
            )
        ):
            raise DistributionApplyError("journal-protocol-incompatible")
        if intent == "purge" and _is_same_or_descendant(path, _EXPLICIT_SPEC_HISTORY_ROOT):
            expected_reason = (
                "explicit-spec-history-purge-directory"
                if action.action == "remove-empty-directory"
                else "explicit-spec-history-purge"
            )
            if action.provenance != "unknown" or action.reason != expected_reason:
                raise DistributionApplyError("journal-protocol-incompatible")
        base_precondition_fields = {
            "root",
            "parents",
            "exists",
            "device",
            "inode",
            "ctime_ns",
            "file_type",
            "link_count",
            "identity",
            "mode",
            "size",
        }
        expected_precondition_fields = (
            base_precondition_fields
            | {"initial_child_digest", "immediate_child_evidence", "expected_remaining_child_digest"}
            if action.action == "remove-empty-directory"
            else base_precondition_fields
        )
        if (
            set(precondition) != expected_precondition_fields
            or set(postcondition) != {"root", "parents", "exists", "identity"}
            or precondition["exists"] is not True
            or postcondition["exists"] is not False
            or postcondition["identity"] is not None
            or precondition["root"] != postcondition["root"]
            or precondition["parents"] != postcondition["parents"]
            or not isinstance(precondition["parents"], list)
        ):
            raise DistributionApplyError("journal-protocol-incompatible")
        _validate_journal_path_condition(
            precondition["root"],
            expected_path=".",
            require_directory=True,
            require_mode=True,
        )
        expected_parents = [
            "/".join(PurePosixPath(path).parts[:index]) for index in range(1, len(PurePosixPath(path).parts))
        ]
        if len(precondition["parents"]) != len(expected_parents):
            raise DistributionApplyError("journal-protocol-incompatible")
        for raw_parent, expected_parent in zip(precondition["parents"], expected_parents, strict=True):
            _validate_journal_path_condition(
                raw_parent,
                expected_path=expected_parent,
                require_directory=True,
                require_mode=True,
            )
        _journal_integer(precondition["device"])
        _journal_integer(precondition["inode"], minimum=1)
        _journal_integer(precondition["ctime_ns"], minimum=1)
        _journal_integer(precondition["link_count"], minimum=1)
        _journal_integer(precondition["mode"])
        if precondition["size"] is not None:
            _journal_integer(precondition["size"])
        if action.action == "prune":
            if precondition["file_type"] not in {"regular", "symlink"} or not _valid_journal_identity_payload(
                precondition["identity"],
                expected_kind=cast("str", precondition["file_type"]),
            ):
                raise DistributionApplyError("journal-protocol-incompatible")
            continue
        if (
            precondition["file_type"] != "directory"
            or precondition["identity"] is not None
            or precondition["size"] is not None
            or _journal_sha256(precondition["initial_child_digest"]) == ""
            or _journal_sha256(precondition["expected_remaining_child_digest"]) != empty_digest
            or not isinstance(precondition["immediate_child_evidence"], list)
        ):
            raise DistributionApplyError("journal-protocol-incompatible")
        evidence_paths: list[str] = []
        for evidence in precondition["immediate_child_evidence"]:
            if (
                not isinstance(evidence, dict)
                or set(evidence)
                != {
                    "child_path",
                    "child_kind",
                    "action_path",
                    "required_checkpoint",
                    "expected_postcondition",
                }
                or evidence["required_checkpoint"] != "published"
                or evidence["child_kind"] not in {"leaf", "directory"}
                or evidence["child_path"] != evidence["action_path"]
                or not isinstance(evidence["expected_postcondition"], dict)
                or evidence["expected_postcondition"] != {"path": evidence["child_path"], "exists": False}
            ):
                raise DistributionApplyError("journal-protocol-incompatible")
            child_path = _journal_relative_path(evidence["child_path"])
            child_action = action_by_path.get(child_path)
            expected_child_action = "remove-empty-directory" if evidence["child_kind"] == "directory" else "prune"
            if (
                PurePosixPath(child_path).parent.as_posix() != path
                or child_action is None
                or child_action.action != expected_child_action
                or action_index[child_path] >= action_index[path]
            ):
                raise DistributionApplyError("journal-protocol-incompatible")
            evidence_paths.append(child_path)
        expected_children = children_by_parent.get(path, [])
        if evidence_paths != expected_children or len(set(evidence_paths)) != len(evidence_paths):
            raise DistributionApplyError("journal-protocol-incompatible")

    for preservation_witness in preservation_witnesses:
        if any(_is_same_or_descendant(action.path, preservation_witness.relative_root) for action in actions):
            raise DistributionApplyError("journal-protocol-incompatible")
    for absence_witness in absence_witnesses:
        if any(_is_same_or_descendant(action.path, absence_witness.relative_root) for action in actions):
            raise DistributionApplyError("journal-protocol-incompatible")

    checkpoints = tuple(action.checkpoint for action in actions)
    if status == "prepared":
        reachable = all(checkpoint == "pending" for checkpoint in checkpoints)
    elif status == "executing":
        reachable = all(checkpoint in {"pending", "published"} for checkpoint in checkpoints)
    elif status == "verifying":
        reachable = all(checkpoint == "published" for checkpoint in checkpoints)
    else:
        reachable = all(checkpoint == "verified" for checkpoint in checkpoints)
    if not reachable:
        raise DistributionApplyError("journal-protocol-incompatible")
    for action in actions:
        if action.action != "remove-empty-directory" or action.checkpoint == "pending":
            continue
        for evidence in cast("list[dict[str, object]]", action.precondition["immediate_child_evidence"]):
            child = action_by_path[cast("str", evidence["action_path"])]
            if action.checkpoint == "published" and child.checkpoint != "published":
                raise DistributionApplyError("journal-protocol-incompatible")
            if action.checkpoint == "verified" and child.checkpoint != "verified":
                raise DistributionApplyError("journal-protocol-incompatible")


def _parse_operation_journal(
    raw: bytes,
    *,
    expected_intent: JournaledDistributionIntent | None = None,
) -> OperationJournal:
    try:
        payload = json.loads(raw.decode("utf-8"))
    except (UnicodeDecodeError, json.JSONDecodeError) as exc:
        raise DistributionApplyError("journal-protocol-incompatible") from exc
    if not isinstance(payload, dict):
        raise DistributionApplyError("journal-protocol-incompatible")
    expected_fields = {
        "schema_version",
        "protocol_version",
        "operation_id",
        "root_binding",
        "workspace_binding",
        "intent",
        "authority",
        "package_version",
        "contract_identity",
        "plan_digest",
        "created_at_ns",
        "status",
        "actions",
        "staging_leases",
        "staging_leases_digest",
        "created_parent_bindings",
        "created_parent_bindings_digest",
    }
    is_deprovision = payload.get("intent") == "deprovision"
    is_purge = payload.get("intent") == "purge"
    is_destructive = is_deprovision or is_purge
    raw_intent = payload.get("intent")
    journal_intent_supported = isinstance(raw_intent, str) and raw_intent in _SUPPORTED_JOURNALED_INTENTS
    raw_authority = payload.get("authority")
    journal_authority_supported = (
        journal_intent_supported
        and isinstance(raw_authority, str)
        and raw_authority == _journal_authority_for_intent(cast("JournaledDistributionIntent", raw_intent))
    )
    canonical_authority_intents = _canonical_journal_authority_intents(raw_authority)
    expected_intent_supported = isinstance(expected_intent, str) and expected_intent in _SUPPORTED_JOURNALED_INTENTS
    authority_mismatch_kind: DistributionRecoveryMismatchKind | None = None
    if journal_intent_supported and canonical_authority_intents:
        if cast("JournaledDistributionIntent", raw_intent) not in canonical_authority_intents:
            authority_mismatch_kind = "intent-authority"
        if expected_intent_supported and (
            raw_intent != expected_intent or expected_intent not in canonical_authority_intents
        ):
            authority_mismatch_kind = "intent-authority"
    if journal_intent_supported and isinstance(raw_authority, str) and not journal_authority_supported:
        authority_mismatch_kind = "intent-authority"
        raise DistributionApplyError(
            "journal-authority-mismatch",
            recovery_mismatch_kind=authority_mismatch_kind,
        )
    if (
        expected_intent_supported
        and journal_intent_supported
        and journal_authority_supported
        and raw_intent != expected_intent
    ):
        raise DistributionApplyError(
            "journal-authority-mismatch",
            recovery_mismatch_kind="intent-authority",
        )
    legacy_witnessless_deprovision = False
    if is_destructive:
        expected_fields.update({
            "leaf_parent_namespace_witnesses",
            "preservation_witnesses",
            "absence_witnesses",
            "source_semantic_identities",
            "generated_state_contract_digest",
            "active_selection_witnesses",
        })
    workspace_fields = {
        "relative_path",
        "exists",
        "device",
        "inode",
        "ctime_ns",
        "file_type",
        "link_count",
    } | ({"mode"} if is_destructive else set())
    if is_deprovision and set(payload) == expected_fields - {"leaf_parent_namespace_witnesses"}:
        legacy_witnessless_deprovision = True
        raw_actions = payload.get("actions")
        raw_leases = payload.get("staging_leases")
        if (
            payload.get("status") != "completed"
            or not isinstance(raw_actions, list)
            or any(not isinstance(item, dict) or item.get("checkpoint") != "verified" for item in raw_actions)
            or raw_leases != []
        ):
            raise DistributionApplyError("journal-protocol-incompatible")
    elif set(payload) != expected_fields:
        raise DistributionApplyError("journal-protocol-incompatible")
    root = payload["root_binding"]
    workspace = payload["workspace_binding"]
    actions = payload["actions"]
    journal_schema_supported = payload["schema_version"] == _DISTRIBUTION_JOURNAL_SCHEMA_VERSION
    schema_intent_supported = payload["schema_version"] == _DISTRIBUTION_JOURNAL_SCHEMA_VERSION
    if (
        not journal_schema_supported
        or not schema_intent_supported
        or not journal_intent_supported
        or not journal_authority_supported
        or payload["protocol_version"] not in _DISTRIBUTION_SUPPORTED_JOURNAL_PROTOCOL_VERSIONS
        or (is_destructive and payload["protocol_version"] != _DISTRIBUTION_JOURNAL_PROTOCOL_VERSION)
        or not isinstance(root, dict)
        or set(root) != {"device", "inode"}
        or not all(isinstance(root[field], int) for field in ("device", "inode"))
        or not isinstance(workspace, dict)
        or set(workspace) != workspace_fields
        or workspace.get("relative_path") != "spec-dock"
        or workspace.get("exists") is not True
        or workspace.get("file_type") != "directory"
        or any(
            isinstance(workspace.get(field), bool) or not isinstance(workspace.get(field), int)
            for field in ("device", "inode", "ctime_ns", "link_count")
        )
        or not isinstance(payload["authority"], str)
        or not isinstance(payload["package_version"], str)
        or not isinstance(payload["operation_id"], str)
        or not isinstance(payload["contract_identity"], str)
        or not isinstance(payload["plan_digest"], str)
        or not isinstance(payload["created_at_ns"], int)
        or payload["status"] not in {"prepared", "executing", "verifying", "completed"}
        or not isinstance(actions, list)
    ):
        raise DistributionApplyError("journal-protocol-incompatible")
    if is_destructive:
        _journal_mode(workspace["mode"])
    preservation_witnesses: tuple[DistributionPreservationWitness, ...] = ()
    absence_witnesses: tuple[DistributionCollapsedAbsenceWitness, ...] = ()
    source_semantic_identities: tuple[DistributionSourceSemanticIdentity, ...] = ()
    generated_state_contract_digest: str | None = None
    active_selection_witnesses: tuple[DistributionActiveSelectionWitness, ...] = ()
    leaf_parent_namespace_witnesses: tuple[DistributionLeafParentNamespaceWitness, ...] = ()
    if is_destructive:
        if not legacy_witnessless_deprovision:
            leaf_parent_namespace_witnesses = _parse_leaf_parent_namespace_witnesses(
                payload["leaf_parent_namespace_witnesses"]
            )
        preservation_witnesses = _parse_preservation_witnesses(payload["preservation_witnesses"])
        absence_witnesses = _parse_absence_witnesses(payload["absence_witnesses"])
        source_semantic_identities = _parse_source_semantic_identities(payload["source_semantic_identities"])
        generated_state_contract_digest = _journal_sha256(payload["generated_state_contract_digest"])
        active_selection_witnesses = _parse_active_selection_witnesses(payload["active_selection_witnesses"])
    parsed_actions: list[OperationJournalAction] = []
    for item in actions:
        if (
            not isinstance(item, dict)
            or set(item) != {"path", "action", "provenance", "reason", "precondition", "postcondition", "checkpoint"}
            or not isinstance(item["path"], str)
            or item["action"]
            not in {
                "create",
                "adopt",
                "upgrade",
                "prune",
                "preserve",
                "block",
                "ensure-directory",
                "remove-empty-directory",
            }
            or item["provenance"] not in {"missing", "current", "historical", "unknown"}
            or not isinstance(item["reason"], str)
            or not isinstance(item["precondition"], dict)
            or not isinstance(item["postcondition"], dict)
            or item["checkpoint"] not in {"pending", "published", "verified"}
        ):
            raise DistributionApplyError("journal-protocol-incompatible")
        parsed_actions.append(
            OperationJournalAction(
                path=item["path"],
                action=item["action"],
                provenance=item["provenance"],
                reason=item["reason"],
                precondition=item["precondition"],
                postcondition=item["postcondition"],
                checkpoint=item["checkpoint"],
            )
        )
    raw_leases = payload["staging_leases"]
    if (
        not isinstance(raw_leases, list)
        or not isinstance(payload["staging_leases_digest"], str)
        or payload["staging_leases_digest"]
        != _staging_leases_digest(
            operation_id=payload["operation_id"],
            leases=raw_leases,
        )
    ):
        raise DistributionApplyError("journal-protocol-incompatible")
    leases: list[DistributionStageOwnership] = []
    for item in raw_leases:
        lease_fields = {"path", "stage_name", "device", "inode", "ctime_ns", "file_type"}
        transition_fields = {"gc_predecessor_name", "gc_ordinal"}
        item_fields = frozenset(item) if isinstance(item, dict) else frozenset()
        has_transition = item_fields == frozenset(lease_fields | {"role"} | transition_fields)
        if (
            not isinstance(item, dict)
            or item_fields
            not in {
                frozenset(lease_fields),
                frozenset(lease_fields | {"role"}),
                frozenset(lease_fields | {"role"} | transition_fields),
            }
            or not isinstance(item["path"], str)
            or not isinstance(item["stage_name"], str)
            or PurePosixPath(item["stage_name"]).name != item["stage_name"]
            or any(not isinstance(item[field], int) for field in ("device", "inode", "ctime_ns"))
            or not (
                all(item[field] == 0 for field in ("device", "inode", "ctime_ns"))
                or all(item[field] > 0 for field in ("device", "inode", "ctime_ns"))
            )
            or item["file_type"] not in {"regular", "symlink"}
            or item.get("role", "stage")
            not in {
                "stage",
                "predecessor-quarantine",
                "backup-reserved",
                "backup-dual",
                "backup-only-reserved",
                "backup-only",
                "gc-reserved",
                "gc-exact",
            }
            or (
                has_transition
                and (
                    item.get("role") not in {"gc-reserved", "gc-exact", "backup-only"}
                    or not isinstance(item["gc_predecessor_name"], str)
                    or PurePosixPath(item["gc_predecessor_name"]).name != item["gc_predecessor_name"]
                    or item["gc_predecessor_name"] == item["stage_name"]
                    or not isinstance(item["gc_ordinal"], int)
                    or isinstance(item["gc_ordinal"], bool)
                    or item["gc_ordinal"] not in {1, 2, 3}
                )
            )
        ):
            raise DistributionApplyError("journal-protocol-incompatible")
        leases.append(
            DistributionStageOwnership(
                path=item["path"],
                stage_name=item["stage_name"],
                device=item["device"],
                inode=item["inode"],
                ctime_ns=item["ctime_ns"],
                file_type=item["file_type"],
                role=item.get(
                    "role",
                    "predecessor-quarantine" if item["stage_name"].endswith(".remove") else "stage",
                ),
                gc_predecessor_name=(item["gc_predecessor_name"] if has_transition else None),
                gc_ordinal=(item["gc_ordinal"] if has_transition else None),
            )
        )
    raw_bindings = payload["created_parent_bindings"]
    if (
        not isinstance(raw_bindings, list)
        or not isinstance(payload["created_parent_bindings_digest"], str)
        or payload["created_parent_bindings_digest"]
        != _created_parent_bindings_digest(
            operation_id=payload["operation_id"],
            bindings=raw_bindings,
        )
    ):
        raise DistributionApplyError("journal-protocol-incompatible")
    created_parent_bindings: list[PathIdentitySnapshot] = []
    for item in raw_bindings:
        if (
            not isinstance(item, dict)
            or set(item) != {"relative_path", "exists", "device", "inode", "ctime_ns", "file_type", "link_count"}
            or not isinstance(item["relative_path"], str)
            or not isinstance(item["exists"], bool)
            or (
                item["exists"] is True
                and (
                    any(not isinstance(item[field], int) for field in ("device", "inode", "ctime_ns", "link_count"))
                    or item["file_type"] != "directory"
                )
            )
            or (
                item["exists"] is False
                and any(item[field] is not None for field in ("device", "inode", "ctime_ns", "file_type", "link_count"))
            )
        ):
            raise DistributionApplyError("journal-protocol-incompatible")
        created_parent_bindings.append(
            PathIdentitySnapshot(
                relative_path=item["relative_path"],
                exists=item["exists"],
                device=item["device"],
                inode=item["inode"],
                ctime_ns=item["ctime_ns"],
                file_type=item["file_type"],
                link_count=item["link_count"],
            )
        )
    if len({item.relative_path for item in created_parent_bindings}) != len(created_parent_bindings):
        raise DistributionApplyError("journal-protocol-incompatible")
    checkpoints = {action.checkpoint for action in parsed_actions}
    prepared_leases_are_guard_inheritable = all(
        lease.role == "stage" and lease.device > 0 and lease.inode > 0 and lease.ctime_ns > 0 for lease in leases
    )
    if is_destructive:
        deprovision_actions = {action.path: action for action in parsed_actions}
        if created_parent_bindings or (
            leases
            and (
                payload["status"] != "executing"
                or any(
                    lease.path not in deprovision_actions
                    or deprovision_actions[lease.path].action != "prune"
                    or deprovision_actions[lease.path].checkpoint == "verified"
                    for lease in leases
                )
            )
        ):
            raise DistributionApplyError("journal-protocol-incompatible")
        _validate_deprovision_journal_actions(
            tuple(parsed_actions),
            intent=cast("Literal['deprovision', 'purge']", payload["intent"]),
            status=cast("JournalStatus", payload["status"]),
            leaf_parent_namespace_witnesses=leaf_parent_namespace_witnesses,
            preservation_witnesses=preservation_witnesses,
            absence_witnesses=absence_witnesses,
            allow_witnessless_completed=legacy_witnessless_deprovision,
        )
    elif (
        (payload["status"] == "prepared" and (checkpoints - {"pending"} or not prepared_leases_are_guard_inheritable))
        or (payload["status"] == "executing" and "verified" in checkpoints)
        or (
            payload["status"] in {"verifying", "completed"}
            and (
                checkpoints != {"verified"} or leases or any(not binding.exists for binding in created_parent_bindings)
            )
        )
    ):
        raise DistributionApplyError("journal-protocol-incompatible")
    return OperationJournal(
        schema_version=payload["schema_version"],
        protocol_version=payload["protocol_version"],
        operation_id=payload["operation_id"],
        root_identity=DistributionRootIdentity(device=root["device"], inode=root["inode"]),
        workspace_identity=PathIdentitySnapshot(
            relative_path="spec-dock",
            exists=True,
            device=workspace["device"],
            inode=workspace["inode"],
            ctime_ns=workspace["ctime_ns"],
            file_type="directory",
            link_count=workspace["link_count"],
            mode=workspace.get("mode"),
        ),
        intent=payload["intent"],
        authority=payload["authority"],
        package_version=payload["package_version"],
        contract_identity=payload["contract_identity"],
        plan_digest=payload["plan_digest"],
        created_at_ns=payload["created_at_ns"],
        status=payload["status"],
        actions=tuple(parsed_actions),
        preservation_witnesses=preservation_witnesses,
        absence_witnesses=absence_witnesses,
        leaf_parent_namespace_witnesses=leaf_parent_namespace_witnesses,
        source_semantic_identities=source_semantic_identities,
        generated_state_contract_digest=generated_state_contract_digest,
        active_selection_witnesses=active_selection_witnesses,
        staging_leases=tuple(leases),
        created_parent_bindings=tuple(created_parent_bindings),
    )


def _journal_package_is_compatible(journal_version: str, executing_version: str) -> bool:
    """Allow the same journal protocol to move forward, never backward."""

    try:
        journal_tuple = _parse_package_version(journal_version, source="journal package version")
        executing_tuple = _parse_package_version(executing_version, source="executing package version")
    except DistributionAdmissionError:
        return False
    return executing_tuple >= journal_tuple


class OperationJournalStore:
    """Descriptor-bound durable storage for one recognized operation journal."""

    def __init__(
        self,
        target_root: Path,
        *,
        identity_path: Path | None = None,
        expected_workspace_identity: tuple[int, int] | None = None,
        workspace_closed_set_validator: Callable[[tuple[str, ...]], None] | None = None,
    ) -> None:
        self.target_root = Path(target_root)
        self.identity_path = Path(identity_path) if identity_path is not None else self.target_root
        self.path = self.target_root / _DISTRIBUTION_JOURNAL_REL
        self.expected_workspace_identity = expected_workspace_identity
        self.workspace_closed_set_validator = workspace_closed_set_validator
        self.require_journal_absent = False
        self._forward_guard: DistributionRetryMarker | None = None
        self._leaf_mutation_validator: Callable[[str, tuple[int, ...]], None] | None = None

    def _validate_workspace_closed_set(self, extra_entries: tuple[str, ...] = ()) -> None:
        if self.require_journal_absent and _path_present_no_follow(self.path):
            raise DistributionApplyError("dual-recovery-state")
        if self.workspace_closed_set_validator is not None:
            self.workspace_closed_set_validator(extra_entries)

    @staticmethod
    def _recovery_metadata_identity(info: os.stat_result) -> tuple[int, int, int, int, int, int, int, int]:
        return (
            info.st_dev,
            info.st_ino,
            stat.S_IFMT(info.st_mode),
            stat.S_IMODE(info.st_mode),
            info.st_ctime_ns,
            info.st_nlink,
            info.st_size,
            info.st_mtime_ns,
        )

    def _assert_recovery_metadata_parent_bound(
        self,
        root_fd: int,
        parent_fd: int,
        expected_root: DistributionRootIdentity,
    ) -> None:
        """Revalidate the held root/spec-dock descriptors without following links."""

        try:
            opened_root = os.fstat(root_fd)
            visible_root = os.lstat(self.identity_path)
            visible_parent = os.stat("spec-dock", dir_fd=root_fd, follow_symlinks=False)
            opened_parent = os.fstat(parent_fd)
        except OSError as exc:
            raise DistributionApplyError("recovery metadata cannot be inspected safely") from exc
        if (
            not stat.S_ISDIR(opened_root.st_mode)
            or stat.S_ISLNK(opened_root.st_mode)
            or (opened_root.st_dev, opened_root.st_ino) != (expected_root.device, expected_root.inode)
            or self._recovery_metadata_identity(visible_root) != self._recovery_metadata_identity(opened_root)
            or not stat.S_ISDIR(visible_parent.st_mode)
            or stat.S_ISLNK(visible_parent.st_mode)
            or self._recovery_metadata_identity(visible_parent) != self._recovery_metadata_identity(opened_parent)
        ):
            raise DistributionApplyError("recovery metadata binding changed")

    def _bound_destructive_recovery_metadata_paths(
        self,
        expected_root: DistributionRootIdentity,
    ) -> tuple[str, ...]:
        """Inventory destructive recovery metadata from one held workspace parent."""

        try:
            root_fd, parent_fd = self._open_parent(expected_root)
        except FileNotFoundError:
            # A target without spec-dock cannot contain recovery metadata.
            return ()
        except OSError as exc:
            raise DistributionApplyError("recovery metadata cannot be inspected safely") from exc
        names = (
            _DISTRIBUTION_RETRY_MARKER_REL.name,
            _DISTRIBUTION_JOURNAL_REL.name,
            _UNINSTALL_RETRY_MARKER_REL.name,
        )
        try:
            self._assert_recovery_metadata_parent_bound(root_fd, parent_fd, expected_root)
            present: list[str] = []
            for name in names:
                try:
                    os.stat(name, dir_fd=parent_fd, follow_symlinks=False)
                except FileNotFoundError:
                    continue
                except OSError as exc:
                    raise DistributionApplyError("recovery metadata cannot be inspected safely") from exc
                present.append(f"spec-dock/{name}")
            self._assert_recovery_metadata_parent_bound(root_fd, parent_fd, expected_root)
            return tuple(present)
        finally:
            os.close(parent_fd)
            os.close(root_fd)

    def _read_bound_uninstall_retry_marker(
        self,
        expected_root: DistributionRootIdentity,
    ) -> bool:
        """Validate the legacy marker using held descriptors and no-follow I/O."""

        try:
            root_fd, parent_fd = self._open_parent(expected_root)
        except FileNotFoundError:
            return False
        except OSError as exc:
            raise DistributionApplyError(
                "legacy-marker-invalid", recovery_metadata_state="legacy-marker-invalid"
            ) from exc
        name = _UNINSTALL_RETRY_MARKER_REL.name
        marker_fd: int | None = None
        max_bytes = 1024 * 1024
        try:
            self._assert_recovery_metadata_parent_bound(root_fd, parent_fd, expected_root)
            try:
                visible_before = os.stat(name, dir_fd=parent_fd, follow_symlinks=False)
            except FileNotFoundError:
                self._assert_recovery_metadata_parent_bound(root_fd, parent_fd, expected_root)
                return False
            except OSError as exc:
                raise DistributionApplyError(
                    "legacy-marker-invalid", recovery_metadata_state="legacy-marker-invalid"
                ) from exc
            if not stat.S_ISREG(visible_before.st_mode) or visible_before.st_nlink != 1:
                raise DistributionApplyError("legacy-marker-invalid", recovery_metadata_state="legacy-marker-invalid")
            nofollow = getattr(os, "O_NOFOLLOW", None)
            if not isinstance(nofollow, int):
                raise DistributionApplyError("legacy-marker-invalid", recovery_metadata_state="legacy-marker-invalid")
            try:
                marker_fd = os.open(
                    name,
                    os.O_RDONLY | nofollow | getattr(os, "O_CLOEXEC", 0),
                    dir_fd=parent_fd,
                )
            except OSError as exc:
                raise DistributionApplyError(
                    "legacy-marker-invalid", recovery_metadata_state="legacy-marker-invalid"
                ) from exc
            opened = os.fstat(marker_fd)
            if (
                self._recovery_metadata_identity(opened) != self._recovery_metadata_identity(visible_before)
                or opened.st_size > max_bytes
            ):
                raise DistributionApplyError("legacy-marker-invalid", recovery_metadata_state="legacy-marker-invalid")
            os.lseek(marker_fd, 0, os.SEEK_SET)
            chunks: list[bytes] = []
            total = 0
            while True:
                chunk = os.read(marker_fd, 64 * 1024)
                if not chunk:
                    break
                total += len(chunk)
                if total > max_bytes:
                    raise DistributionApplyError(
                        "legacy-marker-invalid", recovery_metadata_state="legacy-marker-invalid"
                    )
                chunks.append(chunk)
            after_read = os.fstat(marker_fd)
            try:
                visible_after = os.stat(name, dir_fd=parent_fd, follow_symlinks=False)
            except OSError as exc:
                raise DistributionApplyError(
                    "legacy-marker-invalid", recovery_metadata_state="legacy-marker-invalid"
                ) from exc
            self._assert_recovery_metadata_parent_bound(root_fd, parent_fd, expected_root)
            if self._recovery_metadata_identity(after_read) != self._recovery_metadata_identity(
                opened
            ) or self._recovery_metadata_identity(visible_after) != self._recovery_metadata_identity(opened):
                raise DistributionApplyError("legacy-marker-invalid", recovery_metadata_state="legacy-marker-invalid")
            try:
                raw = json.loads(b"".join(chunks).decode("utf-8"))
            except (UnicodeDecodeError, json.JSONDecodeError) as exc:
                raise DistributionApplyError(
                    "legacy-marker-invalid", recovery_metadata_state="legacy-marker-invalid"
                ) from exc
            if raw != _UNINSTALL_RETRY_MARKER_PAYLOAD:
                raise DistributionApplyError("legacy-marker-invalid", recovery_metadata_state="legacy-marker-invalid")
            return True
        finally:
            if marker_fd is not None:
                os.close(marker_fd)
            os.close(parent_fd)
            os.close(root_fd)

    def _assert_destructive_recovery_metadata_bound(
        self,
        expected_root: DistributionRootIdentity,
    ) -> tuple[str, ...]:
        """Reject a legacy recovery marker racing any new destructive state."""

        paths = self._bound_destructive_recovery_metadata_paths(expected_root)
        legacy_path = _UNINSTALL_RETRY_MARKER_REL.as_posix()
        if legacy_path not in paths:
            return paths
        current_paths = {
            _DISTRIBUTION_RETRY_MARKER_REL.as_posix(),
            _DISTRIBUTION_JOURNAL_REL.as_posix(),
        }
        if current_paths.intersection(paths):
            raise DistributionApplyError("dual-recovery-state", recovery_metadata_state="dual-recovery-state")
        self._read_bound_uninstall_retry_marker(expected_root)
        after_paths = self._bound_destructive_recovery_metadata_paths(expected_root)
        if legacy_path not in after_paths:
            return after_paths
        if current_paths.intersection(after_paths):
            raise DistributionApplyError("dual-recovery-state", recovery_metadata_state="dual-recovery-state")
        raise DistributionApplyError(
            "legacy-marker-unconvertible",
            recovery_metadata_state="legacy-marker-unconvertible",
        )

    @staticmethod
    def _workspace_condition(journal: OperationJournal) -> dict[str, object]:
        return _path_snapshot_condition(
            journal.workspace_identity,
            include_mode=_is_destructive_intent(journal.intent),
        )

    def _open_parent(
        self,
        expected_root: DistributionRootIdentity,
        expected_workspace: dict[str, object] | None = None,
    ) -> tuple[int, int]:
        if expected_workspace is None and self.expected_workspace_identity is not None:
            expected_workspace = {
                "exists": True,
                "file_type": "directory",
                "device": self.expected_workspace_identity[0],
                "inode": self.expected_workspace_identity[1],
            }
        flags = _distribution_directory_flags()
        parent_fd: int | None = None
        try:
            root_fd = os.open(self.target_root, flags)
        except OSError as exc:
            raise DistributionApplyError("journal-root-mismatch") from exc
        try:
            opened = os.fstat(root_fd)
            visible = os.lstat(self.identity_path)
            if (
                stat.S_ISLNK(visible.st_mode)
                or not stat.S_ISDIR(visible.st_mode)
                or (opened.st_dev, opened.st_ino) != (expected_root.device, expected_root.inode)
                or (visible.st_dev, visible.st_ino) != (expected_root.device, expected_root.inode)
            ):
                raise DistributionApplyError("journal-root-mismatch")
            parent_fd = os.open("spec-dock", flags, dir_fd=root_fd)
            if expected_workspace is not None:
                parent = os.fstat(parent_fd)
                if (
                    expected_workspace.get("exists") is not True
                    or expected_workspace.get("file_type") != "directory"
                    or (parent.st_dev, parent.st_ino)
                    != (
                        expected_workspace.get("device"),
                        expected_workspace.get("inode"),
                    )
                    or ("mode" in expected_workspace and stat.S_IMODE(parent.st_mode) != expected_workspace.get("mode"))
                ):
                    raise DistributionApplyError("journal-parent-mismatch")
            self._validate_workspace_closed_set()
        except Exception:
            if parent_fd is not None:
                os.close(parent_fd)
            os.close(root_fd)
            raise
        assert parent_fd is not None
        return root_fd, parent_fd

    @staticmethod
    def _same_marker_evidence(
        current: DistributionRetryMarker,
        expected: DistributionRetryMarker,
    ) -> bool:
        return (
            current == expected
            and current.purpose
            in {
                _DISTRIBUTION_JOURNAL_GUARD_PURPOSE,
                _DISTRIBUTION_FRESH_JOURNAL_GUARD_PURPOSE,
                _DISTRIBUTION_DEPROVISION_JOURNAL_GUARD_PURPOSE,
                _DISTRIBUTION_PURGE_JOURNAL_GUARD_PURPOSE,
            }
            and current.source_snapshot is not None
            and current.source_snapshot == expected.source_snapshot
            and current.source_sha256 is not None
            and current.source_sha256 == expected.source_sha256
        )

    def _assert_current_forward_guard(self, marker: DistributionRetryMarker) -> None:
        try:
            current = _read_distribution_retry_marker(self.target_root)
        except DistributionAdmissionError as exc:
            raise DistributionApplyError("dual-recovery-state") from exc
        if current is None or not self._same_marker_evidence(current, marker):
            raise DistributionApplyError("dual-recovery-state")

    @staticmethod
    def _assert_bound_regular_entry(
        parent_fd: int,
        name: str,
        held_fd: int,
        expected_snapshot: PathIdentitySnapshot,
        expected_sha256: str,
        *,
        identity_error: str,
    ) -> os.stat_result:
        try:
            visible_before = os.stat(name, dir_fd=parent_fd, follow_symlinks=False)
            held_before = os.fstat(held_fd)
            raw = _read_fd_bytes(held_fd)
            held_after = os.fstat(held_fd)
            visible_after = os.stat(name, dir_fd=parent_fd, follow_symlinks=False)
        except OSError as exc:
            raise DistributionApplyError(identity_error) from exc
        if (
            not stat.S_ISREG(held_before.st_mode)
            or held_before.st_nlink != 1
            or not _same_stat_identity(held_before, expected_snapshot)
            or _stat_identity_tuple(visible_before) != _stat_identity_tuple(held_before)
            or _stat_identity_tuple(held_after) != _stat_identity_tuple(held_before)
            or _stat_identity_tuple(visible_after) != _stat_identity_tuple(held_before)
            or hashlib.sha256(raw).hexdigest() != expected_sha256
        ):
            raise DistributionApplyError(identity_error)
        return held_after

    def _open_bound_forward_guard(self, parent_fd: int) -> int | None:
        marker = self._forward_guard
        if marker is None:
            return None
        expected_snapshot = marker.source_snapshot
        expected_sha256 = marker.source_sha256
        if expected_snapshot is None or expected_sha256 is None:
            raise DistributionApplyError("dual-recovery-state")
        nofollow = getattr(os, "O_NOFOLLOW", None)
        if not isinstance(nofollow, int):
            raise DistributionApplyError("platform lacks required no-follow file support")
        try:
            guard_fd = os.open(
                _DISTRIBUTION_RETRY_MARKER_REL.name,
                os.O_RDONLY | nofollow | getattr(os, "O_CLOEXEC", 0),
                dir_fd=parent_fd,
            )
        except OSError as exc:
            raise DistributionApplyError("dual-recovery-state") from exc
        try:
            self._assert_bound_regular_entry(
                parent_fd,
                _DISTRIBUTION_RETRY_MARKER_REL.name,
                guard_fd,
                expected_snapshot,
                expected_sha256,
                identity_error="dual-recovery-state",
            )
        except Exception:
            os.close(guard_fd)
            raise
        return guard_fd

    def _assert_bound_forward_guard(self, parent_fd: int, guard_fd: int | None) -> None:
        if guard_fd is None:
            return
        assert self._forward_guard is not None
        assert self._forward_guard.source_snapshot is not None
        assert self._forward_guard.source_sha256 is not None
        self._assert_bound_regular_entry(
            parent_fd,
            _DISTRIBUTION_RETRY_MARKER_REL.name,
            guard_fd,
            self._forward_guard.source_snapshot,
            self._forward_guard.source_sha256,
            identity_error="dual-recovery-state",
        )

    def bind_forward_guard(self, marker: DistributionRetryMarker) -> None:
        self._assert_current_forward_guard(marker)
        self._forward_guard = marker

    def _assert_guard_anchors_journal(self, journal: OperationJournal) -> None:
        guard = self._forward_guard
        if guard is None:
            raise DistributionApplyError("dual-recovery-state")
        if guard.operation_id != journal.operation_id:
            raise DistributionApplyError("journal-plan-mismatch")
        if guard.contract_identity != journal.contract_identity:
            raise DistributionApplyError("journal-contract-mismatch")
        if guard.plan_digest != journal.plan_digest:
            raise DistributionApplyError("journal-plan-mismatch")
        if guard.journal_digest is not None and journal.source_sha256 not in {
            guard.journal_digest,
            guard.journal_predecessor_digest,
        }:
            raise DistributionApplyError("journal-precondition-mismatch")

    def _anchor_digestless_initial_journal(
        self,
        journal: OperationJournal,
        plan: ExecutableMutationPlan,
    ) -> None:
        guard = self._forward_guard
        if guard is None or guard.journal_digest is not None:
            return
        expected_staging_leases: tuple[DistributionStageOwnership, ...] = ()
        if journal.staging_leases:
            expected_staging_leases = _validated_legacy_stage_leases(
                plan,
                guard,
                self.target_root,
                allow_operation_created_parents=True,
            )
        if (
            journal.status != "prepared"
            or journal.staging_leases != expected_staging_leases
            or any(action.checkpoint != "pending" for action in journal.actions)
            or journal.source_sha256 is None
            or _journal_digest(journal) not in _executable_plan_digest_candidates(plan)
        ):
            raise DistributionApplyError("journal-precondition-mismatch")
        expected_initial = self._initial_journal(
            plan,
            package_version=journal.package_version,
            operation_id=journal.operation_id,
            created_at_ns=journal.created_at_ns,
        )
        if journal.created_parent_bindings != expected_initial.created_parent_bindings:
            raise DistributionApplyError("journal-precondition-mismatch")
        expected_actions = {
            action.path: (
                action.action,
                action.provenance,
                action.reason,
                _action_precondition_payload(plan.distribution_plan, action),
                _action_postcondition_payload(plan.distribution_plan, action),
                _legacy_action_postcondition_payload(plan.distribution_plan, action),
                _legacy_action_postcondition_payload(
                    plan.distribution_plan,
                    action,
                    fixed_link_count=True,
                ),
            )
            for action in plan.actions
        }
        if len(expected_actions) != len(journal.actions):
            raise DistributionApplyError("journal-precondition-mismatch")
        for record in journal.actions:
            expected = expected_actions.get(record.path)
            if expected is None or (record.action, record.provenance, record.reason) != expected[:3]:
                raise DistributionApplyError("journal-precondition-mismatch")
            expected_conditions = [expected[3]]
            if record.action == "adopt" and record.postcondition.get("file_type") != "directory":
                expected_conditions.extend((expected[4], expected[5], expected[6]))
            else:
                expected_conditions.append(expected[4])
            for index, recorded_condition in enumerate((record.precondition, record.postcondition)):
                candidates = expected_conditions if index == 1 else [expected[3]]
                normalized_candidates = [
                    OperationJournalStore._normalize_initial_action_condition(candidate) for candidate in candidates
                ]
                if recorded_condition not in candidates and recorded_condition not in normalized_candidates:
                    raise DistributionApplyError("journal-precondition-mismatch")
        anchored = self.prepare_legacy_guard(
            None,
            package_version=guard.package_version,
            replace_marker=guard,
            stage_ownership=expected_staging_leases,
            journal_digest=journal.source_sha256,
            journal_predecessor_digest=None,
            journal_created_at_ns=journal.created_at_ns,
        )
        self.bind_forward_guard(anchored)

    def _write(
        self,
        journal: OperationJournal,
        *,
        predecessor: OperationJournal | None = None,
        require_absent: bool = False,
    ) -> OperationJournal:
        destructive_recovery = _is_destructive_intent(journal.intent)
        if destructive_recovery:
            self._assert_destructive_recovery_metadata_bound(journal.root_identity)
        content = _journal_bytes(journal)
        predecessor_content = _journal_bytes(predecessor) if predecessor is not None else None
        if predecessor is not None and self._forward_guard is not None:
            assert predecessor_content is not None
            predecessor_digest = predecessor.source_sha256 or hashlib.sha256(predecessor_content).hexdigest()
            anchored_guard = self.prepare_legacy_guard(
                None,
                package_version=self._forward_guard.package_version,
                replace_marker=self._forward_guard,
                stage_ownership=self._forward_guard.stage_ownership,
                journal_digest=hashlib.sha256(content).hexdigest(),
                journal_predecessor_digest=predecessor_digest,
            )
            self.bind_forward_guard(anchored_guard)
        root_fd, parent_fd = self._open_parent(
            journal.root_identity,
            self._workspace_condition(journal),
        )
        destination = _DISTRIBUTION_JOURNAL_REL.name
        stage = f".distribution-journal-{secrets.token_hex(16)}.stage"
        stage_info: os.stat_result | None = None
        stage_fd: int | None = None
        destination_fd: int | None = None
        guard_fd: int | None = None
        published_new = False
        preserve_published = False
        swapped_out: os.stat_result | None = None
        stage_cleanup_identity: os.stat_result | None = None
        stage_cleanup_suppressed = False
        try:
            guard_fd = self._open_bound_forward_guard(parent_fd)
            try:
                destination_info = os.stat(destination, dir_fd=parent_fd, follow_symlinks=False)
            except FileNotFoundError:
                destination_info = None
            if require_absent and destination_info is not None:
                raise DistributionApplyError("dual-recovery-state")
            if predecessor is not None and destination_info is None:
                raise DistributionApplyError("journal-precondition-mismatch")
            if destination_info is not None and (
                not stat.S_ISREG(destination_info.st_mode) or destination_info.st_nlink != 1
            ):
                raise DistributionApplyError("journal-protocol-incompatible")
            nofollow = getattr(os, "O_NOFOLLOW", None)
            if not isinstance(nofollow, int):
                raise DistributionApplyError("platform lacks required no-follow file support")
            if predecessor is not None:
                assert destination_info is not None
                expected_snapshot = predecessor.source_snapshot
                expected_sha256 = predecessor.source_sha256
                if expected_snapshot is None or expected_sha256 is None:
                    raise DistributionApplyError("journal-precondition-mismatch")
                try:
                    destination_fd = os.open(
                        destination,
                        os.O_RDONLY | nofollow | getattr(os, "O_CLOEXEC", 0),
                        dir_fd=parent_fd,
                    )
                except OSError as exc:
                    raise DistributionApplyError("journal-precondition-mismatch") from exc
                if (
                    not _same_stat_identity(destination_info, expected_snapshot)
                    or _stat_identity_tuple(os.fstat(destination_fd)) != _stat_identity_tuple(destination_info)
                    or hashlib.sha256(_read_fd_bytes(destination_fd)).hexdigest() != expected_sha256
                    or _stat_identity_tuple(os.fstat(destination_fd)) != _stat_identity_tuple(destination_info)
                ):
                    raise DistributionApplyError("journal-precondition-mismatch")
            try:
                stage_fd = os.open(
                    stage,
                    os.O_RDWR | os.O_CREAT | os.O_EXCL | nofollow | getattr(os, "O_CLOEXEC", 0),
                    0o600,
                    dir_fd=parent_fd,
                )
            except OSError as exc:
                raise DistributionApplyError("journal publish failed") from exc
            _write_fd_bytes(stage_fd, content)
            os.fchmod(stage_fd, 0o600)
            stage_info = os.fstat(stage_fd)
            stage_cleanup_identity = stage_info
            visible_stage = os.stat(stage, dir_fd=parent_fd, follow_symlinks=False)
            if _stat_identity_tuple(visible_stage) != _stat_identity_tuple(stage_info) or not _held_fd_has_exact_bytes(
                stage_fd, content
            ):
                raise DistributionApplyError("journal-precondition-mismatch")
            self._validate_workspace_closed_set((stage,))
            self._assert_bound_forward_guard(parent_fd, guard_fd)
            if destination_info is None:
                if destructive_recovery:
                    self._assert_destructive_recovery_metadata_bound(journal.root_identity)
                _rename_distribution_no_replace(parent_fd, stage, parent_fd, destination)
                published_new = True
                if destructive_recovery:
                    try:
                        self._assert_destructive_recovery_metadata_bound(journal.root_identity)
                    except DistributionApplyError:
                        # The successor journal is already durable.  Do not
                        # roll it back merely because a legacy state appeared
                        # after its publication.
                        preserve_published = True
                        raise
                published = os.stat(destination, dir_fd=parent_fd, follow_symlinks=False)
                if _stat_identity_tuple(published) != _stat_identity_tuple(
                    os.fstat(stage_fd)
                ) or not _held_fd_has_exact_bytes(stage_fd, content):
                    raise DistributionApplyError("journal-precondition-mismatch")
            else:
                assert destination_fd is not None
                if destructive_recovery:
                    self._assert_destructive_recovery_metadata_bound(journal.root_identity)
                swapped_out = _swap_regular_distribution_target_if_bound(
                    parent_fd,
                    stage,
                    destination,
                    target_fd=destination_fd,
                    staging_fd=stage_fd,
                    expected_target=destination_info,
                    identity_message="journal-precondition-mismatch",
                )
                stage_cleanup_identity = swapped_out
                published_new = True
                if destructive_recovery:
                    try:
                        self._assert_destructive_recovery_metadata_bound(journal.root_identity)
                    except DistributionApplyError:
                        # Keep the published successor as durable recovery
                        # evidence; a late legacy marker must not trigger the
                        # old publication rollback path.
                        preserve_published = True
                        raise
                if not _held_fd_has_exact_bytes(stage_fd, content):
                    try:
                        _rename_distribution_swap(parent_fd, stage, parent_fd, destination)
                        os.fsync(parent_fd)
                        stage_cleanup_identity = stage_info
                    except OSError as exc:
                        raise DistributionApplyError("journal-precondition-mismatch") from exc
                    raise DistributionApplyError("journal-precondition-mismatch")
            os.fsync(parent_fd)
            self._assert_bound_forward_guard(parent_fd, guard_fd)
            published_info = os.fstat(stage_fd)
            successor_snapshot = _snapshot_from_stat(
                _DISTRIBUTION_JOURNAL_REL.as_posix(),
                published_info,
            )
            self._assert_bound_regular_entry(
                parent_fd,
                destination,
                stage_fd,
                successor_snapshot,
                hashlib.sha256(content).hexdigest(),
                identity_error="journal-precondition-mismatch",
            )
            if destructive_recovery:
                try:
                    self._assert_destructive_recovery_metadata_bound(journal.root_identity)
                except DistributionApplyError:
                    preserve_published = True
                    raise
            visible = os.lstat(self.identity_path)
            if (visible.st_dev, visible.st_ino) != (
                journal.root_identity.device,
                journal.root_identity.inode,
            ):
                raise DistributionApplyError("journal-root-mismatch")
            if swapped_out is not None:
                assert stage_cleanup_identity is not None
                _remove_distribution_stage_if_owned(
                    parent_fd,
                    stage,
                    stage_cleanup_identity,
                    strict=True,
                )
                stage_cleanup_identity = None
            return replace(
                journal,
                source_snapshot=successor_snapshot,
                source_sha256=hashlib.sha256(content).hexdigest(),
            )
        except Exception:
            if published_new and stage_fd is not None and stage_info is not None and not preserve_published:
                try:
                    if swapped_out is None:
                        _remove_distribution_target_if_bound(
                            parent_fd,
                            destination,
                            os.fstat(stage_fd),
                            held_fd=stage_fd,
                            identity_message="journal-precondition-mismatch",
                        )
                    elif destination_fd is not None:
                        visible_destination = os.stat(destination, dir_fd=parent_fd, follow_symlinks=False)
                        visible_stage = os.stat(stage, dir_fd=parent_fd, follow_symlinks=False)
                        if _stat_identity_tuple(visible_destination) == _stat_identity_tuple(
                            os.fstat(stage_fd)
                        ) and _stat_identity_tuple(visible_stage) == _stat_identity_tuple(os.fstat(destination_fd)):
                            _rename_distribution_swap(parent_fd, stage, parent_fd, destination)
                            os.fsync(parent_fd)
                            stage_cleanup_identity = stage_info
                except (DistributionApplyError, OSError):
                    pass
            if swapped_out is not None and stage_cleanup_identity is swapped_out:
                try:
                    assert stage_fd is not None
                    visible_successor = os.stat(destination, dir_fd=parent_fd, follow_symlinks=False)
                    successor_info = os.fstat(stage_fd)
                    if _stat_structure_tuple(visible_successor) != _stat_structure_tuple(
                        successor_info
                    ) or not _held_fd_has_exact_bytes(stage_fd, content):
                        # Preserve the predecessor when the canonical name no
                        # longer contains our published successor.  It is
                        # recovery evidence, not an unowned cleanup target.
                        stage_cleanup_identity = None
                        stage_cleanup_suppressed = True
                except OSError:
                    stage_cleanup_identity = None
                    stage_cleanup_suppressed = True
            if stage_cleanup_identity is not None:
                _remove_distribution_stage_if_owned(parent_fd, stage, stage_cleanup_identity)
            elif not stage_cleanup_suppressed:
                # A write failure can occur before stage_info is captured.  The
                # O_EXCL-created stage is still owned by this operation and
                # must not strand a markerless fresh workspace.
                with suppress(OSError, DistributionApplyError):
                    orphan_info = os.stat(stage, dir_fd=parent_fd, follow_symlinks=False)
                    _remove_distribution_stage_if_owned(parent_fd, stage, orphan_info)
            raise
        finally:
            if guard_fd is not None:
                os.close(guard_fd)
            if destination_fd is not None:
                os.close(destination_fd)
            if stage_fd is not None:
                os.close(stage_fd)
            os.close(parent_fd)
            os.close(root_fd)

    def _read_unbound_journal_bytes(self) -> bytes | None:
        """Read only enough journal evidence to classify a recovery intent."""

        try:
            directory_flags = _distribution_directory_flags()
        except DistributionApplyError:
            return None
        nofollow = getattr(os, "O_NOFOLLOW", None)
        if not isinstance(nofollow, int):
            return None
        root_fd: int | None = None
        parent_fd: int | None = None
        journal_fd: int | None = None
        try:
            root_fd = os.open(self.target_root, directory_flags)
            parent_fd = os.open("spec-dock", directory_flags, dir_fd=root_fd)
            info = os.stat(_DISTRIBUTION_JOURNAL_REL.name, dir_fd=parent_fd, follow_symlinks=False)
            if not stat.S_ISREG(info.st_mode) or info.st_nlink != 1:
                return None
            journal_fd = os.open(
                _DISTRIBUTION_JOURNAL_REL.name,
                os.O_RDONLY | nofollow | getattr(os, "O_CLOEXEC", 0),
                dir_fd=parent_fd,
            )
            opened = os.fstat(journal_fd)
            if (
                not stat.S_ISREG(opened.st_mode)
                or opened.st_nlink != 1
                or (opened.st_dev, opened.st_ino, opened.st_ctime_ns, opened.st_nlink)
                != (info.st_dev, info.st_ino, info.st_ctime_ns, info.st_nlink)
            ):
                return None
            raw = _read_fd_bytes(journal_fd)
            after_read = os.fstat(journal_fd)
            if len(raw) > 16 * 1024 * 1024 or _stat_identity_tuple(after_read) != _stat_identity_tuple(opened):
                return None
            return raw
        except (OSError, DistributionApplyError):
            return None
        finally:
            if journal_fd is not None:
                os.close(journal_fd)
            if parent_fd is not None:
                os.close(parent_fd)
            if root_fd is not None:
                os.close(root_fd)

    def _read_optional_bound_journal_after_metadata_race(
        self,
        expected_root: DistributionRootIdentity,
        *,
        expected_intent: JournaledDistributionIntent,
    ) -> OperationJournal | None:
        """Read a canonical journal without re-admitting destructive metadata."""

        root_fd, parent_fd = self._open_parent(expected_root)
        journal_fd: int | None = None
        try:
            self._assert_recovery_metadata_parent_bound(root_fd, parent_fd, expected_root)
            name = _DISTRIBUTION_JOURNAL_REL.name
            try:
                visible_before = os.stat(name, dir_fd=parent_fd, follow_symlinks=False)
            except FileNotFoundError:
                self._assert_recovery_metadata_parent_bound(root_fd, parent_fd, expected_root)
                return None
            except OSError as exc:
                raise DistributionApplyError("journal-protocol-incompatible") from exc
            if not stat.S_ISREG(visible_before.st_mode) or visible_before.st_nlink != 1:
                raise DistributionApplyError("journal-protocol-incompatible")
            nofollow = getattr(os, "O_NOFOLLOW", None)
            if not isinstance(nofollow, int):
                raise DistributionApplyError("platform lacks required no-follow file support")
            try:
                journal_fd = os.open(
                    name,
                    os.O_RDONLY | nofollow | getattr(os, "O_CLOEXEC", 0),
                    dir_fd=parent_fd,
                )
            except OSError as exc:
                raise DistributionApplyError("journal-protocol-incompatible") from exc
            opened = os.fstat(journal_fd)
            if self._recovery_metadata_identity(opened) != self._recovery_metadata_identity(visible_before):
                raise DistributionApplyError("journal-protocol-incompatible")
            try:
                raw = _read_fd_bytes(journal_fd)
                after_read = os.fstat(journal_fd)
                visible_after = os.stat(name, dir_fd=parent_fd, follow_symlinks=False)
            except OSError as exc:
                raise DistributionApplyError("journal-protocol-incompatible") from exc
            if (
                len(raw) > 16 * 1024 * 1024
                or self._recovery_metadata_identity(after_read) != self._recovery_metadata_identity(opened)
                or self._recovery_metadata_identity(visible_after) != self._recovery_metadata_identity(opened)
            ):
                raise DistributionApplyError("journal-protocol-incompatible")
            self._assert_recovery_metadata_parent_bound(root_fd, parent_fd, expected_root)
            journal = replace(
                _parse_operation_journal(raw, expected_intent=expected_intent),
                source_snapshot=_snapshot_from_stat(_DISTRIBUTION_JOURNAL_REL.as_posix(), after_read),
                source_sha256=hashlib.sha256(raw).hexdigest(),
            )
            if journal.root_identity != expected_root:
                raise DistributionApplyError("journal-root-mismatch")
            parent = os.fstat(parent_fd)
            expected_workspace = self._workspace_condition(journal)
            if (
                expected_workspace.get("exists") is not True
                or expected_workspace.get("file_type") != "directory"
                or (parent.st_dev, parent.st_ino)
                != (
                    expected_workspace.get("device"),
                    expected_workspace.get("inode"),
                )
                or ("mode" in expected_workspace and stat.S_IMODE(parent.st_mode) != expected_workspace.get("mode"))
            ):
                raise DistributionApplyError("journal-parent-mismatch")
            self._assert_recovery_metadata_parent_bound(root_fd, parent_fd, expected_root)
            return journal
        finally:
            if journal_fd is not None:
                os.close(journal_fd)
            os.close(parent_fd)
            os.close(root_fd)

    def _is_exact_prepared_journal_for_plan(
        self,
        journal: OperationJournal,
        plan: ExecutableMutationPlan,
        guard: DistributionRetryMarker,
        *,
        expected_root: DistributionRootIdentity,
    ) -> bool:
        """Prove that a reread journal is this guard-only prepare publication."""

        if (
            guard.operation_id is None
            or guard.journal_digest is None
            or guard.journal_created_at_ns is None
            or journal.root_identity != expected_root
            or journal.intent != plan.intent
            or journal.authority != _journal_authority_for_intent(plan.intent)
            or journal.package_version != guard.package_version
            or journal.operation_id != guard.operation_id
            or journal.contract_identity != plan.contract_identity
            or journal.plan_digest != plan.plan_digest
            or journal.created_at_ns != guard.journal_created_at_ns
            or journal.status != "prepared"
            or journal.staging_leases != guard.stage_ownership
            or any(action.checkpoint != "pending" for action in journal.actions)
            or journal.source_sha256 != guard.journal_digest
        ):
            return False
        try:
            self._assert_guard_anchors_journal(journal)
            expected = replace(
                self._initial_journal(
                    plan,
                    package_version=guard.package_version,
                    operation_id=guard.operation_id,
                    created_at_ns=guard.journal_created_at_ns,
                ),
                staging_leases=guard.stage_ownership,
            )
        except DistributionApplyError:
            return False
        return replace(journal, source_snapshot=None, source_sha256=None) == expected

    def _read(
        self,
        expected_root: DistributionRootIdentity,
        *,
        expected_intent: JournaledDistributionIntent | None = None,
    ) -> OperationJournal:
        if expected_intent is not None and _is_destructive_intent(expected_intent):
            self._assert_destructive_recovery_metadata_bound(expected_root)
        if expected_intent is not None:
            initial_raw = self._read_unbound_journal_bytes()
            if initial_raw is not None:
                try:
                    _parse_operation_journal(initial_raw, expected_intent=expected_intent)
                except DistributionApplyError as exc:
                    if exc.recovery_mismatch_kind == "intent-authority":
                        raise
        root_fd, parent_fd = self._open_parent(expected_root)
        try:
            nofollow = getattr(os, "O_NOFOLLOW", None)
            if not isinstance(nofollow, int):
                raise DistributionApplyError("platform lacks required no-follow file support")
            try:
                info = os.stat(_DISTRIBUTION_JOURNAL_REL.name, dir_fd=parent_fd, follow_symlinks=False)
                fd = os.open(
                    _DISTRIBUTION_JOURNAL_REL.name,
                    os.O_RDONLY | nofollow | getattr(os, "O_CLOEXEC", 0),
                    dir_fd=parent_fd,
                )
            except FileNotFoundError as exc:
                raise DistributionApplyError("operation journal is missing") from exc
            except OSError as exc:
                raise DistributionApplyError("journal-protocol-incompatible") from exc
            try:
                opened = os.fstat(fd)
                if (
                    not stat.S_ISREG(info.st_mode)
                    or info.st_nlink != 1
                    or (opened.st_dev, opened.st_ino, opened.st_ctime_ns, opened.st_nlink)
                    != (info.st_dev, info.st_ino, info.st_ctime_ns, info.st_nlink)
                ):
                    raise DistributionApplyError("journal-protocol-incompatible")
                raw = _read_fd_bytes(fd)
                if len(raw) > 16 * 1024 * 1024:
                    raise DistributionApplyError("journal-protocol-incompatible")
                after_read = os.fstat(fd)
                if _stat_identity_tuple(after_read) != _stat_identity_tuple(opened):
                    raise DistributionApplyError("journal-protocol-incompatible")
            finally:
                os.close(fd)
            journal = replace(
                _parse_operation_journal(raw, expected_intent=expected_intent),
                source_snapshot=_snapshot_from_stat(_DISTRIBUTION_JOURNAL_REL.as_posix(), after_read),
                source_sha256=hashlib.sha256(raw).hexdigest(),
            )
            if journal.root_identity != expected_root:
                raise DistributionApplyError("journal-root-mismatch")
            parent = os.fstat(parent_fd)
            expected_workspace = self._workspace_condition(journal)
            if (
                expected_workspace.get("exists") is not True
                or expected_workspace.get("file_type") != "directory"
                or (parent.st_dev, parent.st_ino)
                != (
                    expected_workspace.get("device"),
                    expected_workspace.get("inode"),
                )
                or ("mode" in expected_workspace and stat.S_IMODE(parent.st_mode) != expected_workspace.get("mode"))
            ):
                raise DistributionApplyError("journal-parent-mismatch")
            return journal
        finally:
            os.close(parent_fd)
            os.close(root_fd)

    @staticmethod
    def _normalize_initial_action_condition(condition: dict[str, object]) -> dict[str, object]:
        parents = condition.get("parents")
        if not isinstance(parents, list):
            return condition
        normalized_parents = [
            {
                **parent,
                **(
                    {"ctime_ns": 0, "link_count": 0}
                    if isinstance(parent, dict) and parent.get("relative_path") == "spec-dock"
                    else {}
                ),
            }
            for parent in parents
        ]
        return {**condition, "parents": normalized_parents}

    def _initial_journal(
        self,
        plan: ExecutableMutationPlan,
        *,
        package_version: str,
        operation_id: str,
        created_at_ns: int,
    ) -> OperationJournal:
        try:
            workspace_info = os.lstat(self.target_root / "spec-dock")
        except OSError as exc:
            raise DistributionApplyError("journal-parent-mismatch") from exc
        if stat.S_ISLNK(workspace_info.st_mode) or not stat.S_ISDIR(workspace_info.st_mode):
            raise DistributionApplyError("journal-parent-mismatch")
        if (
            self.expected_workspace_identity is not None
            and (
                workspace_info.st_dev,
                workspace_info.st_ino,
            )
            != self.expected_workspace_identity
        ):
            raise DistributionApplyError("journal-parent-mismatch")

        def initial_action(action: DistributionAction) -> OperationJournalAction:
            if plan.intent == "deprovision":
                precondition, postcondition = _deprovision_action_conditions(plan, action)
            elif plan.intent == "purge":
                precondition, postcondition = _purge_action_conditions(plan, action)
            else:
                precondition = _action_precondition_payload(plan.distribution_plan, action)
                postcondition = _action_postcondition_payload(plan.distribution_plan, action)
            return OperationJournalAction(
                path=action.path,
                action=action.action,
                provenance=action.provenance,
                reason=action.reason,
                precondition=self._normalize_initial_action_condition(precondition),
                postcondition=self._normalize_initial_action_condition(postcondition),
            )

        return OperationJournal(
            schema_version=(
                _DISTRIBUTION_FRESH_JOURNAL_SCHEMA_VERSION
                if plan.intent == "fresh"
                else _DISTRIBUTION_JOURNAL_SCHEMA_VERSION
            ),
            protocol_version=_DISTRIBUTION_JOURNAL_PROTOCOL_VERSION,
            operation_id=operation_id,
            root_identity=plan.root_identity,
            workspace_identity=replace(
                _snapshot_from_stat("spec-dock", workspace_info),
                # Guard and journal publication intentionally mutate this
                # directory's ctime.  The authority boundary is its held
                # dev/inode/type binding, so keep the serialized initial
                # journal reconstructable across a guard-only crash.
                ctime_ns=0,
                link_count=0,
            ),
            intent=plan.intent,
            authority=_journal_authority_for_intent(plan.intent),
            package_version=package_version,
            contract_identity=plan.contract_identity,
            plan_digest=plan.plan_digest,
            created_at_ns=created_at_ns,
            status="prepared",
            actions=tuple(
                initial_action(action)
                for action in (
                    plan.actions
                    if _is_destructive_intent(plan.intent)
                    else sorted(plan.actions, key=lambda item: (item.path, item.action, item.reason))
                )
            ),
            preservation_witnesses=plan.preservation_witnesses,
            absence_witnesses=tuple(_durable_absence_witness(witness) for witness in plan.absence_witnesses),
            leaf_parent_namespace_witnesses=tuple(
                _durable_leaf_parent_namespace_witness(witness) for witness in plan.leaf_parent_namespace_witnesses
            ),
            source_semantic_identities=plan.source_semantic_identities,
            generated_state_contract_digest=plan.generated_state_contract_digest,
            active_selection_witnesses=plan.active_selection_witnesses,
            created_parent_bindings=tuple(
                _missing_snapshot(path)
                for path in sorted({
                    *{
                        parent.relative_path
                        for action in plan.actions
                        for parent in dict(plan.distribution_plan.target_snapshots)[action.path].parents
                        if not parent.exists
                    },
                    *{
                        action.path
                        for action in plan.actions
                        if action.action == "ensure-directory"
                        and not dict(plan.distribution_plan.target_snapshots)[action.path].target.exists
                    },
                })
            ),
            staging_leases=(),
        )

    def prepare(self, plan: ExecutableMutationPlan, *, package_version: str) -> OperationJournal:
        guard = self._forward_guard
        if guard is None:
            try:
                existing_guard = _read_distribution_retry_marker(self.target_root)
            except DistributionAdmissionError as exc:
                raise DistributionApplyError("dual-recovery-state") from exc
            if existing_guard is not None:
                guard = existing_guard
            else:
                guard = self.prepare_legacy_guard(plan, package_version=package_version)
            self.bind_forward_guard(guard)
        legacy_plan_digests = _executable_plan_digest_candidates(plan)
        if (
            guard.operation_id is None
            or guard.contract_identity != plan.contract_identity
            or guard.plan_digest not in legacy_plan_digests
        ):
            raise DistributionApplyError("dual-recovery-state")
        if guard.plan_digest != plan.plan_digest:
            guard = self.prepare_legacy_guard(
                None,
                package_version=guard.package_version,
                replace_marker=guard,
                plan_digest_override=plan.plan_digest,
                stage_ownership=guard.stage_ownership,
            )
            self.bind_forward_guard(guard)
        operation_id = guard.operation_id
        if operation_id is None:
            raise DistributionApplyError("dual-recovery-state")
        created_at_ns = guard.journal_created_at_ns or time.time_ns()
        journal = replace(
            self._initial_journal(
                plan,
                package_version=package_version,
                operation_id=operation_id,
                created_at_ns=created_at_ns,
            ),
            staging_leases=guard.stage_ownership,
        )
        initial_digest = hashlib.sha256(_journal_bytes(journal)).hexdigest()
        if guard.journal_digest is None:
            guard = self.prepare_legacy_guard(
                None,
                package_version=guard.package_version,
                replace_marker=guard,
                stage_ownership=guard.stage_ownership,
                journal_digest=initial_digest,
                journal_predecessor_digest=None,
                journal_created_at_ns=created_at_ns,
            )
            self.bind_forward_guard(guard)
        elif guard.journal_digest != initial_digest:
            raise DistributionApplyError("journal-precondition-mismatch")
        return self._write(journal, require_absent=True)

    def prepare_legacy_guard(
        self,
        plan: ExecutableMutationPlan | None,
        *,
        package_version: str,
        replace_marker: DistributionRetryMarker | None = None,
        plan_digest_override: str | None = None,
        stage_ownership: tuple[DistributionStageOwnership, ...] = (),
        journal_digest: str | None = None,
        journal_predecessor_digest: str | None = None,
        journal_created_at_ns: int | None = None,
    ) -> DistributionRetryMarker:
        """Publish an old-installer-visible guard before the new journal exists."""

        created_at_ns = time.time_ns()
        if plan is None:
            if replace_marker is None or replace_marker.operation_id is None:
                raise DistributionApplyError("dual-recovery-state")
            operation = replace_marker.operation
            target_root = replace_marker.target_root
            operation_id = replace_marker.operation_id
            contract_identity = replace_marker.contract_identity
            plan_digest = plan_digest_override or replace_marker.plan_digest
        else:
            operation = plan.intent
            target_root = plan.root_identity
            operation_id = hashlib.sha256(
                f"{plan.plan_digest}:{created_at_ns}:{secrets.token_hex(16)}".encode()
            ).hexdigest()
            contract_identity = plan.contract_identity
            plan_digest = plan.plan_digest
            if journal_digest is None:
                initial = replace(
                    self._initial_journal(
                        plan,
                        package_version=package_version,
                        operation_id=operation_id,
                        created_at_ns=created_at_ns,
                    ),
                    staging_leases=stage_ownership,
                )
                journal_digest = hashlib.sha256(_journal_bytes(initial)).hexdigest()
                journal_created_at_ns = created_at_ns
        marker = DistributionRetryMarker(
            operation=operation,
            package_version=package_version,
            target_root=target_root,
            last_completed_phase="preflight-complete",
            purpose=_journal_guard_purpose_for_intent(operation),
            operation_id=operation_id,
            contract_identity=contract_identity,
            plan_digest=plan_digest,
            stage_ownership=stage_ownership,
            journal_digest=journal_digest,
            journal_predecessor_digest=journal_predecessor_digest,
            journal_created_at_ns=(
                None
                if plan_digest_override is not None and journal_digest is None
                else journal_created_at_ns
                if journal_created_at_ns is not None
                else (replace_marker.journal_created_at_ns if replace_marker is not None else None)
            ),
        )
        payload: dict[str, object] = {
            "schema_version": _DISTRIBUTION_JOURNAL_GUARD_SCHEMA_VERSION,
            "operation": marker.operation,
            "package_version": marker.package_version,
            "target_root": {
                "device": marker.target_root.device,
                "inode": marker.target_root.inode,
            },
            "last_completed_phase": marker.last_completed_phase,
            "purpose": marker.purpose,
            "stage_ownership": [
                {
                    "path": lease.path,
                    "stage_name": lease.stage_name,
                    "device": lease.device,
                    "inode": lease.inode,
                    "ctime_ns": lease.ctime_ns,
                    "file_type": lease.file_type,
                }
                for lease in stage_ownership
            ],
            "operation_id": marker.operation_id,
            "contract_identity": marker.contract_identity,
            "plan_digest": marker.plan_digest,
        }
        if marker.journal_digest is not None:
            payload["journal_digest"] = marker.journal_digest
            payload["journal_predecessor_digest"] = marker.journal_predecessor_digest
            payload["journal_created_at_ns"] = marker.journal_created_at_ns
        content = (json.dumps(payload, sort_keys=True, separators=(",", ":")) + "\n").encode("utf-8")
        try:
            workspace_info = os.lstat(self.target_root / "spec-dock")
        except OSError as exc:
            raise DistributionApplyError("journal-parent-mismatch") from exc
        if stat.S_ISLNK(workspace_info.st_mode) or not stat.S_ISDIR(workspace_info.st_mode):
            raise DistributionApplyError("journal-parent-mismatch")
        workspace_condition = _path_snapshot_condition(_snapshot_from_stat("spec-dock", workspace_info))
        if self.expected_workspace_identity is not None:
            workspace_condition.update({
                "device": self.expected_workspace_identity[0],
                "inode": self.expected_workspace_identity[1],
            })
        root_fd, parent_fd = self._open_parent(marker.target_root, workspace_condition)
        destination = _DISTRIBUTION_RETRY_MARKER_REL.name
        stage = f".distribution-retry-{secrets.token_hex(16)}.stage"
        stage_info: os.stat_result | None = None
        swapped_out: os.stat_result | None = None
        stage_cleanup_identity: os.stat_result | None = None
        stage_cleanup_suppressed = False
        held_fd: int | None = None
        stage_fd: int | None = None
        destructive_recovery = _is_destructive_intent(marker.operation)
        try:
            if destructive_recovery:
                self._assert_destructive_recovery_metadata_bound(marker.target_root)
            try:
                destination_info = os.stat(destination, dir_fd=parent_fd, follow_symlinks=False)
            except FileNotFoundError:
                destination_info = None
            if replace_marker is None and destination_info is not None:
                raise DistributionApplyError("dual-recovery-state")
            if replace_marker is not None:
                expected = replace_marker.source_snapshot
                expected_sha256 = replace_marker.source_sha256
                if expected is None or expected_sha256 is None or destination_info is None:
                    current = _read_distribution_retry_marker(self.target_root)
                    if current != replace_marker or current is None:
                        raise DistributionApplyError("legacy-marker-unconvertible")
                    expected = current.source_snapshot
                    expected_sha256 = current.source_sha256
                assert expected is not None
                assert expected_sha256 is not None
                if (
                    not expected.exists
                    or expected.file_type != "regular"
                    or expected.link_count != 1
                    or destination_info is None
                    or (
                        destination_info.st_dev,
                        destination_info.st_ino,
                        destination_info.st_ctime_ns,
                        _file_type(destination_info.st_mode),
                        destination_info.st_nlink,
                    )
                    != (
                        expected.device,
                        expected.inode,
                        expected.ctime_ns,
                        expected.file_type,
                        expected.link_count,
                    )
                ):
                    raise DistributionApplyError("legacy-marker-unconvertible")
            nofollow = getattr(os, "O_NOFOLLOW", None)
            if not isinstance(nofollow, int):
                raise DistributionApplyError("platform lacks required no-follow file support")
            if replace_marker is not None:
                try:
                    held_fd = os.open(
                        destination,
                        os.O_RDONLY | nofollow | getattr(os, "O_CLOEXEC", 0),
                        dir_fd=parent_fd,
                    )
                except OSError as exc:
                    raise DistributionApplyError("legacy-marker-unconvertible") from exc
                held_before = os.fstat(held_fd)
                assert destination_info is not None
                if (
                    held_before.st_dev,
                    held_before.st_ino,
                    held_before.st_ctime_ns,
                    held_before.st_mode,
                    held_before.st_nlink,
                ) != (
                    destination_info.st_dev,
                    destination_info.st_ino,
                    destination_info.st_ctime_ns,
                    destination_info.st_mode,
                    destination_info.st_nlink,
                ):
                    raise DistributionApplyError("legacy-marker-unconvertible")
                chunks: list[bytes] = []
                while True:
                    chunk = os.read(held_fd, 1024 * 1024)
                    if not chunk:
                        break
                    chunks.append(chunk)
                held_after = os.fstat(held_fd)
                if (
                    held_before.st_dev,
                    held_before.st_ino,
                    held_before.st_ctime_ns,
                    held_before.st_mode,
                    held_before.st_nlink,
                ) != (
                    held_after.st_dev,
                    held_after.st_ino,
                    held_after.st_ctime_ns,
                    held_after.st_mode,
                    held_after.st_nlink,
                ) or hashlib.sha256(b"".join(chunks)).hexdigest() != expected_sha256:
                    raise DistributionApplyError("legacy-marker-unconvertible")
            stage_fd = os.open(
                stage,
                os.O_RDWR | os.O_CREAT | os.O_EXCL | nofollow | getattr(os, "O_CLOEXEC", 0),
                0o600,
                dir_fd=parent_fd,
            )
            _write_fd_bytes(stage_fd, content)
            os.fchmod(stage_fd, 0o600)
            stage_info = os.fstat(stage_fd)
            stage_cleanup_identity = stage_info
            visible_stage = os.stat(stage, dir_fd=parent_fd, follow_symlinks=False)
            if _stat_identity_tuple(visible_stage) != _stat_identity_tuple(stage_info) or not _held_fd_has_exact_bytes(
                stage_fd, content
            ):
                raise DistributionApplyError("legacy-marker-unconvertible")
            self._validate_workspace_closed_set((stage,))
            if replace_marker is None:
                if destructive_recovery:
                    self._assert_destructive_recovery_metadata_bound(marker.target_root)
                _rename_distribution_no_replace(parent_fd, stage, parent_fd, destination)
                published = os.stat(destination, dir_fd=parent_fd, follow_symlinks=False)
                if _stat_identity_tuple(published) != _stat_identity_tuple(
                    os.fstat(stage_fd)
                ) or not _held_fd_has_exact_bytes(stage_fd, content):
                    raise DistributionApplyError("legacy-marker-unconvertible")
            else:
                assert destination_info is not None
                assert held_fd is not None
                if destructive_recovery:
                    self._assert_destructive_recovery_metadata_bound(marker.target_root)
                swapped_out = _swap_regular_distribution_target_if_bound(
                    parent_fd,
                    stage,
                    destination,
                    target_fd=held_fd,
                    staging_fd=stage_fd,
                    expected_target=destination_info,
                    identity_message="legacy-marker-unconvertible",
                )
                stage_cleanup_identity = swapped_out
                if not _held_fd_has_exact_bytes(stage_fd, content):
                    try:
                        _rename_distribution_swap(parent_fd, stage, parent_fd, destination)
                        os.fsync(parent_fd)
                        stage_cleanup_identity = stage_info
                    except OSError as exc:
                        raise DistributionApplyError("legacy-marker-unconvertible") from exc
                    raise DistributionApplyError("legacy-marker-unconvertible")
            if destructive_recovery:
                self._assert_destructive_recovery_metadata_bound(marker.target_root)
            os.fsync(parent_fd)
            published_info = os.fstat(stage_fd)
            successor_snapshot = _snapshot_from_stat(
                _DISTRIBUTION_RETRY_MARKER_REL.as_posix(),
                published_info,
            )
            self._assert_bound_regular_entry(
                parent_fd,
                destination,
                stage_fd,
                successor_snapshot,
                hashlib.sha256(content).hexdigest(),
                identity_error="legacy-marker-unconvertible",
            )
            if destructive_recovery:
                self._assert_destructive_recovery_metadata_bound(marker.target_root)
            if swapped_out is not None:
                assert stage_cleanup_identity is not None
                _remove_distribution_stage_if_owned(
                    parent_fd,
                    stage,
                    stage_cleanup_identity,
                    strict=True,
                )
                stage_cleanup_identity = None
                os.fsync(parent_fd)
            return replace(
                marker,
                source_snapshot=successor_snapshot,
                source_sha256=hashlib.sha256(content).hexdigest(),
            )
        except Exception:
            if swapped_out is not None and stage_cleanup_identity is swapped_out:
                try:
                    assert stage_fd is not None
                    visible_successor = os.stat(destination, dir_fd=parent_fd, follow_symlinks=False)
                    successor_info = os.fstat(stage_fd)
                    if _stat_structure_tuple(visible_successor) != _stat_structure_tuple(
                        successor_info
                    ) or not _held_fd_has_exact_bytes(stage_fd, content):
                        # Preserve the predecessor when the canonical name no
                        # longer contains our published successor.  It is
                        # recovery evidence, not an unowned cleanup target.
                        stage_cleanup_identity = None
                        stage_cleanup_suppressed = True
                except OSError:
                    stage_cleanup_identity = None
                    stage_cleanup_suppressed = True
            if stage_cleanup_identity is not None:
                _remove_distribution_stage_if_owned(parent_fd, stage, stage_cleanup_identity)
            elif not stage_cleanup_suppressed:
                # Preserve the original write error while removing a stage
                # whose metadata was not captured before the failure.
                with suppress(OSError, DistributionApplyError):
                    orphan_info = os.stat(stage, dir_fd=parent_fd, follow_symlinks=False)
                    _remove_distribution_stage_if_owned(parent_fd, stage, orphan_info)
            raise
        finally:
            if stage_fd is not None:
                os.close(stage_fd)
            if held_fd is not None:
                os.close(held_fd)
            os.close(parent_fd)
            os.close(root_fd)

    def restore_marker_bytes(self, marker: DistributionRetryMarker, content: bytes) -> None:
        """Restore a legacy marker after a conversion lost its journal race."""

        expected = marker.source_snapshot
        expected_sha256 = marker.source_sha256
        if expected is None or expected_sha256 is None:
            raise DistributionApplyError("legacy-marker-unconvertible")
        root_fd, parent_fd = self._open_parent(marker.target_root)
        stage = f".distribution-retry-{secrets.token_hex(16)}.restore"
        stage_info: os.stat_result | None = None
        stage_fd: int | None = None
        held_fd: int | None = None
        swapped_out: os.stat_result | None = None
        try:
            try:
                destination_info = os.stat(
                    _DISTRIBUTION_RETRY_MARKER_REL.name,
                    dir_fd=parent_fd,
                    follow_symlinks=False,
                )
            except OSError as exc:
                raise DistributionApplyError("legacy-marker-unconvertible") from exc
            if (
                not stat.S_ISREG(destination_info.st_mode)
                or destination_info.st_nlink != 1
                or destination_info.st_dev != expected.device
                or destination_info.st_ino != expected.inode
                or destination_info.st_ctime_ns != expected.ctime_ns
                or _file_type(destination_info.st_mode) != expected.file_type
                or destination_info.st_nlink != expected.link_count
            ):
                raise DistributionApplyError("legacy-marker-unconvertible")
            nofollow = getattr(os, "O_NOFOLLOW", None)
            if not isinstance(nofollow, int):
                raise DistributionApplyError("platform lacks required no-follow file support")
            held_fd = os.open(
                _DISTRIBUTION_RETRY_MARKER_REL.name,
                os.O_RDONLY | nofollow | getattr(os, "O_CLOEXEC", 0),
                dir_fd=parent_fd,
            )
            if _stat_identity_tuple(os.fstat(held_fd)) != _stat_identity_tuple(destination_info):
                raise DistributionApplyError("legacy-marker-unconvertible")
            stage_fd = os.open(
                stage,
                os.O_RDWR | os.O_CREAT | os.O_EXCL | nofollow | getattr(os, "O_CLOEXEC", 0),
                0o600,
                dir_fd=parent_fd,
            )
            _write_fd_bytes(stage_fd, content)
            os.fchmod(stage_fd, 0o600)
            stage_info = os.fstat(stage_fd)
            visible_stage = os.stat(stage, dir_fd=parent_fd, follow_symlinks=False)
            if _stat_identity_tuple(visible_stage) != _stat_identity_tuple(stage_info) or not _held_fd_has_exact_bytes(
                stage_fd, content
            ):
                raise DistributionApplyError("legacy-marker-unconvertible")
            self._validate_workspace_closed_set((stage,))
            swapped_out = _swap_regular_distribution_target_if_bound(
                parent_fd,
                stage,
                _DISTRIBUTION_RETRY_MARKER_REL.name,
                target_fd=held_fd,
                staging_fd=stage_fd,
                expected_target=destination_info,
                identity_message="legacy-marker-unconvertible",
            )
            os.fsync(parent_fd)
            published = os.fstat(stage_fd)
            successor_snapshot = _snapshot_from_stat(
                _DISTRIBUTION_RETRY_MARKER_REL.as_posix(),
                published,
            )
            self._assert_bound_regular_entry(
                parent_fd,
                _DISTRIBUTION_RETRY_MARKER_REL.name,
                stage_fd,
                successor_snapshot,
                hashlib.sha256(content).hexdigest(),
                identity_error="legacy-marker-unconvertible",
            )
            _remove_distribution_stage_if_owned(parent_fd, stage, swapped_out, strict=True)
            os.fsync(parent_fd)
        except Exception:
            if stage_info is not None and swapped_out is None:
                with suppress(OSError, DistributionApplyError):
                    _remove_distribution_stage_if_owned(parent_fd, stage, stage_info, strict=True)
            raise
        finally:
            if stage_fd is not None:
                os.close(stage_fd)
            if held_fd is not None:
                os.close(held_fd)
            os.close(parent_fd)
            os.close(root_fd)

    def resume(self, plan: ExecutableMutationPlan, *, package_version: str) -> OperationJournal:
        journal = self._read(plan.root_identity)
        _assert_gc_transition_graph(journal)
        current_guard = _read_distribution_retry_marker(self.target_root)
        if current_guard is None or current_guard.purpose != _journal_guard_purpose_for_intent(plan.intent):
            raise DistributionApplyError("dual-recovery-state")
        self.bind_forward_guard(current_guard)
        if journal.root_identity != plan.root_identity:
            raise DistributionApplyError("journal-root-mismatch")
        if journal.intent != plan.intent:
            raise DistributionApplyError("journal-intent-mismatch")
        if journal.authority != _journal_authority_for_intent(plan.intent):
            raise DistributionApplyError("journal-authority-mismatch")
        if (
            journal.protocol_version not in _DISTRIBUTION_SUPPORTED_JOURNAL_PROTOCOL_VERSIONS
            or not _journal_package_is_compatible(
                journal.package_version,
                package_version,
            )
        ):
            raise DistributionApplyError("journal-protocol-incompatible")
        if journal.contract_identity != plan.contract_identity:
            raise DistributionApplyError("journal-contract-mismatch")
        if not _plan_digest_matches(plan, journal.plan_digest):
            raise DistributionApplyError("journal-plan-mismatch")
        if journal.status == "prepared" and journal.staging_leases:
            validated_guard_leases = _validated_legacy_stage_leases(
                plan,
                current_guard,
                self.target_root,
                allow_operation_created_parents=True,
            )
            if journal.staging_leases != validated_guard_leases:
                raise DistributionApplyError("journal-precondition-mismatch")
        self._anchor_digestless_initial_journal(journal, plan)
        self._assert_guard_anchors_journal(journal)
        journal = self._migrate_legacy_protocol_journal(journal, plan.distribution_plan)
        if _is_destructive_intent(journal.intent):
            self._leaf_mutation_validator = _deprovision_recovery_leaf_mutation_validator(
                self,
                journal,
                forward_guard=self._forward_guard,
                intent=journal.intent,
            )
        journal = self._resume_displaced_quarantine_cleanup(
            journal,
            {action.path for action in journal.actions if action.checkpoint != "pending"},
            leaf_mutation_validator=self._leaf_mutation_validator,
        )
        return journal

    def load_for_assessment(
        self,
        assessment: WorkspaceAssessment,
        *,
        package_version: str,
        require_guard: bool = True,
    ) -> OperationJournal:
        journal = self._read(assessment.root_identity)
        _assert_gc_transition_graph(journal)
        if require_guard:
            current_guard = _read_distribution_retry_marker(self.target_root)
            if current_guard is None or current_guard.purpose != _journal_guard_purpose_for_intent(assessment.intent):
                raise DistributionApplyError("dual-recovery-state")
            self.bind_forward_guard(current_guard)
        elif journal.status != "completed":
            raise DistributionApplyError("dual-recovery-state")
        if journal.root_identity != assessment.root_identity:
            raise DistributionApplyError("journal-root-mismatch")
        if journal.intent != assessment.intent:
            raise DistributionApplyError("journal-intent-mismatch")
        if journal.authority != _journal_authority_for_intent(assessment.intent):
            raise DistributionApplyError("journal-authority-mismatch")
        if (
            journal.protocol_version not in _DISTRIBUTION_SUPPORTED_JOURNAL_PROTOCOL_VERSIONS
            or not _journal_package_is_compatible(
                journal.package_version,
                package_version,
            )
        ):
            raise DistributionApplyError("journal-protocol-incompatible")
        if journal.contract_identity != assessment.contract_identity:
            raise DistributionApplyError("journal-contract-mismatch")
        if _is_destructive_intent(assessment.intent) and journal.status in {"prepared", "executing"}:
            _assert_deprovision_zero_predecessor_reservations(self.target_root, journal)
        if require_guard:
            if self._forward_guard is not None and self._forward_guard.journal_digest is None:
                self._anchor_digestless_initial_journal(
                    journal,
                    _resume_executable_plan(assessment, journal),
                )
            self._assert_guard_anchors_journal(journal)
            if _is_destructive_intent(journal.intent):
                self._leaf_mutation_validator = _deprovision_recovery_leaf_mutation_validator(
                    self,
                    journal,
                    forward_guard=self._forward_guard,
                    intent=journal.intent,
                )
            journal = self._resume_displaced_quarantine_cleanup(
                journal,
                {action.path for action in journal.actions if action.checkpoint != "pending"},
                leaf_mutation_validator=self._leaf_mutation_validator,
            )
        journal = self._migrate_legacy_protocol_journal(journal, assessment.distribution_plan)
        return journal

    def _migrate_legacy_protocol_journal(
        self,
        journal: OperationJournal,
        plan: DistributionPlan,
    ) -> OperationJournal:
        """Promote protocol-1 successor records before current validation.

        Protocol 1 did not persist the structural identity of a published
        regular/symlink successor.  Such a record is compatible only when its
        semantic postcondition still matches the current target; the current
        observation is then write-ahead as the protocol-2 exact binding before
        any further resume or cleanup transition.
        """

        if journal.protocol_version != _DISTRIBUTION_LEGACY_JOURNAL_PROTOCOL_VERSION:
            return journal
        snapshots = dict(plan.target_snapshots)
        migrated_actions: list[OperationJournalAction] = []
        has_legacy_successor = False
        for record in journal.actions:
            if not _is_legacy_successor_postcondition(record):
                migrated_actions.append(record)
                continue
            has_legacy_successor = True
            snapshot = snapshots.get(record.path)
            if snapshot is None or not _snapshot_matches_condition(
                snapshot,
                record.postcondition,
                journal.created_parent_bindings,
            ):
                raise DistributionApplyError("journal-precondition-mismatch")
            target = snapshot.target
            if (
                not target.exists
                or target.file_type == "directory"
                or any(value is None for value in (target.device, target.inode, target.ctime_ns, target.link_count))
            ):
                raise DistributionApplyError("journal-protocol-incompatible")
            lease = next(
                (item for item in journal.staging_leases if item.path == record.path and item.role == "stage"),
                None,
            )
            if lease is None:
                if journal.status != "completed" or self._forward_guard is not None:
                    raise DistributionApplyError("journal-protocol-incompatible")
                migrated_actions.append(
                    replace(
                        record,
                        postcondition={
                            **record.postcondition,
                            "device": target.device,
                            "inode": target.inode,
                            "ctime_ns": target.ctime_ns,
                            "link_count": target.link_count,
                        },
                    )
                )
                continue
            parent_chain = _open_distribution_parent_chain(
                self.target_root,
                record.path,
                create_missing=False,
            )
            try:
                successor_postcondition = self._capture_exact_canonical_successor(
                    parent_chain[-1],
                    PurePosixPath(record.path).name,
                    record.path,
                    lease,
                    record.postcondition,
                )
            finally:
                _close_distribution_parent_chain(parent_chain)
            migrated_actions.append(replace(record, postcondition=successor_postcondition))
        if not has_legacy_successor:
            return journal
        migrated_journal = replace(
            journal,
            protocol_version=_DISTRIBUTION_JOURNAL_PROTOCOL_VERSION,
            actions=tuple(migrated_actions),
        )
        if journal.status == "completed" and self._forward_guard is None:
            return migrated_journal
        return self.write(migrated_journal, predecessor=journal)

    def write(
        self,
        journal: OperationJournal,
        *,
        predecessor: OperationJournal | None = None,
    ) -> OperationJournal:
        if predecessor is None:
            predecessor = self._read(journal.root_identity)
        return self._write(journal, predecessor=predecessor)

    def mark_executing(self, journal: OperationJournal) -> OperationJournal:
        if journal.status not in {"prepared", "executing"}:
            raise DistributionApplyError("journal-precondition-mismatch")
        return self.write(replace(journal, status="executing"), predecessor=journal)

    def checkpoint_published(
        self,
        journal: OperationJournal,
        completed_paths: tuple[str, ...],
    ) -> OperationJournal:
        leaf_mutation_validator = self._leaf_mutation_validator
        if _is_destructive_intent(journal.intent) and leaf_mutation_validator is None:
            raise DistributionApplyError("journal-precondition-mismatch")
        if _is_destructive_intent(journal.intent):
            _assert_deprovision_recovery_marker_bound(self, self._forward_guard)
            self._assert_destructive_recovery_metadata_bound(journal.root_identity)
        completed = set(completed_paths)
        persisted = self._read(journal.root_identity)
        self._assert_guard_anchors_journal(persisted)
        if (
            persisted.operation_id != journal.operation_id
            or persisted.contract_identity != journal.contract_identity
            or persisted.plan_digest != journal.plan_digest
        ):
            raise DistributionApplyError("journal-precondition-mismatch")

        def validate_pending_checkpoint_boundaries(active: OperationJournal) -> None:
            if leaf_mutation_validator is None:
                return
            directory_mutation_validator = _deprovision_recovery_directory_mutation_validator(
                self,
                active,
                forward_guard=self._forward_guard,
                intent=active.intent,
            )
            for record in active.actions:
                if record.checkpoint != "pending" or record.path not in completed:
                    continue
                try:
                    parent_chain = _open_distribution_parent_chain(
                        self.target_root,
                        record.path,
                        create_missing=False,
                    )
                except DistributionApplyError as exc:
                    raise DistributionApplyError(
                        "deprovision-visible-parent-chain-mismatch",
                        failed_paths=(PurePosixPath(record.path).parent.as_posix(),),
                    ) from exc
                try:
                    validator = (
                        directory_mutation_validator
                        if record.action == "remove-empty-directory"
                        else leaf_mutation_validator
                    )
                    validator(record.path, parent_chain)
                finally:
                    _close_distribution_parent_chain(parent_chain)

        validate_pending_checkpoint_boundaries(persisted)
        active = self._resume_displaced_quarantine_cleanup(
            persisted,
            completed,
            leaf_mutation_validator=leaf_mutation_validator,
        )
        validate_pending_checkpoint_boundaries(active)
        records = {record.path: record for record in journal.actions}
        cleanup_transitions: dict[
            str,
            tuple[DistributionStageOwnership, dict[str, object], dict[str, object]],
        ] = {}
        updated_leases = {lease.path: lease for lease in active.staging_leases}
        leases_changed = False
        for lease in active.staging_leases:
            if lease.path not in completed or lease.role != "stage":
                continue
            try:
                parent_chain = _open_distribution_parent_chain(
                    self.target_root,
                    lease.path,
                    create_missing=False,
                )
            except DistributionApplyError as exc:
                raise DistributionApplyError("managed staging cleanup failed") from exc
            try:
                try:
                    stage_info = os.stat(lease.stage_name, dir_fd=parent_chain[-1], follow_symlinks=False)
                except FileNotFoundError:
                    if lease.device == lease.inode == lease.ctime_ns == 0:
                        raise DistributionApplyError("managed staging cleanup failed") from None
                    record = records.get(lease.path)
                    if record is None:
                        raise DistributionApplyError("managed staging cleanup failed") from None
                    target_name = PurePosixPath(lease.path).name
                    try:
                        target_info = os.stat(target_name, dir_fd=parent_chain[-1], follow_symlinks=False)
                    except FileNotFoundError as exc:
                        if record.action == "prune" and _journal_postcondition(record).get("exists") is False:
                            continue
                        raise DistributionApplyError("managed staging cleanup failed") from exc
                    target_identity = _distribution_stage_identity(parent_chain[-1], target_name, lease.path)
                    if (
                        record.action == "adopt"
                        and target_info.st_nlink == 1
                        and _journal_postcondition(record).get("identity")
                        == _distribution_identity_payload(target_identity)
                    ):
                        continue
                    if (
                        target_info.st_dev != lease.device
                        or target_info.st_ino != lease.inode
                        or _file_type(target_info.st_mode) != lease.file_type
                        or target_info.st_nlink != 1
                        or _journal_postcondition(record).get("identity")
                        != _distribution_identity_payload(target_identity)
                    ):
                        raise DistributionApplyError("managed staging cleanup failed") from None
                    continue
                if lease.device == lease.inode == lease.ctime_ns == 0:
                    record = records.get(lease.path)
                    candidate = _distribution_stage_identity(
                        parent_chain[-1],
                        lease.stage_name,
                        lease.path,
                    )
                    if (
                        record is None
                        or record.action != "prune"
                        or stage_info.st_dev != record.precondition.get("device")
                        or stage_info.st_ino != record.precondition.get("inode")
                        or _file_type(stage_info.st_mode) != record.precondition.get("file_type")
                        or stage_info.st_nlink != record.precondition.get("link_count") == 1
                        or record.precondition.get("identity") != _distribution_identity_payload(candidate)
                    ):
                        raise DistributionApplyError("managed staging cleanup failed")
                    updated_leases[lease.path] = _distribution_stage_ownership(
                        lease.path,
                        lease.stage_name,
                        stage_info,
                    )
                    leases_changed = True
                    continue
                if (
                    stage_info.st_dev == lease.device
                    and stage_info.st_ino == lease.inode
                    and stage_info.st_ctime_ns == lease.ctime_ns
                    and _file_type(stage_info.st_mode) == lease.file_type
                    and stage_info.st_nlink == 1
                ):
                    continue
                record = records.get(lease.path)
                if record is None or record.action != "upgrade":
                    raise DistributionApplyError("managed staging cleanup failed")
                target_name = PurePosixPath(lease.path).name
                target_info = os.stat(target_name, dir_fd=parent_chain[-1], follow_symlinks=False)
                target_identity = _distribution_stage_identity(parent_chain[-1], target_name, lease.path)
                stage_identity = _distribution_stage_identity(parent_chain[-1], lease.stage_name, lease.path)
                pre = record.precondition
                post = _journal_postcondition(record)
                canonical_is_published_lease = (
                    target_info.st_dev == lease.device
                    and target_info.st_ino == lease.inode
                    and target_info.st_ctime_ns == lease.ctime_ns
                    and _file_type(target_info.st_mode) == lease.file_type
                    and target_info.st_nlink == 1
                    and post.get("identity") == _distribution_identity_payload(target_identity)
                )
                stage_is_displaced_predecessor = (
                    stage_info.st_dev == pre.get("device")
                    and stage_info.st_ino == pre.get("inode")
                    and _file_type(stage_info.st_mode) == pre.get("file_type")
                    and stage_info.st_nlink == pre.get("link_count") == 1
                    and pre.get("identity") == _distribution_identity_payload(stage_identity)
                )
                if not canonical_is_published_lease or not stage_is_displaced_predecessor:
                    raise DistributionApplyError("managed staging cleanup failed")
                cleanup_transitions[lease.path] = (lease, pre, post)
            finally:
                _close_distribution_parent_chain(parent_chain)
        if leases_changed:
            active = self.write(
                replace(
                    active,
                    staging_leases=tuple(updated_leases[lease.path] for lease in active.staging_leases),
                ),
                predecessor=active,
            )
        successor_actions: dict[str, OperationJournalAction] = {}
        for lease in active.staging_leases:
            if lease.path not in completed or lease.role != "stage":
                continue
            record = next((item for item in active.actions if item.path == lease.path), None)
            if record is None or record.action not in {"create", "upgrade"}:
                continue
            if record.postcondition.get("file_type") == "directory":
                continue
            parent_chain = _open_distribution_parent_chain(
                self.target_root,
                lease.path,
                create_missing=False,
            )
            try:
                successor_postcondition = self._capture_exact_canonical_successor(
                    parent_chain[-1],
                    PurePosixPath(lease.path).name,
                    lease.path,
                    lease,
                    record.postcondition,
                )
            finally:
                _close_distribution_parent_chain(parent_chain)
            successor_actions[lease.path] = replace(record, postcondition=successor_postcondition)
        if successor_actions:
            active = self.write(
                replace(
                    active,
                    actions=tuple(successor_actions.get(record.path, record) for record in active.actions),
                ),
                predecessor=active,
            )
        for lease in active.staging_leases:
            if lease.path not in completed or lease.role != "stage":
                continue
            try:
                parent_chain = _open_distribution_parent_chain(
                    self.target_root,
                    lease.path,
                    create_missing=False,
                )
            except DistributionApplyError as exc:
                raise DistributionApplyError("managed staging cleanup failed") from exc
            try:
                try:
                    stage_info = os.stat(lease.stage_name, dir_fd=parent_chain[-1], follow_symlinks=False)
                except FileNotFoundError:
                    continue
                if lease.path not in cleanup_transitions and (
                    stage_info.st_dev != lease.device
                    or stage_info.st_ino != lease.inode
                    or stage_info.st_ctime_ns != lease.ctime_ns
                    or _file_type(stage_info.st_mode) != lease.file_type
                    or stage_info.st_nlink != 1
                ):
                    raise DistributionApplyError("managed staging cleanup failed")

                def record_cleanup_transition(updated: DistributionStageOwnership) -> None:
                    nonlocal active
                    active = self.record_staging_lease(active, updated)

                cleanup_leaf_validator: Callable[[], None] | None = None
                if leaf_mutation_validator is not None:

                    def validate_cleanup_leaf(
                        bound_path: str = lease.path,
                        bound_chain: tuple[int, ...] = parent_chain,
                    ) -> None:
                        leaf_mutation_validator(bound_path, bound_chain)

                    cleanup_leaf_validator = validate_cleanup_leaf

                _remove_distribution_stage_if_owned(
                    parent_chain[-1],
                    lease.stage_name,
                    stage_info,
                    strict=True,
                    transition_path=lease.path if lease.path in cleanup_transitions else None,
                    canonical_name=(PurePosixPath(lease.path).name if lease.path in cleanup_transitions else None),
                    canonical_ownership=(
                        cleanup_transitions[lease.path][0] if lease.path in cleanup_transitions else None
                    ),
                    canonical_condition=(
                        cleanup_transitions[lease.path][2] if lease.path in cleanup_transitions else None
                    ),
                    stage_condition=(cleanup_transitions[lease.path][1] if lease.path in cleanup_transitions else None),
                    transition_recorder=(record_cleanup_transition if lease.path in cleanup_transitions else None),
                    mutation_validator=cleanup_leaf_validator,
                    post_link_mutation_validator=cleanup_leaf_validator,
                )
            finally:
                _close_distribution_parent_chain(parent_chain)
        actions = tuple(
            replace(action, checkpoint="published")
            if action.path in completed and action.checkpoint == "pending"
            else action
            for action in active.actions
        )
        published = self.write(
            replace(
                active,
                status="executing",
                actions=actions,
            ),
            predecessor=active,
        )
        published_records = {record.path: record for record in published.actions}
        for lease in published.staging_leases:
            if lease.path not in completed or lease.role != "backup-only":
                continue
            parent_chain = _open_distribution_parent_chain(
                self.target_root,
                lease.path,
                create_missing=False,
            )
            try:
                parent_fd = parent_chain[-1]
                backup_name = lease.stage_name
                backup = _stat_optional_no_follow(parent_fd, backup_name)
                if backup is None:
                    continue
                if (
                    backup.st_dev != lease.device
                    or backup.st_ino != lease.inode
                    or backup.st_ctime_ns != lease.ctime_ns
                    or _file_type(backup.st_mode) != lease.file_type
                    or backup.st_nlink != 1
                ):
                    raise DistributionApplyError("managed staging cleanup failed")
                record = published_records.get(lease.path)
                if record is None:
                    raise DistributionApplyError("managed staging cleanup failed")
                target_name = PurePosixPath(lease.path).name
                if record.action == "prune":

                    def validate_prune_backup_gc(
                        bound_parent_fd: int = parent_fd,
                        bound_target_name: str = target_name,
                        bound_path: str = lease.path,
                        bound_parent_chain: tuple[int, ...] = parent_chain,
                    ) -> None:
                        if leaf_mutation_validator is not None:
                            leaf_mutation_validator(bound_path, bound_parent_chain)
                        if _stat_optional_no_follow(bound_parent_fd, bound_target_name) is not None:
                            raise DistributionApplyError("managed staging cleanup failed")

                    validate_backup_gc: Callable[[], None] = validate_prune_backup_gc
                else:
                    successors = tuple(
                        item for item in published.staging_leases if item.path == lease.path and item.role == "stage"
                    )
                    if len(successors) != 1:
                        raise DistributionApplyError("managed staging cleanup failed")
                    bound_postcondition = _journal_postcondition(record)
                    self._assert_exact_canonical_successor(
                        parent_fd,
                        target_name,
                        lease.path,
                        successors[0],
                        bound_postcondition,
                    )

                    def validate_successor_backup_gc(
                        bound_parent_fd: int = parent_fd,
                        bound_target_name: str = target_name,
                        bound_path: str = lease.path,
                        bound_parent_chain: tuple[int, ...] = parent_chain,
                        bound_successor: DistributionStageOwnership = successors[0],
                        bound_postcondition: dict[str, object] = bound_postcondition,
                    ) -> None:
                        if leaf_mutation_validator is not None:
                            leaf_mutation_validator(bound_path, bound_parent_chain)
                        self._assert_exact_canonical_successor(
                            bound_parent_fd,
                            bound_target_name,
                            bound_path,
                            bound_successor,
                            bound_postcondition,
                        )

                    validate_backup_gc = validate_successor_backup_gc

                def record_backup_gc(updated: DistributionStageOwnership) -> None:
                    nonlocal published
                    published = self.record_staging_lease(published, updated)

                _remove_distribution_stage_if_owned(
                    parent_fd,
                    backup_name,
                    backup,
                    strict=True,
                    mutation_validator=validate_backup_gc,
                    post_link_mutation_validator=(validate_backup_gc if leaf_mutation_validator is not None else None),
                    gc_path=lease.path,
                    gc_recorder=record_backup_gc,
                )
            finally:
                _close_distribution_parent_chain(parent_chain)
        staging_leases = tuple(lease for lease in published.staging_leases if lease.path not in completed)
        return self.write(
            replace(published, staging_leases=staging_leases),
            predecessor=published,
        )

    @staticmethod
    def _capture_exact_canonical_successor(
        parent_fd: int,
        target_name: str,
        path: str,
        successor: DistributionStageOwnership,
        postcondition: dict[str, object],
    ) -> dict[str, object]:
        canonical = os.stat(target_name, dir_fd=parent_fd, follow_symlinks=False)
        canonical_identity = _distribution_stage_identity(parent_fd, target_name, path)
        if (
            canonical.st_dev != successor.device
            or canonical.st_ino != successor.inode
            or _file_type(canonical.st_mode) != successor.file_type
            or canonical.st_nlink != 1
            or postcondition.get("identity") != _distribution_identity_payload(canonical_identity)
        ):
            raise DistributionApplyError("managed staging cleanup failed")
        return {
            **postcondition,
            "device": canonical.st_dev,
            "inode": canonical.st_ino,
            "ctime_ns": canonical.st_ctime_ns,
            "link_count": canonical.st_nlink,
        }

    @staticmethod
    def _assert_exact_canonical_successor(
        parent_fd: int,
        target_name: str,
        path: str,
        successor: DistributionStageOwnership,
        postcondition: dict[str, object],
    ) -> None:
        OperationJournalStore._capture_exact_canonical_successor(
            parent_fd,
            target_name,
            path,
            successor,
            postcondition,
        )

    def _resume_displaced_quarantine_cleanup(
        self,
        journal: OperationJournal,
        completed: set[str],
        *,
        leaf_mutation_validator: Callable[[str, tuple[int, ...]], None] | None = None,
    ) -> OperationJournal:
        """Finish a write-ahead predecessor quarantine without losing its successor lease."""

        if _is_destructive_intent(journal.intent) and leaf_mutation_validator is None:
            raise DistributionApplyError("journal-precondition-mismatch")

        def validate_roleless_backup_parents(active_journal: OperationJournal) -> None:
            if not _is_destructive_intent(active_journal.intent):
                return
            # Legacy roleless backup promotion writes a new journal lease.  It
            # must be preceded by the same root/parent attachment proof as a
            # leaf mutation so a rebound parent cannot first alter recovery
            # metadata and only then fail at the next cleanup boundary.
            for quarantine in tuple(
                lease for lease in active_journal.staging_leases if lease.role == "predecessor-quarantine"
            ):
                backup_name = _distribution_quarantine_backup_name(quarantine.stage_name)
                explicit_backups = tuple(
                    lease
                    for lease in active_journal.staging_leases
                    if lease.path == quarantine.path
                    and lease.stage_name == backup_name
                    and lease.role in {"backup-reserved", "backup-dual", "backup-only-reserved", "backup-only"}
                )
                if explicit_backups:
                    continue
                parent_chain = _open_distribution_parent_chain(
                    self.target_root,
                    quarantine.path,
                    create_missing=False,
                )
                try:
                    if _stat_optional_no_follow(parent_chain[-1], backup_name) is not None:
                        _assert_deprovision_recovery_parent_attachment(
                            self,
                            active_journal,
                            quarantine.path,
                            parent_chain,
                            forward_guard=self._forward_guard,
                            intent=active_journal.intent,
                        )
                finally:
                    _close_distribution_parent_chain(parent_chain)

        validate_roleless_backup_parents(journal)
        active = self._resume_gc_cleanup(journal, leaf_mutation_validator=leaf_mutation_validator)
        validate_roleless_backup_parents(active)
        active = self._promote_roleless_backup_leases(
            active,
            leaf_mutation_validator=leaf_mutation_validator,
        )
        records = {record.path: record for record in active.actions}
        quarantine_leases = tuple(
            lease
            for lease in active.staging_leases
            if lease.role == "predecessor-quarantine"
            and (
                lease.path in completed
                or (
                    (record := records.get(lease.path)) is not None
                    and record.checkpoint == "pending"
                    and record.action in {"create", "adopt"}
                )
            )
        )
        if not quarantine_leases:
            return active
        if len({lease.path for lease in quarantine_leases}) != len(quarantine_leases):
            raise DistributionApplyError("managed staging cleanup failed")

        for quarantine_lease in quarantine_leases:
            record = records.get(quarantine_lease.path)
            original_stage_name = quarantine_lease.stage_name.rsplit(".", 2)[0]
            successors = tuple(
                lease
                for lease in active.staging_leases
                if lease.path == quarantine_lease.path
                and lease.role == "stage"
                and (record is None or record.action == "upgrade" or lease.stage_name != original_stage_name)
                and lease.stage_name != _distribution_quarantine_backup_name(quarantine_lease.stage_name)
            )
            backup_leases = tuple(
                lease
                for lease in active.staging_leases
                if lease.path == quarantine_lease.path
                and lease.role in {"backup-reserved", "backup-dual", "backup-only-reserved", "backup-only"}
            )
            if (
                record is None
                or record.action not in {"create", "adopt", "upgrade", "prune"}
                or (record.action == "upgrade" and len(successors) != 1)
                or (record.action != "upgrade" and successors)
            ):
                raise DistributionApplyError("managed staging cleanup failed")
            successor = successors[0] if successors else None
            if successor is not None and not quarantine_lease.stage_name.startswith(f"{successor.stage_name}."):
                raise DistributionApplyError("managed staging cleanup failed")
            try:
                parent_chain = _open_distribution_parent_chain(
                    self.target_root,
                    quarantine_lease.path,
                    create_missing=False,
                )
            except DistributionApplyError as exc:
                raise DistributionApplyError("managed staging cleanup failed") from exc
            try:
                parent_fd = parent_chain[-1]
                target_name = PurePosixPath(quarantine_lease.path).name

                def validate_leaf_boundary(
                    bound_path: str = quarantine_lease.path,
                    bound_parent_chain: tuple[int, ...] = parent_chain,
                ) -> None:
                    if leaf_mutation_validator is not None:
                        leaf_mutation_validator(bound_path, bound_parent_chain)

                def validate_leaf_attachment(
                    bound_path: str = quarantine_lease.path,
                    bound_parent_chain: tuple[int, ...] = parent_chain,
                ) -> None:
                    if leaf_mutation_validator is not None:
                        leaf_mutation_validator(bound_path, bound_parent_chain)

                def validate_canonical_authority(
                    bound_record: OperationJournalAction = record,
                    bound_successor: DistributionStageOwnership | None = successor,
                    bound_parent_fd: int = parent_fd,
                    bound_target_name: str = target_name,
                    bound_path: str = quarantine_lease.path,
                ) -> None:
                    if bound_record.action == "upgrade":
                        assert bound_successor is not None
                        self._assert_exact_canonical_successor(
                            bound_parent_fd,
                            bound_target_name,
                            bound_path,
                            bound_successor,
                            _journal_postcondition(bound_record),
                        )
                    elif bound_record.action == "prune":
                        if _stat_optional_no_follow(bound_parent_fd, bound_target_name) is not None:
                            raise DistributionApplyError("managed staging cleanup failed")
                    elif not _entry_matches_journal_condition(
                        bound_parent_fd,
                        bound_target_name,
                        bound_path,
                        bound_record.precondition,
                    ):
                        raise DistributionApplyError("managed staging cleanup failed")

                validate_leaf_boundary()
                validate_canonical_authority()
                bound_postcondition = _journal_postcondition(record)
                if successor is not None:
                    self._assert_exact_canonical_successor(
                        parent_fd,
                        target_name,
                        quarantine_lease.path,
                        successor,
                        bound_postcondition,
                    )

                quarantine_info = _stat_optional_no_follow(parent_fd, quarantine_lease.stage_name)
                original_info = _stat_optional_no_follow(parent_fd, original_stage_name)
                backup_name = _distribution_quarantine_backup_name(quarantine_lease.stage_name)
                backup_info = _stat_optional_no_follow(parent_fd, backup_name)

                def record_transition(
                    lease: DistributionStageOwnership,
                    bound_path: str = quarantine_lease.path,
                    bound_parent_chain: tuple[int, ...] = parent_chain,
                ) -> None:
                    nonlocal active
                    active = self.record_staging_lease(active, lease)
                    if lease.role not in {"gc-reserved", "gc-exact"}:
                        validate_leaf_boundary()
                    elif leaf_mutation_validator is not None:
                        _assert_visible_distribution_chain_exactly_bound(
                            self.target_root,
                            bound_path,
                            bound_parent_chain,
                        )

                if backup_info is not None:
                    if original_info is not None:
                        raise DistributionApplyError("managed staging cleanup failed")
                    if quarantine_info is None:
                        exact_backup = tuple(lease for lease in backup_leases if lease.role == "backup-only")
                        if not exact_backup:
                            reserved_backup = tuple(
                                lease for lease in backup_leases if lease.role == "backup-only-reserved"
                            )
                            dual_backup_leases = tuple(lease for lease in backup_leases if lease.role == "backup-dual")
                            if (
                                len(reserved_backup) != 1
                                or len(dual_backup_leases) != 1
                                or backup_info.st_dev != dual_backup_leases[0].device
                                or backup_info.st_ino != dual_backup_leases[0].inode
                                or _file_type(backup_info.st_mode) != dual_backup_leases[0].file_type
                                or backup_info.st_nlink != 1
                            ):
                                raise DistributionApplyError("managed staging cleanup failed")
                            record_transition(
                                _distribution_stage_ownership(
                                    quarantine_lease.path,
                                    backup_name,
                                    backup_info,
                                    role="backup-only",
                                )
                            )
                            exact_backup = tuple(
                                lease
                                for lease in active.staging_leases
                                if lease.path == quarantine_lease.path and lease.role == "backup-only"
                            )
                        if (
                            len(exact_backup) != 1
                            or backup_info.st_dev != exact_backup[0].device
                            or backup_info.st_ino != exact_backup[0].inode
                            or backup_info.st_ctime_ns != exact_backup[0].ctime_ns
                            or _file_type(backup_info.st_mode) != exact_backup[0].file_type
                            or backup_info.st_nlink != 1
                        ):
                            raise DistributionApplyError("managed staging cleanup failed")
                    else:
                        exact_dual = tuple(lease for lease in backup_leases if lease.role == "backup-dual")
                        if not exact_dual:
                            reserved_backup = tuple(lease for lease in backup_leases if lease.role == "backup-reserved")
                            quarantine_identity = _distribution_stage_identity(
                                parent_fd,
                                quarantine_lease.stage_name,
                                quarantine_lease.path,
                                allow_backup_link=True,
                            )
                            if (
                                len(reserved_backup) != 1
                                or quarantine_info.st_dev != backup_info.st_dev
                                or quarantine_info.st_ino != backup_info.st_ino
                                or quarantine_info.st_dev != quarantine_lease.device
                                or quarantine_info.st_ino != quarantine_lease.inode
                                or quarantine_info.st_nlink != backup_info.st_nlink
                                or quarantine_info.st_nlink != 2
                                or _file_type(quarantine_info.st_mode) != quarantine_lease.file_type
                                or record.precondition.get("identity")
                                != _distribution_identity_payload(quarantine_identity)
                            ):
                                raise DistributionApplyError("managed staging cleanup failed")
                            record_transition(
                                _distribution_stage_ownership(
                                    quarantine_lease.path,
                                    backup_name,
                                    backup_info,
                                    role="backup-dual",
                                )
                            )
                            exact_dual = tuple(
                                lease
                                for lease in active.staging_leases
                                if lease.path == quarantine_lease.path and lease.role == "backup-dual"
                            )
                        if (
                            len(exact_dual) != 1
                            or quarantine_info.st_dev != backup_info.st_dev
                            or quarantine_info.st_ino != backup_info.st_ino
                            or backup_info.st_dev != exact_dual[0].device
                            or backup_info.st_ino != exact_dual[0].inode
                            or backup_info.st_ctime_ns != exact_dual[0].ctime_ns
                        ):
                            raise DistributionApplyError("managed staging cleanup failed")
                    backup_leases = tuple(
                        lease
                        for lease in active.staging_leases
                        if lease.path == quarantine_lease.path
                        and lease.role in {"backup-reserved", "backup-dual", "backup-only-reserved", "backup-only"}
                    )
                if quarantine_info is not None and original_info is not None:
                    raise DistributionApplyError("managed staging cleanup failed")

                reserved = quarantine_lease.device == quarantine_lease.inode == quarantine_lease.ctime_ns == 0
                if original_info is not None:
                    if record.action in {"create", "adopt"}:
                        source_leases = tuple(
                            lease
                            for lease in active.staging_leases
                            if lease.path == quarantine_lease.path
                            and lease.role == "stage"
                            and lease.stage_name == original_stage_name
                        )
                        if (
                            len(source_leases) == 1
                            and source_leases[0].device == source_leases[0].inode == source_leases[0].ctime_ns == 0
                            and _file_type(original_info.st_mode) == source_leases[0].file_type
                            and original_info.st_nlink == 1
                        ):
                            record_transition(
                                _distribution_stage_ownership(
                                    quarantine_lease.path,
                                    original_stage_name,
                                    original_info,
                                )
                            )
                            source_leases = tuple(
                                lease
                                for lease in active.staging_leases
                                if lease.path == quarantine_lease.path
                                and lease.role == "stage"
                                and lease.stage_name == original_stage_name
                            )
                        if (
                            len(source_leases) != 1
                            or original_info.st_dev != source_leases[0].device
                            or original_info.st_ino != source_leases[0].inode
                            or original_info.st_ctime_ns != source_leases[0].ctime_ns
                        ):
                            raise DistributionApplyError("managed staging cleanup failed")
                        _remove_distribution_target_if_bound(
                            parent_fd,
                            original_stage_name,
                            original_info,
                            identity_message="managed staging cleanup failed",
                            transition_path=quarantine_lease.path,
                            transition_name=quarantine_lease.stage_name,
                            transition_recorder=record_transition,
                            canonical_validator=validate_canonical_authority,
                            mutation_validator=validate_leaf_boundary,
                            post_link_mutation_validator=(
                                validate_leaf_boundary if leaf_mutation_validator is not None else None
                            ),
                        )
                    else:
                        assert successor is not None
                        _remove_distribution_stage_if_owned(
                            parent_fd,
                            original_stage_name,
                            original_info,
                            strict=True,
                            transition_path=quarantine_lease.path,
                            canonical_name=target_name,
                            canonical_ownership=successor,
                            canonical_condition=_journal_postcondition(record),
                            stage_condition=record.precondition,
                            transition_name=quarantine_lease.stage_name,
                            transition_recorder=record_transition,
                            mutation_validator=validate_leaf_boundary,
                            post_link_mutation_validator=(
                                validate_leaf_boundary if leaf_mutation_validator is not None else None
                            ),
                        )
                elif quarantine_info is not None:
                    dual_backup = next(
                        (lease for lease in backup_leases if lease.role == "backup-dual"),
                        None,
                    )
                    quarantine_authority = dual_backup if backup_info is not None else quarantine_lease
                    quarantine_identity = _distribution_stage_identity(
                        parent_fd,
                        quarantine_lease.stage_name,
                        quarantine_lease.path,
                        allow_backup_link=backup_info is not None,
                    )
                    stale_source = next(
                        (
                            lease
                            for lease in active.staging_leases
                            if lease.path == quarantine_lease.path
                            and lease.role == "stage"
                            and lease.stage_name == original_stage_name
                        ),
                        None,
                    )
                    if record.action in {"create", "adopt"}:
                        payload_is_owned = stale_source is not None and (
                            stale_source.device == stale_source.inode == stale_source.ctime_ns == 0
                            or (
                                quarantine_info.st_dev == stale_source.device
                                and quarantine_info.st_ino == stale_source.inode
                            )
                        )
                    else:
                        payload_is_owned = record.precondition.get("identity") == _distribution_identity_payload(
                            quarantine_identity
                        )
                    if (
                        _file_type(quarantine_info.st_mode) != quarantine_lease.file_type
                        or quarantine_info.st_nlink not in ({1, 2} if backup_info is not None else {1})
                        or not payload_is_owned
                        or (
                            not reserved
                            and (
                                quarantine_authority is None
                                or quarantine_info.st_dev != quarantine_authority.device
                                or quarantine_info.st_ino != quarantine_authority.inode
                                or quarantine_info.st_ctime_ns != quarantine_authority.ctime_ns
                            )
                        )
                    ):
                        raise DistributionApplyError("managed staging cleanup failed")
                    if reserved:
                        record_transition(
                            _distribution_stage_ownership(
                                quarantine_lease.path,
                                quarantine_lease.stage_name,
                                quarantine_info,
                                role="predecessor-quarantine",
                            )
                        )
                    validate_leaf_boundary()
                    validate_canonical_authority()

                    def validate_canonical_for_unlink(
                        bound_parent_fd: int = parent_fd,
                        bound_target_name: str = target_name,
                        bound_path: str = quarantine_lease.path,
                        bound_successor: DistributionStageOwnership | None = successor,
                        bound_postcondition: dict[str, object] = bound_postcondition,
                        bound_action: str = record.action,
                    ) -> None:
                        if bound_action in {"create", "adopt", "prune"}:
                            validate_canonical_authority()
                        else:
                            assert bound_successor is not None
                            self._assert_exact_canonical_successor(
                                bound_parent_fd,
                                bound_target_name,
                                bound_path,
                                bound_successor,
                                bound_postcondition,
                            )

                    _unlink_distribution_quarantine_with_backup(
                        parent_fd,
                        quarantine_lease.stage_name,
                        original_stage_name,
                        quarantine_info,
                        canonical_validator=validate_canonical_for_unlink,
                        mutation_validator=validate_leaf_boundary,
                        post_link_mutation_validator=(
                            validate_leaf_boundary if leaf_mutation_validator is not None else None
                        ),
                        allow_existing_backup=True,
                        backup_recorder=record_transition,
                        transition_path=quarantine_lease.path,
                    )
                elif reserved:
                    raise DistributionApplyError("managed staging cleanup failed")
            finally:
                _close_distribution_parent_chain(parent_chain)

            retained_backup = next(
                (
                    lease
                    for lease in active.staging_leases
                    if lease.path == quarantine_lease.path and lease.role == "backup-only"
                ),
                None,
            )
            if retained_backup is None:
                raise DistributionApplyError("managed staging cleanup failed")
            parent_chain = _open_distribution_parent_chain(
                self.target_root,
                quarantine_lease.path,
                create_missing=False,
            )
            try:
                parent_fd = parent_chain[-1]

                def validate_backup_boundary(
                    bound_path: str = quarantine_lease.path,
                    bound_parent_chain: tuple[int, ...] = parent_chain,
                ) -> None:
                    if leaf_mutation_validator is not None:
                        leaf_mutation_validator(bound_path, bound_parent_chain)

                validate_backup_boundary()
                validate_canonical_authority()
                backup_name = retained_backup.stage_name
                backup = _stat_optional_no_follow(parent_fd, backup_name)
                if backup is not None:
                    if (
                        backup.st_dev != retained_backup.device
                        or backup.st_ino != retained_backup.inode
                        or backup.st_ctime_ns != retained_backup.ctime_ns
                        or _file_type(backup.st_mode) != retained_backup.file_type
                        or backup.st_nlink != 1
                    ):
                        raise DistributionApplyError("managed staging cleanup failed")

                    def validate_backup_gc() -> None:
                        validate_leaf_attachment()
                        validate_canonical_authority()

                    _remove_distribution_stage_if_owned(
                        parent_fd,
                        backup_name,
                        backup,
                        strict=True,
                        mutation_validator=validate_backup_gc,
                        post_link_mutation_validator=(
                            validate_backup_gc if leaf_mutation_validator is not None else None
                        ),
                        gc_path=quarantine_lease.path,
                        gc_recorder=record_transition,
                    )
            finally:
                _close_distribution_parent_chain(parent_chain)

            retained = tuple(
                lease
                for lease in active.staging_leases
                if not (
                    lease.path == quarantine_lease.path
                    and (
                        lease.role
                        in {
                            "predecessor-quarantine",
                            "backup-reserved",
                            "backup-dual",
                            "backup-only-reserved",
                            "backup-only",
                            "gc-reserved",
                            "gc-exact",
                        }
                        or (
                            record.action in {"create", "adopt"}
                            and lease.role == "stage"
                            and lease.stage_name == original_stage_name
                        )
                    )
                )
            )
            active = self.write(replace(active, staging_leases=retained), predecessor=active)
        return active

    def _resume_gc_cleanup(
        self,
        journal: OperationJournal,
        *,
        leaf_mutation_validator: Callable[[str, tuple[int, ...]], None] | None = None,
    ) -> OperationJournal:
        """Finish journal-owned private-name GC before any target action resumes."""

        if _is_destructive_intent(journal.intent) and leaf_mutation_validator is None:
            raise DistributionApplyError("journal-precondition-mismatch")
        _assert_gc_transition_graph(journal)
        active = journal
        records = {record.path: record for record in active.actions}
        gc_leases = _ordered_gc_transition_leases(active)
        for stale_gc_lease in gc_leases:
            current_gc = tuple(
                lease
                for lease in active.staging_leases
                if lease.path == stale_gc_lease.path
                and lease.stage_name == stale_gc_lease.stage_name
                and lease.role in {"gc-reserved", "gc-exact"}
            )
            if not current_gc:
                continue
            if len(current_gc) != 1:
                raise DistributionApplyError("managed staging cleanup failed")
            gc_lease = current_gc[0]
            record = records.get(gc_lease.path)
            if record is None:
                raise DistributionApplyError("managed staging cleanup failed")
            original_name = gc_lease.gc_predecessor_name or gc_lease.stage_name.rsplit(".", 2)[0]
            sources = tuple(
                lease
                for lease in active.staging_leases
                if lease.path == gc_lease.path and lease.stage_name == original_name
            )
            source_candidates = tuple(lease for lease in sources if lease.role == "stage") or sources
            if not source_candidates and gc_lease.role == "gc-exact" and gc_lease.gc_predecessor_name is not None:
                source_candidates = (gc_lease,)
            backup_sources = _explicit_gc_backup_sources(active, gc_lease)
            if len(backup_sources) > 1:
                raise DistributionApplyError("managed staging cleanup failed")
            backup_source = backup_sources[0] if backup_sources else None
            if (
                not source_candidates
                and gc_lease.gc_ordinal == 2
                and gc_lease.gc_predecessor_name is not None
                and backup_source is not None
            ):
                source_candidates = (backup_source,)
            if len(source_candidates) != 1:
                raise DistributionApplyError("managed staging cleanup failed")
            source = source_candidates[0]
            parallel_predecessor_name = (
                backup_source.stage_name
                if backup_source is not None
                else next(
                    (
                        _distribution_quarantine_backup_name(lease.stage_name)
                        for lease in active.staging_leases
                        if lease.path == gc_lease.path and lease.role == "predecessor-quarantine"
                    ),
                    None,
                )
            )
            successor_gc = next(
                (
                    lease
                    for lease in active.staging_leases
                    if lease.path == gc_lease.path
                    and lease.stage_name != gc_lease.stage_name
                    and lease.role in {"gc-reserved", "gc-exact"}
                    and lease.gc_predecessor_name == gc_lease.stage_name
                    and lease.gc_ordinal is not None
                    and gc_lease.gc_ordinal is not None
                    and lease.gc_ordinal == gc_lease.gc_ordinal + 1
                ),
                None,
            )
            parallel_gc = next(
                (
                    lease
                    for lease in active.staging_leases
                    if lease.path == gc_lease.path
                    and lease.stage_name != gc_lease.stage_name
                    and lease.role in {"gc-reserved", "gc-exact", "backup-only"}
                    and gc_lease.gc_ordinal == 2
                    and lease.gc_ordinal == 3
                    and parallel_predecessor_name is not None
                    and lease.gc_predecessor_name == parallel_predecessor_name
                ),
                None,
            )
            transition_continues = successor_gc is not None or parallel_gc is not None
            parent_chain = _open_distribution_parent_chain(
                self.target_root,
                gc_lease.path,
                create_missing=False,
            )
            try:
                parent_fd = parent_chain[-1]
                target_name = PurePosixPath(gc_lease.path).name

                def validate_gc_authority(
                    bound_record: OperationJournalAction = record,
                    bound_parent_fd: int = parent_fd,
                    bound_target_name: str = target_name,
                    bound_path: str = gc_lease.path,
                ) -> None:
                    _assert_created_parent_bindings_closed_set(self.target_root, active)  # noqa: B023
                    if bound_record.checkpoint == "pending" and bound_record.action in {"create", "adopt"}:
                        condition = bound_record.precondition
                    else:
                        condition = _journal_postcondition(bound_record)
                    if not _entry_matches_journal_condition(
                        bound_parent_fd,
                        bound_target_name,
                        bound_path,
                        condition,
                    ):
                        raise DistributionApplyError("managed staging cleanup failed")

                def validate_gc_mutation(
                    bound_path: str = gc_lease.path,
                    bound_parent_chain: tuple[int, ...] = parent_chain,
                ) -> None:
                    if leaf_mutation_validator is not None:
                        leaf_mutation_validator(bound_path, bound_parent_chain)
                    validate_gc_authority()

                original = _stat_optional_no_follow(parent_fd, original_name)
                quarantined = _stat_optional_no_follow(parent_fd, gc_lease.stage_name)
                successor_info = (
                    _stat_optional_no_follow(parent_fd, successor_gc.stage_name) if successor_gc is not None else None
                )
                parallel_info = (
                    _stat_optional_no_follow(parent_fd, parallel_gc.stage_name) if parallel_gc is not None else None
                )
                backup_info = (
                    _stat_optional_no_follow(parent_fd, backup_source.stage_name) if backup_source is not None else None
                )

                def record_gc(
                    updated: DistributionStageOwnership,
                    bound_path: str = gc_lease.path,
                    bound_parent_chain: tuple[int, ...] = parent_chain,
                ) -> None:
                    nonlocal active
                    active = self.record_staging_lease(active, updated)
                    if leaf_mutation_validator is not None:
                        _assert_visible_distribution_chain_exactly_bound(
                            self.target_root,
                            bound_path,
                            bound_parent_chain,
                        )

                if quarantined is None and (successor_info is not None or parallel_info is not None):
                    continuation_info = successor_info or parallel_info
                    assert continuation_info is not None
                    if (
                        continuation_info.st_dev != gc_lease.device
                        or continuation_info.st_ino != gc_lease.inode
                        or _file_type(continuation_info.st_mode) != gc_lease.file_type
                        or continuation_info.st_nlink not in {1, 2}
                    ):
                        raise DistributionApplyError("managed staging cleanup failed")
                    if (
                        parallel_gc is not None
                        and parallel_info is not None
                        and parallel_gc.role == "gc-exact"
                        and parallel_gc.gc_ordinal == 3
                        and parallel_info.st_nlink == 1
                    ):
                        record_gc(
                            _distribution_stage_ownership(
                                gc_lease.path,
                                parallel_gc.stage_name,
                                parallel_info,
                                role="backup-only",
                                gc_predecessor_name=parallel_gc.gc_predecessor_name,
                                gc_ordinal=parallel_gc.gc_ordinal,
                            )
                        )
                elif quarantined is None and original is not None:
                    if gc_lease.gc_ordinal == 3 and gc_lease.gc_predecessor_name is not None:
                        if (
                            original.st_dev != source.device
                            or original.st_ino != source.inode
                            or _file_type(original.st_mode) != source.file_type
                            or original.st_nlink not in {1, 2}
                        ):
                            raise DistributionApplyError("managed staging cleanup failed")
                        validate_gc_mutation()
                        _rename_distribution_no_replace(
                            parent_fd,
                            original_name,
                            parent_fd,
                            gc_lease.stage_name,
                        )
                        os.fsync(parent_fd)
                        validate_gc_mutation()
                        promoted = os.stat(gc_lease.stage_name, dir_fd=parent_fd, follow_symlinks=False)
                        if (
                            promoted.st_dev != source.device
                            or promoted.st_ino != source.inode
                            or _file_type(promoted.st_mode) != source.file_type
                            or promoted.st_nlink not in {1, 2}
                        ):
                            raise DistributionApplyError("managed staging cleanup failed")
                        record_gc(
                            _distribution_stage_ownership(
                                gc_lease.path,
                                gc_lease.stage_name,
                                promoted,
                                role="gc-exact",
                                gc_predecessor_name=gc_lease.gc_predecessor_name,
                                gc_ordinal=gc_lease.gc_ordinal,
                            )
                        )
                        return self._resume_gc_cleanup(active, leaf_mutation_validator=leaf_mutation_validator)
                    if (
                        original.st_dev != source.device
                        or original.st_ino != source.inode
                        or (gc_lease.role != "gc-reserved" and original.st_ctime_ns != source.ctime_ns)
                        or _file_type(original.st_mode) != source.file_type
                        or original.st_nlink != 1
                    ):
                        raise DistributionApplyError("managed staging cleanup failed")
                    _remove_distribution_stage_if_owned(
                        parent_fd,
                        original_name,
                        original,
                        strict=True,
                        mutation_validator=validate_gc_mutation,
                        post_link_mutation_validator=(
                            validate_gc_mutation if leaf_mutation_validator is not None else None
                        ),
                        gc_path=gc_lease.path,
                        gc_recorder=record_gc,
                        gc_name=gc_lease.stage_name,
                        gc_ordinal=gc_lease.gc_ordinal or 1,
                        gc_predecessor_name=original_name,
                    )
                    quarantined = None
                elif quarantined is not None:
                    if gc_lease.role == "gc-reserved":
                        if (
                            quarantined.st_dev != source.device
                            or quarantined.st_ino != source.inode
                            or _file_type(quarantined.st_mode) != source.file_type
                            or quarantined.st_nlink not in {1, 2}
                        ):
                            raise DistributionApplyError("managed staging cleanup failed")
                        record_gc(
                            DistributionStageOwnership(
                                path=gc_lease.path,
                                stage_name=gc_lease.stage_name,
                                device=quarantined.st_dev,
                                inode=quarantined.st_ino,
                                ctime_ns=quarantined.st_ctime_ns,
                                file_type=("regular" if stat.S_ISREG(quarantined.st_mode) else "symlink"),
                                role="gc-exact",
                                gc_predecessor_name=gc_lease.gc_predecessor_name,
                                gc_ordinal=gc_lease.gc_ordinal,
                            )
                        )
                        gc_lease = next(
                            lease
                            for lease in active.staging_leases
                            if lease.path == gc_lease.path
                            and lease.stage_name == gc_lease.stage_name
                            and lease.role == "gc-exact"
                        )
                    exact_backup_authority = (
                        backup_source is not None
                        and backup_info is not None
                        and backup_info.st_dev == quarantined.st_dev == gc_lease.device
                        and backup_info.st_ino == quarantined.st_ino == gc_lease.inode
                        and _file_type(backup_info.st_mode) == _file_type(quarantined.st_mode) == gc_lease.file_type
                        and backup_info.st_nlink == quarantined.st_nlink == 2
                        and (
                            backup_source.role == "backup-reserved"
                            or (
                                gc_lease.gc_ordinal == 2
                                and gc_lease.gc_predecessor_name is not None
                                and (
                                    parallel_gc is None
                                    or (
                                        parallel_gc.gc_ordinal == 3
                                        and parallel_gc.gc_predecessor_name == backup_source.stage_name
                                    )
                                )
                            )
                            or (
                                backup_info.st_dev == backup_source.device
                                and backup_info.st_ino == backup_source.inode
                                and backup_info.st_ctime_ns == backup_source.ctime_ns
                                and _file_type(backup_info.st_mode) == backup_source.file_type
                            )
                        )
                    )
                    exact_peer_authority = (
                        parallel_gc is not None
                        and parallel_info is not None
                        and original is None
                        and parallel_info.st_dev == quarantined.st_dev == gc_lease.device
                        and parallel_info.st_ino == quarantined.st_ino == gc_lease.inode
                        and _file_type(parallel_info.st_mode) == _file_type(quarantined.st_mode) == gc_lease.file_type
                        and quarantined.st_nlink == 2
                    )
                    exact_terminal_authority = (
                        gc_lease.gc_ordinal == 3
                        and gc_lease.gc_predecessor_name is not None
                        and original is None
                        and quarantined.st_nlink == 1
                        and backup_source is not None
                        and backup_source.role == "backup-dual"
                        and backup_source.device == quarantined.st_dev == gc_lease.device
                        and backup_source.inode == quarantined.st_ino == gc_lease.inode
                        and backup_source.file_type == _file_type(quarantined.st_mode) == gc_lease.file_type
                        and not any(
                            lease.path == gc_lease.path
                            and lease.role in {"gc-reserved", "gc-exact"}
                            and lease.gc_ordinal is not None
                            and lease.gc_ordinal < 3
                            for lease in active.staging_leases
                        )
                    )
                    transition_continues = transition_continues or exact_peer_authority
                    if (
                        quarantined.st_dev != gc_lease.device
                        or quarantined.st_ino != gc_lease.inode
                        or (
                            quarantined.st_ctime_ns != gc_lease.ctime_ns
                            and not exact_backup_authority
                            and not exact_peer_authority
                            and not exact_terminal_authority
                        )
                        or _file_type(quarantined.st_mode) != gc_lease.file_type
                        or quarantined.st_nlink not in {1, 2}
                    ):
                        raise DistributionApplyError("managed staging cleanup failed")
                    if (
                        quarantined.st_nlink == 2
                        and not exact_peer_authority
                        and not exact_backup_authority
                        and (
                            original is None
                            or original.st_dev != quarantined.st_dev
                            or original.st_ino != quarantined.st_ino
                            or original.st_nlink != 2
                        )
                    ):
                        raise DistributionApplyError("managed staging cleanup failed")
                    validate_gc_mutation()
                    verified = os.stat(gc_lease.stage_name, dir_fd=parent_fd, follow_symlinks=False)
                    if _stat_identity_tuple(verified) != _stat_identity_tuple(quarantined):
                        raise DistributionApplyError("managed staging cleanup failed")
                    os.unlink(gc_lease.stage_name, dir_fd=parent_fd)
                    os.fsync(parent_fd)
                    validate_gc_mutation()
                    retained_peer_name = (
                        parallel_gc.stage_name if exact_peer_authority and parallel_gc is not None else None
                    )
                    retained_backup_name = (
                        backup_source.stage_name
                        if exact_backup_authority
                        and backup_source is not None
                        and successor_gc is None
                        and parallel_gc is None
                        else None
                    )
                    if (
                        (original is not None and successor_gc is not None)
                        or retained_peer_name is not None
                        or retained_backup_name is not None
                    ):
                        retained_source_name = retained_peer_name or retained_backup_name or original_name
                        retained_source = os.stat(retained_source_name, dir_fd=parent_fd, follow_symlinks=False)
                        if original is not None and successor_gc is not None:
                            record_gc(
                                replace(
                                    successor_gc,
                                    gc_predecessor_name=original_name,
                                    gc_ordinal=3,
                                )
                            )
                        record_gc(
                            _distribution_stage_ownership(
                                gc_lease.path,
                                retained_source_name,
                                retained_source,
                                role="backup-only",
                                gc_predecessor_name=(
                                    (
                                        parallel_gc.gc_predecessor_name
                                        if retained_peer_name is not None and parallel_gc is not None
                                        else gc_lease.stage_name
                                    )
                                    if retained_peer_name is not None or retained_backup_name is not None
                                    else None
                                ),
                                gc_ordinal=(
                                    (
                                        parallel_gc.gc_ordinal
                                        if retained_peer_name is not None and parallel_gc is not None
                                        else 3
                                    )
                                    if retained_peer_name is not None or retained_backup_name is not None
                                    else None
                                ),
                            )
                        )
                        transition_continues = True
                    validate_gc_mutation()
                    if original is not None and successor_gc is None:
                        retained_source = os.stat(original_name, dir_fd=parent_fd, follow_symlinks=False)
                        if (
                            retained_source.st_dev != quarantined.st_dev
                            or retained_source.st_ino != quarantined.st_ino
                            or retained_source.st_nlink != 1
                        ):
                            raise DistributionApplyError("managed staging cleanup failed")
                        os.unlink(original_name, dir_fd=parent_fd)
                        os.fsync(parent_fd)
                        validate_gc_mutation()
            finally:
                _close_distribution_parent_chain(parent_chain)
            completed_quarantines = {
                lease.stage_name
                for lease in active.staging_leases
                if lease.path == gc_lease.path
                and lease.role == "predecessor-quarantine"
                and _distribution_quarantine_backup_name(lease.stage_name) == original_name
            }
            if not transition_continues and source.role == "backup-only" and len(completed_quarantines) != 1:
                raise DistributionApplyError("managed staging cleanup failed")
            retained = tuple(
                lease
                for lease in active.staging_leases
                if not (
                    lease.path == gc_lease.path
                    and (
                        (
                            not transition_continues
                            and lease.role
                            in {
                                "gc-reserved",
                                "gc-exact",
                                "backup-reserved",
                                "backup-dual",
                                "backup-only-reserved",
                                "backup-only",
                            }
                        )
                        or (
                            transition_continues
                            and lease.stage_name == gc_lease.stage_name
                            and lease.role in {"gc-reserved", "gc-exact"}
                        )
                        or lease.stage_name == gc_lease.stage_name
                        or (not transition_continues and lease.stage_name == original_name)
                        or (not transition_continues and lease.stage_name in completed_quarantines)
                    )
                )
            )
            active = self.write(replace(active, staging_leases=retained), predecessor=active)
        return active

    def _promote_roleless_backup_leases(
        self,
        journal: OperationJournal,
        *,
        leaf_mutation_validator: Callable[[str, tuple[int, ...]], None] | None = None,
    ) -> OperationJournal:
        """Upgrade prior roleless backup records only from their exact namespace state."""

        active = journal
        records = {record.path: record for record in active.actions}
        quarantine_leases = tuple(lease for lease in active.staging_leases if lease.role == "predecessor-quarantine")
        for quarantine in quarantine_leases:
            backup_name = _distribution_quarantine_backup_name(quarantine.stage_name)
            roleless = tuple(
                lease
                for lease in active.staging_leases
                if lease.path == quarantine.path and lease.role == "stage" and lease.stage_name == backup_name
            )
            explicit_backups = tuple(
                lease
                for lease in active.staging_leases
                if lease.path == quarantine.path
                and lease.stage_name == backup_name
                and lease.role in {"backup-reserved", "backup-dual", "backup-only-reserved", "backup-only"}
            )
            if explicit_backups:
                continue
            if len(roleless) > 1:
                raise DistributionApplyError("managed staging cleanup failed")
            # 55796 serialized the recovery inode only once under the
            # roleless ``.remove`` name.  Its derived backup pathname was not
            # separately journaled, so the parser exposes only the inferred
            # predecessor role.  Later role-aware recovery may promote that
            # exact inode only after proving the derived backup namespace.
            legacy = roleless[0] if roleless else quarantine
            record = records.get(quarantine.path)
            if record is None or record.action not in {"upgrade", "prune"}:
                if not roleless:
                    continue
                raise DistributionApplyError("managed staging cleanup failed")
            parent_chain = _open_distribution_parent_chain(
                self.target_root,
                quarantine.path,
                create_missing=False,
            )
            try:
                parent_fd = parent_chain[-1]
                backup = _stat_optional_no_follow(parent_fd, backup_name)
                visible_quarantine = _stat_optional_no_follow(parent_fd, quarantine.stage_name)
                if backup is None and not roleless:
                    continue
                if (
                    backup is None
                    or backup.st_dev != legacy.device
                    or backup.st_ino != legacy.inode
                    or (backup.st_ctime_ns != legacy.ctime_ns and bool(roleless))
                    or _file_type(backup.st_mode) != legacy.file_type
                ):
                    raise DistributionApplyError("managed staging cleanup failed")
                backup_identity = _distribution_stage_identity(
                    parent_fd,
                    backup_name,
                    quarantine.path,
                    allow_backup_link=visible_quarantine is not None,
                )
                if record.precondition.get("identity") != _distribution_identity_payload(backup_identity):
                    raise DistributionApplyError("managed staging cleanup failed")
                if visible_quarantine is None:
                    if backup.st_nlink != 1:
                        raise DistributionApplyError("managed staging cleanup failed")
                    role: Literal["backup-dual", "backup-only"] = "backup-only"
                else:
                    if (
                        backup.st_nlink != 2
                        or visible_quarantine.st_dev != backup.st_dev
                        or visible_quarantine.st_ino != backup.st_ino
                        or visible_quarantine.st_nlink != 2
                    ):
                        raise DistributionApplyError("managed staging cleanup failed")
                    role = "backup-dual"
                promoted = DistributionStageOwnership(
                    path=quarantine.path,
                    stage_name=backup_name,
                    device=backup.st_dev,
                    inode=backup.st_ino,
                    ctime_ns=backup.st_ctime_ns,
                    file_type=quarantine.file_type,
                    role=role,
                )
                if _is_destructive_intent(journal.intent):
                    if leaf_mutation_validator is None:
                        raise DistributionApplyError("journal-precondition-mismatch")
                    leaf_mutation_validator(quarantine.path, parent_chain)
            finally:
                _close_distribution_parent_chain(parent_chain)
            retained = tuple(item for item in active.staging_leases if not roleless or item is not legacy)
            active = self.write(
                replace(active, staging_leases=(*retained, promoted)),
                predecessor=active,
            )
        return active

    def record_staging_lease(
        self,
        journal: OperationJournal,
        lease: DistributionStageOwnership,
    ) -> OperationJournal:
        if _is_destructive_intent(journal.intent):
            _assert_deprovision_recovery_marker_bound(self, self._forward_guard)
            self._assert_destructive_recovery_metadata_bound(journal.root_identity)
        # A retry re-emits the durable zero lease before its no-replace rename.
        # Do not rewrite the journal/forward guard in that window.
        if (
            lease.role == "predecessor-quarantine"
            and lease.device == lease.inode == lease.ctime_ns == 0
            and lease in journal.staging_leases
        ):
            return journal
        backup_roles = {
            "backup-reserved",
            "backup-dual",
            "backup-only-reserved",
            "backup-only",
        }
        gc_roles = {"gc-reserved", "gc-exact"}
        if lease.role == "predecessor-quarantine":
            retained = tuple(
                item
                for item in journal.staging_leases
                if not (item.path == lease.path and item.role == "predecessor-quarantine")
            )
        elif lease.role in backup_roles:
            retained = tuple(
                item
                for item in journal.staging_leases
                if not (
                    item.path == lease.path
                    and (
                        (
                            item.role in backup_roles
                            and (
                                lease.role in {"backup-only", "backup-reserved", "backup-dual"}
                                or item.role == lease.role
                            )
                        )
                        or (
                            lease.role == "backup-only"
                            and item.role in gc_roles
                            and item.stage_name == lease.stage_name
                        )
                    )
                )
            )
        elif lease.role in gc_roles:
            retained = tuple(
                item
                for item in journal.staging_leases
                if not (item.path == lease.path and item.stage_name == lease.stage_name and item.role in gc_roles)
            )
        else:
            retained = tuple(item for item in journal.staging_leases if item.path != lease.path or item.role != "stage")
        return self.write(replace(journal, staging_leases=(*retained, lease)), predecessor=journal)

    def record_created_parent_bindings(
        self,
        journal: OperationJournal,
        bindings: tuple[PathIdentitySnapshot, ...],
    ) -> OperationJournal:
        existing = {binding.relative_path: binding for binding in journal.created_parent_bindings}
        for binding in bindings:
            current = existing.get(binding.relative_path)
            if current is not None and current.exists and not _same_structure_identity(current, binding):
                raise DistributionApplyError("journal-precondition-mismatch")
            existing[binding.relative_path] = binding
        ordered = tuple(existing[path] for path in sorted(existing))
        return self.write(replace(journal, created_parent_bindings=ordered), predecessor=journal)

    def mark_verified(self, journal: OperationJournal) -> OperationJournal:
        if _is_destructive_intent(journal.intent):
            _assert_deprovision_recovery_marker_bound(self, self._forward_guard)
            self._assert_destructive_recovery_metadata_bound(journal.root_identity)
        if (
            journal.staging_leases
            or any(action.checkpoint == "pending" for action in journal.actions)
            or any(not binding.exists for binding in journal.created_parent_bindings)
        ):
            raise DistributionApplyError("journal-precondition-mismatch")
        self._assert_published_successor_postconditions(journal)
        if _is_destructive_intent(journal.intent):
            if journal.status not in {"executing", "verifying"} or any(
                action.checkpoint != "published" for action in journal.actions
            ):
                raise DistributionApplyError("journal-precondition-mismatch")
            return self.write(replace(journal, status="verifying"), predecessor=journal)
        actions = tuple(replace(action, checkpoint="verified") for action in journal.actions)
        return self.write(replace(journal, status="verifying", actions=actions), predecessor=journal)

    def mark_completed(self, journal: OperationJournal) -> OperationJournal:
        if _is_destructive_intent(journal.intent):
            _assert_deprovision_recovery_marker_bound(self, self._forward_guard)
            self._assert_destructive_recovery_metadata_bound(journal.root_identity)
        if _is_destructive_intent(journal.intent):
            if (
                journal.status != "verifying"
                or journal.staging_leases
                or any(action.checkpoint != "published" for action in journal.actions)
            ):
                raise DistributionApplyError("journal-precondition-mismatch")
            self._assert_published_successor_postconditions(journal)
            actions = tuple(replace(action, checkpoint="verified") for action in journal.actions)
            return self.write(
                replace(journal, status="completed", actions=actions),
                predecessor=journal,
            )
        if journal.staging_leases or any(action.checkpoint != "verified" for action in journal.actions):
            raise DistributionApplyError("journal-precondition-mismatch")
        self._assert_published_successor_postconditions(journal)
        return self.write(replace(journal, status="completed"), predecessor=journal)

    def _assert_published_successor_postconditions(self, journal: OperationJournal) -> None:
        for record in journal.actions:
            if record.action not in {"create", "upgrade"} or record.checkpoint == "pending":
                continue
            condition = _journal_postcondition(record)
            if any(field not in condition for field in ("device", "inode", "ctime_ns", "link_count")):
                raise DistributionApplyError("journal-protocol-incompatible")
            parent_chain = _open_distribution_parent_chain(
                self.target_root,
                record.path,
                create_missing=False,
            )
            try:
                if not _entry_matches_journal_condition(
                    parent_chain[-1],
                    PurePosixPath(record.path).name,
                    record.path,
                    condition,
                ):
                    raise DistributionApplyError("journal-precondition-mismatch")
            finally:
                _close_distribution_parent_chain(parent_chain)

    def remove_completed(self, journal: OperationJournal, *, guard_already_removed: bool = False) -> None:
        if (
            journal.status != "completed"
            or journal.staging_leases
            or any(action.checkpoint != "verified" for action in journal.actions)
        ):
            raise DistributionApplyError("journal-precondition-mismatch")
        if _is_destructive_intent(journal.intent):
            self._assert_destructive_recovery_metadata_bound(journal.root_identity)
        self._remove_exact(
            journal,
            failure_reason="journal finalization failed",
            require_guard=not guard_already_removed,
        )

    def discard_prepared(self, journal: OperationJournal) -> None:
        """Roll back a journal that has not acquired leases or mutation progress."""

        if (
            journal.status != "prepared"
            or journal.staging_leases
            or any(action.checkpoint != "pending" for action in journal.actions)
        ):
            raise DistributionApplyError("journal-precondition-mismatch")
        self._remove_exact(journal, failure_reason="journal rollback failed")

    def _remove_exact(
        self,
        journal: OperationJournal,
        *,
        failure_reason: str,
        require_guard: bool = True,
    ) -> None:
        destructive_recovery = _is_destructive_intent(journal.intent)
        if destructive_recovery:
            self._assert_destructive_recovery_metadata_bound(journal.root_identity)
        root_fd, parent_fd = self._open_parent(journal.root_identity, self._workspace_condition(journal))
        guard_fd: int | None = None
        try:
            if require_guard:
                guard_fd = self._open_bound_forward_guard(parent_fd)
            name = _DISTRIBUTION_JOURNAL_REL.name
            try:
                info = os.stat(name, dir_fd=parent_fd, follow_symlinks=False)
            except FileNotFoundError:
                return
            if not stat.S_ISREG(info.st_mode) or info.st_nlink != 1:
                raise DistributionApplyError("journal-protocol-incompatible")
            expected_snapshot = journal.source_snapshot
            expected_sha256 = journal.source_sha256
            if expected_snapshot is None or expected_sha256 is None or not _same_stat_identity(info, expected_snapshot):
                raise DistributionApplyError("journal-precondition-mismatch")

            def pre_delete_check() -> None:
                if require_guard:
                    self._assert_bound_forward_guard(parent_fd, guard_fd)
                if destructive_recovery:
                    self._assert_destructive_recovery_metadata_bound(journal.root_identity)

            self._quarantine_and_remove(
                parent_fd,
                name,
                info,
                expected_snapshot=expected_snapshot,
                expected_sha256=expected_sha256,
                pre_delete_check=(pre_delete_check if require_guard or destructive_recovery else None),
                identity_error="journal-precondition-mismatch",
                failure_reason=failure_reason,
            )
        finally:
            if guard_fd is not None:
                os.close(guard_fd)
            os.close(parent_fd)
            os.close(root_fd)

    def _quarantine_and_remove(
        self,
        parent_fd: int,
        name: str,
        expected: os.stat_result,
        *,
        expected_snapshot: PathIdentitySnapshot,
        expected_sha256: str,
        pre_delete_check: Callable[[], None] | None = None,
        identity_error: str,
        failure_reason: str,
    ) -> None:
        """Move a bound regular file aside before deleting its exact identity."""

        identity_token = hashlib.sha256(
            f"{expected.st_dev}:{expected.st_ino}:{expected.st_ctime_ns}".encode()
        ).hexdigest()[:16]
        token = f"{identity_token}-{secrets.token_hex(16)}"
        quarantine = f".{name}.{token}.remove"
        nofollow = getattr(os, "O_NOFOLLOW", None)
        if not isinstance(nofollow, int):
            raise DistributionApplyError("platform lacks required no-follow file support")
        try:
            held_fd = os.open(
                name,
                os.O_RDONLY | nofollow | getattr(os, "O_CLOEXEC", 0),
                dir_fd=parent_fd,
            )
        except OSError as exc:
            raise DistributionApplyError(identity_error) from exc
        raw: bytes | None = None
        held_before: os.stat_result | None = None
        try:
            try:
                held_before = os.fstat(held_fd)
                if (
                    held_before.st_dev,
                    held_before.st_ino,
                    held_before.st_ctime_ns,
                    held_before.st_mode,
                    held_before.st_nlink,
                ) != (
                    expected.st_dev,
                    expected.st_ino,
                    expected.st_ctime_ns,
                    expected.st_mode,
                    expected.st_nlink,
                ) or not _same_stat_identity(held_before, expected_snapshot):
                    raise DistributionApplyError(identity_error)
                raw = _read_fd_bytes(held_fd)
                if hashlib.sha256(raw).hexdigest() != expected_sha256 or _stat_identity_tuple(
                    os.fstat(held_fd)
                ) != _stat_identity_tuple(held_before):
                    raise DistributionApplyError(identity_error)
                _rename_distribution_no_replace(parent_fd, name, parent_fd, quarantine)
            except OSError as exc:
                raise DistributionApplyError(failure_reason) from exc
            try:
                moved = os.stat(quarantine, dir_fd=parent_fd, follow_symlinks=False)
                held_after = os.fstat(held_fd)
            except OSError as exc:
                raise DistributionApplyError(failure_reason) from exc
            moved_identity = (
                moved.st_dev,
                moved.st_ino,
                moved.st_ctime_ns,
                moved.st_mode,
                moved.st_nlink,
            )
            held_identity = (
                held_after.st_dev,
                held_after.st_ino,
                held_after.st_ctime_ns,
                held_after.st_mode,
                held_after.st_nlink,
            )
            if moved_identity != held_identity:
                self._restore_quarantined_entry(
                    parent_fd,
                    name,
                    quarantine,
                    held_fd,
                    identity_error=identity_error,
                    failure_reason=failure_reason,
                    require_held_identity=False,
                )
                raise DistributionApplyError(identity_error)
            try:
                # Persist the name transition before the destructive step.  A
                # later cleanup failure can then restore the still-linked exact
                # inode instead of losing the canonical recovery authority.
                os.fsync(parent_fd)
                if pre_delete_check is not None:
                    pre_delete_check()
                _remove_distribution_stage_if_owned(
                    parent_fd,
                    quarantine,
                    moved,
                    strict=True,
                    mutation_validator=pre_delete_check,
                )
                if pre_delete_check is not None:
                    pre_delete_check()
            except (DistributionApplyError, OSError) as exc:
                manual_state = exc.recovery_metadata_state if isinstance(exc, DistributionApplyError) else None
                if (
                    manual_state is None
                    and isinstance(exc, DistributionApplyError)
                    and str(exc)
                    in {
                        "dual-recovery-state",
                        "legacy-marker-unconvertible",
                        "legacy-marker-invalid",
                    }
                ):
                    manual_state = str(exc)
                try:
                    if raw is None or held_before is None:
                        raise DistributionApplyError(failure_reason)
                    recovery_outcome = self._recover_quarantined_recovery_entry(
                        parent_fd,
                        name,
                        quarantine,
                        held_fd,
                        raw,
                        held_before,
                        expected_sha256=expected_sha256,
                        failure_reason=failure_reason,
                        pre_delete_check=pre_delete_check,
                    )
                except (DistributionApplyError, OSError) as recovery_exc:
                    recovery_state = (
                        recovery_exc.recovery_metadata_state
                        if isinstance(recovery_exc, DistributionApplyError)
                        else None
                    )
                    if (
                        recovery_state is None
                        and isinstance(recovery_exc, DistributionApplyError)
                        and str(recovery_exc)
                        in {
                            "dual-recovery-state",
                            "legacy-marker-unconvertible",
                            "legacy-marker-invalid",
                        }
                    ):
                        recovery_state = str(recovery_exc)
                    raise DistributionApplyError(
                        failure_reason,
                        recovery_metadata_state=manual_state or recovery_state or "dual-recovery-state",
                    ) from recovery_exc
                if recovery_outcome == "manual-conflict" and manual_state is None:
                    manual_state = "quarantine-preserved"
                raise DistributionApplyError(
                    failure_reason,
                    recovery_metadata_state=manual_state,
                ) from exc
        finally:
            os.close(held_fd)

    def _recover_quarantined_recovery_entry(
        self,
        parent_fd: int,
        name: str,
        quarantine: str,
        held_fd: int,
        raw: bytes,
        expected: os.stat_result,
        *,
        expected_sha256: str,
        failure_reason: str,
        pre_delete_check: Callable[[], None] | None,
    ) -> Literal["canonical-restored", "manual-conflict"]:
        """Recover a quarantined entry from the observed namespace state."""

        held = os.fstat(held_fd)
        expected_mode = stat.S_IMODE(expected.st_mode)
        if (
            not stat.S_ISREG(held.st_mode)
            or held.st_dev != expected.st_dev
            or held.st_ino != expected.st_ino
            or stat.S_IMODE(held.st_mode) != expected_mode
            or held.st_size != len(raw)
            or hashlib.sha256(raw).hexdigest() != expected_sha256
            or not _held_fd_has_exact_bytes(held_fd, raw)
        ):
            raise DistributionApplyError(failure_reason)
        if pre_delete_check is not None:
            pre_delete_check()

        def is_exact(info: os.stat_result | None) -> bool:
            return (
                info is not None
                and stat.S_ISREG(info.st_mode)
                and info.st_dev == held.st_dev
                and info.st_ino == held.st_ino
                and info.st_ctime_ns == held.st_ctime_ns
                and info.st_mode == held.st_mode
                and info.st_nlink == held.st_nlink
            )

        def publish_private() -> None:
            private_name = f".{name}.{secrets.token_hex(16)}.restore"
            self._publish_exact_recovery_bytes_no_replace(
                parent_fd,
                private_name,
                held_fd,
                raw,
                expected,
                expected_sha256=expected_sha256,
                failure_reason=failure_reason,
            )

        def publish_canonical_or_private() -> bool:
            try:
                self._publish_exact_recovery_bytes_no_replace(
                    parent_fd,
                    name,
                    held_fd,
                    raw,
                    expected,
                    expected_sha256=expected_sha256,
                    failure_reason=failure_reason,
                )
            except (DistributionApplyError, OSError):
                publish_private()
                return False
            return True

        canonical = _stat_optional_no_follow(parent_fd, name)
        quarantined = _stat_optional_no_follow(parent_fd, quarantine)
        if is_exact(canonical):
            if quarantined is None:
                return "canonical-restored"
            if is_exact(quarantined):
                return "manual-conflict"
            return "manual-conflict"

        if canonical is None and is_exact(quarantined) and held.st_nlink == expected.st_nlink:
            try:
                self._restore_quarantined_entry(
                    parent_fd,
                    name,
                    quarantine,
                    held_fd,
                    identity_error=failure_reason,
                    failure_reason=failure_reason,
                    require_held_identity=True,
                )
                held = os.fstat(held_fd)
                restored = os.stat(name, dir_fd=parent_fd, follow_symlinks=False)
                if not is_exact(restored) or _stat_optional_no_follow(parent_fd, quarantine) is not None:
                    raise DistributionApplyError(failure_reason)
                return "canonical-restored"
            except (DistributionApplyError, OSError):
                canonical = _stat_optional_no_follow(parent_fd, name)
                quarantined = _stat_optional_no_follow(parent_fd, quarantine)
                if is_exact(canonical):
                    if quarantined is None:
                        return "canonical-restored"
                    if is_exact(quarantined):
                        return "manual-conflict"
                    return "manual-conflict"
                if canonical is None and is_exact(quarantined):
                    return "manual-conflict"

        if canonical is None and is_exact(quarantined):
            return "manual-conflict"

        if canonical is None:
            if quarantined is None and held.st_nlink == 0:
                if not publish_canonical_or_private():
                    return "manual-conflict"
                if _stat_optional_no_follow(parent_fd, name) is not None:
                    return "canonical-restored"
                raise DistributionApplyError(failure_reason)
            if quarantined is not None:
                if not publish_canonical_or_private():
                    return "manual-conflict"
                canonical = _stat_optional_no_follow(parent_fd, name)
                if canonical is not None:
                    return "manual-conflict"
            publish_private()
            return "manual-conflict"

        publish_private()
        return "manual-conflict"

    @staticmethod
    def _publish_exact_recovery_bytes_no_replace(
        parent_fd: int,
        destination: str,
        held_fd: int,
        raw: bytes,
        expected: os.stat_result,
        *,
        expected_sha256: str,
        failure_reason: str,
    ) -> None:
        """Publish exact held recovery bytes without replacing any pathname."""

        nofollow = getattr(os, "O_NOFOLLOW", None)
        if not isinstance(nofollow, int):
            raise DistributionApplyError("platform lacks required no-follow file support")
        expected_mode = stat.S_IMODE(expected.st_mode)
        held = os.fstat(held_fd)
        if (
            not stat.S_ISREG(held.st_mode)
            or held.st_dev != expected.st_dev
            or held.st_ino != expected.st_ino
            or stat.S_IMODE(held.st_mode) != expected_mode
            or held.st_size != len(raw)
            or hashlib.sha256(raw).hexdigest() != expected_sha256
            or not _held_fd_has_exact_bytes(held_fd, raw)
        ):
            raise DistributionApplyError(failure_reason)
        try:
            os.stat(destination, dir_fd=parent_fd, follow_symlinks=False)
        except FileNotFoundError:
            pass
        except OSError as exc:
            raise DistributionApplyError(failure_reason) from exc
        else:
            raise FileExistsError(errno.EEXIST, os.strerror(errno.EEXIST), destination)

        stage = f".{destination}.{secrets.token_hex(16)}.restore"
        stage_fd: int | None = None
        stage_info: os.stat_result | None = None
        try:
            try:
                stage_fd = os.open(
                    stage,
                    os.O_RDWR | os.O_CREAT | os.O_EXCL | nofollow | getattr(os, "O_CLOEXEC", 0),
                    expected_mode,
                    dir_fd=parent_fd,
                )
                _write_fd_bytes(stage_fd, raw)
                os.fchmod(stage_fd, expected_mode)
                stage_info = os.fstat(stage_fd)
                visible_stage = os.stat(stage, dir_fd=parent_fd, follow_symlinks=False)
            except OSError as exc:
                raise DistributionApplyError(failure_reason) from exc
            if (
                not stat.S_ISREG(stage_info.st_mode)
                or stage_info.st_nlink != 1
                or stat.S_IMODE(stage_info.st_mode) != expected_mode
                or visible_stage.st_dev != stage_info.st_dev
                or visible_stage.st_ino != stage_info.st_ino
                or visible_stage.st_nlink != 1
                or stat.S_IMODE(visible_stage.st_mode) != expected_mode
                or not _held_fd_has_exact_bytes(stage_fd, raw)
            ):
                raise DistributionApplyError(failure_reason)
            _rename_distribution_no_replace(parent_fd, stage, parent_fd, destination)
            os.fsync(parent_fd)
            try:
                published = os.stat(destination, dir_fd=parent_fd, follow_symlinks=False)
                published_fd = os.open(
                    destination,
                    os.O_RDONLY | nofollow | getattr(os, "O_CLOEXEC", 0),
                    dir_fd=parent_fd,
                )
            except OSError as exc:
                raise DistributionApplyError(failure_reason) from exc
            try:
                assert stage_fd is not None
                opened = os.fstat(published_fd)
                held_after_publish = os.fstat(stage_fd)
                if (
                    not stat.S_ISREG(published.st_mode)
                    or published.st_nlink != 1
                    or stat.S_IMODE(published.st_mode) != expected_mode
                    or not stat.S_ISREG(held_after_publish.st_mode)
                    or held_after_publish.st_nlink != 1
                    or stat.S_IMODE(held_after_publish.st_mode) != expected_mode
                    or _stat_identity_tuple(opened) != _stat_identity_tuple(published)
                    or _stat_identity_tuple(held_after_publish) != _stat_identity_tuple(opened)
                    or not _held_fd_has_exact_bytes(published_fd, raw)
                ):
                    raise DistributionApplyError(failure_reason)
                opened_after = os.fstat(published_fd)
                held_after_validation = os.fstat(stage_fd)
                published_after = os.stat(destination, dir_fd=parent_fd, follow_symlinks=False)
                validated_identity = _stat_identity_tuple(opened_after)
                if (
                    _stat_identity_tuple(opened) != validated_identity
                    or _stat_identity_tuple(held_after_validation) != validated_identity
                    or _stat_identity_tuple(published_after) != validated_identity
                ):
                    raise DistributionApplyError(failure_reason)
            except OSError as exc:
                raise DistributionApplyError(failure_reason) from exc
            finally:
                os.close(published_fd)
            if _stat_optional_no_follow(parent_fd, stage) is not None:
                raise DistributionApplyError(failure_reason)
        finally:
            if stage_fd is not None:
                os.close(stage_fd)
            if stage_info is not None:
                with suppress(OSError):
                    residual = os.stat(stage, dir_fd=parent_fd, follow_symlinks=False)
                    if _stat_identity_tuple(residual) == _stat_identity_tuple(stage_info):
                        os.unlink(stage, dir_fd=parent_fd)
                        os.fsync(parent_fd)

    @staticmethod
    def _restore_quarantined_entry(
        parent_fd: int,
        name: str,
        quarantine: str,
        held_fd: int,
        *,
        identity_error: str,
        failure_reason: str,
        require_held_identity: bool,
    ) -> None:
        """Restore the held recovery entry after a post-rename failure."""

        try:
            quarantined = os.stat(quarantine, dir_fd=parent_fd, follow_symlinks=False)
            held = os.fstat(held_fd)
        except OSError as exc:
            raise DistributionApplyError(failure_reason) from exc
        if require_held_identity and (
            quarantined.st_dev,
            quarantined.st_ino,
            quarantined.st_ctime_ns,
            quarantined.st_mode,
            quarantined.st_nlink,
        ) != (
            held.st_dev,
            held.st_ino,
            held.st_ctime_ns,
            held.st_mode,
            held.st_nlink,
        ):
            raise DistributionApplyError(identity_error)
        try:
            _rename_distribution_no_replace(parent_fd, quarantine, parent_fd, name)
            os.fsync(parent_fd)
        except OSError as exc:
            raise DistributionApplyError(failure_reason) from exc

    def remove_legacy_marker(self, marker: DistributionRetryMarker) -> None:
        if marker.target_root != _root_identity_for_assessment(self.target_root):
            raise DistributionApplyError("journal-root-mismatch")
        destructive_recovery = _is_destructive_intent(marker.operation)
        if destructive_recovery:
            self._assert_destructive_recovery_metadata_bound(marker.target_root)
        if (
            marker.purpose
            in {
                _DISTRIBUTION_JOURNAL_GUARD_PURPOSE,
                _DISTRIBUTION_FRESH_JOURNAL_GUARD_PURPOSE,
            }
            or marker.purpose == _DISTRIBUTION_DEPROVISION_JOURNAL_GUARD_PURPOSE
        ):
            self._assert_current_forward_guard(marker)
        else:
            current = _read_distribution_retry_marker(self.target_root)
            if current != marker:
                raise DistributionApplyError("legacy-marker-unconvertible")
        root_fd, parent_fd = self._open_parent(marker.target_root)
        try:
            name = _DISTRIBUTION_RETRY_MARKER_REL.name
            try:
                info = os.stat(name, dir_fd=parent_fd, follow_symlinks=False)
            except OSError as exc:
                raise DistributionApplyError("legacy-marker-unconvertible") from exc
            if not stat.S_ISREG(info.st_mode) or info.st_nlink != 1:
                raise DistributionApplyError("legacy-marker-unconvertible")
            expected_snapshot = marker.source_snapshot
            expected_sha256 = marker.source_sha256
            if expected_snapshot is None or expected_sha256 is None or not _same_stat_identity(info, expected_snapshot):
                raise DistributionApplyError("legacy-marker-unconvertible")

            def pre_delete_check() -> None:
                if destructive_recovery:
                    self._assert_destructive_recovery_metadata_bound(marker.target_root)

            self._quarantine_and_remove(
                parent_fd,
                name,
                info,
                expected_snapshot=expected_snapshot,
                expected_sha256=expected_sha256,
                pre_delete_check=pre_delete_check if destructive_recovery else None,
                identity_error="legacy-marker-unconvertible",
                failure_reason="legacy-marker-unconvertible",
            )
        finally:
            os.close(parent_fd)
            os.close(root_fd)


def _generated_regular_asset(
    path: str,
    content: bytes,
    *,
    mode: int,
    refreshable_existing_identities: tuple[DistributionIdentity, ...] | None = None,
) -> DistributionAsset:
    return DistributionAsset(
        path=path,
        identity=DistributionIdentity(
            kind="regular",
            sha256=hashlib.sha256(content).hexdigest(),
            mode=mode,
        ),
        generated_content=content,
        refreshable_existing_identities=refreshable_existing_identities,
    )


def _journal_digest(
    journal: OperationJournal,
    *,
    legacy_create_upgrade_fixed_link_count: bool = False,
) -> str:
    payload: dict[str, object] = {
        "schema_version": (
            _DISTRIBUTION_FRESH_JOURNAL_SCHEMA_VERSION
            if journal.intent == "fresh"
            else _DISTRIBUTION_JOURNAL_SCHEMA_VERSION
        ),
        "intent": journal.intent,
        "root_binding": {
            "device": journal.root_identity.device,
            "inode": journal.root_identity.inode,
        },
        "contract_identity": journal.contract_identity,
        "actions": [
            {
                "path": action.path,
                "action": action.action,
                "provenance": action.provenance,
                "reason": action.reason,
                "precondition": _plan_digest_condition(action.precondition),
                "postcondition": _plan_digest_condition(
                    _journal_digest_postcondition(
                        action,
                        legacy_create_upgrade_fixed_link_count=legacy_create_upgrade_fixed_link_count,
                    )
                ),
            }
            for action in journal.actions
        ],
    }
    if journal.intent == "fresh":
        required_directories: list[str] = []
        for action in journal.actions:
            identity = action.postcondition.get("identity")
            if (
                action.postcondition.get("file_type") == "directory"
                and isinstance(identity, dict)
                and identity.get("kind") == "directory"
            ):
                required_directories.append(action.path)
        payload["required_directories"] = required_directories
    encoded = json.dumps(payload, sort_keys=True, separators=(",", ":")).encode("utf-8")
    return hashlib.sha256(encoded).hexdigest()


def _journal_digest_postcondition(
    action: OperationJournalAction,
    *,
    legacy_create_upgrade_fixed_link_count: bool = False,
) -> dict[str, object]:
    """Exclude runtime successor identity from the canonical plan digest."""

    condition = action.postcondition
    if action.action not in {"create", "upgrade"} or condition.get("file_type") == "directory":
        return condition
    normalized = {
        key: value for key, value in condition.items() if key not in {"device", "inode", "ctime_ns", "link_count"}
    }
    if legacy_create_upgrade_fixed_link_count:
        normalized["link_count"] = 1
    return normalized


def _is_legacy_adopt_postcondition(record: OperationJournalAction) -> bool:
    condition = record.postcondition
    return (
        record.action == "adopt"
        and condition.get("exists") is True
        and condition.get("file_type") != "directory"
        and not {"device", "inode", "ctime_ns"}.intersection(condition)
        and set(condition) == {"root", "parents", "exists", "file_type", "link_count", "identity"}
        and all(field in record.precondition for field in ("device", "inode", "ctime_ns", "link_count"))
    )


def _is_legacy_successor_postcondition(record: OperationJournalAction) -> bool:
    condition = record.postcondition
    return (
        record.checkpoint != "pending"
        and record.action in {"create", "upgrade"}
        and condition.get("exists") is True
        and condition.get("file_type") in {"regular", "symlink"}
        and not {"device", "inode", "ctime_ns"}.intersection(condition)
        and set(condition) == {"root", "parents", "exists", "file_type", "link_count", "identity"}
        and condition.get("link_count") == 1
    )


def _is_fresh_workbench_seed_create(
    journal: OperationJournal,
    record: OperationJournalAction,
) -> bool:
    return (
        journal.intent == "fresh"
        and journal.protocol_version == _DISTRIBUTION_JOURNAL_PROTOCOL_VERSION
        and record.path == "spec-dock/.workbench/README.md"
        and record.action == "create"
        and record.provenance == "missing"
        and record.reason == "target-missing"
    )


def _fresh_workbench_seed_recovery_postcondition(
    snapshot: DistributionTargetSnapshot,
    journal: OperationJournal,
    record: OperationJournalAction,
) -> dict[str, object]:
    """Bind an externally appeared fresh seed to its observed node identity."""

    condition = _journal_postcondition(record)
    if not _is_fresh_workbench_seed_create(journal, record) or record.checkpoint != "pending":
        return condition
    structural_fields = {"device", "inode", "ctime_ns"}
    present_fields = structural_fields.intersection(condition)
    if present_fields:
        if present_fields != structural_fields:
            raise DistributionApplyError("journal-precondition-mismatch")
        return condition
    target = snapshot.target
    if not target.exists:
        return condition
    if target.file_type != "regular" or any(
        getattr(target, field) is None for field in ("device", "inode", "ctime_ns", "link_count")
    ):
        raise DistributionApplyError("journal-precondition-mismatch")
    return {
        **condition,
        "device": target.device,
        "inode": target.inode,
        "ctime_ns": target.ctime_ns,
        "link_count": target.link_count,
    }


def _journal_postcondition(record: OperationJournalAction) -> dict[str, object]:
    """Return a validated postcondition view across protocol-1 revisions.

    Protocol 1 journals written before Issue 369's structural-identity
    strengthening contain a non-directory ``adopt`` postcondition without
    device/inode/ctime.  The precondition was already required to capture the
    complete structural identity, so derive all structural fields from that
    immutable witness.  This covers both the original fixed-link-count
    serializer and the intermediate symlink serializer without weakening
    replacement detection.  Malformed or partially expanded shapes are
    returned unchanged and remain fail-closed in the normal contract validator.
    """

    condition = record.postcondition
    if not _is_legacy_adopt_postcondition(record):
        return condition
    precondition = record.precondition
    required = ("device", "inode", "ctime_ns", "link_count")
    if any(field not in precondition for field in required):
        return condition
    return {
        **condition,
        "device": precondition["device"],
        "inode": precondition["inode"],
        "ctime_ns": precondition["ctime_ns"],
        "link_count": precondition["link_count"],
    }


def _snapshot_matches_condition(
    snapshot: DistributionTargetSnapshot,
    condition: dict[str, object],
    created_parent_bindings: tuple[PathIdentitySnapshot, ...] = (),
) -> bool:
    root_condition = condition.get("root")
    if not isinstance(root_condition, dict) or not _path_snapshot_matches_condition(snapshot.root, root_condition):
        return False
    parent_conditions = condition.get("parents")
    if not isinstance(parent_conditions, list):
        return False
    actual_parents = {parent.relative_path: parent for parent in snapshot.parents}
    bound_parents = {parent.relative_path: parent for parent in created_parent_bindings}
    for parent_condition in parent_conditions:
        if not isinstance(parent_condition, dict):
            return False
        relative_path = parent_condition.get("relative_path")
        if not isinstance(relative_path, str):
            return False
        actual_parent = actual_parents.get(relative_path)
        if actual_parent is None or not _path_snapshot_matches_condition(actual_parent, parent_condition):
            bound_parent = bound_parents.get(relative_path)
            if (
                parent_condition.get("exists") is not False
                or actual_parent is None
                or bound_parent is None
                or not bound_parent.exists
                or actual_parent.file_type != "directory"
                or not _same_structure_identity(actual_parent, bound_parent)
            ):
                return False
    target = snapshot.target
    if condition.get("exists") != target.exists:
        return False
    if "mode" in condition and condition.get("mode") != target.mode:
        return False
    directory_metadata_wildcard = condition.get("file_type") == "directory" and condition.get("identity") is None
    directory_wildcard = (
        condition.get("file_type") == "directory"
        and condition.get("identity")
        == {
            "kind": "directory",
            "sha256": None,
            "mode": None,
            "target": None,
        }
        and condition.get("device") == 0
        and condition.get("inode") == 0
    )
    identity_condition = condition.get("identity")
    directory_identity_wildcard = (
        condition.get("file_type") == "directory"
        and isinstance(identity_condition, dict)
        and identity_condition.get("kind") == "directory"
        and not directory_wildcard
    )
    if "device" in condition and condition.get("device") not in ({0} if directory_wildcard else {target.device}):
        return False
    if "inode" in condition and condition.get("inode") not in ({0} if directory_wildcard else {target.inode}):
        return False
    if (
        "ctime_ns" in condition
        and not directory_metadata_wildcard
        and not directory_identity_wildcard
        and condition.get("ctime_ns") not in ({0} if directory_wildcard else {target.ctime_ns})
    ):
        return False
    if "file_type" in condition and condition.get("file_type") != target.file_type:
        return False
    if "link_count" in condition and not directory_metadata_wildcard and not directory_identity_wildcard:
        expected_link_count = condition.get("link_count")
        if expected_link_count not in ({0} if directory_wildcard else {target.link_count}):
            return False
    if directory_wildcard:
        bound_target = bound_parents.get(target.relative_path)
        if bound_target is not None:
            return (
                target.file_type == "directory"
                and target.exists
                and bound_target.exists
                and _same_structure_identity(target, bound_target)
            )
        # The fresh workspace is bound separately by OperationJournalStore's
        # root/workspace identity checks; it is the only directory postcondition
        # that intentionally has no created-parent record.
        return target.relative_path == "spec-dock" and target.file_type == "directory" and target.exists
    if directory_identity_wildcard:
        return target.file_type == "directory" and target.exists
    return condition.get("identity") == _distribution_identity_payload(target.identity)


def _path_snapshot_matches_condition(snapshot: PathIdentitySnapshot, condition: dict[str, object]) -> bool:
    if not all(
        condition.get(field) == getattr(snapshot, field)
        for field in ("relative_path", "exists", "device", "inode", "file_type")
    ):
        return False
    return "mode" not in condition or condition["mode"] == snapshot.mode


def _condition_has_complete_parent_chain(
    snapshot: DistributionTargetSnapshot,
    condition: dict[str, object],
) -> bool:
    parent_conditions = condition.get("parents")
    if not isinstance(parent_conditions, list):
        return False
    relative_paths = tuple(
        parent.get("relative_path") if isinstance(parent, dict) else None for parent in parent_conditions
    )
    return relative_paths == tuple(parent.relative_path for parent in snapshot.parents)


def _condition_has_complete_target_identity(condition: dict[str, object]) -> bool:
    required_fields = {
        "root",
        "parents",
        "exists",
        "device",
        "inode",
        "ctime_ns",
        "file_type",
        "link_count",
        "identity",
    }
    if set(condition) != required_fields or not isinstance(condition["exists"], bool):
        return False
    if condition["exists"] is False:
        return all(
            condition[field] is None for field in ("device", "inode", "ctime_ns", "file_type", "link_count", "identity")
        )
    if condition["file_type"] == "directory" and condition["identity"] is None:
        return all(
            isinstance(condition[field], int) and not isinstance(condition[field], bool)
            for field in ("device", "inode", "ctime_ns", "link_count")
        )
    return (
        all(
            isinstance(condition[field], int) and not isinstance(condition[field], bool)
            for field in ("device", "inode", "ctime_ns", "link_count")
        )
        and isinstance(condition["file_type"], str)
        and isinstance(condition["identity"], dict)
    )


def _explicit_gc_backup_sources(
    journal: OperationJournal,
    gc_lease: DistributionStageOwnership,
) -> tuple[DistributionStageOwnership, ...]:
    predecessor_name = gc_lease.gc_predecessor_name
    if predecessor_name is None:
        return ()
    return tuple(
        lease
        for lease in journal.staging_leases
        if lease.path == gc_lease.path
        and lease.role in {"backup-reserved", "backup-dual"}
        and (
            lease.stage_name == predecessor_name
            or lease.stage_name == _distribution_quarantine_backup_name(predecessor_name)
            or (predecessor_name.startswith(f"{lease.stage_name}.") and predecessor_name.endswith(".gc"))
        )
    )


def _ordered_gc_transition_leases(journal: OperationJournal) -> tuple[DistributionStageOwnership, ...]:
    return tuple(
        sorted(
            (lease for lease in journal.staging_leases if lease.role in {"gc-reserved", "gc-exact"}),
            key=lambda lease: (
                lease.path,
                lease.gc_ordinal if lease.gc_ordinal is not None else 0,
                0 if lease.role == "gc-exact" else 1,
                lease.stage_name,
            ),
        )
    )


def _gc_transition_companion_is_explicit(
    journal: OperationJournal,
    left: DistributionStageOwnership,
    right: DistributionStageOwnership,
) -> bool:
    if left.path != right.path or left.stage_name == right.stage_name:
        return False
    if (
        left.gc_ordinal is not None
        and right.gc_ordinal is not None
        and left.role in {"gc-reserved", "gc-exact", "backup-only"}
        and right.role in {"gc-reserved", "gc-exact", "backup-only"}
    ):
        if right.gc_predecessor_name == left.stage_name and right.gc_ordinal == left.gc_ordinal + 1:
            return True
        if left.gc_predecessor_name == right.stage_name and left.gc_ordinal == right.gc_ordinal + 1:
            return True
        ordinal_two, ordinal_three = (left, right) if left.gc_ordinal == 2 else (right, left)
        if ordinal_two.gc_ordinal == 2 and ordinal_three.gc_ordinal == 3:
            return any(
                backup.path == left.path
                and backup.stage_name == ordinal_three.gc_predecessor_name
                and backup.role in {"backup-reserved", "backup-dual", "backup-only-reserved", "backup-only"}
                and backup.device == ordinal_two.device
                and backup.inode == ordinal_two.inode
                and backup.file_type == ordinal_two.file_type
                for backup in journal.staging_leases
            )
    gc_lease, backup = (left, right) if left.gc_ordinal is not None else (right, left)
    if (
        gc_lease.gc_ordinal in {1, 3}
        and gc_lease.gc_predecessor_name == backup.stage_name
        and backup.role in {"backup-reserved", "backup-dual", "backup-only-reserved", "backup-only"}
    ):
        return True
    if gc_lease.gc_ordinal != 2 or backup.role not in {
        "backup-reserved",
        "backup-dual",
        "backup-only-reserved",
        "backup-only",
    }:
        return False
    if (
        gc_lease.gc_predecessor_name is not None
        and gc_lease.gc_predecessor_name.startswith(f"{backup.stage_name}.")
        and gc_lease.gc_predecessor_name.endswith(".gc")
        and gc_lease.device == backup.device
        and gc_lease.inode == backup.inode
        and gc_lease.file_type == backup.file_type
    ):
        return True
    return any(
        predecessor.path == gc_lease.path
        and predecessor.stage_name == gc_lease.gc_predecessor_name
        and predecessor.role in {"gc-reserved", "gc-exact"}
        and predecessor.gc_ordinal == 1
        and predecessor.gc_predecessor_name == backup.stage_name
        and predecessor.device == gc_lease.device == backup.device
        and predecessor.inode == gc_lease.inode == backup.inode
        and predecessor.file_type == gc_lease.file_type == backup.file_type
        for predecessor in journal.staging_leases
    )


def _assert_gc_transition_graph(journal: OperationJournal) -> None:
    """Reject malformed GC authority graphs before inspecting or mutating names."""

    if any(
        len(_explicit_gc_backup_sources(journal, lease)) > 1
        for lease in journal.staging_leases
        if lease.role in {"gc-reserved", "gc-exact"}
    ):
        raise DistributionApplyError("journal-plan-mismatch")
    leases_by_name: dict[str, list[DistributionStageOwnership]] = {}
    for lease in journal.staging_leases:
        leases_by_name.setdefault(lease.stage_name, []).append(lease)

    transition_ordinals: set[tuple[str, int]] = set()
    outgoing_edges: dict[tuple[str, str], list[int]] = {}
    for lease in journal.staging_leases:
        has_predecessor = lease.gc_predecessor_name is not None
        if has_predecessor != (lease.gc_ordinal is not None):
            raise DistributionApplyError("journal-plan-mismatch")
        if not has_predecessor:
            continue
        predecessor_name = lease.gc_predecessor_name
        ordinal = lease.gc_ordinal
        assert predecessor_name is not None
        assert ordinal is not None
        if (
            lease.role not in {"gc-reserved", "gc-exact", "backup-only"}
            or lease.stage_name == PurePosixPath(lease.path).name
            or PurePosixPath(predecessor_name).name != predecessor_name
            or predecessor_name == lease.stage_name
            or predecessor_name == PurePosixPath(lease.path).name
            or ordinal not in {1, 2, 3}
            or (lease.path, ordinal) in transition_ordinals
        ):
            raise DistributionApplyError("journal-plan-mismatch")
        transition_ordinals.add((lease.path, ordinal))
        outgoing_edges.setdefault((lease.path, predecessor_name), []).append(ordinal)

        named_predecessors = leases_by_name.get(predecessor_name, [])
        if any(candidate.path != lease.path for candidate in named_predecessors):
            raise DistributionApplyError("journal-plan-mismatch")
        same_path_predecessors = tuple(candidate for candidate in named_predecessors if candidate.path == lease.path)
        if len(same_path_predecessors) > 1:
            raise DistributionApplyError("journal-plan-mismatch")
        if same_path_predecessors:
            predecessor = same_path_predecessors[0]
            if (
                lease.device > 0
                and predecessor.device > 0
                and (
                    lease.device != predecessor.device
                    or lease.inode != predecessor.inode
                    or lease.file_type != predecessor.file_type
                )
            ):
                raise DistributionApplyError("journal-plan-mismatch")
            if predecessor.gc_ordinal is not None:
                if predecessor.role not in {"gc-reserved", "gc-exact"} or ordinal != predecessor.gc_ordinal + 1:
                    raise DistributionApplyError("journal-plan-mismatch")
            elif ordinal == 1:
                if predecessor.role not in {
                    "stage",
                    "predecessor-quarantine",
                    "backup-reserved",
                    "backup-dual",
                    "backup-only-reserved",
                    "backup-only",
                }:
                    raise DistributionApplyError("journal-plan-mismatch")
            elif ordinal == 3:
                if predecessor.role not in {
                    "backup-reserved",
                    "backup-dual",
                    "backup-only-reserved",
                    "backup-only",
                }:
                    raise DistributionApplyError("journal-plan-mismatch")
            else:
                raise DistributionApplyError("journal-plan-mismatch")
            continue

        backup_predecessors = tuple(
            candidate
            for candidate in journal.staging_leases
            if candidate.path == lease.path
            and candidate.role in {"backup-reserved", "backup-dual"}
            and (
                candidate.stage_name == _distribution_quarantine_backup_name(predecessor_name)
                or (
                    predecessor_name.startswith(f"{candidate.stage_name}.")
                    and predecessor_name.endswith(".gc")
                    and lease.device > 0
                    and candidate.device == lease.device
                    and candidate.inode == lease.inode
                    and candidate.file_type == lease.file_type
                )
            )
        )
        derived_missing_backup = any(
            candidate.path == lease.path
            and candidate.role == "predecessor-quarantine"
            and _distribution_quarantine_backup_name(candidate.stage_name) == predecessor_name
            for candidate in journal.staging_leases
        )
        if not ((ordinal == 2 and len(backup_predecessors) == 1) or (ordinal in {1, 3} and derived_missing_backup)):
            raise DistributionApplyError("journal-plan-mismatch")
    for (path, predecessor_name), ordinals in outgoing_edges.items():
        if len(ordinals) == 1:
            continue
        graph_predecessor = next(
            (lease for lease in journal.staging_leases if lease.path == path and lease.stage_name == predecessor_name),
            None,
        )
        derived_missing_backup = any(
            lease.path == path
            and lease.role == "predecessor-quarantine"
            and _distribution_quarantine_backup_name(lease.stage_name) == predecessor_name
            for lease in journal.staging_leases
        )
        if sorted(ordinals) != [1, 3] or not (
            (graph_predecessor is not None and graph_predecessor.role in {"backup-reserved", "backup-dual"})
            or derived_missing_backup
        ):
            raise DistributionApplyError("journal-plan-mismatch")
    for path in {lease.path for lease in journal.staging_leases}:
        ordinal_two = next(
            (
                lease
                for lease in journal.staging_leases
                if lease.path == path and lease.gc_ordinal == 2 and lease.role in {"gc-reserved", "gc-exact"}
            ),
            None,
        )
        ordinal_three = next(
            (
                lease
                for lease in journal.staging_leases
                if lease.path == path
                and lease.gc_ordinal == 3
                and lease.role in {"gc-reserved", "gc-exact", "backup-only"}
            ),
            None,
        )
        if ordinal_two is None or ordinal_three is None or ordinal_three.gc_predecessor_name is None:
            continue
        retained_predecessor = next(
            (
                lease
                for lease in journal.staging_leases
                if lease.path == path
                and lease.stage_name == ordinal_three.gc_predecessor_name
                and lease.role in {"backup-reserved", "backup-dual", "backup-only-reserved", "backup-only"}
            ),
            None,
        )
        if (
            retained_predecessor is not None
            and ordinal_two.device > 0
            and retained_predecessor.device > 0
            and (
                ordinal_two.device != retained_predecessor.device
                or ordinal_two.inode != retained_predecessor.inode
                or ordinal_two.file_type != retained_predecessor.file_type
            )
        ):
            raise DistributionApplyError("journal-plan-mismatch")


def _assert_journal_action_contract(assessment: WorkspaceAssessment, journal: OperationJournal) -> None:
    plan = assessment.distribution_plan
    if plan.target_root is None or journal.intent != assessment.intent:
        raise DistributionApplyError("journal-plan-mismatch")
    current_actions = {action.path: action for action in assessment.actions}
    records = {record.path: record for record in journal.actions}
    completed_missing_obsolete = {
        record.path
        for record in journal.actions
        if record.action == "prune" and record.checkpoint != "pending" and record.path not in current_actions
    }
    if len(records) != len(journal.actions) or set(records) - completed_missing_obsolete != set(current_actions):
        raise DistributionApplyError("journal-plan-mismatch")
    lease_keys = {(lease.path, lease.stage_name) for lease in journal.staging_leases}
    if len(lease_keys) != len(journal.staging_leases):
        raise DistributionApplyError("journal-plan-mismatch")
    _assert_gc_transition_graph(journal)
    allowed_created_parents: set[str] = set()
    for record in journal.actions:
        if not _condition_has_complete_target_identity(record.precondition):
            raise DistributionApplyError("journal-plan-mismatch")
        # A required-directory action owns the directory it creates.  The
        # kernel records that target as a created-parent binding so a retry
        # can revalidate its exact inode; permit that binding even though the
        # directory itself is not listed in its parent chain.
        if record.action == "ensure-directory" and record.precondition.get("exists") is False:
            allowed_created_parents.add(record.path)
        parents = record.precondition.get("parents")
        if not isinstance(parents, list):
            raise DistributionApplyError("journal-plan-mismatch")
        allowed_created_parents.update(
            parent["relative_path"]
            for parent in parents
            if isinstance(parent, dict)
            and parent.get("exists") is False
            and isinstance(parent.get("relative_path"), str)
        )
    if any(binding.relative_path not in allowed_created_parents for binding in journal.created_parent_bindings):
        raise DistributionApplyError("journal-plan-mismatch")
    actual_parents = {
        parent.relative_path: parent for snapshot in dict(plan.target_snapshots).values() for parent in snapshot.parents
    }
    for binding in journal.created_parent_bindings:
        if not binding.exists:
            continue
        actual = actual_parents.get(binding.relative_path)
        if actual is None:
            # A standalone required-directory action has no child asset
            # whose parent chain would expose the directory.  Its target
            # snapshot is the authoritative structure identity instead.
            directory_snapshot = dict(plan.target_snapshots).get(binding.relative_path)
            actual = directory_snapshot.target if directory_snapshot is not None else None
        if actual is None or not _same_structure_identity(actual, binding):
            raise DistributionApplyError("journal-precondition-mismatch")
    for lease in journal.staging_leases:
        if lease.path not in records:
            raise DistributionApplyError("journal-plan-mismatch")
        expected = _expected_target_identity(plan, lease.path)
        known_identities = tuple(
            identity for identity in (expected, *_historical_stage_identities(plan, lease.path)) if identity is not None
        )
        if not any(
            _matches_distribution_stage_name(lease.stage_name, lease.path, identity) for identity in known_identities
        ):
            raise DistributionApplyError("journal-plan-mismatch")
    current_specs = {
        **_target_identity_specs(plan.current_assets, plan.scaffold_assets),
        **{item.path: DistributionIdentity(kind="directory") for item in plan.required_directories},
    }
    obsolete_paths = {item["path"] for item in plan.manifest.obsolete_exact_files} - set(current_specs)
    for record in journal.actions:
        if not _intent_allows_distribution_action(journal.intent, record.action):
            raise DistributionApplyError("journal-plan-mismatch")
        postcondition = _journal_postcondition(record)
        expected_identity: DistributionIdentity | None = None
        purge_history_action = (
            journal.intent == "purge"
            and _is_same_or_descendant(record.path, _EXPLICIT_SPEC_HISTORY_ROOT)
            and record.provenance == "unknown"
            and record.reason in {"explicit-spec-history-purge", "explicit-spec-history-purge-directory"}
        )
        if record.action == "prune":
            if (record.path not in obsolete_paths and not purge_history_action) or postcondition.get(
                "exists"
            ) is not False:
                raise DistributionApplyError("journal-plan-mismatch")
        elif record.action == "ensure-directory":
            if not any(item.path == record.path for item in plan.required_directories):
                raise DistributionApplyError("journal-plan-mismatch")
            expected_identity = DistributionIdentity(kind="directory")
        else:
            expected_identity = (
                DistributionIdentity(kind="directory") if purge_history_action else current_specs.get(record.path)
            )
            valid_purge_directory = (
                purge_history_action and expected_identity is not None and record.action == "remove-empty-directory"
            )
            if (
                expected_identity is None or record.action not in {"create", "adopt", "upgrade", "preserve"}
            ) and not valid_purge_directory:
                raise DistributionApplyError("journal-plan-mismatch")
        target_snapshot = dict(plan.target_snapshots).get(record.path)
        if record.action == "ensure-directory":
            assert expected_identity is not None
            if (
                postcondition.get("exists") is not True
                or postcondition.get("file_type") != "directory"
                or postcondition.get("identity") != _distribution_identity_payload(expected_identity)
            ):
                raise DistributionApplyError("journal-plan-mismatch")
        elif (
            record.action != "prune"
            and expected_identity is not None
            and expected_identity.kind != "directory"
            and (
                postcondition.get("exists") is not True
                or postcondition.get("file_type") != expected_identity.kind
                or (
                    record.action == "adopt"
                    and (
                        target_snapshot is None
                        or any(
                            postcondition.get(field) != getattr(target_snapshot.target, field)
                            for field in ("device", "inode", "ctime_ns")
                        )
                    )
                )
                or (
                    record.action in {"create", "upgrade"}
                    and record.checkpoint != "pending"
                    and (
                        target_snapshot is None
                        or any(
                            postcondition.get(field) != getattr(target_snapshot.target, field)
                            for field in ("device", "inode", "ctime_ns", "link_count")
                        )
                    )
                )
                or (
                    postcondition.get("link_count")
                    != (
                        target_snapshot.target.link_count
                        if target_snapshot is not None
                        and (
                            record.action == "adopt"
                            or (
                                _is_fresh_workbench_seed_create(journal, record)
                                and record.checkpoint != "pending"
                                and all(
                                    field in postcondition for field in ("device", "inode", "ctime_ns", "link_count")
                                )
                            )
                        )
                        else 1
                    )
                )
                or postcondition.get("identity") != _distribution_identity_payload(expected_identity)
            )
        ):
            raise DistributionApplyError("journal-plan-mismatch")
        snapshot = dict(plan.target_snapshots).get(record.path)
        if snapshot is None and record.path in completed_missing_obsolete:
            snapshot = _observe_target(plan.target_root, record.path).snapshot
        if (
            snapshot is None
            or not _condition_has_complete_parent_chain(snapshot, record.precondition)
            or not _condition_has_complete_parent_chain(snapshot, postcondition)
        ):
            raise DistributionApplyError("journal-plan-mismatch")
        if record.checkpoint == "pending":
            current = current_actions[record.path]
            if (record.action, record.provenance, record.reason) != (
                current.action,
                current.provenance,
                current.reason,
            ):
                raise DistributionApplyError("journal-plan-mismatch")
            if not _snapshot_matches_condition(
                snapshot,
                record.precondition,
                journal.created_parent_bindings,
            ):
                raise DistributionApplyError("journal-plan-mismatch")


def _resume_executable_plan(
    assessment: WorkspaceAssessment,
    journal: OperationJournal,
) -> ExecutableMutationPlan:
    journal_digests = {
        _journal_digest(journal),
        _journal_digest(journal, legacy_create_upgrade_fixed_link_count=True),
    }
    expected_digests = {journal.plan_digest, *_mutation_plan_digest_candidates(assessment)}
    if not journal_digests.intersection(expected_digests):
        raise DistributionApplyError("journal-plan-mismatch")
    _assert_journal_action_contract(assessment, journal)
    plan = assessment.distribution_plan
    if plan.target_root is None:
        raise DistributionApplyError("journal-plan-mismatch")
    snapshots = dict(plan.target_snapshots)
    original_actions: list[DistributionAction] = []
    pending_actions: list[DistributionAction] = []
    for record in journal.actions:
        snapshot = snapshots.get(record.path)
        if snapshot is None and record.action == "prune" and record.checkpoint != "pending":
            snapshot = _observe_target(plan.target_root, record.path).snapshot
        if snapshot is None:
            raise DistributionApplyError("journal-precondition-mismatch")
        expected = record.precondition if record.checkpoint == "pending" else _journal_postcondition(record)
        if not _snapshot_matches_condition(snapshot, expected, journal.created_parent_bindings):
            raise DistributionApplyError("journal-precondition-mismatch")
        action = DistributionAction(
            path=record.path,
            operation=_plan_operation_for_intent(journal.intent),
            action=record.action,
            provenance=record.provenance,
            reason=record.reason,
        )
        original_actions.append(action)
        if record.checkpoint == "pending":
            pending_actions.append(action)
    pending_plan = replace(assessment.distribution_plan, actions=tuple(pending_actions))
    return ExecutableMutationPlan(
        intent=journal.intent,
        root_identity=journal.root_identity,
        contract_identity=journal.contract_identity,
        plan_digest=journal.plan_digest,
        distribution_plan=pending_plan,
        actions=tuple(original_actions),
        leaf_parent_namespace_witnesses=journal.leaf_parent_namespace_witnesses,
        preservation_witnesses=journal.preservation_witnesses,
        absence_witnesses=journal.absence_witnesses,
        source_semantic_identities=journal.source_semantic_identities,
        generated_state_contract_digest=journal.generated_state_contract_digest,
        active_selection_witnesses=journal.active_selection_witnesses,
    )


def _reconcile_pending_journal_actions(
    assessment: WorkspaceAssessment,
    journal: OperationJournal,
) -> OperationJournal:
    """Advance crash-ambiguous pending records only from exact observation."""

    snapshots = dict(assessment.distribution_plan.target_snapshots)
    reconciled: list[OperationJournalAction] = []
    changed = False
    for record in journal.actions:
        if record.checkpoint != "pending":
            reconciled.append(record)
            continue
        snapshot = snapshots.get(record.path)
        if snapshot is None:
            raise DistributionApplyError("journal-precondition-mismatch")
        matches_pre = _snapshot_matches_condition(snapshot, record.precondition, journal.created_parent_bindings)
        postcondition = _fresh_workbench_seed_recovery_postcondition(snapshot, journal, record)
        matches_post = _snapshot_matches_condition(
            snapshot,
            postcondition,
            journal.created_parent_bindings,
        )
        if matches_post and (not matches_pre or record.action in {"adopt", "preserve"}):
            reconciled.append(replace(record, checkpoint="published", postcondition=postcondition))
            changed = True
            continue
        if matches_pre and not matches_post:
            reconciled.append(record)
            continue
        raise DistributionApplyError("journal-precondition-mismatch")
    if not changed:
        return journal
    return replace(journal, status="executing", actions=tuple(reconciled))


def _reconcile_created_parent_bindings(
    store: OperationJournalStore,
    assessment: WorkspaceAssessment,
    journal: OperationJournal,
) -> OperationJournal:
    """Bind a safely recoverable parent that appeared before an abrupt stop.

    A user may have published an exact provider asset into a missing parent
    between attempts.  Such a parent is adoptable only when every existing
    child is already represented by a journal action's exact postcondition;
    unknown children remain a fail-closed journal mismatch.
    """

    _assert_created_parent_bindings_closed_set(store.target_root, journal)

    actual_parents = {
        parent.relative_path: parent
        for snapshot in dict(assessment.distribution_plan.target_snapshots).values()
        for parent in snapshot.parents
    }
    bindings = {binding.relative_path: binding for binding in journal.created_parent_bindings}
    pending_directory_records = {
        record.path: record
        for record in journal.actions
        if record.checkpoint == "pending"
        and record.action == "ensure-directory"
        and record.precondition.get("exists") is False
    }
    changed = False
    candidate_paths = tuple(
        sorted(
            {
                *bindings,
                *pending_directory_records,
            },
            key=lambda path: (path.count("/"), path),
        )
    )
    for relative_path in candidate_paths:
        binding = bindings.get(relative_path)
        if binding is not None and binding.exists:
            continue
        actual = actual_parents.get(relative_path)
        if actual is None:
            directory_snapshot = dict(assessment.distribution_plan.target_snapshots).get(relative_path)
            actual = directory_snapshot.target if directory_snapshot is not None else None
        if actual is None or not actual.exists:
            continue
        if actual.file_type != "directory":
            raise DistributionApplyError("journal-precondition-mismatch")
        parent_path = store.target_root / PurePosixPath(relative_path)
        try:
            children = tuple(parent_path.iterdir())
        except OSError as exc:
            raise DistributionApplyError("journal-precondition-mismatch") from exc
        tentative_bindings = (
            *(item for path, item in bindings.items() if path != relative_path),
            actual,
        )
        snapshots = dict(assessment.distribution_plan.target_snapshots)
        records = {record.path: record for record in journal.actions}
        for child in children:
            child_path = f"{relative_path}/{child.name}"
            record = records.get(child_path)
            snapshot = snapshots.get(child_path)
            child_postcondition = (
                _fresh_workbench_seed_recovery_postcondition(snapshot, journal, record)
                if record is not None and snapshot is not None
                else None
            )
            if (
                record is None
                or snapshot is None
                or child_postcondition is None
                or not _snapshot_matches_condition(snapshot, child_postcondition, tentative_bindings)
            ):
                raise DistributionApplyError("journal-precondition-mismatch")
        bindings[relative_path] = actual
        changed = True
    if not changed:
        return journal
    return store.write(
        replace(
            journal,
            created_parent_bindings=tuple(bindings[path] for path in sorted(bindings)),
        ),
        predecessor=journal,
    )


def _entry_matches_journal_condition(
    parent_fd: int,
    name: str,
    path: str,
    condition: dict[str, object],
) -> bool:
    try:
        info = os.stat(name, dir_fd=parent_fd, follow_symlinks=False)
        identity = _distribution_stage_identity(
            parent_fd,
            name,
            path,
            allow_backup_link=path == "spec-dock/.workbench/README.md",
        )
    except FileNotFoundError:
        return condition.get("exists") is False
    except (OSError, DistributionApplyError):
        return False
    for field_name, actual in (
        ("device", info.st_dev),
        ("inode", info.st_ino),
        ("ctime_ns", info.st_ctime_ns),
        ("file_type", _file_type(info.st_mode)),
        ("link_count", info.st_nlink),
    ):
        if (
            field_name in condition
            and not (
                condition[field_name] == 0
                and field_name in {"device", "inode", "ctime_ns", "link_count"}
                and condition.get("file_type") == "directory"
            )
            and condition[field_name] != actual
        ):
            return False
    condition_identity = condition.get("identity")
    if (
        condition.get("exists") is True
        and condition.get("file_type") == "directory"
        and isinstance(condition_identity, dict)
        and condition_identity.get("kind") == "directory"
    ):
        return _file_type(info.st_mode) == "directory"
    return condition.get("exists") is True and condition.get("identity") == _distribution_identity_payload(identity)


def _entry_matches_staging_lease(
    parent_fd: int,
    name: str,
    lease: DistributionStageOwnership,
    *,
    require_ctime: bool = True,
) -> bool:
    try:
        info = os.stat(name, dir_fd=parent_fd, follow_symlinks=False)
    except (FileNotFoundError, OSError):
        return False
    return (
        lease.device > 0
        and info.st_dev == lease.device
        and info.st_ino == lease.inode
        and (not require_ctime or info.st_ctime_ns == lease.ctime_ns)
        and _file_type(info.st_mode) == lease.file_type
        and info.st_nlink == 1
    )


def _assert_workspace_closed_set_tree(workspace: Path, allowed: frozenset[str]) -> None:
    def walk(current: Path, relative: str) -> None:
        try:
            entries = tuple(os.scandir(current))
        except OSError as exc:
            raise DistributionApplyError("journal-parent-mismatch") from exc
        for entry in entries:
            child = f"{relative}/{entry.name}" if relative else entry.name
            has_allowed_descendant = any(path.startswith(f"{child}/") for path in allowed)
            if child not in allowed and not has_allowed_descendant:
                raise DistributionApplyError("journal-parent-mismatch")
            try:
                info = entry.stat(follow_symlinks=False)
            except OSError as exc:
                raise DistributionApplyError("journal-parent-mismatch") from exc
            if has_allowed_descendant:
                if stat.S_ISLNK(info.st_mode) or not stat.S_ISDIR(info.st_mode):
                    raise DistributionApplyError("journal-parent-mismatch")
                walk(Path(entry.path), child)

    walk(workspace, "")


def _journal_workspace_top_level_entries(journal: OperationJournal) -> frozenset[str]:
    """Index immutable journal paths that may appear below ``spec-dock``."""

    allowed: set[str] = set()
    for path in (
        *(action.path for action in journal.actions),
        *(binding.relative_path for binding in journal.created_parent_bindings),
        *(lease.path for lease in journal.staging_leases),
    ):
        root, separator, remainder = path.partition("/")
        if root == "spec-dock" and separator and remainder:
            allowed.add(remainder.partition("/")[0])
    return frozenset(allowed)


def _assert_created_workspace_closed_set(
    target_root: Path,
    expected_identity: tuple[int, int] | None,
    journal: OperationJournal | None,
    allowed_workspace_entries: frozenset[str] | None = None,
    journal_workspace_entries: frozenset[str] | None = None,
) -> None:
    """Re-prove a fresh bootstrap directory and reject unknown root children."""

    if expected_identity is None:
        return
    workspace = target_root / "spec-dock"
    try:
        info = os.lstat(workspace)
    except OSError as exc:
        raise DistributionApplyError("journal-parent-mismatch") from exc
    if stat.S_ISLNK(info.st_mode) or not stat.S_ISDIR(info.st_mode) or (info.st_dev, info.st_ino) != expected_identity:
        raise DistributionApplyError("journal-parent-mismatch")
    if allowed_workspace_entries is not None and journal is None:
        _assert_workspace_closed_set_tree(workspace, allowed_workspace_entries)
        return
    workspace_fd: int | None = None
    try:
        workspace_fd = os.open(workspace, _distribution_directory_flags())
        opened = os.fstat(workspace_fd)
        if (opened.st_dev, opened.st_ino) != expected_identity:
            raise DistributionApplyError("journal-parent-mismatch")
        with os.scandir(workspace_fd) as entries:
            names = {entry.name for entry in entries}
    except OSError as exc:
        raise DistributionApplyError("journal-parent-mismatch") from exc
    finally:
        if workspace_fd is not None:
            with suppress(OSError):
                os.close(workspace_fd)
    allowed = set()
    if _path_present_no_follow(workspace / _DISTRIBUTION_RETRY_MARKER_REL.name):
        allowed.add(_DISTRIBUTION_RETRY_MARKER_REL.name)
    if journal is not None:
        allowed.add(_DISTRIBUTION_JOURNAL_REL.name)
        allowed.update(
            journal_workspace_entries
            if journal_workspace_entries is not None
            else _journal_workspace_top_level_entries(journal)
        )
        for lease in journal.staging_leases:
            root, separator, remainder = lease.path.partition("/")
            if root == "spec-dock" and separator and remainder and "/" not in remainder:
                allowed.add(lease.stage_name)
    if names - allowed:
        raise DistributionApplyError("journal-parent-mismatch")


def _assert_fresh_guard_only_closed_set(
    target_root: Path,
    plan: ExecutableMutationPlan,
    marker: DistributionRetryMarker,
    extra_entries: tuple[str, ...] = (),
) -> tuple[tuple[int, int], frozenset[str]]:
    """Re-prove a fresh workspace before converting a guard-only retry.

    A guard-only retry has no journal from which the bootstrap witness can be
    restored.  The guard plan still binds the current workspace identity via
    its action preconditions, so reject any child that is not an exact prefix
    of a planned path or an operation-owned recovery entry before publishing a
    journal.
    """

    workspace = target_root / "spec-dock"
    try:
        workspace_info = os.lstat(workspace)
    except OSError as exc:
        raise DistributionApplyError("journal-parent-mismatch") from exc
    if stat.S_ISLNK(workspace_info.st_mode) or not stat.S_ISDIR(workspace_info.st_mode):
        raise DistributionApplyError("journal-parent-mismatch")

    workspace_identities: set[tuple[int, int]] = set()
    for _, snapshot in plan.distribution_plan.target_snapshots:
        for parent in snapshot.parents:
            if parent.relative_path == "spec-dock" and parent.exists:
                if parent.file_type != "directory" or parent.device is None or parent.inode is None:
                    raise DistributionApplyError("journal-parent-mismatch")
                workspace_identities.add((parent.device, parent.inode))
        target = snapshot.target
        if target.relative_path == "spec-dock" and target.exists:
            if target.file_type != "directory" or target.device is None or target.inode is None:
                raise DistributionApplyError("journal-parent-mismatch")
            workspace_identities.add((target.device, target.inode))
    if len(workspace_identities) != 1 or (workspace_info.st_dev, workspace_info.st_ino) not in workspace_identities:
        raise DistributionApplyError("journal-parent-mismatch")

    allowed: set[str] = {
        _DISTRIBUTION_RETRY_MARKER_REL.name,
        _DISTRIBUTION_JOURNAL_REL.name,
    }

    def add_path(relative_path: str) -> None:
        parts = PurePosixPath(relative_path).parts
        if not parts or parts[0] != "spec-dock":
            return
        for index in range(1, len(parts) + 1):
            allowed.add(PurePosixPath(*parts[1:index]).as_posix())

    for action in plan.actions:
        add_path(action.path)
    for lease in marker.stage_ownership:
        add_path(lease.path)
        lease_parts = PurePosixPath(lease.path).parts
        if len(lease_parts) >= 2 and lease_parts[0] == "spec-dock":
            lease_parent = PurePosixPath(*lease_parts[1:-1])
            allowed.add((lease_parent / lease.stage_name).as_posix() if lease_parent.parts else lease.stage_name)
    for extra in extra_entries:
        relative = PurePosixPath(extra)
        if relative.is_absolute() or ".." in relative.parts or len(relative.parts) != 1:
            raise DistributionApplyError("journal-parent-mismatch")
        allowed.add(relative.as_posix())

    _assert_workspace_closed_set_tree(workspace, frozenset(allowed))
    return (workspace_info.st_dev, workspace_info.st_ino), frozenset(allowed)


def _assert_created_parent_bindings_closed_set(
    target_root: Path,
    journal: OperationJournal,
) -> None:
    """Treat recovered parent bindings as hints and re-prove their contents."""

    originally_missing: set[str] = set()
    for action in journal.actions:
        parents = action.precondition.get("parents")
        if not isinstance(parents, list):
            raise DistributionApplyError("journal-precondition-mismatch")
        if action.action == "ensure-directory" and action.precondition.get("exists") is False:
            originally_missing.add(action.path)
        originally_missing.update(
            parent["relative_path"]
            for parent in parents
            if isinstance(parent, dict)
            and parent.get("exists") is False
            and isinstance(parent.get("relative_path"), str)
        )
    bindings = {binding.relative_path: binding for binding in journal.created_parent_bindings}
    for relative_path, binding in bindings.items():
        if relative_path not in originally_missing or not binding.exists:
            continue
        try:
            parent_chain = _open_distribution_parent_chain(
                target_root,
                f"{relative_path}/.closed-set-probe",
                create_missing=False,
            )
        except DistributionApplyError as exc:
            raise DistributionApplyError("journal-precondition-mismatch") from exc
        try:
            _assert_created_parent_binding_fd_closed_set(
                parent_chain[-1],
                relative_path,
                binding,
                journal,
            )
        finally:
            _close_distribution_parent_chain(parent_chain)


def _assert_created_parent_binding_fd_closed_set(
    parent_fd: int,
    relative_path: str,
    binding: PathIdentitySnapshot,
    journal: OperationJournal,
) -> None:
    """Re-prove one created parent using the descriptor held by the mutator."""

    bindings = {item.relative_path: item for item in journal.created_parent_bindings}
    records = {record.path: record for record in journal.actions}
    before = os.fstat(parent_fd)
    if not _same_stat_structure(before, binding):
        raise DistributionApplyError("journal-precondition-mismatch")
    try:
        names = os.listdir(parent_fd)
    except OSError as exc:
        raise DistributionApplyError("journal-precondition-mismatch") from exc
    for name in names:
        child_path = f"{relative_path}/{name}"
        child_binding = bindings.get(child_path)
        if child_binding is not None and child_binding.exists:
            try:
                child_info = os.stat(name, dir_fd=parent_fd, follow_symlinks=False)
            except OSError as exc:
                raise DistributionApplyError("journal-precondition-mismatch") from exc
            if child_info.st_nlink < 1 or not _same_stat_structure(child_info, child_binding):
                raise DistributionApplyError("journal-precondition-mismatch")
            continue
        record = records.get(child_path)
        if record is not None:
            canonical_is_exact_lease = any(
                lease.path == child_path
                and lease.role == "stage"
                and _entry_matches_staging_lease(
                    parent_fd,
                    name,
                    lease,
                    require_ctime=False,
                )
                for lease in journal.staging_leases
            )
            if (record.checkpoint != "pending" or canonical_is_exact_lease) and _entry_matches_journal_condition(
                parent_fd, name, child_path, _journal_postcondition(record)
            ):
                continue
        matched_stage = False
        for lease in journal.staging_leases:
            if PurePosixPath(lease.path).parent.as_posix() != relative_path:
                continue
            if lease.stage_name != name:
                continue
            if lease.device == lease.inode == lease.ctime_ns == 0:
                try:
                    reserved_info = os.stat(name, dir_fd=parent_fd, follow_symlinks=False)
                except OSError as exc:
                    raise DistributionApplyError("journal-precondition-mismatch") from exc
                companion: DistributionStageOwnership | None = None
                allowed_links = {1}
                requires_companion = False
                if lease.role == "gc-reserved":
                    companion = next(
                        (
                            item
                            for item in journal.staging_leases
                            if item.path == lease.path
                            and item.stage_name == lease.gc_predecessor_name
                            and item.device > 0
                            and (
                                (lease.gc_ordinal == 1 and item.role in {"stage", "backup-dual", "backup-only"})
                                or (lease.gc_ordinal == 2 and item.role == "gc-exact" and item.gc_ordinal == 1)
                                or (
                                    lease.gc_ordinal == 3
                                    and item.role in {"backup-reserved", "backup-dual", "backup-only"}
                                )
                            )
                        ),
                        None,
                    )
                    requires_companion = True
                    allowed_links = (
                        {2}
                        if lease.gc_ordinal in {2, 3}
                        or (companion is not None and companion.role in {"backup-dual", "backup-only"})
                        else {1}
                    )
                elif lease.role in {"backup-reserved", "backup-only-reserved"}:
                    companion = next(
                        (
                            item
                            for item in journal.staging_leases
                            if item.path == lease.path
                            and item.device > 0
                            and (
                                (
                                    item.role == "predecessor-quarantine"
                                    and _distribution_quarantine_backup_name(item.stage_name) == lease.stage_name
                                )
                                or (
                                    lease.role == "backup-reserved"
                                    and item.role == "gc-exact"
                                    and item.gc_predecessor_name == lease.stage_name
                                )
                            )
                        ),
                        None,
                    )
                    requires_companion = True
                    allowed_links = {1, 2} if lease.role == "backup-only-reserved" else {2}
                if (
                    _file_type(reserved_info.st_mode) == lease.file_type
                    and reserved_info.st_nlink in allowed_links
                    and not (requires_companion and companion is None)
                    and (
                        companion is None
                        or (reserved_info.st_dev == companion.device and reserved_info.st_ino == companion.inode)
                    )
                ):
                    matched_stage = True
                    break
            try:
                exact_info = os.stat(name, dir_fd=parent_fd, follow_symlinks=False)
            except OSError as exc:
                raise DistributionApplyError("journal-precondition-mismatch") from exc
            if lease.role == "predecessor-quarantine":
                dual_backup = next(
                    (item for item in journal.staging_leases if item.path == lease.path and item.role == "backup-dual"),
                    None,
                )
                if (
                    dual_backup is not None
                    and exact_info.st_dev == dual_backup.device
                    and exact_info.st_ino == dual_backup.inode
                    and exact_info.st_ctime_ns == dual_backup.ctime_ns
                    and _file_type(exact_info.st_mode) == dual_backup.file_type
                    and exact_info.st_nlink == 2
                ):
                    matched_stage = True
                    break
            gc_companion = next(
                (
                    item
                    for item in journal.staging_leases
                    if item.path == lease.path
                    and item.stage_name != lease.stage_name
                    and item.device > 0
                    and _gc_transition_companion_is_explicit(journal, lease, item)
                ),
                None,
            )
            if lease.role == "backup-dual" and exact_info.st_nlink == 2:
                for candidate in journal.staging_leases:
                    if (
                        candidate.path != lease.path
                        or candidate.role != "gc-exact"
                        or candidate.device != lease.device
                        or candidate.inode != lease.inode
                        or not _gc_transition_companion_is_explicit(journal, lease, candidate)
                    ):
                        continue
                    try:
                        candidate_info = os.stat(
                            candidate.stage_name,
                            dir_fd=parent_fd,
                            follow_symlinks=False,
                        )
                    except FileNotFoundError:
                        continue
                    except OSError as exc:
                        raise DistributionApplyError("journal-precondition-mismatch") from exc
                    if (
                        candidate_info.st_dev == exact_info.st_dev == lease.device
                        and candidate_info.st_ino == exact_info.st_ino == lease.inode
                        and _file_type(candidate_info.st_mode) == _file_type(exact_info.st_mode) == lease.file_type
                        and candidate_info.st_nlink == 2
                    ):
                        matched_stage = True
                        break
                if matched_stage:
                    break
            if (
                lease.role == "backup-dual"
                and exact_info.st_dev == lease.device
                and exact_info.st_ino == lease.inode
                and _file_type(exact_info.st_mode) == lease.file_type
                and exact_info.st_nlink == 1
                and any(
                    candidate.path == lease.path
                    and candidate.role in {"gc-reserved", "gc-exact"}
                    and candidate.gc_ordinal == 3
                    and candidate.gc_predecessor_name == lease.stage_name
                    for candidate in journal.staging_leases
                )
                and all(
                    candidate.role == "gc-exact"
                    and candidate.device == lease.device
                    and candidate.inode == lease.inode
                    and candidate.file_type == lease.file_type
                    and _stat_optional_no_follow(parent_fd, candidate.stage_name) is None
                    for candidate in journal.staging_leases
                    if candidate.path == lease.path
                    and candidate.role in {"gc-reserved", "gc-exact"}
                    and candidate.gc_ordinal in {1, 2}
                )
            ):
                matched_stage = True
                break
            if (
                lease.role == "gc-exact"
                and exact_info.st_dev == lease.device
                and exact_info.st_ino == lease.inode
                and exact_info.st_ctime_ns == lease.ctime_ns
                and _file_type(exact_info.st_mode) == lease.file_type
                and exact_info.st_nlink == 1
            ):
                matched_stage = True
                break
            if (
                lease.role == "gc-exact"
                and lease.gc_ordinal == 3
                and exact_info.st_dev == lease.device
                and exact_info.st_ino == lease.inode
                and _file_type(exact_info.st_mode) == lease.file_type
                and exact_info.st_nlink == 1
            ):
                completed_predecessor = next(
                    (
                        candidate
                        for candidate in journal.staging_leases
                        if candidate.path == lease.path
                        and candidate.role == "gc-exact"
                        and candidate.gc_ordinal == 2
                        and candidate.device == lease.device
                        and candidate.inode == lease.inode
                        and candidate.file_type == lease.file_type
                    ),
                    None,
                )
                if (
                    completed_predecessor is not None
                    and _stat_optional_no_follow(parent_fd, completed_predecessor.stage_name) is None
                ):
                    matched_stage = True
                    break
            if lease.role == "gc-exact" and lease.gc_ordinal == 2 and exact_info.st_nlink == 2:
                graph_successor = next(
                    (
                        candidate
                        for candidate in journal.staging_leases
                        if candidate.path == lease.path
                        and candidate.role == "gc-reserved"
                        and candidate.gc_ordinal == 3
                        and any(
                            backup.path == lease.path
                            and backup.stage_name == candidate.gc_predecessor_name
                            and backup.role in {"backup-reserved", "backup-dual"}
                            and backup.device == lease.device
                            and backup.inode == lease.inode
                            and backup.file_type == lease.file_type
                            for backup in journal.staging_leases
                        )
                    ),
                    None,
                )
                if graph_successor is not None:
                    try:
                        graph_info = os.stat(
                            graph_successor.stage_name,
                            dir_fd=parent_fd,
                            follow_symlinks=False,
                        )
                    except FileNotFoundError:
                        graph_info = None
                    except OSError as exc:
                        raise DistributionApplyError("journal-precondition-mismatch") from exc
                    if (
                        graph_info is not None
                        and graph_info.st_dev == exact_info.st_dev == lease.device
                        and graph_info.st_ino == exact_info.st_ino == lease.inode
                        and _file_type(graph_info.st_mode) == _file_type(exact_info.st_mode) == lease.file_type
                        and graph_info.st_nlink == 2
                    ):
                        matched_stage = True
                        break
            if lease.role == "gc-exact" and exact_info.st_nlink == 2:
                for candidate in journal.staging_leases:
                    if (
                        candidate.path != lease.path
                        or candidate.stage_name == lease.stage_name
                        or candidate.device != lease.device
                        or candidate.inode != lease.inode
                        or not _gc_transition_companion_is_explicit(journal, lease, candidate)
                    ):
                        continue
                    try:
                        candidate_info = os.stat(
                            candidate.stage_name,
                            dir_fd=parent_fd,
                            follow_symlinks=False,
                        )
                    except FileNotFoundError:
                        continue
                    except OSError as exc:
                        raise DistributionApplyError("journal-precondition-mismatch") from exc
                    if (
                        candidate_info.st_dev == exact_info.st_dev == lease.device
                        and candidate_info.st_ino == exact_info.st_ino == lease.inode
                        and _file_type(candidate_info.st_mode) == _file_type(exact_info.st_mode) == lease.file_type
                        and candidate_info.st_nlink == 2
                    ):
                        matched_stage = True
                        break
                if matched_stage:
                    break
            if gc_companion is not None:
                try:
                    companion_info = os.stat(
                        gc_companion.stage_name,
                        dir_fd=parent_fd,
                        follow_symlinks=False,
                    )
                except FileNotFoundError:
                    if (
                        lease.role != "gc-exact"
                        and exact_info.st_dev == gc_companion.device
                        and exact_info.st_ino == gc_companion.inode
                        and _file_type(exact_info.st_mode) == gc_companion.file_type
                        and exact_info.st_nlink == 1
                    ):
                        matched_stage = True
                        break
                    gc_companion = None
                except OSError as exc:
                    raise DistributionApplyError("journal-precondition-mismatch") from exc
                if gc_companion is not None:
                    exact_gc = lease if lease.role == "gc-exact" else gc_companion
                    if (
                        exact_info.st_nlink == 2
                        and exact_info.st_dev == companion_info.st_dev == exact_gc.device
                        and exact_info.st_ino == companion_info.st_ino == exact_gc.inode
                        and companion_info.st_ctime_ns == exact_gc.ctime_ns
                        and _file_type(exact_info.st_mode) == _file_type(companion_info.st_mode) == exact_gc.file_type
                        and companion_info.st_nlink == 2
                    ):
                        matched_stage = True
                        break
            expected_links = 2 if lease.role == "backup-dual" else 1
            if (
                lease.device > 0
                and exact_info.st_dev == lease.device
                and exact_info.st_ino == lease.inode
                and exact_info.st_ctime_ns == lease.ctime_ns
                and _file_type(exact_info.st_mode) == lease.file_type
                and exact_info.st_nlink == expected_links
            ):
                matched_stage = True
                break
            record = records.get(lease.path)
            canonical_name = PurePosixPath(lease.path).name
            if (
                record is not None
                and record.action == "upgrade"
                and _entry_matches_staging_lease(
                    parent_fd,
                    canonical_name,
                    lease,
                    require_ctime=False,
                )
                and _entry_matches_journal_condition(parent_fd, name, lease.path, record.precondition)
            ):
                matched_stage = True
                break
        if not matched_stage:
            raise DistributionApplyError("journal-precondition-mismatch")
    after = os.fstat(parent_fd)
    if _stat_identity_tuple(after) != _stat_identity_tuple(before):
        raise DistributionApplyError("journal-precondition-mismatch")


def _journal_version_precondition_identity(journal: OperationJournal) -> DistributionIdentity | None:
    for action in journal.actions:
        if action.path != "spec-dock/spec-dock.version":
            continue
        identity = action.precondition.get("identity")
        if (
            isinstance(identity, dict)
            and identity.get("kind") == "regular"
            and isinstance(identity.get("sha256"), str)
            and (identity.get("mode") is None or isinstance(identity.get("mode"), int))
        ):
            return DistributionIdentity(
                kind="regular",
                sha256=identity["sha256"],
                mode=identity.get("mode"),
            )
    return None


def _validated_legacy_stage_leases(
    plan: ExecutableMutationPlan,
    marker: DistributionRetryMarker,
    target_root: Path,
    *,
    allow_operation_created_parents: bool = False,
) -> tuple[DistributionStageOwnership, ...]:
    """Bind exact legacy private stages to the reconstructed current plan."""

    if not marker.stage_ownership:
        return ()
    actions = {action.path: action for action in plan.actions}
    snapshots = _plan_snapshot_map(plan.distribution_plan)
    seen: set[tuple[str, str]] = set()
    validated: list[DistributionStageOwnership] = []
    for lease in marker.stage_ownership:
        key = (lease.path, lease.stage_name)
        action = actions.get(lease.path)
        snapshot = snapshots.get(lease.path)
        expected = _expected_target_identity(plan.distribution_plan, lease.path)
        historical = _historical_stage_identities(plan.distribution_plan, lease.path)
        if (
            key in seen
            or action is None
            or action.action not in {"create", "adopt", "upgrade", "prune"}
            or snapshot is None
            or expected is None
            or not any(
                _matches_distribution_stage_name(lease.stage_name, lease.path, identity)
                for identity in (expected, *historical)
            )
        ):
            raise DistributionApplyError("legacy-marker-unconvertible")
        seen.add(key)
        try:
            parent_chain = _open_distribution_parent_chain(
                target_root,
                lease.path,
                create_missing=False,
                expected_snapshot=None if allow_operation_created_parents else snapshot,
            )
        except DistributionApplyError as exc:
            raise DistributionApplyError("legacy-marker-unconvertible") from exc
        try:
            try:
                current = os.stat(lease.stage_name, dir_fd=parent_chain[-1], follow_symlinks=False)
            except OSError as exc:
                raise DistributionApplyError("legacy-marker-unconvertible") from exc
            if (
                current.st_dev != lease.device
                or current.st_ino != lease.inode
                or current.st_ctime_ns != lease.ctime_ns
                or _file_type(current.st_mode) != lease.file_type
                or current.st_nlink != 1
            ):
                raise DistributionApplyError("legacy-marker-unconvertible")
        finally:
            _close_distribution_parent_chain(parent_chain)
        validated.append(lease)
    return tuple(validated)


def _execute_distribution_reconciliation(
    install_root: Path,
    *,
    manifest_path: Path,
    scaffold_root: Path,
    target_root: Path,
    intent: JournaledDistributionIntent,
    package_version: str,
    legacy_marker: DistributionRetryMarker | None = None,
    generated_assets: tuple[DistributionAsset, ...] = (),
    version_refreshable_existing_identities: tuple[DistributionIdentity, ...] | None = None,
    root_identity_path: Path | None = None,
    created_workspace_identity: tuple[int, int] | None = None,
    preserved_state_validator: Callable[[], None] | None = None,
) -> DistributionProcessResult:
    """Execute one journaled distribution intent through the shared service."""

    preserved_validation_active = True
    journal: OperationJournal | None = None
    boundary_workspace_identity = created_workspace_identity
    boundary_workspace_closed_set: frozenset[str] | None = None
    guard_only_plan: ExecutableMutationPlan | None = None
    guard_only_marker: DistributionRetryMarker | None = None
    boundary_journal: OperationJournal | None = None
    journal_workspace_entries: frozenset[str] | None = None

    def revalidate_guard_only_workspace(extra_entries: tuple[str, ...] = ()) -> None:
        if guard_only_plan is None or guard_only_marker is None:
            return
        _assert_fresh_guard_only_closed_set(
            target_root,
            guard_only_plan,
            guard_only_marker,
            extra_entries,
        )

    def validate_preserved_state() -> None:
        _assert_created_workspace_closed_set(
            target_root,
            boundary_workspace_identity,
            journal or boundary_journal,
            boundary_workspace_closed_set if journal is None else None,
            journal_workspace_entries,
        )
        if preserved_validation_active and preserved_state_validator is not None:
            preserved_state_validator()

    def validate_first_target_mutation() -> Callable[[], None] | None:
        validate_preserved_state()

        def commit() -> None:
            nonlocal preserved_validation_active
            preserved_validation_active = False

        return commit

    store = OperationJournalStore(
        target_root,
        identity_path=root_identity_path,
        expected_workspace_identity=created_workspace_identity,
        workspace_closed_set_validator=revalidate_guard_only_workspace,
    )
    journal_present = _path_present_no_follow(store.path)
    legacy_present = _path_present_no_follow(target_root / _DISTRIBUTION_RETRY_MARKER_REL)
    journal_seed: OperationJournal | None = None
    guard_marker = legacy_marker
    marker_read_error: DistributionAdmissionError | None = None
    operation_package_version = package_version
    version_refresh_identities = version_refreshable_existing_identities
    terminal_journal_without_guard = False
    if not journal_present and legacy_present and guard_marker is None:
        try:
            guard_marker = _read_distribution_retry_marker(target_root)
        except DistributionAdmissionError as exc:
            marker_read_error = exc
    if (
        not journal_present
        and guard_marker is not None
        and guard_marker.purpose == _journal_guard_purpose_for_intent(intent)
    ):
        operation_package_version = guard_marker.package_version
    if journal_present:
        try:
            journal_seed = store._read(_root_identity_for_assessment(target_root))
            _assert_gc_transition_graph(journal_seed)
            if intent == "fresh":
                workspace_device = journal_seed.workspace_identity.device
                workspace_inode = journal_seed.workspace_identity.inode
                if not isinstance(workspace_device, int) or not isinstance(workspace_inode, int):
                    raise DistributionApplyError("journal-protocol-incompatible")
                boundary_workspace_identity = (workspace_device, workspace_inode)
                boundary_journal = journal_seed
            if guard_marker is None:
                try:
                    guard_marker = _read_distribution_retry_marker(target_root)
                except DistributionAdmissionError as exc:
                    raise DistributionApplyError("dual-recovery-state") from exc
            terminal_journal_without_guard = journal_seed.status == "completed" and guard_marker is None
            if not terminal_journal_without_guard and (
                guard_marker is None
                or guard_marker.purpose != _journal_guard_purpose_for_intent(intent)
                or guard_marker.operation != journal_seed.intent
                or guard_marker.package_version != journal_seed.package_version
                or guard_marker.target_root != journal_seed.root_identity
                or guard_marker.last_completed_phase != "preflight-complete"
            ):
                raise DistributionApplyError("dual-recovery-state")
            if guard_marker is not None:
                store.bind_forward_guard(guard_marker)
                store._assert_guard_anchors_journal(journal_seed)
            operation_package_version = journal_seed.package_version
            journal_version_identity = _journal_version_precondition_identity(journal_seed)
            if journal_version_identity is not None:
                version_refresh_identities = (journal_version_identity,)
        except DistributionApplyError as exc:
            return DistributionProcessResult(
                status="recovery_required",
                intent=intent,
                actions=(),
                reason=str(exc),
            )
    try:
        validate_preserved_state()
    except DistributionApplyError as exc:
        return DistributionProcessResult(
            status="recovery_required",
            intent=intent,
            actions=(),
            reason=str(exc),
        )
    version_asset = _generated_regular_asset(
        "spec-dock/spec-dock.version",
        f"{operation_package_version}\n".encode(),
        mode=0o644,
        refreshable_existing_identities=version_refresh_identities,
    )
    assessment = build_workspace_assessment(
        install_root,
        manifest_path=manifest_path,
        scaffold_root=scaffold_root,
        target_root=target_root,
        intent=intent,
        generated_assets=(version_asset, *generated_assets),
    )
    if marker_read_error is not None:
        return DistributionProcessResult(
            status="recovery_required",
            intent=intent,
            actions=assessment.actions,
            reason="legacy-marker-unconvertible",
        )
    if not journal_present and not legacy_present and assessment.blockers:
        reasons = ", ".join(f"{action.path}: {action.reason}" for action in assessment.blockers)
        return DistributionProcessResult(
            status="blocked",
            intent=intent,
            actions=assessment.actions,
            reason=reasons,
        )
    if (
        not journal_present
        and not legacy_present
        and all(action.action in {"adopt", "preserve"} for action in assessment.actions)
    ):
        return DistributionProcessResult(
            status="completed",
            intent=intent,
            actions=assessment.actions,
            plan_digest=_mutation_plan_digest(assessment),
        )
    plan_digest: str | None = None
    journal = None
    legacy_marker_bytes: bytes | None = None
    legacy_marker_replaced = False
    restore_legacy_marker_on_failure = False
    try:
        if legacy_present and guard_marker is None:
            guard_marker = _read_distribution_retry_marker(target_root)
        if (
            journal_present
            and legacy_present
            and (
                journal_seed is None
                or guard_marker is None
                or guard_marker.operation != journal_seed.intent
                or guard_marker.package_version != journal_seed.package_version
                or guard_marker.target_root != journal_seed.root_identity
                or guard_marker.last_completed_phase != "preflight-complete"
            )
        ):
            raise DistributionApplyError("dual-recovery-state")
        if legacy_present:
            if not journal_present:
                executable = build_executable_mutation_plan(assessment)
                plan_digest = executable.plan_digest
                legacy_fresh_conversion = (
                    guard_marker is not None
                    and guard_marker.purpose == _DISTRIBUTION_RETRY_PURPOSE
                    and guard_marker.operation == "fresh"
                    and intent == "fresh"
                )
                if intent == "fresh" and created_workspace_identity is None:
                    assert guard_marker is not None
                    (
                        boundary_workspace_identity,
                        boundary_workspace_closed_set,
                    ) = _assert_fresh_guard_only_closed_set(target_root, executable, guard_marker)
                    store.expected_workspace_identity = boundary_workspace_identity
                    guard_only_plan = executable
                    guard_only_marker = guard_marker
                package_compatible = guard_marker is not None and (
                    guard_marker.package_version == package_version
                    if legacy_fresh_conversion
                    else _journal_package_is_compatible(guard_marker.package_version, package_version)
                )
                if (
                    guard_marker is None
                    or guard_marker.operation != intent
                    or not package_compatible
                    or guard_marker.target_root != executable.root_identity
                    or (guard_marker.last_completed_phase != "preflight-complete" and not legacy_fresh_conversion)
                ):
                    raise DistributionApplyError("legacy-marker-unconvertible")
                if guard_marker.purpose == _journal_guard_purpose_for_intent(intent):
                    if (
                        guard_marker.operation_id is None
                        or guard_marker.contract_identity != executable.contract_identity
                        or not _plan_digest_matches(executable, guard_marker.plan_digest)
                    ):
                        raise DistributionApplyError("forward-guard-plan-mismatch")
                    _validated_legacy_stage_leases(executable, guard_marker, target_root)
                    store.bind_forward_guard(guard_marker)
                    validate_preserved_state()
                    journal = store.prepare(executable, package_version=guard_marker.package_version)
                    store.workspace_closed_set_validator = None
                    guard_only_plan = None
                    guard_only_marker = None
                else:
                    legacy_stage_leases = _validated_legacy_stage_leases(executable, guard_marker, target_root)
                    store.require_journal_absent = legacy_fresh_conversion
                    restore_legacy_marker_on_failure = legacy_fresh_conversion
                    store._validate_workspace_closed_set()
                    validate_preserved_state()
                    legacy_marker_bytes = _read_no_follow_regular(
                        target_root / _DISTRIBUTION_RETRY_MARKER_REL,
                        label="distribution retry marker",
                    )
                    guard_marker = store.prepare_legacy_guard(
                        executable,
                        package_version=package_version,
                        replace_marker=guard_marker,
                        stage_ownership=legacy_stage_leases,
                    )
                    legacy_marker_replaced = True
                    guard_only_marker = guard_marker
                    store.bind_forward_guard(guard_marker)
                    validate_preserved_state()
                    journal = store.prepare(executable, package_version=package_version)
                    legacy_marker_replaced = False
                    store.require_journal_absent = False
                    store.workspace_closed_set_validator = None
                    guard_only_plan = None
                    guard_only_marker = None
            else:
                assert journal_seed is not None
                journal = store.load_for_assessment(
                    assessment,
                    package_version=package_version,
                    require_guard=not terminal_journal_without_guard,
                )
        elif journal_present:
            journal = store.load_for_assessment(
                assessment,
                package_version=package_version,
                require_guard=not terminal_journal_without_guard,
            )
        if journal_present:
            assert journal is not None
            validate_preserved_state()
            journal = _reconcile_created_parent_bindings(store, assessment, journal)
            if journal.status == "completed":
                executable = _resume_executable_plan(assessment, journal)
                if assessment.blockers or any(
                    action.action not in {"adopt", "preserve"} for action in assessment.actions
                ):
                    raise DistributionApplyError("distribution postcondition failed")
                if guard_marker is not None:
                    validate_preserved_state()
                    store.remove_legacy_marker(store._forward_guard or guard_marker)
                validate_preserved_state()
                store.remove_completed(journal, guard_already_removed=True)
                if journal.package_version != package_version and intent != "fresh":
                    return _execute_distribution_reconciliation(
                        install_root,
                        manifest_path=manifest_path,
                        scaffold_root=scaffold_root,
                        target_root=target_root,
                        intent=intent,
                        package_version=package_version,
                        generated_assets=generated_assets,
                        version_refreshable_existing_identities=(version_asset.identity,),
                        root_identity_path=root_identity_path,
                        created_workspace_identity=created_workspace_identity,
                        preserved_state_validator=(preserved_state_validator if preserved_validation_active else None),
                    )
                return DistributionProcessResult(
                    status="completed",
                    intent=intent,
                    actions=assessment.actions,
                    plan_digest=journal.plan_digest,
                )
            if journal.status == "verifying":
                executable = _resume_executable_plan(assessment, journal)
                if assessment.blockers or any(
                    action.action not in {"adopt", "preserve"} for action in assessment.actions
                ):
                    raise DistributionApplyError("distribution postcondition failed")
                validate_preserved_state()
                journal = store.mark_completed(journal)
                if guard_marker is not None:
                    validate_preserved_state()
                    store.remove_legacy_marker(store._forward_guard or guard_marker)
                validate_preserved_state()
                store.remove_completed(journal, guard_already_removed=True)
                if journal.package_version != package_version and intent != "fresh":
                    return _execute_distribution_reconciliation(
                        install_root,
                        manifest_path=manifest_path,
                        scaffold_root=scaffold_root,
                        target_root=target_root,
                        intent=intent,
                        package_version=package_version,
                        generated_assets=generated_assets,
                        version_refreshable_existing_identities=(version_asset.identity,),
                        root_identity_path=root_identity_path,
                        created_workspace_identity=created_workspace_identity,
                        preserved_state_validator=(preserved_state_validator if preserved_validation_active else None),
                    )
                return DistributionProcessResult(
                    status="completed",
                    intent=intent,
                    actions=assessment.actions,
                    plan_digest=journal.plan_digest,
                )
            reconciled = _reconcile_pending_journal_actions(assessment, journal)
            if reconciled != journal:
                validate_preserved_state()
                journal = store.write(reconciled)
            published_paths = tuple(action.path for action in journal.actions if action.checkpoint == "published")
            if any(lease.path in published_paths for lease in journal.staging_leases):
                validate_preserved_state()
                journal = store.checkpoint_published(journal, published_paths)
            executable = _resume_executable_plan(assessment, journal)
        elif journal is None:
            executable = build_executable_mutation_plan(assessment)
            validate_preserved_state()
            guard_marker = store.prepare_legacy_guard(executable, package_version=package_version)
            store.bind_forward_guard(guard_marker)
            validate_preserved_state()
            journal = store.prepare(executable, package_version=package_version)
        plan_digest = executable.plan_digest
        validate_preserved_state()
        journal = store.mark_executing(journal)
        active_journal = journal
        journal_workspace_entries = _journal_workspace_top_level_entries(active_journal)
        refreshed_assessment = build_workspace_assessment(
            install_root,
            manifest_path=manifest_path,
            scaffold_root=scaffold_root,
            target_root=target_root,
            intent=intent,
            generated_assets=(version_asset, *generated_assets),
        )
        refreshed_executable = _resume_executable_plan(refreshed_assessment, journal)

        recorded_completed: tuple[str, ...] = ()
        recorded_phase: str | None = None
        batch_fresh_progress = intent == "fresh" and all(
            record.action in {"create", "adopt", "preserve", "ensure-directory"} for record in active_journal.actions
        )

        def record_staging_lease(lease: DistributionStageOwnership) -> None:
            nonlocal active_journal, journal
            validate_preserved_state()
            active_journal = store.record_staging_lease(active_journal, lease)
            journal = active_journal

        def remove_staging_leases(path: str, stage_names: tuple[str, ...]) -> None:
            nonlocal active_journal, journal
            validate_preserved_state()
            completes_gc = any(
                lease.path == path and lease.stage_name in stage_names and lease.role == "backup-only"
                for lease in active_journal.staging_leases
            )
            retained = tuple(
                lease
                for lease in active_journal.staging_leases
                if not (
                    lease.path == path
                    and (
                        lease.stage_name in stage_names or (completes_gc and lease.role in {"gc-reserved", "gc-exact"})
                    )
                )
            )
            active_journal = store.write(
                replace(active_journal, staging_leases=retained),
                predecessor=active_journal,
            )
            journal = active_journal

        def record_created_parents(bindings: tuple[PathIdentitySnapshot, ...]) -> None:
            nonlocal active_journal, journal
            validate_preserved_state()
            active_journal = store.record_created_parent_bindings(active_journal, bindings)
            journal = active_journal

        def record_progress(
            phase: str,
            completed: tuple[str, ...],
            _pending: tuple[str, ...],
            phase_complete: bool,
        ) -> None:
            nonlocal active_journal, journal, recorded_completed, recorded_phase
            phase_boundary = phase != recorded_phase or phase_complete
            if phase_boundary:
                validate_preserved_state()
                _assert_created_parent_bindings_closed_set(target_root, active_journal)
            checkpoint_due = phase_complete or not batch_fresh_progress
            if checkpoint_due and completed != recorded_completed:
                active_journal = store.checkpoint_published(active_journal, completed)
                journal = active_journal
                recorded_completed = completed
            recorded_phase = phase

        def validate_mutation_boundary() -> None:
            validate_preserved_state()
            if intent != "fresh":
                _assert_created_parent_bindings_closed_set(target_root, active_journal)

        def validate_held_parent_boundary(path: str, parent_chain: tuple[int, ...]) -> None:
            record = next((item for item in active_journal.actions if item.path == path), None)
            if record is None:
                raise DistributionApplyError("journal-precondition-mismatch")
            parents = record.precondition.get("parents")
            if not isinstance(parents, list):
                raise DistributionApplyError("journal-precondition-mismatch")
            bindings = {item.relative_path: item for item in active_journal.created_parent_bindings}
            for index, parent in enumerate(parents, start=1):
                if not isinstance(parent, dict) or not isinstance(parent.get("relative_path"), str):
                    raise DistributionApplyError("journal-precondition-mismatch")
                binding = bindings.get(parent["relative_path"])
                if binding is None or not binding.exists:
                    continue
                if index >= len(parent_chain):
                    raise DistributionApplyError("journal-precondition-mismatch")
                _assert_created_parent_binding_fd_closed_set(
                    parent_chain[index],
                    binding.relative_path,
                    binding,
                    active_journal,
                )

        apply_distribution_plan(
            refreshed_executable.distribution_plan,
            allow_stale_stage_cleanup=bool(active_journal.staging_leases),
            stage_ownership=active_journal.staging_leases,
            stage_ownership_recorder=record_staging_lease,
            stage_ownership_remover=remove_staging_leases,
            created_parent_bindings=active_journal.created_parent_bindings,
            created_parent_recorder=record_created_parents,
            write_ahead_stage_reservations=True,
            progress_recorder=record_progress,
            before_mutation=validate_mutation_boundary,
            held_parent_validator=validate_held_parent_boundary,
            first_target_mutation_validator=validate_first_target_mutation,
        )
        # No later callback may reinterpret service-owned output as an
        # externally appeared preserved path.  Mutation paths deactivate at
        # their first namespace write; an all-adopt/preserve plan reaches this
        # boundary without a target mutation and is deactivated here.
        preserved_validation_active = False
        post = build_workspace_assessment(
            install_root,
            manifest_path=manifest_path,
            scaffold_root=scaffold_root,
            target_root=target_root,
            intent=intent,
            generated_assets=(version_asset, *generated_assets),
        )
        if post.blockers or any(action.action not in {"adopt", "preserve"} for action in post.actions):
            raise DistributionApplyError("distribution postcondition failed")
        validate_preserved_state()
        _resume_executable_plan(post, active_journal)
        active_journal = store.mark_verified(active_journal)
        validate_preserved_state()
        active_journal = store.mark_completed(active_journal)
        if guard_marker is not None:
            validate_preserved_state()
            store.remove_legacy_marker(store._forward_guard or guard_marker)
        validate_preserved_state()
        store.remove_completed(active_journal, guard_already_removed=True)
        journal = active_journal
    except Exception as caught:
        failure: Exception = caught
        if (
            restore_legacy_marker_on_failure
            and legacy_marker_replaced
            and legacy_marker_bytes is not None
            and journal is None
        ):
            try:
                store.require_journal_absent = False
                current_guard = store._forward_guard or guard_marker
                if current_guard is None:
                    raise DistributionApplyError("dual-recovery-state")
                store.restore_marker_bytes(current_guard, legacy_marker_bytes)
                legacy_marker_replaced = False
            except Exception:
                failure = DistributionApplyError("dual-recovery-state")
        if not isinstance(failure, DistributionApplyError):
            reason = "generated-state-reconciliation-failed"
        else:
            reason = str(failure)
            sensitive_paths = tuple(
                str(path) for path in (install_root, scaffold_root, target_root) if path.is_absolute()
            )
            if (
                any(path in reason for path in sensitive_paths)
                or "credential=" in reason.lower()
                or re.search(r"(?:^|[\s=])/", reason) is not None
            ):
                reason = "distribution-apply-failed"
        return DistributionProcessResult(
            status="recovery_required",
            intent=intent,
            actions=assessment.actions,
            plan_digest=plan_digest,
            reason=reason,
            applied_paths=(
                tuple(action.path for action in journal.actions if action.checkpoint != "pending")
                if journal is not None
                else ()
            ),
            pending_paths=(
                tuple(action.path for action in journal.actions if action.checkpoint == "pending")
                if journal is not None
                else ()
            ),
        )
    if operation_package_version != package_version and intent != "fresh":
        return _execute_distribution_reconciliation(
            install_root,
            manifest_path=manifest_path,
            scaffold_root=scaffold_root,
            target_root=target_root,
            intent=intent,
            package_version=package_version,
            generated_assets=generated_assets,
            version_refreshable_existing_identities=(version_asset.identity,),
            root_identity_path=root_identity_path,
            created_workspace_identity=created_workspace_identity,
            preserved_state_validator=(preserved_state_validator if preserved_validation_active else None),
        )
    return DistributionProcessResult(
        status="completed",
        intent=intent,
        actions=assessment.actions,
        plan_digest=executable.plan_digest,
    )


