def _assert_deprovision_root_bound(
    target_root: Path,
    expected: DistributionRootIdentity,
) -> None:
    if _root_identity_for_assessment(target_root) != expected:
        raise DistributionApplyError("deprovision-root-binding-mismatch")


def _assert_deprovision_preservation_witnesses(
    target_root: Path,
    witnesses: tuple[DistributionPreservationWitness, ...],
) -> None:
    for expected in witnesses:
        current, blockers = _capture_preservation_witness(target_root, expected.relative_root)
        if blockers or current is None or current != expected:
            raise DistributionApplyError(
                "deprovision-preservation-witness-mismatch",
                failed_paths=(expected.relative_root,),
            )


def _assert_deprovision_absence_witnesses(
    target_root: Path,
    witnesses: tuple[DistributionCollapsedAbsenceWitness, ...],
) -> None:
    for witness in witnesses:
        if witness.anchor_path == ".":
            anchor = _snapshot_from_stat(".", os.lstat(target_root))
        else:
            observation = _observe_target(target_root, witness.anchor_path)
            if observation.state != "directory" or observation.snapshot is None:
                raise DistributionApplyError(
                    "deprovision-absence-witness-mismatch",
                    failed_paths=(witness.relative_root,),
                )
            anchor = observation.snapshot.target
        expected_anchor = witness.surviving_anchor
        if (
            not anchor.exists
            or anchor.file_type != "directory"
            or anchor.device != expected_anchor.device
            or anchor.inode != expected_anchor.inode
            or anchor.mode != expected_anchor.mode
        ):
            raise DistributionApplyError(
                "deprovision-absence-witness-mismatch",
                failed_paths=(witness.relative_root,),
            )
        if _observe_target(target_root, witness.relative_root).state != "missing":
            raise DistributionApplyError(
                "deprovision-absence-witness-mismatch",
                failed_paths=(witness.relative_root,),
            )


def _assert_deprovision_invocation_state(
    assessment: WorkspaceAssessment,
) -> None:
    plan = assessment.distribution_plan
    if plan.target_root is None:
        raise DistributionApplyError("deprovision-root-binding-mismatch")
    _assert_deprovision_root_bound(plan.target_root, assessment.root_identity)
    try:
        _revalidate_deprovision_source_snapshots(assessment)
    except DistributionPlanError as exc:
        raise DistributionApplyError("deprovision-source-snapshot-mismatch") from exc
    _assert_deprovision_preservation_witnesses(
        plan.target_root,
        assessment.preservation_witnesses,
    )
    _assert_deprovision_absence_witnesses(
        plan.target_root,
        assessment.absence_witnesses,
    )


def _distribution_process_result_from_state(
    assessment: WorkspaceAssessment | None = None,
    journal: OperationJournal | None = None,
    *,
    state: DistributionDeprovisionServiceState = "journal",
    executable: ExecutableMutationPlan | None = None,
    plan_digest: str | None = None,
    failure_paths: tuple[str, ...] = (),
    error_code: str | None = None,
    error_message: str | None = None,
    retry_policy: DistributionRetryPolicy = "same-keep-command",
    intent: JournaledDistributionIntent = "deprovision",
    recovery_mismatch_kind: DistributionRecoveryMismatchKind = "same-intent",
) -> DistributionProcessResult:
    operation_label = "purge" if intent == "purge" else "deprovision"
    if intent == "purge" and retry_policy == "same-keep-command":
        retry_policy = "same-remove-command"
    actions = assessment.actions if assessment is not None else ()
    outcomes = _deprovision_assessment_outcomes(assessment) if assessment is not None else ()
    status: DistributionProcessStatus
    reason: str | None = None
    applied_paths: tuple[str, ...] = ()
    pending_paths: tuple[str, ...] = ()
    phase: DistributionDeprovisionPhase
    last_completed: DistributionDeprovisionCompletedPhase
    failed_paths = tuple(sorted(set(failure_paths), key=os.fsencode))
    errors: tuple[DistributionProcessError, ...] = ()
    state_failed_paths: tuple[str, ...]

    manual_recovery_states = {
        "legacy-marker",
        "legacy-marker-invalid",
        "dual-recovery-state",
        "quarantine-preserved",
    }
    journal_progress_state = state == "journal" or (journal is not None and state in manual_recovery_states)
    if journal_progress_state:
        if assessment is None or journal is None:
            raise DistributionPlanError(f"{operation_label} journal result state is incomplete")
        target_root = assessment.distribution_plan.target_root
        if target_root is None:
            raise DistributionPlanError(f"{operation_label} result state is missing its target root")
        pending_records = tuple(record for record in journal.actions if record.checkpoint == "pending")
        pending_paths = tuple(sorted({record.path for record in pending_records}, key=os.fsencode))
        if journal.status == "completed":
            phase = "marker-finalization"
            guard_path = _DISTRIBUTION_RETRY_MARKER_REL.as_posix()
            if _path_present_no_follow(target_root / guard_path):
                last_completed = "post-verified"
                state_failed_paths = (guard_path,)
            else:
                last_completed = "marker-finalized"
                state_failed_paths = (_DISTRIBUTION_JOURNAL_REL.as_posix(),)
        elif journal.status == "verifying" or not pending_records:
            phase = "post-verify"
            last_completed = "uninstall-applied"
            state_failed_paths = pending_paths
        elif any(record.action == "prune" for record in pending_records):
            phase = "uninstall-apply"
            last_completed = "marker-written"
            state_failed_paths = pending_paths
        else:
            phase = "root-cleanup"
            last_completed = "uninstall-applied"
            state_failed_paths = pending_paths
        failed_paths = tuple(
            sorted(
                {*state_failed_paths, *failure_paths, *pending_paths},
                key=os.fsencode,
            )
        )
        failure_path_set = set(failure_paths)
        checkpoints = {record.path: record.checkpoint for record in journal.actions}
        journal_outcomes: list[DistributionActionOutcome] = []
        for outcome in outcomes:
            checkpoint = checkpoints.get(outcome.path)
            if outcome.path in failure_path_set:
                journal_outcomes.append(
                    replace(
                        outcome,
                        status="failed",
                        error=f"Managed distribution {operation_label} action failed.",
                    )
                )
            elif checkpoint is None:
                journal_outcomes.append(outcome)
            elif checkpoint == "pending":
                journal_outcomes.append(replace(outcome, status="pending"))
            elif outcome.category == "empty_dir":
                journal_outcomes.append(replace(outcome, status="empty_dir_removed"))
            else:
                journal_outcomes.append(replace(outcome, status="removed"))
        outcomes = tuple(journal_outcomes)
        status = "recovery_required"
        plan_digest = journal.plan_digest
        reason = f"{operation_label}-recovery-required"
        applied_paths = tuple(record.path for record in journal.actions if record.checkpoint != "pending")
        errors = (
            DistributionProcessError(
                code=f"{operation_label}-recovery-required",
                message=f"Managed distribution {operation_label} recovery is required.",
            ),
        )
        if state in manual_recovery_states:
            if state == "legacy-marker":
                status = "recovery_required"
                reason = "legacy-marker-unconvertible"
                errors = (
                    DistributionProcessError(
                        code="legacy-marker-unconvertible",
                        message="Legacy uninstall recovery requires manual review.",
                    ),
                )
            elif state == "legacy-marker-invalid":
                status = "error"
                reason = "legacy-marker-invalid"
                errors = (
                    DistributionProcessError(
                        code="legacy-marker-invalid",
                        message="Legacy uninstall recovery evidence is invalid.",
                    ),
                )
            elif state == "dual-recovery-state":
                status = "recovery_required"
                reason = "dual-recovery-state"
                errors = (
                    DistributionProcessError(
                        code="dual-recovery-state",
                        message="Conflicting uninstall recovery evidence requires manual review.",
                    ),
                )
            retry_policy = "manual-recovery"
    elif state == "eligibility-error":
        status = "error"
        retry_policy = "none"
        phase = "preflight"
        last_completed = "not-started"
        reason = error_code or f"{operation_label}-preflight-failed"
        errors = (
            DistributionProcessError(
                code=reason,
                message=error_message or f"Managed distribution {operation_label} preflight failed.",
            ),
        )
    elif state == "planned":
        if assessment is None:
            raise DistributionPlanError(f"{operation_label} planned result state is incomplete")
        status = "planned"
        phase = "preflight"
        last_completed = "preflight-complete"
    elif state == "blocked":
        if assessment is None:
            raise DistributionPlanError(f"{operation_label} blocked result state is incomplete")
        status = "blocked"
        phase = "preflight"
        last_completed = "preflight-complete"
        reason = error_code or f"{operation_label}-preflight-blocked"
        failed_paths = tuple(
            sorted(
                {
                    *failed_paths,
                    *(action.path for action in assessment.blockers),
                },
                key=os.fsencode,
            )
        )
        errors = (
            DistributionProcessError(
                code=reason,
                message=error_message or f"Managed distribution {operation_label} is blocked by preserved state.",
            ),
        )
    elif state == "legacy-marker":
        status = "recovery_required"
        phase = "preflight"
        last_completed = "not-started"
        reason = "legacy-marker-unconvertible"
        failed_paths = (_UNINSTALL_RETRY_MARKER_REL.as_posix(),)
        errors = (
            DistributionProcessError(
                code="legacy-marker-unconvertible",
                message="Legacy uninstall recovery requires manual review.",
            ),
        )
        retry_policy = "manual-recovery"
    elif state == "legacy-marker-invalid":
        status = "error"
        phase = "preflight"
        last_completed = "not-started"
        reason = "legacy-marker-invalid"
        failed_paths = (_UNINSTALL_RETRY_MARKER_REL.as_posix(),)
        errors = (
            DistributionProcessError(
                code="legacy-marker-invalid",
                message="Legacy uninstall recovery evidence is invalid.",
            ),
        )
        retry_policy = "manual-recovery"
    elif state == "dual-recovery-state":
        status = "recovery_required"
        phase = "preflight"
        last_completed = "not-started"
        reason = "dual-recovery-state"
        errors = (
            DistributionProcessError(
                code="dual-recovery-state",
                message="Conflicting uninstall recovery evidence requires manual review.",
            ),
        )
        retry_policy = "manual-recovery"
    elif state == "quarantine-preserved":
        if assessment is None or executable is None:
            raise DistributionPlanError(f"{operation_label} quarantine-preserved result state is incomplete")
        status = "recovery_required"
        phase = "marker-write"
        last_completed = "marker-written"
        reason = f"{operation_label}-guard-only"
        plan_digest = executable.plan_digest
        pending_paths = tuple(sorted({action.path for action in executable.actions}, key=os.fsencode))
        failed_paths = tuple(
            sorted(
                {
                    *failed_paths,
                    *pending_paths,
                    _DISTRIBUTION_JOURNAL_REL.as_posix(),
                },
                key=os.fsencode,
            )
        )
        errors = (
            DistributionProcessError(
                code=f"{operation_label}-recovery-required",
                message=f"Managed distribution {operation_label} recovery is required.",
            ),
        )
        retry_policy = "manual-recovery"
    elif state == "recovery-mismatch":
        status = "recovery_required"
        phase = "preflight"
        last_completed = "not-started"
        reason = f"{operation_label}-recovery-mismatch"
        errors = (
            DistributionProcessError(
                code=f"{operation_label}-recovery-mismatch",
                message=f"Managed distribution {operation_label} recovery evidence does not match.",
            ),
        )
        if intent == "purge" or recovery_mismatch_kind == "intent-authority":
            retry_policy = "manual-recovery"
    elif state == "guard-only":
        if assessment is None or executable is None:
            raise DistributionPlanError(f"{operation_label} guard-only result state is incomplete")
        status = "recovery_required"
        phase = "marker-write"
        last_completed = "marker-written"
        reason = f"{operation_label}-guard-only"
        plan_digest = executable.plan_digest
        pending_paths = tuple(sorted({action.path for action in executable.actions}, key=os.fsencode))
        pending_set = set(pending_paths)
        outcomes = tuple(
            replace(outcome, status="pending") if outcome.path in pending_set else outcome for outcome in outcomes
        )
        failed_paths = tuple(
            sorted(
                {
                    *failed_paths,
                    *pending_paths,
                    _DISTRIBUTION_JOURNAL_REL.as_posix(),
                },
                key=os.fsencode,
            )
        )
        errors = (
            DistributionProcessError(
                code=f"{operation_label}-recovery-required",
                message=f"Managed distribution {operation_label} recovery is required.",
            ),
        )
    elif state == "mutating-success":
        if assessment is None or executable is None:
            raise DistributionPlanError(f"{operation_label} success result state is incomplete")
        status = "completed"
        phase = "complete"
        last_completed = "marker-finalized"
        plan_digest = executable.plan_digest
        applied_paths = tuple(action.path for action in executable.actions)
        outcomes = _deprovision_assessment_outcomes(assessment, applied=True)
        if intent == "purge":
            retry_policy = "none"
    elif state == "no-op-success":
        if assessment is None:
            raise DistributionPlanError("deprovision no-op result state is incomplete")
        status = "completed"
        phase = "complete"
        last_completed = "post-verified"
        if intent == "purge":
            retry_policy = "none"
    else:
        raise DistributionPlanError(f"unsupported {operation_label} result state")

    if intent == "purge" and assessment is not None:
        outcomes = _explicit_spec_history_purge_outcomes(
            assessment,
            outcomes,
            include_absent=state in {"mutating-success", "no-op-success"},
        )
    result = DistributionProcessResult(
        status=status,
        intent=intent,
        actions=actions,
        plan_digest=plan_digest,
        reason=reason,
        applied_paths=applied_paths,
        pending_paths=pending_paths,
        action_outcomes=outcomes,
        phase=phase,
        last_completed_phase=last_completed,
        failed_paths=failed_paths,
        errors=errors,
        retry_policy=retry_policy,
    )
    _validate_deprovision_process_result(result, intent=intent)
    return result


def _validate_deprovision_process_result(
    result: DistributionProcessResult,
    *,
    intent: JournaledDistributionIntent = "deprovision",
) -> None:
    operation_label = "purge" if intent == "purge" else "deprovision"
    if (
        result.intent != intent
        or result.phase is None
        or result.last_completed_phase is None
        or result.pending_paths != tuple(sorted(set(result.pending_paths), key=os.fsencode))
        or result.failed_paths != tuple(sorted(set(result.failed_paths), key=os.fsencode))
        or not set(result.pending_paths).issubset(result.failed_paths)
    ):
        raise DistributionPlanError(f"{operation_label} result population is incomplete")
    if result.status in {"planned", "completed"}:
        if result.errors or result.failed_paths or result.pending_paths:
            raise DistributionPlanError(f"{operation_label} success result contains failure state")
    elif not result.errors:
        raise DistributionPlanError(f"{operation_label} failure result is missing its operation error")


def _assert_deprovision_directory_dependencies_published(
    journal: OperationJournal,
    record: OperationJournalAction,
) -> tuple[DistributionImmediateChildEvidence, ...]:
    raw_evidence = record.precondition.get("immediate_child_evidence")
    if not isinstance(raw_evidence, list):
        raise DistributionApplyError("journal-precondition-mismatch")
    records = {item.path: item for item in journal.actions}
    evidence: list[DistributionImmediateChildEvidence] = []
    for item in raw_evidence:
        if not isinstance(item, dict):
            raise DistributionApplyError("journal-precondition-mismatch")
        child_path = item.get("child_path")
        child_kind = item.get("child_kind")
        action_path = item.get("action_path")
        child = records.get(cast("str", action_path))
        if (
            not isinstance(child_path, str)
            or child_kind not in {"leaf", "directory"}
            or action_path != child_path
            or child is None
            or child.checkpoint != "published"
            or item.get("required_checkpoint") != "published"
            or item.get("expected_postcondition") != {"path": child_path, "exists": False}
        ):
            raise DistributionApplyError("journal-precondition-mismatch")
        evidence.append(
            DistributionImmediateChildEvidence(
                child_path=child_path,
                child_kind=cast("DistributionDirectoryChildKind", child_kind),
                action_path=child_path,
                required_checkpoint="published",
                expected_postcondition={"path": child_path, "exists": False},
            )
        )
    return tuple(evidence)


def _leaf_namespace_entry_matches_protocol(
    entry: DistributionTreeEntrySnapshot,
    *,
    expected_path: str,
    expected_snapshot: DistributionSourceSnapshot | PathIdentitySnapshot | None,
    expected_sha256: str | None,
) -> bool:
    return not (
        expected_snapshot is None
        or expected_sha256 is None
        or entry.relative_path != expected_path
        or entry.kind != "regular"
        or entry.device != expected_snapshot.device
        or entry.inode != expected_snapshot.inode
        or entry.ctime_ns != expected_snapshot.ctime_ns
        or entry.mode != expected_snapshot.mode
        or entry.link_count != 1
        or entry.size != expected_snapshot.size
        or entry.sha256 != expected_sha256
        or entry.link_target is not None
    )


def _leaf_namespace_entry_matches_lease(
    entry: DistributionTreeEntrySnapshot,
    *,
    parent_path: str,
    expected_entry: DistributionTreeEntrySnapshot | None,
    lease: DistributionStageOwnership,
) -> bool:
    expected_path = f"{parent_path}/{lease.stage_name}"
    if (
        expected_entry is None
        or entry.relative_path != expected_path
        or entry.kind != lease.file_type
        or entry.device != lease.device
        or entry.inode != lease.inode
        or entry.kind != expected_entry.kind
        or entry.mode != expected_entry.mode
    ):
        return False
    if lease.role == "backup-dual":
        if entry.link_count != 2:
            return False
    elif lease.role == "backup-only":
        if entry.link_count != 1:
            return False
    elif lease.role == "predecessor-quarantine":
        # Creating the independent backup hardlink changes both ctime and
        # link_count after the predecessor lease was durably recorded.  The
        # inode and content identity remain exact, while the operation-owned
        # transition may legitimately expose one or two links here.
        if entry.link_count not in {1, 2}:
            return False
    elif lease.role in {"gc-reserved", "gc-exact"}:
        # GC may briefly retain a second operation-owned hardlink while the
        # predecessor and its next private name are both journaled.
        if entry.link_count not in {1, 2}:
            return False
    elif entry.link_count != 1:
        return False
    if entry.kind == "regular":
        return entry.size == expected_entry.size and entry.sha256 == expected_entry.sha256 and entry.link_target is None
    return entry.size is None and entry.sha256 is None and entry.link_target == expected_entry.link_target


def _assert_deprovision_leaf_parent_namespace(
    parent_fd: int,
    path: str,
    *,
    leaf_parent_namespace_witnesses: dict[str, DistributionLeafParentNamespaceWitness],
    journal: OperationJournal,
    forward_guard: DistributionRetryMarker | None = None,
    durably_quarantined_paths: frozenset[str] = frozenset(),
    owned_zero_predecessor_paths: frozenset[str] = frozenset(),
    pending_absent_paths: frozenset[str] = frozenset(),
) -> None:
    """Reject any semantic immediate-child namespace change before a leaf mutation."""

    parent_path = PurePosixPath(path).parent.as_posix()
    if parent_path == ".":
        return
    witness = leaf_parent_namespace_witnesses.get(parent_path)
    if witness is None:
        raise DistributionApplyError(
            "deprovision-parent-namespace-mismatch",
            failed_paths=(parent_path,),
        )
    try:
        held = os.fstat(parent_fd)
        if (
            not stat.S_ISDIR(held.st_mode)
            or stat.S_ISLNK(held.st_mode)
            or held.st_dev != witness.binding.device
            or held.st_ino != witness.binding.inode
            or stat.S_IMODE(held.st_mode) != witness.binding.mode
        ):
            raise DistributionApplyError(
                "deprovision-parent-namespace-mismatch",
                failed_paths=(parent_path,),
            )
        _binding, captured_entries = _capture_immediate_directory_entries_from_fd(parent_fd, parent_path)
    except DistributionApplyError:
        raise
    except (_PreservationCaptureError, OSError, DistributionPlanError) as exc:
        raise DistributionApplyError(
            "deprovision-parent-namespace-mismatch",
            failed_paths=(parent_path,),
        ) from exc

    expected_entries = {entry.relative_path: entry for entry in witness.initial_entries}
    actual_entries = {entry.relative_path: entry for entry in captured_entries}

    # Protocol entries are operation-owned metadata, not target namespace
    # authority.  They must still match their held, content-bound identities.
    if parent_path == "spec-dock":
        protocol_records = (
            (
                _DISTRIBUTION_RETRY_MARKER_REL.as_posix(),
                forward_guard.source_snapshot if forward_guard is not None else None,
                forward_guard.source_sha256 if forward_guard is not None else None,
            ),
            (
                _DISTRIBUTION_JOURNAL_REL.as_posix(),
                journal.source_snapshot,
                journal.source_sha256,
            ),
        )
        for protocol_path, source_snapshot, source_sha256 in protocol_records:
            protocol_entry = actual_entries.pop(protocol_path, None)
            if protocol_entry is None or not _leaf_namespace_entry_matches_protocol(
                protocol_entry,
                expected_path=protocol_path,
                expected_snapshot=source_snapshot,
                expected_sha256=source_sha256,
            ):
                raise DistributionApplyError(
                    "deprovision-parent-namespace-mismatch",
                    failed_paths=(parent_path,),
                )
            expected_entries.pop(protocol_path, None)

    # A zero reservation is intentionally not a namespace allowlist entry.  A
    # nonzero lease is accepted only when the exact leased stage is present.
    leases = tuple(
        lease for lease in journal.staging_leases if PurePosixPath(lease.path).parent.as_posix() == parent_path
    )

    def has_exact_operation_replacement(
        lease: DistributionStageOwnership,
        expected_entry: DistributionTreeEntrySnapshot | None,
    ) -> bool:
        if expected_entry is None:
            return False
        for replacement in leases:
            if (
                replacement is lease
                or replacement.device != lease.device
                or replacement.inode != lease.inode
                or replacement.file_type != lease.file_type
            ):
                continue
            replacement_entry = actual_entries.get(f"{parent_path}/{replacement.stage_name}")
            if replacement_entry is not None and _leaf_namespace_entry_matches_lease(
                replacement_entry,
                parent_path=parent_path,
                expected_entry=expected_entry,
                lease=replacement,
            ):
                return True
        return False

    for lease in leases:
        stage_path = f"{parent_path}/{lease.stage_name}"
        stage_entry = actual_entries.get(stage_path)
        if lease.device == lease.inode == lease.ctime_ns == 0:
            if stage_entry is not None:
                if lease.path in owned_zero_predecessor_paths:
                    record = next(
                        (item for item in journal.actions if item.path == lease.path and item.action == "prune"),
                        None,
                    )
                    if record is not None and _leaf_namespace_entry_matches_precondition_semantic(
                        stage_entry,
                        record.precondition,
                    ):
                        actual_entries.pop(stage_path, None)
                        durably_quarantined_paths = frozenset((*durably_quarantined_paths, lease.path))
                        continue
                raise DistributionApplyError(
                    "deprovision-parent-namespace-mismatch",
                    failed_paths=(parent_path,),
                )
            continue
        if stage_entry is None:
            if lease.role == "predecessor-quarantine" and lease.path in durably_quarantined_paths:
                # The predecessor may already have been durably unlinked after
                # an exact backup was retained.  The invocation-local marker
                # permits only that exact nonzero predecessor to be absent; it
                # never authorizes an arbitrary sibling.
                continue
            if has_exact_operation_replacement(lease, expected_entries.get(lease.path)):
                # GC moves an operation-owned backup through a private name
                # while its prior lease remains durable.  Accept only the
                # exact same no-follow inode under the recorded GC lease.
                continue
        expected_entry = expected_entries.get(lease.path)
        if stage_entry is None or not _leaf_namespace_entry_matches_lease(
            stage_entry,
            parent_path=parent_path,
            expected_entry=expected_entry,
            lease=lease,
        ):
            raise DistributionApplyError(
                "deprovision-parent-namespace-mismatch",
                failed_paths=(parent_path,),
            )
        actual_entries.pop(stage_path, None)
        expected_entries.pop(stage_path, None)

    published_paths = {
        record.path
        for record in journal.actions
        if record.checkpoint != "pending" and PurePosixPath(record.path).parent.as_posix() == parent_path
    }
    for published_path in published_paths:
        expected_entries.pop(published_path, None)
    for quarantined_path in durably_quarantined_paths:
        if PurePosixPath(quarantined_path).parent.as_posix() == parent_path:
            expected_entries.pop(quarantined_path, None)
    for absent_path in pending_absent_paths:
        if PurePosixPath(absent_path).parent.as_posix() == parent_path:
            expected_entries.pop(absent_path, None)

    expected_semantics = {
        relative_path: _directory_child_semantic_payload(
            entry,
            classification="namespace",
            owner_source="leaf-parent-namespace",
        )
        for relative_path, entry in expected_entries.items()
    }
    actual_semantics = {
        relative_path: _directory_child_semantic_payload(
            entry,
            classification="namespace",
            owner_source="leaf-parent-namespace",
        )
        for relative_path, entry in actual_entries.items()
    }
    if expected_semantics != actual_semantics:
        raise DistributionApplyError(
            "deprovision-parent-namespace-mismatch",
            failed_paths=(parent_path,),
        )


def _deprovision_directory_snapshot_from_record(
    record: OperationJournalAction,
) -> DistributionDirectoryMutationSnapshot:
    precondition = record.precondition
    if record.action != "remove-empty-directory":
        raise DistributionApplyError("journal-precondition-mismatch")
    try:
        binding = PathIdentitySnapshot(
            relative_path=record.path,
            exists=True,
            device=cast("int", precondition["device"]),
            inode=cast("int", precondition["inode"]),
            ctime_ns=cast("int", precondition["ctime_ns"]),
            file_type="directory",
            link_count=cast("int", precondition["link_count"]),
            mode=cast("int", precondition["mode"]),
        )
        initial_child_digest = cast("str", precondition["initial_child_digest"])
        expected_remaining_child_digest = cast(
            "str",
            precondition["expected_remaining_child_digest"],
        )
        raw_evidence = cast("list[dict[str, object]]", precondition["immediate_child_evidence"])
    except (KeyError, TypeError) as exc:
        raise DistributionApplyError("journal-precondition-mismatch") from exc
    evidence = tuple(
        DistributionImmediateChildEvidence(
            child_path=cast("str", item["child_path"]),
            child_kind=cast("DistributionDirectoryChildKind", item["child_kind"]),
            action_path=cast("str", item["action_path"]),
            required_checkpoint="published",
            expected_postcondition=cast("dict[str, object]", item["expected_postcondition"]),
        )
        for item in raw_evidence
    )
    return DistributionDirectoryMutationSnapshot(
        relative_path=record.path,
        binding=binding,
        initial_entries=(),
        initial_child_digest=initial_child_digest,
        immediate_child_evidence=evidence,
        expected_remaining_child_digest=expected_remaining_child_digest,
    )


def _deprovision_path_snapshot_from_condition(
    value: object,
    *,
    expected_path: str,
) -> PathIdentitySnapshot:
    if (
        not isinstance(value, dict)
        or set(value) != {"relative_path", "exists", "device", "inode", "ctime_ns", "file_type", "link_count", "mode"}
        or value.get("relative_path") != expected_path
        or value.get("exists") is not True
        or value.get("file_type") != "directory"
        or any(not isinstance(value.get(field), int) for field in ("device", "inode", "ctime_ns", "link_count", "mode"))
        or any(isinstance(value.get(field), bool) for field in ("device", "inode", "ctime_ns", "link_count", "mode"))
    ):
        raise DistributionApplyError("journal-precondition-mismatch")
    return PathIdentitySnapshot(
        relative_path=expected_path,
        exists=True,
        device=cast("int", value["device"]),
        inode=cast("int", value["inode"]),
        ctime_ns=cast("int", value["ctime_ns"]),
        file_type="directory",
        link_count=cast("int", value["link_count"]),
        mode=cast("int", value["mode"]),
    )


def _deprovision_record_parent_bindings(
    record: OperationJournalAction,
) -> tuple[PathIdentitySnapshot, tuple[PathIdentitySnapshot, ...]]:
    precondition = record.precondition
    root = _deprovision_path_snapshot_from_condition(precondition.get("root"), expected_path=".")
    raw_parents = precondition.get("parents")
    if not isinstance(raw_parents, list):
        raise DistributionApplyError("journal-precondition-mismatch")
    parents = tuple(
        _deprovision_path_snapshot_from_condition(
            raw_parent,
            expected_path="/".join(PurePosixPath(record.path).parts[:index]),
        )
        for index, raw_parent in enumerate(raw_parents, start=1)
    )
    return root, parents


def _assert_deprovision_pending_parent_chain_matches(
    snapshot: DistributionTargetSnapshot,
    record: OperationJournalAction,
) -> None:
    expected_root, expected_parents = _deprovision_record_parent_bindings(record)
    if snapshot.root.relative_path != expected_root.relative_path or not _same_structure_identity(
        snapshot.root,
        expected_root,
    ):
        raise DistributionApplyError("journal-precondition-mismatch")
    if len(snapshot.parents) != len(expected_parents) or any(
        actual.relative_path != expected.relative_path or not _same_structure_identity(actual, expected)
        for actual, expected in zip(snapshot.parents, expected_parents, strict=True)
    ):
        raise DistributionApplyError("journal-precondition-mismatch")


def _deprovision_pending_snapshot_is_exact_absence(
    snapshot: DistributionTargetSnapshot,
    record: OperationJournalAction,
) -> bool:
    """Accept only the journaled postcondition after a pre-checkpoint unlink."""

    if record.action not in {"prune", "remove-empty-directory"} or snapshot.target.exists:
        return False
    precondition = record.precondition
    postcondition = record.postcondition
    if (
        precondition.get("exists") is not True
        or set(postcondition) != {"root", "parents", "exists", "identity"}
        or postcondition.get("exists") is not False
        or postcondition.get("identity") is not None
        or postcondition.get("root") != precondition.get("root")
        or postcondition.get("parents") != precondition.get("parents")
    ):
        return False
    try:
        _assert_deprovision_pending_parent_chain_matches(snapshot, record)
    except DistributionApplyError:
        return False
    return True


def _deprovision_recovery_pending_target_is_exact_absent(
    target_root: Path,
    record: OperationJournalAction,
) -> bool:
    observation = _observe_target(target_root, record.path)
    return observation.snapshot is not None and _deprovision_pending_snapshot_is_exact_absence(
        observation.snapshot,
        record,
    )


def _assert_deprovision_pending_record_matches(
    target_root: Path,
    record: OperationJournalAction,
) -> DistributionTargetSnapshot:
    observation = _observe_target(target_root, record.path)
    if observation.snapshot is None:
        raise DistributionApplyError("journal-precondition-mismatch")
    snapshot = observation.snapshot
    if _deprovision_pending_snapshot_is_exact_absence(snapshot, record):
        return snapshot
    if not snapshot.target.exists:
        raise DistributionApplyError("journal-precondition-mismatch")
    if record.action == "prune":
        if not _snapshot_matches_condition(snapshot, record.precondition, ()):
            raise DistributionApplyError("journal-precondition-mismatch")
        _assert_deprovision_pending_parent_chain_matches(snapshot, record)
        return snapshot
    target = snapshot.target
    if (
        observation.state != "directory"
        or not target.exists
        or target.device != record.precondition.get("device")
        or target.inode != record.precondition.get("inode")
        or target.file_type != "directory"
        or target.mode != record.precondition.get("mode")
    ):
        raise DistributionApplyError("journal-precondition-mismatch")
    _assert_deprovision_pending_parent_chain_matches(snapshot, record)
    return snapshot


def _assert_deprovision_published_summaries(
    target_root: Path,
    journal: OperationJournal,
) -> None:
    published_directories = {
        record.path
        for record in journal.actions
        if record.action == "remove-empty-directory" and record.checkpoint != "pending"
    }
    for record in journal.actions:
        if record.checkpoint == "pending":
            continue
        if any(
            record.path != directory and _is_same_or_descendant(record.path, directory)
            for directory in published_directories
        ):
            continue
        if _observe_target(target_root, record.path).state != "missing":
            raise DistributionApplyError("journal-precondition-mismatch")


def _assert_deprovision_terminal_bindings(
    target_root: Path,
    journal: OperationJournal,
) -> None:
    """Verify every surviving root/parent binding before completion."""

    expected_bindings: dict[str, PathIdentitySnapshot] = {
        journal.workspace_identity.relative_path: journal.workspace_identity,
    }
    removed_directories = {
        record.path
        for record in journal.actions
        if record.action == "remove-empty-directory" and record.checkpoint != "pending"
    }
    for record in journal.actions:
        expected_root, expected_parents = _deprovision_record_parent_bindings(record)
        for binding in (expected_root, *expected_parents):
            prior = expected_bindings.get(binding.relative_path)
            if prior is not None and not _same_structure_identity(prior, binding):
                raise DistributionApplyError(
                    "deprovision-terminal-binding-mismatch",
                    failed_paths=(binding.relative_path,),
                )
            expected_bindings[binding.relative_path] = binding

    for witness in journal.absence_witnesses:
        binding = witness.surviving_anchor
        prior = expected_bindings.get(binding.relative_path)
        if prior is not None and not _same_structure_identity(prior, binding):
            raise DistributionApplyError(
                "deprovision-terminal-binding-mismatch",
                failed_paths=(binding.relative_path,),
            )
        expected_bindings[binding.relative_path] = binding

    for relative_path, expected in expected_bindings.items():
        if relative_path in removed_directories or any(
            _is_same_or_descendant(relative_path, directory) for directory in removed_directories
        ):
            continue
        actual: PathIdentitySnapshot | None
        if relative_path == ".":
            try:
                actual = _snapshot_from_stat(relative_path, os.lstat(target_root))
            except OSError:
                actual = _missing_snapshot(relative_path)
            is_missing = not actual.exists
        else:
            observation = _observe_target(target_root, relative_path)
            actual = observation.snapshot.target if observation.snapshot is not None else None
            is_missing = observation.state == "missing"
        if is_missing and relative_path in removed_directories:
            continue
        if actual is None or not _same_structure_identity(actual, expected):
            raise DistributionApplyError(
                "deprovision-terminal-binding-mismatch",
                failed_paths=(relative_path,),
            )


def _deprovision_recovery_target_only_assets(
    journal: OperationJournal,
) -> tuple[DistributionAsset, ...]:
    """Recover target-only identity from the immutable journal precondition."""

    records = tuple(record for record in journal.actions if record.path == "spec-dock/spec-dock.version")
    if not records:
        return ()
    if len(records) != 1 or records[0].action != "prune":
        raise DistributionApplyError("journal-contract-mismatch")
    precondition = records[0].precondition
    if precondition.get("exists") is not True:
        raise DistributionApplyError("journal-contract-mismatch")
    raw_identity = precondition.get("identity")
    if (
        not isinstance(raw_identity, dict)
        or set(raw_identity) != {"kind", "sha256", "mode", "target"}
        or raw_identity.get("kind") != "regular"
        or not isinstance(raw_identity.get("sha256"), str)
        or _SHA256_RE.fullmatch(raw_identity["sha256"]) is None
        or not isinstance(raw_identity.get("mode"), int)
        or isinstance(raw_identity["mode"], bool)
        or raw_identity["mode"] < 0
        or raw_identity.get("target") is not None
    ):
        raise DistributionApplyError("journal-contract-mismatch")
    return (
        DistributionAsset(
            path="spec-dock/spec-dock.version",
            identity=DistributionIdentity(
                kind="regular",
                sha256=raw_identity["sha256"],
                mode=raw_identity["mode"],
            ),
        ),
    )


def _assert_deprovision_recovery_contract_identity(
    contract: DistributionDeprovisionContract,
    journal: OperationJournal,
) -> None:
    """Reject manifest/catalog drift while tolerating target-side progress."""

    if contract.manifest is None or journal.generated_state_contract_digest is None:
        raise DistributionApplyError("journal-contract-mismatch")
    if contract.generated_state.contract_digest != journal.generated_state_contract_digest:
        raise DistributionApplyError("journal-contract-mismatch")
    target_only_assets = _deprovision_recovery_target_only_assets(journal)
    digest = _deprovision_contract_digest(
        physical_assets=contract.managed_assets,
        shortcuts=contract.removable_shortcuts,
        target_only_assets=target_only_assets,
        managed_roots=contract.managed_roots,
        preserved_roots=contract.preserved_roots,
        generated_state_digest=journal.generated_state_contract_digest,
        manifest=contract.manifest,
    )
    if digest != journal.contract_identity:
        raise DistributionApplyError("journal-contract-mismatch")


def _assert_explicit_spec_history_purge_recovery_contract_identity(
    contract: DistributionExplicitSpecHistoryPurgeContract,
    journal: OperationJournal,
) -> None:
    """Validate the purge envelope without treating it as a deprovision contract."""

    if journal.intent != "purge" or journal.authority != contract.authority:
        raise DistributionApplyError("journal-contract-mismatch")
    component = contract.deprovision_contract
    if component.manifest is None or journal.generated_state_contract_digest is None:
        raise DistributionApplyError("journal-contract-mismatch")
    if component.generated_state.contract_digest != journal.generated_state_contract_digest:
        raise DistributionApplyError("journal-contract-mismatch")
    if component.source_semantic_identities != journal.source_semantic_identities:
        raise DistributionApplyError("journal-contract-mismatch")
    target_only_assets = _deprovision_recovery_target_only_assets(journal)
    component_digest = _deprovision_contract_digest(
        physical_assets=component.managed_assets,
        shortcuts=component.removable_shortcuts,
        target_only_assets=target_only_assets,
        managed_roots=component.managed_roots,
        preserved_roots=component.preserved_roots,
        generated_state_digest=journal.generated_state_contract_digest,
        manifest=component.manifest,
    )
    if component_digest != component.contract_digest:
        raise DistributionApplyError("journal-contract-mismatch")
    root_binding, entries, tree_digest = _reconstruct_explicit_spec_history_purge_tree(journal)
    if (
        contract.history_root != _EXPLICIT_SPEC_HISTORY_ROOT
        or contract.history_root_binding != root_binding
        or contract.history_entries != entries
        or contract.history_tree_digest != tree_digest
        or contract.contract_digest
        != _explicit_spec_history_purge_contract_digest(
            deprovision_contract=component,
            history_root=contract.history_root,
            history_tree_digest=contract.history_tree_digest,
        )
        or contract.contract_digest != journal.contract_identity
    ):
        raise DistributionApplyError("journal-contract-mismatch")


def _deprovision_recovery_record_identity(
    record: OperationJournalAction,
) -> DistributionIdentity:
    precondition = record.precondition
    raw_identity = precondition.get("identity")
    kind = precondition.get("file_type")
    if kind not in {"regular", "symlink"} or not isinstance(raw_identity, dict):
        raise DistributionApplyError("journal-plan-mismatch")
    identity = DistributionIdentity(
        kind=cast("str", kind),
        sha256=raw_identity.get("sha256"),
        mode=raw_identity.get("mode"),
        target=raw_identity.get("target"),
    )
    if _distribution_identity_payload(identity) != raw_identity:
        raise DistributionApplyError("journal-plan-mismatch")
    if identity.kind == "regular" and precondition.get("mode") != identity.mode:
        raise DistributionApplyError("journal-plan-mismatch")
    return identity


def _deprovision_recovery_identity_matches(
    actual: DistributionIdentity,
    expected: DistributionIdentity,
) -> bool:
    if actual.kind != expected.kind:
        return False
    if actual.kind == "regular":
        return actual.sha256 == expected.sha256 and actual.mode == expected.mode
    return actual.target == expected.target


def _deprovision_recovery_historical_provenance(
    target_root: Path,
    path: str,
    identity: DistributionIdentity,
    manifest: DistributionManifest,
    journal: OperationJournal,
) -> str | None:
    if any(
        record["path"] == path and _removal_identity_matches(identity, record)
        for record in _historical_records(manifest)
    ):
        return "direct"
    if _trusted_manifest_matches(target_root, path, identity, manifest, require_mode=True):
        return "trusted-manifest"

    # A trusted envelope may itself already be published away by the time a
    # later claim is reconciled.  Its strict journal precondition is the
    # durable envelope witness in that case.
    action_by_path = {record.path: record for record in journal.actions}
    for trusted in manifest.trusted_consumer_manifests:
        if not any(claim["path"] == path and _removal_identity_matches(identity, claim) for claim in trusted["claims"]):
            continue
        envelope_action = action_by_path.get(trusted["path"])
        if envelope_action is None or envelope_action.action != "prune":
            continue
        envelope_identity = _deprovision_recovery_record_identity(envelope_action)
        if _removal_identity_matches(envelope_identity, trusted):
            return "trusted-manifest"
    return None


def _validate_deprovision_recovery_action_semantics(
    target_root: Path,
    contract: DistributionDeprovisionContract,
    journal: OperationJournal,
) -> None:
    """Keep journal action authority aligned with the canonical contract."""

    manifest = contract.manifest
    if manifest is None:
        raise DistributionApplyError("journal-contract-mismatch")
    target_only_assets = _deprovision_recovery_target_only_assets(journal)
    current_assets = (
        *contract.managed_assets,
        *contract.removable_shortcuts,
        *contract.target_only_assets,
        *target_only_assets,
    )
    current_identities = {asset.path: asset.identity for asset in current_assets}
    current_sizes = {
        asset.path: asset.source_snapshot.size for asset in current_assets if asset.source_snapshot is not None
    }
    for entry in contract.generated_state.entries:
        current_identities[entry.path] = entry.identity
        if entry.observed.size is not None:
            current_sizes[entry.path] = entry.observed.size
    current_slots = set(contract.generated_state.current_slots)
    obsolete = {item["path"]: item for item in manifest.obsolete_exact_files}

    for record in journal.actions:
        if record.action == "remove-empty-directory":
            if record.provenance != "current" or record.reason != "owned-directory-empty-after-prune":
                raise DistributionApplyError("journal-plan-mismatch")
            continue
        if record.action != "prune":
            raise DistributionApplyError("journal-plan-mismatch")
        identity = _deprovision_recovery_record_identity(record)
        expected = current_identities.get(record.path)
        if expected is not None:
            if _deprovision_recovery_identity_matches(identity, expected):
                if (
                    record.provenance != "current"
                    or record.reason != "current-identity-match"
                    or (
                        identity.kind == "regular"
                        and record.precondition.get("size")
                        != current_sizes.get(record.path, record.precondition.get("size"))
                    )
                ):
                    raise DistributionApplyError("journal-plan-mismatch")
                continue
            if expected.kind == "regular" and identity.kind == "regular" and expected.sha256 == identity.sha256:
                # A current byte match with a different mode is the explicit
                # current-mode-mismatch blocker, never historical authority.
                raise DistributionApplyError("journal-plan-mismatch")
            historical = _deprovision_recovery_historical_provenance(
                target_root,
                record.path,
                identity,
                manifest,
                journal,
            )
            if historical is None or (
                record.provenance != "historical" or record.reason != "historical-identity-match"
            ):
                raise DistributionApplyError("journal-plan-mismatch")
            continue
        if record.path in current_slots:
            if _observe_target(target_root, record.path).state != "missing":
                raise DistributionApplyError("journal-plan-mismatch")
            if record.provenance != "current" or record.reason != "current-identity-match":
                raise DistributionApplyError("journal-plan-mismatch")
            continue
        obsolete_item = obsolete.get(record.path)
        if obsolete_item is None:
            raise DistributionApplyError("journal-plan-mismatch")
        historical = _deprovision_recovery_historical_provenance(
            target_root,
            record.path,
            identity,
            manifest,
            journal,
        )
        expected_reason = (
            "trusted-manifest-identity-match"
            if historical == "trusted-manifest"
            else "direct-obsolete-identity-match"
            if historical == "direct"
            else None
        )
        if historical is None or record.provenance != "historical" or record.reason != expected_reason:
            raise DistributionApplyError("journal-plan-mismatch")


def _validate_explicit_spec_history_purge_recovery_action_semantics(
    target_root: Path,
    contract: DistributionExplicitSpecHistoryPurgeContract,
    journal: OperationJournal,
) -> None:
    """Validate purge actions against the immutable component and history tree."""

    if journal.intent != "purge" or journal.authority != contract.authority:
        raise DistributionApplyError("journal-contract-mismatch")
    root_binding, history_entries, tree_digest = _reconstruct_explicit_spec_history_purge_tree(journal)
    if (
        contract.history_root != _EXPLICIT_SPEC_HISTORY_ROOT
        or contract.history_root_binding != root_binding
        or contract.history_entries != history_entries
        or contract.history_tree_digest != tree_digest
    ):
        raise DistributionApplyError("journal-contract-mismatch")
    history_paths = {contract.history_root, *(entry.relative_path for entry in history_entries)}
    component_actions = tuple(action for action in journal.actions if action.path not in history_paths)
    _validate_deprovision_recovery_action_semantics(
        target_root,
        contract.deprovision_contract,
        replace(journal, actions=component_actions),
    )
    entry_by_path = {entry.relative_path: entry for entry in history_entries}
    root_record = next(
        (record for record in journal.actions if record.path == contract.history_root),
        None,
    )
    if contract.history_root_binding.exists:
        if root_record is None:
            raise DistributionApplyError("journal-plan-mismatch")
        root_entry = _history_tree_entry_from_journal_record(root_record)
        if root_entry.kind != "directory" or root_entry.relative_path != contract.history_root:
            raise DistributionApplyError("journal-plan-mismatch")
        if root_record.action != "remove-empty-directory":
            raise DistributionApplyError("journal-plan-mismatch")
    elif root_record is not None:
        raise DistributionApplyError("journal-plan-mismatch")
    for record in journal.actions:
        if record.path not in history_paths:
            continue
        if record.path == contract.history_root:
            continue
        entry = entry_by_path.get(record.path)
        if entry is None:
            raise DistributionApplyError("journal-plan-mismatch")
        reconstructed = _history_tree_entry_from_journal_record(record)
        if reconstructed != entry:
            raise DistributionApplyError("journal-plan-mismatch")
        if entry.kind == "regular" and record.action != "prune":
            raise DistributionApplyError("journal-plan-mismatch")
        if entry.kind == "directory" and record.action != "remove-empty-directory":
            raise DistributionApplyError("journal-plan-mismatch")
        if record.provenance != "unknown" or record.reason != (
            "explicit-spec-history-purge" if entry.kind == "regular" else "explicit-spec-history-purge-directory"
        ):
            raise DistributionApplyError("journal-plan-mismatch")
    recorded_history_paths = {
        record.path for record in journal.actions if _is_same_or_descendant(record.path, contract.history_root)
    }
    expected_history_paths = set(entry_by_path)
    if contract.history_root_binding.exists:
        expected_history_paths.add(contract.history_root)
    if recorded_history_paths != expected_history_paths:
        raise DistributionApplyError("journal-plan-mismatch")


def _validate_deprovision_recovery_leaf_parent_namespaces(
    target_root: Path,
    journal: OperationJournal,
    *,
    forward_guard: DistributionRetryMarker | None = None,
    intent: JournaledDistributionIntent = "deprovision",
) -> None:
    """Re-prove every pending leaf parent before recovery can checkpoint it."""

    if not _is_destructive_intent(intent):
        raise DistributionApplyError("journal-intent-mismatch")
    witnesses = {witness.relative_path: witness for witness in journal.leaf_parent_namespace_witnesses}
    durably_quarantined_paths = frozenset(
        lease.path
        for lease in journal.staging_leases
        if (lease.role == "predecessor-quarantine" and lease.device > 0 and lease.inode > 0 and lease.ctime_ns > 0)
    )
    owned_zero_predecessor_paths = frozenset(
        lease.path
        for lease in journal.staging_leases
        if (
            lease.role == "predecessor-quarantine"
            and lease.device == 0
            and lease.inode == 0
            and lease.ctime_ns == 0
            and _deprovision_zero_predecessor_reservation_is_owned(target_root, journal, lease)
        )
    )
    for record in journal.actions:
        if record.checkpoint != "pending" or record.action != "prune":
            continue
        parent_path = PurePosixPath(record.path).parent.as_posix()
        if parent_path == ".":
            continue
        # Assessment intentionally omits a witness for a leaf that was
        # already absent.  There is no leaf mutation or checkpoint to
        # reconcile for that journal record.
        if record.precondition.get("exists") is not True:
            continue
        witness = witnesses.get(parent_path)
        if witness is None:
            raise DistributionApplyError(
                "deprovision-parent-namespace-mismatch",
                failed_paths=(parent_path,),
            )
        snapshot = _assert_deprovision_pending_record_matches(target_root, record)
        parent_chain = _open_distribution_parent_chain(
            target_root,
            record.path,
            create_missing=False,
        )
        try:
            _assert_distribution_chain_bound(
                parent_chain,
                snapshot,
                record.path,
                exact=False,
            )
            _assert_visible_distribution_chain_exactly_bound(target_root, record.path, parent_chain)
            _assert_deprovision_leaf_parent_namespace(
                parent_chain[-1],
                record.path,
                leaf_parent_namespace_witnesses=witnesses,
                journal=journal,
                forward_guard=forward_guard,
                durably_quarantined_paths=durably_quarantined_paths,
                owned_zero_predecessor_paths=owned_zero_predecessor_paths,
            )
        finally:
            _close_distribution_parent_chain(parent_chain)


def _assert_deprovision_recovery_marker_bound(
    store: OperationJournalStore,
    expected_guard: DistributionRetryMarker | None,
) -> None:
    """Require the live retry marker to remain the held deprovision guard."""

    current_guard = store._forward_guard
    if expected_guard is None or current_guard is None:
        raise DistributionApplyError("dual-recovery-state")
    if (
        current_guard.operation != expected_guard.operation
        or current_guard.operation_id != expected_guard.operation_id
        or current_guard.target_root != expected_guard.target_root
        or current_guard.contract_identity != expected_guard.contract_identity
        or current_guard.plan_digest != expected_guard.plan_digest
        or current_guard.purpose != expected_guard.purpose
    ):
        raise DistributionApplyError("dual-recovery-state")
    store._assert_destructive_recovery_metadata_bound(expected_guard.target_root)
    store._assert_current_forward_guard(current_guard)


def _assert_deprovision_recovery_parent_attachment(
    store: OperationJournalStore,
    journal: OperationJournal,
    path: str,
    parent_chain: tuple[int, ...],
    *,
    forward_guard: DistributionRetryMarker | None,
    intent: JournaledDistributionIntent = "deprovision",
) -> OperationJournal:
    """Re-prove the immutable deprovision root-to-leaf-parent attachment."""

    _assert_deprovision_recovery_marker_bound(store, forward_guard)
    persisted = store._read(journal.root_identity)
    store._assert_guard_anchors_journal(persisted)
    if (
        persisted.operation_id != journal.operation_id
        or persisted.intent != intent
        or persisted.authority != _journal_authority_for_intent(intent)
        or persisted.contract_identity != journal.contract_identity
        or persisted.plan_digest != journal.plan_digest
    ):
        raise DistributionApplyError(
            "deprovision-visible-parent-chain-mismatch",
            failed_paths=(PurePosixPath(path).parent.as_posix(),),
        )
    record = next((item for item in persisted.actions if item.path == path), None)
    if record is None or record.action not in {"prune", "remove-empty-directory"}:
        raise DistributionApplyError(
            "journal-precondition-mismatch",
            failed_paths=(PurePosixPath(path).parent.as_posix(),),
        )
    expected_root, expected_parents = _deprovision_record_parent_bindings(record)
    expected_bindings = (expected_root, *expected_parents)
    if len(parent_chain) != len(expected_bindings) or any(
        not _same_stat_structure(os.fstat(fd), expected)
        for fd, expected in zip(parent_chain, expected_bindings, strict=True)
    ):
        raise DistributionApplyError(
            "deprovision-visible-parent-chain-mismatch",
            failed_paths=(PurePosixPath(path).parent.as_posix(),),
        )
    _assert_visible_distribution_chain_exactly_bound(store.target_root, path, parent_chain)
    return persisted


def _deprovision_recovery_leaf_mutation_validator(
    store: OperationJournalStore,
    journal: OperationJournal,
    *,
    forward_guard: DistributionRetryMarker | None,
    intent: JournaledDistributionIntent = "deprovision",
) -> Callable[[str, tuple[int, ...]], None]:
    """Bind recovery cleanup to the journal's immutable parent witnesses."""

    if forward_guard is None:
        raise DistributionApplyError("dual-recovery-state")

    def validate(path: str, parent_chain: tuple[int, ...]) -> None:
        persisted = _assert_deprovision_recovery_parent_attachment(
            store,
            journal,
            path,
            parent_chain,
            forward_guard=forward_guard,
            intent=intent,
        )
        record = next((item for item in persisted.actions if item.path == path), None)
        assert record is not None
        if record.action != "prune":
            return
        witnesses = {item.relative_path: item for item in persisted.leaf_parent_namespace_witnesses}
        durably_quarantined_paths = frozenset(
            lease.path
            for lease in persisted.staging_leases
            if lease.role == "predecessor-quarantine" and lease.device > 0 and lease.inode > 0 and lease.ctime_ns > 0
        )
        owned_zero_predecessor_paths = frozenset(
            lease.path
            for lease in persisted.staging_leases
            if (
                lease.role == "predecessor-quarantine"
                and lease.device == 0
                and lease.inode == 0
                and lease.ctime_ns == 0
                and _deprovision_zero_predecessor_reservation_is_owned(store.target_root, persisted, lease)
            )
        )
        _assert_deprovision_leaf_parent_namespace(
            parent_chain[-1],
            path,
            leaf_parent_namespace_witnesses=witnesses,
            journal=persisted,
            forward_guard=store._forward_guard or forward_guard,
            durably_quarantined_paths=durably_quarantined_paths,
            owned_zero_predecessor_paths=owned_zero_predecessor_paths,
            pending_absent_paths=frozenset(
                item.path
                for item in persisted.actions
                if (
                    item.checkpoint == "pending"
                    and item.action == "prune"
                    and _deprovision_recovery_pending_target_is_exact_absent(store.target_root, item)
                )
            ),
        )

    return validate


def _deprovision_recovery_directory_mutation_validator(
    store: OperationJournalStore,
    journal: OperationJournal,
    *,
    forward_guard: DistributionRetryMarker | None,
    require_absent: bool = True,
    intent: JournaledDistributionIntent = "deprovision",
) -> Callable[[str, tuple[int, ...]], None]:
    """Bind directory recovery to its journaled binding and empty postcondition."""

    if forward_guard is None:
        raise DistributionApplyError("dual-recovery-state")

    def validate(path: str, parent_chain: tuple[int, ...]) -> None:
        _assert_deprovision_recovery_marker_bound(store, forward_guard)
        persisted = store._read(journal.root_identity)
        store._assert_guard_anchors_journal(persisted)
        if (
            persisted.operation_id != journal.operation_id
            or persisted.intent != intent
            or persisted.authority != _journal_authority_for_intent(intent)
            or persisted.contract_identity != journal.contract_identity
            or persisted.plan_digest != journal.plan_digest
        ):
            raise DistributionApplyError(
                "deprovision-directory-mismatch",
                failed_paths=(path,),
            )
        record = next((item for item in persisted.actions if item.path == path), None)
        if record is None or record.action != "remove-empty-directory":
            raise DistributionApplyError(
                "deprovision-directory-mismatch",
                failed_paths=(path,),
            )
        try:
            directory_snapshot = _deprovision_directory_snapshot_from_record(record)
            expected_root, expected_parents = _deprovision_record_parent_bindings(record)
        except (DistributionApplyError, KeyError, TypeError, ValueError) as exc:
            if isinstance(exc, DistributionApplyError):
                raise
            raise DistributionApplyError(
                "deprovision-directory-mismatch",
                failed_paths=(path,),
            ) from exc
        if (
            directory_snapshot.relative_path != path
            or directory_snapshot.binding.relative_path != path
            or directory_snapshot.expected_remaining_child_digest != _directory_child_digest(())
            or _SHA256_RE.fullmatch(directory_snapshot.initial_child_digest) is None
            or any(
                evidence.child_path != evidence.action_path
                or PurePosixPath(evidence.child_path).parent.as_posix() != path
                or evidence.child_kind not in {"leaf", "directory"}
                or evidence.expected_postcondition != {"path": evidence.child_path, "exists": False}
                for evidence in directory_snapshot.immediate_child_evidence
            )
            or tuple(evidence.child_path for evidence in directory_snapshot.immediate_child_evidence)
            != tuple(
                sorted(
                    (evidence.child_path for evidence in directory_snapshot.immediate_child_evidence),
                    key=os.fsencode,
                )
            )
            or len({evidence.child_path for evidence in directory_snapshot.immediate_child_evidence})
            != len(directory_snapshot.immediate_child_evidence)
        ):
            raise DistributionApplyError(
                "deprovision-directory-mismatch",
                failed_paths=(path,),
            )
        records = {item.path: item for item in persisted.actions}
        if any(
            evidence.action_path not in records
            or records[evidence.action_path].action not in {"prune", "remove-empty-directory"}
            or records[evidence.action_path].path != evidence.child_path
            or records[evidence.action_path].postcondition.get("exists") is not False
            or records[evidence.action_path].postcondition.get("identity") is not None
            or (evidence.child_kind == "leaf" and records[evidence.action_path].action != "prune")
            or (evidence.child_kind == "directory" and records[evidence.action_path].action != "remove-empty-directory")
            for evidence in directory_snapshot.immediate_child_evidence
        ):
            raise DistributionApplyError(
                "deprovision-directory-mismatch",
                failed_paths=(path,),
            )
        expected_bindings = (expected_root, *expected_parents)
        if len(parent_chain) != len(expected_bindings) or any(
            not _same_stat_structure(os.fstat(fd), expected)
            for fd, expected in zip(parent_chain, expected_bindings, strict=True)
        ):
            raise DistributionApplyError(
                "deprovision-visible-parent-chain-mismatch",
                failed_paths=(PurePosixPath(path).parent.as_posix(),),
            )
        _assert_visible_distribution_chain_exactly_bound(store.target_root, path, parent_chain)
        observation = _observe_target(store.target_root, path)
        snapshot = observation.snapshot
        if snapshot is None:
            raise DistributionApplyError(
                "deprovision-directory-mismatch",
                failed_paths=(path,),
            )
        if require_absent:
            if not _deprovision_pending_snapshot_is_exact_absence(snapshot, record):
                raise DistributionApplyError(
                    "deprovision-directory-mismatch",
                    failed_paths=(path,),
                )
            _assert_deprovision_directory_dependencies_published(persisted, record)
            return
        if (
            not snapshot.target.exists
            or snapshot.target.file_type != "directory"
            or not _same_structure_identity(snapshot.target, directory_snapshot.binding)
        ):
            raise DistributionApplyError(
                "deprovision-directory-mismatch",
                failed_paths=(path,),
            )
        flags = _distribution_directory_flags()
        target_fd: int | None = None
        try:
            target_name = PurePosixPath(path).name
            visible_before = os.stat(target_name, dir_fd=parent_chain[-1], follow_symlinks=False)
            if not stat.S_ISDIR(visible_before.st_mode):
                raise DistributionApplyError(
                    "deprovision-directory-mismatch",
                    failed_paths=(path,),
                )
            target_fd = os.open(target_name, flags, dir_fd=parent_chain[-1])
            opened = os.fstat(target_fd)
            visible_after = os.stat(target_name, dir_fd=parent_chain[-1], follow_symlinks=False)
            if (
                _stat_identity_tuple(visible_before) != _stat_identity_tuple(opened)
                or _stat_identity_tuple(opened) != _stat_identity_tuple(visible_after)
                or not _same_stat_structure(opened, directory_snapshot.binding)
            ):
                raise DistributionApplyError(
                    "deprovision-directory-mismatch",
                    failed_paths=(path,),
                )
        except DistributionApplyError:
            raise
        except OSError as exc:
            raise DistributionApplyError(
                "deprovision-directory-mismatch",
                failed_paths=(path,),
            ) from exc
        finally:
            if target_fd is not None:
                os.close(target_fd)

    return validate


def _validate_deprovision_recovery_contract_before_reconciliation(
    install_root: Path,
    *,
    manifest_path: Path,
    scaffold_root: Path,
    target_root: Path,
    expected_root_identity: DistributionRootIdentity,
    journal: OperationJournal,
    forward_guard: DistributionRetryMarker | None = None,
    intent: JournaledDistributionIntent = "deprovision",
) -> None:
    """Validate immutable authority before a missing target can advance a checkpoint."""

    _assert_deprovision_zero_predecessor_reservations(target_root, journal)
    if intent == "purge":
        purge_contract = build_explicit_spec_history_purge_contract(
            install_root,
            manifest_path=manifest_path,
            scaffold_root=scaffold_root,
            target_root=target_root,
            expected_root_identity=expected_root_identity,
            recovery_journal=journal,
        )
        if (
            purge_contract.deprovision_contract.manifest is None
            or purge_contract.deprovision_contract.generated_state.blockers
        ):
            raise DistributionApplyError("journal-contract-mismatch")
        _assert_explicit_spec_history_purge_recovery_contract_identity(purge_contract, journal)
        _validate_explicit_spec_history_purge_recovery_action_semantics(target_root, purge_contract, journal)
    else:
        contract = build_deprovision_contract(
            install_root,
            manifest_path=manifest_path,
            scaffold_root=scaffold_root,
            target_root=target_root,
            expected_root_identity=expected_root_identity,
            recovery_journal=journal,
        )
        if contract.manifest is None or contract.generated_state.blockers:
            raise DistributionApplyError("journal-contract-mismatch")
        if contract.source_semantic_identities != journal.source_semantic_identities:
            raise DistributionApplyError("journal-contract-mismatch")
        _assert_deprovision_recovery_contract_identity(contract, journal)
        _validate_deprovision_recovery_action_semantics(target_root, contract, journal)
    if journal.plan_digest != _deprovision_journal_plan_digest(journal):
        raise DistributionApplyError("journal-plan-mismatch")
    for record in journal.actions:
        if record.checkpoint != "pending":
            continue
        _assert_deprovision_pending_record_matches(target_root, record)
    _validate_deprovision_recovery_leaf_parent_namespaces(
        target_root,
        journal,
        forward_guard=forward_guard,
        intent=intent,
    )


def _build_deprovision_recovery_assessment(
    current: WorkspaceAssessment,
    journal: OperationJournal,
) -> tuple[WorkspaceAssessment, ExecutableMutationPlan]:
    contract = current.deprovision_contract
    plan = current.distribution_plan
    if contract is None or plan.target_root is None:
        raise DistributionApplyError("journal-contract-mismatch")
    if contract.source_semantic_identities != journal.source_semantic_identities:
        raise DistributionApplyError("journal-contract-mismatch")
    if journal.generated_state_contract_digest is None:
        raise DistributionApplyError("journal-protocol-incompatible")
    purge_contract = current.explicit_spec_history_purge_contract
    if journal.intent == "purge":
        if purge_contract is None:
            raise DistributionApplyError("journal-contract-mismatch")
        _assert_explicit_spec_history_purge_recovery_contract_identity(purge_contract, journal)
    else:
        _assert_deprovision_recovery_contract_identity(contract, journal)
    original_actions = tuple(
        DistributionAction(
            path=record.path,
            operation="uninstall",
            action=record.action,
            provenance=record.provenance,
            reason=record.reason,
        )
        for record in journal.actions
    )
    pending_snapshots: list[tuple[str, DistributionTargetSnapshot]] = []
    for record in journal.actions:
        if record.checkpoint != "pending":
            continue
        pending_snapshots.append((
            record.path,
            _assert_deprovision_pending_record_matches(plan.target_root, record),
        ))
    directory_snapshots = tuple(
        _deprovision_directory_snapshot_from_record(record)
        for record in journal.actions
        if record.action == "remove-empty-directory"
    )
    recovery_plan = replace(
        plan,
        actions=tuple(
            action
            for action, record in zip(original_actions, journal.actions, strict=True)
            if record.checkpoint == "pending" and record.action == "prune"
        ),
        target_snapshots=tuple(pending_snapshots),
    )
    assessment = WorkspaceAssessment(
        intent=journal.intent,
        root_identity=journal.root_identity,
        contract_identity=journal.contract_identity,
        distribution_plan=recovery_plan,
        actions=original_actions,
        blockers=(),
        directory_snapshots=directory_snapshots,
        leaf_parent_namespace_witnesses=journal.leaf_parent_namespace_witnesses,
        preservation_witnesses=journal.preservation_witnesses,
        absence_witnesses=journal.absence_witnesses,
        deprovision_contract=contract,
        explicit_spec_history_purge_contract=purge_contract,
    )
    executable = ExecutableMutationPlan(
        intent=journal.intent,
        root_identity=journal.root_identity,
        contract_identity=journal.contract_identity,
        plan_digest=journal.plan_digest,
        distribution_plan=recovery_plan,
        actions=original_actions,
        directory_snapshots=directory_snapshots,
        leaf_parent_namespace_witnesses=journal.leaf_parent_namespace_witnesses,
        preservation_witnesses=journal.preservation_witnesses,
        absence_witnesses=journal.absence_witnesses,
        source_semantic_identities=journal.source_semantic_identities,
        generated_state_contract_digest=journal.generated_state_contract_digest,
        active_selection_witnesses=journal.active_selection_witnesses,
    )
    return assessment, executable


def _build_deprovision_recovery_contract_assessment(
    install_root: Path,
    *,
    manifest_path: Path,
    scaffold_root: Path,
    target_root: Path,
    expected_root_identity: DistributionRootIdentity,
    journal: OperationJournal,
) -> tuple[WorkspaceAssessment, ExecutableMutationPlan]:
    """Rebind provider semantics without classifying removed journal descendants."""

    _assert_deprovision_zero_predecessor_reservations(target_root, journal)
    purge_contract: DistributionExplicitSpecHistoryPurgeContract | None = None
    if journal.intent == "purge":
        purge_contract = build_explicit_spec_history_purge_contract(
            install_root,
            manifest_path=manifest_path,
            scaffold_root=scaffold_root,
            target_root=target_root,
            expected_root_identity=expected_root_identity,
            recovery_journal=journal,
        )
        contract = purge_contract.deprovision_contract
    else:
        contract = build_deprovision_contract(
            install_root,
            manifest_path=manifest_path,
            scaffold_root=scaffold_root,
            target_root=target_root,
            expected_root_identity=expected_root_identity,
            recovery_journal=journal,
        )
    if contract.manifest is None or contract.generated_state.blockers:
        raise DistributionApplyError("journal-contract-mismatch")
    current_assets = tuple(
        asset
        for asset in contract.managed_assets
        if asset.source_semantic_identity is not None
        and asset.source_semantic_identity.canonical_source_path.startswith("install-root/")
    )
    scaffold_assets = tuple(
        asset
        for asset in contract.managed_assets
        if asset.source_semantic_identity is not None
        and asset.source_semantic_identity.canonical_source_path.startswith("spec-dock-scaffold/")
    )
    generated_assets = (
        tuple(
            DistributionAsset(
                path=entry.path,
                identity=entry.identity,
                generated_observed_target=entry.observed,
            )
            for entry in contract.generated_state.entries
        )
        + contract.target_only_assets
    )
    current_plan = DistributionPlan(
        current_assets=current_assets,
        actions=(),
        manifest=contract.manifest,
        scaffold_root=scaffold_root,
        install_root=install_root,
        manifest_path=manifest_path,
        target_root=target_root,
        operation="uninstall",
        target_snapshots=(),
        scaffold_assets=(*scaffold_assets, *generated_assets),
    )
    current = WorkspaceAssessment(
        intent=journal.intent,
        root_identity=expected_root_identity,
        contract_identity=purge_contract.contract_digest if purge_contract is not None else contract.contract_digest,
        distribution_plan=current_plan,
        actions=(),
        blockers=(),
        deprovision_contract=contract,
        explicit_spec_history_purge_contract=purge_contract,
    )
    return _build_deprovision_recovery_assessment(current, journal)


def _reconcile_deprovision_pending_actions(
    store: OperationJournalStore,
    journal: OperationJournal,
    *,
    intent: JournaledDistributionIntent = "deprovision",
) -> OperationJournal:
    _assert_deprovision_recovery_marker_bound(store, store._forward_guard)
    if store._leaf_mutation_validator is None:
        store._leaf_mutation_validator = _deprovision_recovery_leaf_mutation_validator(
            store,
            journal,
            forward_guard=store._forward_guard,
            intent=intent,
        )
    _assert_deprovision_zero_predecessor_reservations(store.target_root, journal)
    # Validate all already-published paths before reconciling any pending
    # action.  This keeps a rebound published directory from allowing an
    # unrelated pending mutation to advance first.
    _assert_deprovision_published_summaries(store.target_root, journal)
    _validate_deprovision_recovery_leaf_parent_namespaces(
        store.target_root,
        journal,
        forward_guard=store._forward_guard,
    )
    active = journal
    completed = tuple(record.path for record in active.actions if record.checkpoint == "published")
    for record in active.actions:
        if record.checkpoint != "pending":
            continue
        snapshot = _assert_deprovision_pending_record_matches(store.target_root, record)
        if snapshot.target.exists:
            if record.action == "remove-empty-directory":
                directory_validator = _deprovision_recovery_directory_mutation_validator(
                    store,
                    active,
                    forward_guard=store._forward_guard,
                    require_absent=False,
                    intent=intent,
                )
                parent_chain = _open_distribution_parent_chain(
                    store.target_root,
                    record.path,
                    create_missing=False,
                )
                try:
                    directory_validator(record.path, parent_chain)
                finally:
                    _close_distribution_parent_chain(parent_chain)
            continue
        if record.action == "remove-empty-directory":
            _assert_deprovision_directory_dependencies_published(active, record)
        _validate_deprovision_recovery_leaf_parent_namespaces(
            store.target_root,
            active,
            forward_guard=store._forward_guard,
        )
        validator = store._leaf_mutation_validator
        if validator is None:
            raise DistributionApplyError("journal-precondition-mismatch")
        if record.action == "remove-empty-directory":
            validator = _deprovision_recovery_directory_mutation_validator(
                store,
                active,
                forward_guard=store._forward_guard,
                intent=intent,
            )
        parent_chain = _open_distribution_parent_chain(
            store.target_root,
            record.path,
            create_missing=False,
        )
        try:
            validator(record.path, parent_chain)
        finally:
            _close_distribution_parent_chain(parent_chain)
        completed = (*completed, record.path)
        active = store.checkpoint_published(active, completed)
    _assert_deprovision_published_summaries(store.target_root, active)
    return active


def _assert_deprovision_remaining_namespace(
    target_root: Path,
    journal: OperationJournal,
) -> None:
    """Verify the bounded surviving managed namespace without reopening removals."""

    allowed_paths = {
        _DISTRIBUTION_RETRY_MARKER_REL.as_posix(),
        _DISTRIBUTION_JOURNAL_REL.as_posix(),
    }
    for witness in journal.preservation_witnesses:
        parts = PurePosixPath(witness.relative_root).parts
        if parts and parts[0] == "spec-dock" and len(parts) >= 2:
            allowed_paths.add(f"spec-dock/{parts[1]}")
    try:
        _binding, entries = _capture_immediate_directory_entries(target_root, "spec-dock")
    except _PreservationCaptureError as exc:
        raise DistributionApplyError(
            "deprovision-remaining-namespace-mismatch",
            failed_paths=(exc.path,),
        ) from exc
    except (DistributionPlanError, OSError) as exc:
        raise DistributionApplyError(
            "deprovision-remaining-namespace-mismatch",
            failed_paths=("spec-dock",),
        ) from exc
    unexpected = tuple(
        sorted(
            {entry.relative_path for entry in entries if entry.relative_path not in allowed_paths},
            key=os.fsencode,
        )
    )
    if unexpected:
        raise DistributionApplyError(
            "deprovision-remaining-namespace-mismatch",
            failed_paths=unexpected,
        )


def _assert_deprovision_postconditions(
    assessment: WorkspaceAssessment,
    journal: OperationJournal,
) -> None:
    plan = assessment.distribution_plan
    if (
        plan.install_root is None
        or plan.manifest_path is None
        or plan.scaffold_root is None
        or plan.target_root is None
    ):
        raise DistributionApplyError("deprovision-postcondition-mismatch")
    _assert_deprovision_invocation_state(assessment)
    if assessment.intent == "purge":
        purge_contract = build_explicit_spec_history_purge_contract(
            plan.install_root,
            manifest_path=plan.manifest_path,
            scaffold_root=plan.scaffold_root,
            target_root=plan.target_root,
            expected_root_identity=assessment.root_identity,
            recovery_journal=journal,
        )
        if purge_contract.deprovision_contract.generated_state.blockers:
            raise DistributionApplyError("deprovision-postcondition-mismatch")
        _assert_explicit_spec_history_purge_recovery_contract_identity(purge_contract, journal)
    else:
        contract = build_deprovision_contract(
            plan.install_root,
            manifest_path=plan.manifest_path,
            scaffold_root=plan.scaffold_root,
            target_root=plan.target_root,
            expected_root_identity=assessment.root_identity,
            recovery_journal=journal,
        )
        if (
            contract.generated_state.blockers
            or contract.source_semantic_identities != journal.source_semantic_identities
        ):
            raise DistributionApplyError("deprovision-postcondition-mismatch")
        _assert_deprovision_recovery_contract_identity(contract, journal)
    _assert_deprovision_published_summaries(plan.target_root, journal)
    _assert_deprovision_terminal_bindings(plan.target_root, journal)
    _assert_deprovision_remaining_namespace(plan.target_root, journal)
    _assert_deprovision_preservation_witnesses(
        plan.target_root,
        journal.preservation_witnesses,
    )
    _assert_deprovision_absence_witnesses(
        plan.target_root,
        journal.absence_witnesses,
    )
    _assert_deprovision_invocation_state(assessment)


def _execute_deprovision_journal_plan(
    assessment: WorkspaceAssessment,
    executable: ExecutableMutationPlan,
    *,
    package_version: str,
    existing_store: OperationJournalStore | None = None,
    existing_journal: OperationJournal | None = None,
    existing_guard: DistributionRetryMarker | None = None,
    intent: JournaledDistributionIntent = "deprovision",
) -> DistributionProcessResult:
    target_root = assessment.distribution_plan.target_root
    if target_root is None:
        return _deprovision_preflight_error_result(intent=intent)
    store = existing_store or OperationJournalStore(target_root)
    journal: OperationJournal | None = existing_journal
    active_journal: OperationJournal | None = None
    guard: DistributionRetryMarker | None = existing_guard
    durably_quarantined_paths: set[str] = set()
    try:
        _assert_deprovision_invocation_state(assessment)
        if journal is None:
            guard = store.prepare_legacy_guard(executable, package_version=package_version)
            store.bind_forward_guard(guard)
            journal = store.prepare(executable, package_version=package_version)
            active_journal = store.mark_executing(journal)
        else:
            if guard is not None and store._forward_guard is None:
                store.bind_forward_guard(guard)
            if journal.status == "prepared":
                active_journal = store.mark_executing(journal)
            elif journal.status == "executing":
                active_journal = _reconcile_deprovision_pending_actions(store, journal, intent=intent)
            else:
                active_journal = journal
            journal = active_journal
        if (
            active_journal is not None
            and active_journal.status in {"prepared", "executing"}
            and store._leaf_mutation_validator is None
        ):
            store._leaf_mutation_validator = _deprovision_recovery_leaf_mutation_validator(
                store,
                active_journal,
                forward_guard=store._forward_guard or guard,
                intent=intent,
            )
        if active_journal is not None:
            durably_quarantined_paths.update(
                lease.path
                for lease in active_journal.staging_leases
                if (
                    lease.role == "predecessor-quarantine"
                    and lease.device > 0
                    and lease.inode > 0
                    and lease.ctime_ns > 0
                )
            )

        def validate_mutation_boundary() -> None:
            _assert_deprovision_recovery_marker_bound(store, store._forward_guard or guard)
            _assert_deprovision_invocation_state(assessment)

        def validate_first_target_mutation() -> Callable[[], None] | None:
            validate_mutation_boundary()
            return None

        def record_staging_lease(lease: DistributionStageOwnership) -> None:
            nonlocal active_journal, journal
            if active_journal is None:
                raise DistributionApplyError("journal-precondition-mismatch")
            validate_mutation_boundary()
            active_journal = store.record_staging_lease(active_journal, lease)
            journal = active_journal
            if lease.role == "predecessor-quarantine" and lease.device > 0 and lease.inode > 0 and lease.ctime_ns > 0:
                durably_quarantined_paths.add(lease.path)

        def remove_staging_leases(path: str, stage_names: tuple[str, ...]) -> None:
            nonlocal active_journal, journal
            if active_journal is None:
                raise DistributionApplyError("journal-precondition-mismatch")
            validate_mutation_boundary()
            retained = tuple(
                lease
                for lease in active_journal.staging_leases
                if not (lease.path == path and lease.stage_name in stage_names)
            )
            active_journal = store.write(
                replace(active_journal, staging_leases=retained),
                predecessor=active_journal,
            )
            journal = active_journal

        def record_progress(
            _phase: str,
            completed: tuple[str, ...],
            _pending: tuple[str, ...],
            _phase_complete: bool,
        ) -> None:
            nonlocal active_journal, journal
            if active_journal is None:
                raise DistributionApplyError("journal-precondition-mismatch")
            already_published = tuple(
                record.path for record in active_journal.actions if record.checkpoint == "published"
            )
            completed_paths = tuple(dict.fromkeys((*already_published, *completed)))
            if completed_paths != already_published:
                active_journal = store.checkpoint_published(active_journal, completed_paths)
                journal = active_journal

        def checkpoint_leaf_published(path: str, parent_chain: tuple[int, ...]) -> None:
            nonlocal active_journal, journal
            if active_journal is None:
                raise DistributionApplyError("journal-precondition-mismatch")
            validate_mutation_boundary()
            validate_leaf_mutation_boundary(path, parent_chain)
            target_name = PurePosixPath(path).name
            try:
                os.stat(target_name, dir_fd=parent_chain[-1], follow_symlinks=False)
            except FileNotFoundError:
                pass
            else:
                raise DistributionApplyError(
                    "deprovision-parent-namespace-mismatch",
                    failed_paths=(PurePosixPath(path).parent.as_posix(),),
                )
            record = next((item for item in active_journal.actions if item.path == path), None)
            if record is None or record.action != "prune" or record.checkpoint != "pending":
                raise DistributionApplyError("journal-precondition-mismatch")
            completed_paths = tuple(
                item.path for item in active_journal.actions if item.checkpoint == "published" or item.path == path
            )
            active_journal = store.checkpoint_published(active_journal, completed_paths)
            journal = active_journal
            durably_quarantined_paths.discard(path)

        directory_snapshots = {snapshot.relative_path: snapshot for snapshot in executable.directory_snapshots}
        target_snapshots = dict(executable.distribution_plan.target_snapshots)
        leaf_parent_namespace_witnesses = {
            witness.relative_path: witness for witness in executable.leaf_parent_namespace_witnesses
        }

        def validate_leaf_mutation_boundary(path: str, parent_chain: tuple[int, ...]) -> None:
            if active_journal is None:
                raise DistributionApplyError("journal-precondition-mismatch")
            _assert_deprovision_recovery_marker_bound(store, store._forward_guard or guard)
            boundary_journal = active_journal
            persisted = store._read(active_journal.root_identity)
            store._assert_guard_anchors_journal(persisted)
            if persisted.operation_id == active_journal.operation_id:
                boundary_journal = persisted
            snapshot = target_snapshots.get(path)
            if snapshot is None:
                raise DistributionApplyError(
                    "journal-precondition-mismatch",
                    failed_paths=(PurePosixPath(path).parent.as_posix(),),
                )
            _assert_distribution_chain_bound(parent_chain, snapshot, path, exact=False)
            _assert_visible_distribution_chain_exactly_bound(target_root, path, parent_chain)
            _assert_deprovision_leaf_parent_namespace(
                parent_chain[-1],
                path,
                leaf_parent_namespace_witnesses=leaf_parent_namespace_witnesses,
                journal=boundary_journal,
                forward_guard=store._forward_guard or guard,
                durably_quarantined_paths=frozenset({
                    *durably_quarantined_paths,
                    *(
                        lease.path
                        for lease in boundary_journal.staging_leases
                        if (
                            lease.role == "predecessor-quarantine"
                            and lease.device > 0
                            and lease.inode > 0
                            and lease.ctime_ns > 0
                        )
                    ),
                }),
            )

        def validate_directory_mutation_boundary(path: str) -> None:
            if active_journal is None:
                raise DistributionApplyError("journal-precondition-mismatch")
            validator = _deprovision_recovery_directory_mutation_validator(
                store,
                active_journal,
                forward_guard=store._forward_guard or guard,
                require_absent=False,
                intent=intent,
            )
            parent_chain = _open_distribution_parent_chain(
                target_root,
                path,
                create_missing=False,
            )
            try:
                validator(path, parent_chain)
            finally:
                _close_distribution_parent_chain(parent_chain)

        records_by_path = {record.path: record for record in active_journal.actions}
        leaf_actions = tuple(
            action
            for action in executable.actions
            if action.action == "prune" and records_by_path[action.path].checkpoint == "pending"
        )
        if active_journal.status == "executing" and leaf_actions:
            store._leaf_mutation_validator = validate_leaf_mutation_boundary
            apply_distribution_plan(
                replace(executable.distribution_plan, actions=leaf_actions),
                allow_stale_stage_cleanup=bool(active_journal.staging_leases),
                stage_ownership=active_journal.staging_leases,
                stage_ownership_recorder=record_staging_lease,
                stage_ownership_remover=remove_staging_leases,
                write_ahead_stage_reservations=True,
                progress_recorder=record_progress,
                before_mutation=validate_mutation_boundary,
                held_parent_validator=validate_leaf_mutation_boundary,
                first_target_mutation_validator=validate_first_target_mutation,
                held_parent_checkpoint_recorder=checkpoint_leaf_published,
            )

        for record in active_journal.actions:
            if active_journal.status != "executing":
                break
            if record.action != "remove-empty-directory" or record.checkpoint != "pending":
                continue
            snapshot = directory_snapshots.get(record.path)
            if snapshot is None:
                raise DistributionApplyError("journal-precondition-mismatch")
            expected_root_binding, expected_parent_bindings = _deprovision_record_parent_bindings(record)
            evidence = _assert_deprovision_directory_dependencies_published(
                active_journal,
                record,
            )

            def validate_directory_before_mutation(bound_path: str = record.path) -> None:
                validate_mutation_boundary()
                validate_directory_mutation_boundary(bound_path)

            _remove_distribution_directory_if_bound(
                target_root,
                Path(record.path),
                expected_root_identity=assessment.root_identity,
                expected_root_binding=expected_root_binding,
                expected_parent_bindings=expected_parent_bindings,
                expected_directory_binding=snapshot.binding,
                immediate_child_evidence=evidence,
                expected_remaining_child_digest=snapshot.expected_remaining_child_digest,
                before_mutation=validate_directory_before_mutation,
                final_mutation_validator=validate_directory_before_mutation,
            )
            completed_paths = tuple(
                item.path
                for item in active_journal.actions
                if item.checkpoint == "published" or item.path == record.path
            )
            active_journal = store.checkpoint_published(
                active_journal,
                completed_paths,
            )
            journal = active_journal

        if active_journal.status == "executing":
            if any(record.checkpoint != "published" for record in active_journal.actions):
                raise DistributionApplyError("journal-precondition-mismatch")
            active_journal = store.mark_verified(active_journal)
            journal = active_journal
        elif active_journal.status not in {"verifying", "completed"}:
            raise DistributionApplyError("journal-precondition-mismatch")
        _assert_deprovision_postconditions(assessment, active_journal)
        if active_journal.status == "verifying":
            active_journal = store.mark_completed(active_journal)
            journal = active_journal
        if active_journal.status != "completed":
            raise DistributionApplyError("journal-precondition-mismatch")
        active_guard = store._forward_guard or guard
        if active_guard is not None:
            store.remove_legacy_marker(active_guard)
        store.remove_completed(active_journal, guard_already_removed=True)
    except Exception as exc:
        failure_paths = exc.failed_paths if isinstance(exc, DistributionApplyError) else ()
        if isinstance(exc, DistributionApplyError):
            if exc.recovery_metadata_state is not None and journal is None:
                durable_journal: OperationJournal | None = None
                try:
                    candidate = store._read_optional_bound_journal_after_metadata_race(
                        assessment.root_identity,
                        expected_intent=intent,
                    )
                    current_guard = store._forward_guard or guard
                    if (
                        candidate is not None
                        and current_guard is not None
                        and store._is_exact_prepared_journal_for_plan(
                            candidate,
                            executable,
                            current_guard,
                            expected_root=assessment.root_identity,
                        )
                    ):
                        durable_journal = candidate
                except (DistributionApplyError, OSError):
                    durable_journal = None
                try:
                    recovery_paths = store._bound_destructive_recovery_metadata_paths(
                        assessment.root_identity,
                    )
                except DistributionApplyError:
                    recovery_paths = tuple(
                        dict.fromkeys((
                            *failure_paths,
                            _DISTRIBUTION_RETRY_MARKER_REL.as_posix(),
                            _DISTRIBUTION_JOURNAL_REL.as_posix(),
                        ))
                    )
                boundary_result = _destructive_recovery_boundary_result(
                    assessment,
                    durable_journal,
                    executable=executable,
                    intent=intent,
                    error=exc,
                    failure_paths=tuple(dict.fromkeys((*recovery_paths, *failure_paths))),
                )
                if boundary_result is not None:
                    return boundary_result
            boundary_result = _destructive_recovery_boundary_result(
                assessment,
                journal,
                executable=executable,
                intent=intent,
                error=exc,
                failure_paths=failure_paths,
            )
            if boundary_result is not None:
                return boundary_result
        if journal is not None:
            with suppress(DistributionApplyError):
                durable = store._read(assessment.root_identity)
                if (
                    durable.operation_id == journal.operation_id
                    and durable.intent == intent
                    and durable.authority == _journal_authority_for_intent(intent)
                ):
                    journal = durable
            return _distribution_process_result_from_state(
                assessment,
                journal,
                failure_paths=failure_paths,
                intent=intent,
            )
        try:
            recovery_paths = store._bound_destructive_recovery_metadata_paths(assessment.root_identity)
        except DistributionApplyError:
            recovery_paths = ()
        return _distribution_process_result_from_state(
            assessment,
            state="guard-only" if recovery_paths else "eligibility-error",
            executable=executable if recovery_paths else None,
            plan_digest=executable.plan_digest,
            failure_paths=failure_paths,
            error_code=f"{intent}-preflight-failed",
            error_message=f"Managed distribution {intent} preflight failed.",
            intent=intent,
        )
    return _distribution_process_result_from_state(
        assessment,
        state="mutating-success",
        executable=executable,
        intent=intent,
    )


def _execute_destructive_distribution(
    install_root: Path,
    *,
    manifest_path: Path,
    scaffold_root: Path,
    target_root: Path,
    package_version: str,
    apply: bool,
    expected_root_identity: DistributionRootIdentity | None = None,
    intent: Literal["deprovision", "purge"] = "deprovision",
) -> DistributionProcessResult:
    """Assess or execute one destructive distribution intent."""

    install_root = Path(install_root)
    manifest_path = Path(manifest_path)
    scaffold_root = Path(scaffold_root)
    target_root = Path(target_root)
    operation_label = "purge" if intent == "purge" else "deprovision"
    try:
        observed_root_identity = _root_identity_for_assessment(target_root)
        if apply:
            if expected_root_identity is None:
                return _deprovision_preflight_error_result(
                    code=f"{operation_label}-root-binding-required",
                    message=f"Managed distribution {operation_label} requires a bound target root.",
                    intent=intent,
                )
            if observed_root_identity != expected_root_identity:
                return _deprovision_preflight_error_result(
                    code=f"{operation_label}-root-binding-mismatch",
                    message=f"Managed distribution {operation_label} target binding changed.",
                    intent=intent,
                )
        elif expected_root_identity is not None and observed_root_identity != expected_root_identity:
            return _deprovision_preflight_error_result(
                code=f"{operation_label}-root-binding-mismatch",
                message=f"Managed distribution {operation_label} target binding changed.",
                intent=intent,
            )
        bound_root_identity = expected_root_identity or observed_root_identity
    except (DistributionAdmissionError, DistributionManifestError, DistributionPlanError, OSError):
        return _deprovision_preflight_error_result(intent=intent)

    store = OperationJournalStore(target_root)
    try:
        metadata_paths = store._bound_destructive_recovery_metadata_paths(bound_root_identity)
    except DistributionApplyError as exc:
        boundary_result = _destructive_recovery_boundary_result(
            None,
            None,
            intent=intent,
            error=exc,
        )
        if boundary_result is not None:
            return boundary_result
        return _deprovision_preflight_error_result(intent=intent)
    guard_only = False
    recovery_mismatch_kind: DistributionRecoveryMismatchKind = "same-intent"
    if metadata_paths:
        if _UNINSTALL_RETRY_MARKER_REL.as_posix() in metadata_paths:
            try:
                store._assert_destructive_recovery_metadata_bound(bound_root_identity)
            except DistributionApplyError as exc:
                boundary_result = _destructive_recovery_boundary_result(
                    None,
                    None,
                    intent=intent,
                    error=exc,
                    failure_paths=metadata_paths,
                )
                if boundary_result is not None:
                    return boundary_result
                return _deprovision_preflight_error_result(intent=intent)
            return _distribution_process_result_from_state(
                state="legacy-marker",
                failure_paths=metadata_paths,
                intent=intent,
            )
        journal_present = _DISTRIBUTION_JOURNAL_REL.as_posix() in metadata_paths
        guard_present = _DISTRIBUTION_RETRY_MARKER_REL.as_posix() in metadata_paths
        if journal_present:
            try:
                store._assert_destructive_recovery_metadata_bound(bound_root_identity)
                journal = store._read(bound_root_identity, expected_intent=intent)
                if journal.intent != intent or journal.authority != _journal_authority_for_intent(intent):
                    recovery_mismatch_kind = "intent-authority"
                    raise DistributionApplyError("journal-protocol-incompatible")
                if not _journal_package_is_compatible(
                    journal.package_version,
                    package_version,
                ):
                    raise DistributionApplyError("journal-protocol-incompatible")
                guard: DistributionRetryMarker | None = None
                if guard_present:
                    guard = _read_distribution_retry_marker(target_root, expected_intent=intent)
                    if (
                        guard is None
                        or guard.purpose != _journal_guard_purpose_for_intent(intent)
                        or guard.operation != intent
                        or guard.operation_id != journal.operation_id
                        or guard.contract_identity != journal.contract_identity
                        or guard.plan_digest != journal.plan_digest
                    ):
                        if guard is not None and (
                            guard.purpose != _journal_guard_purpose_for_intent(intent) or guard.operation != intent
                        ):
                            recovery_mismatch_kind = "intent-authority"
                        raise DistributionApplyError("dual-recovery-state")
                    store.bind_forward_guard(guard)
                    store._assert_guard_anchors_journal(journal)
                elif journal.status != "completed":
                    raise DistributionApplyError("dual-recovery-state")
                if apply and journal.status in {"prepared", "executing"}:
                    store._leaf_mutation_validator = _deprovision_recovery_leaf_mutation_validator(
                        store,
                        journal,
                        forward_guard=store._forward_guard or guard,
                        intent=intent,
                    )
                if apply and journal.status in {"prepared", "executing"}:
                    _validate_deprovision_recovery_contract_before_reconciliation(
                        install_root,
                        manifest_path=manifest_path,
                        scaffold_root=scaffold_root,
                        target_root=target_root,
                        expected_root_identity=bound_root_identity,
                        journal=journal,
                        forward_guard=store._forward_guard or guard,
                        intent=intent,
                    )
                if apply and journal.status == "executing":
                    journal = _reconcile_deprovision_pending_actions(store, journal, intent=intent)
                recovery_assessment, recovery_executable = _build_deprovision_recovery_contract_assessment(
                    install_root,
                    manifest_path=manifest_path,
                    scaffold_root=scaffold_root,
                    target_root=target_root,
                    expected_root_identity=bound_root_identity,
                    journal=journal,
                )
                _assert_deprovision_published_summaries(target_root, journal)
            except (DistributionAdmissionError, DistributionApplyError, DistributionPlanError) as exc:
                if isinstance(exc, (DistributionAdmissionError, DistributionApplyError)):
                    boundary_result = _destructive_recovery_boundary_result(
                        None,
                        None,
                        intent=intent,
                        error=exc,
                        failure_paths=metadata_paths,
                    )
                    if boundary_result is not None:
                        return boundary_result
                if getattr(exc, "recovery_mismatch_kind", None) == "intent-authority":
                    recovery_mismatch_kind = "intent-authority"
                return _distribution_process_result_from_state(
                    state="recovery-mismatch",
                    failure_paths=metadata_paths,
                    intent=intent,
                    recovery_mismatch_kind=recovery_mismatch_kind,
                )
            if not apply:
                return _distribution_process_result_from_state(
                    recovery_assessment,
                    journal,
                    intent=intent,
                )
            return _execute_deprovision_journal_plan(
                recovery_assessment,
                recovery_executable,
                package_version=package_version,
                existing_store=store,
                existing_journal=journal,
                existing_guard=guard,
                intent=intent,
            )
        guard_only = True

    try:
        if intent == "purge":
            assessment = build_explicit_spec_history_purge_assessment(
                install_root,
                manifest_path=manifest_path,
                scaffold_root=scaffold_root,
                target_root=target_root,
                expected_root_identity=bound_root_identity,
            )
        else:
            assessment = build_deprovision_workspace_assessment(
                install_root,
                manifest_path=manifest_path,
                scaffold_root=scaffold_root,
                target_root=target_root,
                expected_root_identity=bound_root_identity,
            )
    except (DistributionAdmissionError, DistributionManifestError, DistributionPlanError, OSError):
        return _deprovision_preflight_error_result(intent=intent)

    if not guard_only and not _deprovision_has_managed_workspace_evidence(assessment):
        return _deprovision_preflight_error_result(
            code="managed-workspace-evidence-missing",
            message=(
                "target is not a managed SpecDock repo: missing managed "
                "'spec-dock/spec-dock.version' state or exact managed distribution evidence"
            ),
            intent=intent,
        )

    if guard_only:
        try:
            store._assert_destructive_recovery_metadata_bound(bound_root_identity)
            guard = _read_distribution_retry_marker(target_root, expected_intent=intent)
            if (
                guard is None
                or guard.purpose != _journal_guard_purpose_for_intent(intent)
                or guard.operation != intent
                or guard.target_root != bound_root_identity
                or not _journal_package_is_compatible(
                    guard.package_version,
                    package_version,
                )
                or assessment.blockers
            ):
                if guard is not None and (
                    guard.purpose != _journal_guard_purpose_for_intent(intent) or guard.operation != intent
                ):
                    recovery_mismatch_kind = "intent-authority"
                raise DistributionApplyError("dual-recovery-state")
            executable = build_executable_mutation_plan(assessment)
            if (
                not executable.actions
                or guard.contract_identity != executable.contract_identity
                or guard.plan_digest not in _executable_plan_digest_candidates(executable)
            ):
                raise DistributionApplyError("journal-plan-mismatch")
            store = OperationJournalStore(target_root)
            store.bind_forward_guard(guard)
        except (DistributionAdmissionError, DistributionApplyError, DistributionPlanError) as exc:
            if isinstance(exc, (DistributionAdmissionError, DistributionApplyError)):
                boundary_result = _destructive_recovery_boundary_result(
                    assessment,
                    None,
                    intent=intent,
                    error=exc,
                    failure_paths=metadata_paths,
                )
                if boundary_result is not None:
                    return boundary_result
            if getattr(exc, "recovery_mismatch_kind", None) == "intent-authority":
                recovery_mismatch_kind = "intent-authority"
            return _distribution_process_result_from_state(
                assessment,
                state="recovery-mismatch",
                failure_paths=metadata_paths,
                intent=intent,
                recovery_mismatch_kind=recovery_mismatch_kind,
            )
        if not apply:
            return _distribution_process_result_from_state(
                assessment,
                state="guard-only",
                executable=executable,
                intent=intent,
            )
        try:
            journal = store.prepare(executable, package_version=guard.package_version)
        except DistributionApplyError as exc:
            if exc.recovery_metadata_state is None:
                return _distribution_process_result_from_state(
                    assessment,
                    state="guard-only",
                    executable=executable,
                    intent=intent,
                )
            durable_journal: OperationJournal | None = None
            try:
                candidate = store._read_optional_bound_journal_after_metadata_race(
                    bound_root_identity,
                    expected_intent=intent,
                )
                current_guard = store._forward_guard or guard
                exact_candidate = candidate is not None and store._is_exact_prepared_journal_for_plan(
                    candidate,
                    executable,
                    current_guard,
                    expected_root=bound_root_identity,
                )
                if exact_candidate:
                    durable_journal = candidate
            except (DistributionApplyError, OSError):
                durable_journal = None
            try:
                refreshed_metadata_paths = store._bound_destructive_recovery_metadata_paths(bound_root_identity)
            except DistributionApplyError:
                refreshed_metadata_paths = tuple(
                    dict.fromkeys((
                        *metadata_paths,
                        _DISTRIBUTION_JOURNAL_REL.as_posix(),
                    ))
                )
            boundary_result = _destructive_recovery_boundary_result(
                assessment,
                durable_journal,
                executable=executable,
                intent=intent,
                error=exc,
                failure_paths=tuple(dict.fromkeys((*refreshed_metadata_paths, *exc.failed_paths))),
            )
            if boundary_result is not None:
                return boundary_result
            return _distribution_process_result_from_state(
                assessment,
                durable_journal,
                state="dual-recovery-state",
                executable=executable,
                intent=intent,
                failure_paths=tuple(dict.fromkeys((*refreshed_metadata_paths, *exc.failed_paths))),
            )
        return _execute_deprovision_journal_plan(
            assessment,
            executable,
            package_version=package_version,
            existing_store=store,
            existing_journal=journal,
            existing_guard=guard,
            intent=intent,
        )

    if not apply:
        if assessment.blockers:
            dry_run_plan_digest = None
        else:
            try:
                dry_run_plan_digest = build_executable_mutation_plan(assessment).plan_digest
            except DistributionPlanError:
                return _deprovision_preflight_error_result(intent=intent)
        return _distribution_process_result_from_state(
            assessment,
            state="planned",
            plan_digest=dry_run_plan_digest,
            intent=intent,
        )
    if assessment.blockers:
        return _deprovision_blocked_result(
            assessment,
            plan_digest=None,
            reason=f"{operation_label}-preflight-blocked",
            intent=intent,
        )

    try:
        executable = build_executable_mutation_plan(assessment)
    except DistributionPlanError:
        return _deprovision_preflight_error_result(intent=intent)
    if executable.actions:
        return _execute_deprovision_journal_plan(
            assessment,
            executable,
            package_version=package_version,
            intent=intent,
        )

    try:
        if _root_identity_for_assessment(target_root) != bound_root_identity:
            return _deprovision_blocked_result(
                assessment,
                plan_digest=executable.plan_digest,
                reason=f"{operation_label}-no-op-postcondition-changed",
                intent=intent,
            )
        if intent == "purge":
            post_assessment = build_explicit_spec_history_purge_assessment(
                install_root,
                manifest_path=manifest_path,
                scaffold_root=scaffold_root,
                target_root=target_root,
                expected_root_identity=bound_root_identity,
            )
        else:
            post_assessment = build_deprovision_workspace_assessment(
                install_root,
                manifest_path=manifest_path,
                scaffold_root=scaffold_root,
                target_root=target_root,
                expected_root_identity=bound_root_identity,
            )
        if post_assessment.blockers:
            return _deprovision_blocked_result(
                post_assessment,
                plan_digest=executable.plan_digest,
                reason=f"{operation_label}-no-op-postcondition-changed",
                intent=intent,
            )
        post_executable = build_executable_mutation_plan(post_assessment)
        if post_executable.actions or post_executable.plan_digest != executable.plan_digest:
            changed_paths = tuple(
                action.path
                for action in post_executable.actions
                if action.path not in {item.path for item in executable.actions}
            )
            return _deprovision_blocked_result(
                post_assessment,
                plan_digest=executable.plan_digest,
                extra_failed_paths=changed_paths,
                reason=f"{operation_label}-no-op-postcondition-changed",
                intent=intent,
            )
        try:
            late_metadata_paths = store._assert_destructive_recovery_metadata_bound(bound_root_identity)
        except DistributionApplyError as exc:
            boundary_result = _destructive_recovery_boundary_result(
                post_assessment,
                None,
                intent=intent,
                error=exc,
            )
            if boundary_result is not None:
                return boundary_result
            late_metadata_paths = ("recovery-metadata-error",)
        if late_metadata_paths:
            return _deprovision_blocked_result(
                post_assessment,
                plan_digest=executable.plan_digest,
                reason=f"{operation_label}-no-op-postcondition-changed",
                intent=intent,
            )
        if _root_identity_for_assessment(target_root) != bound_root_identity:
            return _deprovision_blocked_result(
                post_assessment,
                plan_digest=executable.plan_digest,
                reason=f"{operation_label}-no-op-postcondition-changed",
                intent=intent,
            )
    except (DistributionAdmissionError, DistributionManifestError, DistributionPlanError, OSError):
        return _deprovision_blocked_result(
            assessment,
            plan_digest=executable.plan_digest,
            reason=f"{operation_label}-no-op-postcondition-changed",
            intent=intent,
        )
    return _distribution_process_result_from_state(
        post_assessment,
        state="no-op-success",
        plan_digest=executable.plan_digest,
        intent=intent,
    )


def execute_deprovision_distribution(
    install_root: Path,
    *,
    manifest_path: Path,
    scaffold_root: Path,
    target_root: Path,
    package_version: str,
    apply: bool,
    expected_root_identity: DistributionRootIdentity | None = None,
) -> DistributionProcessResult:
    """Assess or execute the managed distribution deprovision intent."""

    return _execute_destructive_distribution(
        install_root,
        manifest_path=manifest_path,
        scaffold_root=scaffold_root,
        target_root=target_root,
        package_version=package_version,
        apply=apply,
        expected_root_identity=expected_root_identity,
        intent="deprovision",
    )


def execute_explicit_spec_history_purge_distribution(
    install_root: Path,
    *,
    manifest_path: Path,
    scaffold_root: Path,
    target_root: Path,
    package_version: str,
    apply: bool,
    expected_root_identity: DistributionRootIdentity | None = None,
) -> DistributionProcessResult:
    """Assess or execute the explicit spec-history purge intent."""

    return _execute_destructive_distribution(
        install_root,
        manifest_path=manifest_path,
        scaffold_root=scaffold_root,
        target_root=target_root,
        package_version=package_version,
        apply=apply,
        expected_root_identity=expected_root_identity,
        intent="purge",
    )


def _distribution_directory_flags() -> int:
    nofollow = getattr(os, "O_NOFOLLOW", None)
    directory = getattr(os, "O_DIRECTORY", None)
    if not isinstance(nofollow, int) or not isinstance(directory, int):
        raise DistributionApplyError("platform lacks required no-follow directory support")
    return os.O_RDONLY | nofollow | directory | getattr(os, "O_CLOEXEC", 0)


def _open_distribution_parent_chain(
    target_root: Path,
    target_rel: str,
    *,
    create_missing: bool = False,
    expected_snapshot: DistributionTargetSnapshot | None = None,
    created_parent_bindings: dict[str, PathIdentitySnapshot] | None = None,
    created_parent_recorder: Callable[[tuple[PathIdentitySnapshot, ...]], None] | None = None,
    first_target_mutation_validator: Callable[[], Callable[[], None] | None] | None = None,
) -> tuple[int, ...]:
    flags = _distribution_directory_flags()
    fds: list[int] = []
    created_missing = False
    try:
        fds.append(os.open(target_root, flags))
        if expected_snapshot is not None:
            _assert_distribution_chain_bound(
                tuple(fds),
                expected_snapshot,
                target_rel,
                exact=not created_missing,
            )
        parts = PurePosixPath(target_rel).parts
        for component_index, component in enumerate(parts[:-1]):
            created_component = False
            component_relative = "/".join(parts[: component_index + 1])
            expected_parent = None
            if expected_snapshot is not None:
                expected_parent = next(
                    (parent for parent in expected_snapshot.parents if parent.relative_path == component_relative),
                    None,
                )
            try:
                next_fd = os.open(component, flags, dir_fd=fds[-1])
                if expected_parent is not None and not expected_parent.exists:
                    bound_parent = (
                        created_parent_bindings.get(component_relative) if created_parent_bindings is not None else None
                    )
                    if (
                        bound_parent is None
                        or not bound_parent.exists
                        or not _same_stat_structure(os.fstat(next_fd), bound_parent)
                    ):
                        os.close(next_fd)
                        raise DistributionApplyError(f"managed target parent appeared during apply for '{target_rel}'")
            except FileNotFoundError:
                if not create_missing:
                    raise DistributionApplyError(f"managed target parent is missing for '{target_rel}'") from None
                if expected_snapshot is not None:
                    _assert_distribution_chain_bound(
                        tuple(fds),
                        expected_snapshot,
                        target_rel,
                        exact=not created_missing,
                    )
                _assert_visible_distribution_chain_bound(target_root, target_rel, tuple(fds))
                commit_first_mutation = (
                    first_target_mutation_validator() if first_target_mutation_validator is not None else None
                )
                try:
                    os.mkdir(component, dir_fd=fds[-1])
                except FileExistsError:
                    if expected_parent is not None and not expected_parent.exists:
                        raise DistributionApplyError(
                            f"managed target parent appeared during apply for '{target_rel}'"
                        ) from None
                else:
                    if commit_first_mutation is not None:
                        commit_first_mutation()
                    os.fsync(fds[-1])
                    created_missing = True
                    created_component = True
                next_fd = os.open(component, flags, dir_fd=fds[-1])
            except OSError as exc:
                raise DistributionApplyError(f"managed target parent is unsafe for '{target_rel}'") from exc
            fds.append(next_fd)
            _assert_visible_distribution_chain_bound(target_root, target_rel, tuple(fds))
            if created_component and created_parent_bindings is not None:
                created_parent_bindings[component_relative] = _snapshot_from_stat(
                    component_relative,
                    os.fstat(next_fd),
                )
                if created_parent_recorder is not None:
                    created_parent_recorder(
                        tuple(created_parent_bindings[path] for path in sorted(created_parent_bindings))
                    )
            if expected_snapshot is not None:
                _assert_distribution_chain_bound(
                    tuple(fds),
                    expected_snapshot,
                    target_rel,
                    exact=not created_missing,
                )
        return tuple(fds)
    except DistributionApplyError:
        for fd in reversed(fds):
            os.close(fd)
        raise
    except OSError as exc:
        for fd in reversed(fds):
            os.close(fd)
        raise DistributionApplyError("managed target root cannot be opened safely") from exc


def _close_distribution_parent_chain(fds: tuple[int, ...]) -> None:
    for fd in reversed(fds):
        os.close(fd)


def _same_stat_identity(left: os.stat_result, right: PathIdentitySnapshot) -> bool:
    return (
        right.exists
        and left.st_dev == right.device
        and left.st_ino == right.inode
        and left.st_ctime_ns == right.ctime_ns
        and _file_type(left.st_mode) == right.file_type
        and left.st_nlink == right.link_count
        and (right.mode is None or stat.S_IMODE(left.st_mode) == right.mode)
    )


def _same_stat_structure(left: os.stat_result, right: PathIdentitySnapshot) -> bool:
    return (
        right.exists
        and left.st_dev == right.device
        and left.st_ino == right.inode
        and _file_type(left.st_mode) == right.file_type
        and (right.mode is None or stat.S_IMODE(left.st_mode) == right.mode)
    )


def _assert_distribution_chain_bound(
    fds: tuple[int, ...],
    snapshot: DistributionTargetSnapshot,
    target_rel: str,
    *,
    exact: bool = False,
) -> None:
    if not snapshot.root.exists:
        raise DistributionApplyError(f"managed target identity changed for '{target_rel}'")
    root_matches = (
        _same_stat_identity(os.fstat(fds[0]), snapshot.root)
        if exact
        else _same_stat_structure(os.fstat(fds[0]), snapshot.root)
    )
    if not root_matches:
        raise DistributionApplyError(f"managed target identity changed for '{target_rel}'")
    for fd, expected in zip(fds[1:], snapshot.parents, strict=False):
        if not expected.exists:
            continue
        parent_matches = (
            _same_stat_identity(os.fstat(fd), expected) if exact else _same_stat_structure(os.fstat(fd), expected)
        )
        if not parent_matches:
            raise DistributionApplyError(f"managed target identity changed for '{target_rel}'")


def _assert_visible_distribution_chain_bound(
    target_root: Path,
    target_rel: str,
    fds: tuple[int, ...],
) -> None:
    parts = PurePosixPath(target_rel).parts
    for index, fd in enumerate(fds):
        visible = target_root.joinpath(*parts[:index]) if index else target_root
        try:
            visible_stat = os.lstat(visible)
            held_stat = os.fstat(fd)
        except OSError as exc:
            raise DistributionApplyError(f"managed target identity changed for '{target_rel}'") from exc
        if (
            visible_stat.st_dev != held_stat.st_dev
            or visible_stat.st_ino != held_stat.st_ino
            or _file_type(visible_stat.st_mode) != _file_type(held_stat.st_mode)
            or stat.S_IMODE(visible_stat.st_mode) != stat.S_IMODE(held_stat.st_mode)
        ):
            raise DistributionApplyError(f"managed target identity changed for '{target_rel}'")


def _visible_distribution_chain_identity_tuple(info: os.stat_result) -> tuple[int, int, int, int, int, int]:
    return (
        info.st_dev,
        info.st_ino,
        stat.S_IFMT(info.st_mode),
        stat.S_IMODE(info.st_mode),
        info.st_ctime_ns,
        info.st_nlink,
    )


def _assert_visible_distribution_chain_exactly_bound(
    target_root: Path,
    target_rel: str,
    held_fds: tuple[int, ...],
) -> None:
    """Re-open the visible root-to-parent chain and compare it with held fds."""

    parts = PurePosixPath(target_rel).parts
    expected_fd_count = max(1, len(parts))
    if len(held_fds) != expected_fd_count:
        raise DistributionApplyError(
            "deprovision-visible-parent-chain-mismatch",
            failed_paths=(PurePosixPath(target_rel).parent.as_posix(),),
        )
    flags = _distribution_directory_flags()
    fresh_fds: list[int] = []

    def mismatch(prefix_index: int) -> DistributionApplyError:
        prefix = "." if prefix_index == 0 else "/".join(parts[:prefix_index])
        return DistributionApplyError(
            "deprovision-visible-parent-chain-mismatch",
            failed_paths=(prefix,),
        )

    def exact_stat(left: os.stat_result, right: os.stat_result) -> bool:
        return _visible_distribution_chain_identity_tuple(left) == _visible_distribution_chain_identity_tuple(right)

    try:
        visible_root_before = os.lstat(target_root)
        root_fd = os.open(target_root, flags)
        fresh_fds.append(root_fd)
        opened_root = os.fstat(root_fd)
        visible_root_after = os.lstat(target_root)
        held_root_before = os.fstat(held_fds[0])
        held_root_after = os.fstat(held_fds[0])
        if (
            not stat.S_ISDIR(visible_root_before.st_mode)
            or stat.S_ISLNK(visible_root_before.st_mode)
            or not exact_stat(visible_root_before, opened_root)
            or not exact_stat(opened_root, visible_root_after)
            or not exact_stat(held_root_before, held_root_after)
            or not exact_stat(opened_root, held_root_after)
        ):
            raise mismatch(0)

        for component_index, component in enumerate(parts[:-1], start=1):
            parent_fd = fresh_fds[-1]
            try:
                visible_before = os.stat(component, dir_fd=parent_fd, follow_symlinks=False)
                if stat.S_ISLNK(visible_before.st_mode) or not stat.S_ISDIR(visible_before.st_mode):
                    raise mismatch(component_index)
                child_fd = os.open(component, flags, dir_fd=parent_fd)
                fresh_fds.append(child_fd)
                opened = os.fstat(child_fd)
                visible_after = os.stat(component, dir_fd=parent_fd, follow_symlinks=False)
            except DistributionApplyError:
                raise
            except OSError as exc:
                raise mismatch(component_index) from exc
            held_before = os.fstat(held_fds[component_index])
            held_after = os.fstat(held_fds[component_index])
            if (
                not exact_stat(visible_before, opened)
                or not exact_stat(opened, visible_after)
                or not exact_stat(held_before, held_after)
                or not exact_stat(opened, held_after)
            ):
                raise mismatch(component_index)
    except DistributionApplyError:
        raise
    except OSError as exc:
        raise mismatch(0) from exc
    finally:
        for fd in reversed(fresh_fds):
            with suppress(OSError):
                os.close(fd)


def _assert_regular_fd_safe(
    fd: int,
    snapshot: PathIdentitySnapshot,
    path: str,
    *,
    exact: bool,
) -> None:
    actual = os.fstat(fd)
    matches = _same_stat_identity(actual, snapshot) if exact else _same_stat_structure(actual, snapshot)
    if not matches or actual.st_nlink != 1:
        raise DistributionApplyError(f"managed target identity changed for '{path}'")


def _read_fd_bytes(fd: int) -> bytes:
    os.lseek(fd, 0, os.SEEK_SET)
    chunks: list[bytes] = []
    while True:
        chunk = os.read(fd, 1024 * 64)
        if not chunk:
            return b"".join(chunks)
        chunks.append(chunk)


def _held_fd_has_exact_bytes(fd: int, expected: bytes) -> bool:
    before = os.fstat(fd)
    content = _read_fd_bytes(fd)
    after = os.fstat(fd)
    return _stat_identity_tuple(before) == _stat_identity_tuple(after) and content == expected


def _source_snapshot(info: os.stat_result) -> DistributionSourceSnapshot:
    return DistributionSourceSnapshot(
        device=info.st_dev,
        inode=info.st_ino,
        ctime_ns=info.st_ctime_ns,
        mtime_ns=info.st_mtime_ns,
        size=info.st_size,
        mode=stat.S_IMODE(info.st_mode),
    )


def _source_asset_bytes(source_path: Path) -> tuple[bytes, DistributionSourceSnapshot]:
    nofollow = getattr(os, "O_NOFOLLOW", None)
    if not isinstance(nofollow, int):
        raise DistributionApplyError("platform lacks required no-follow file support")
    try:
        source_stat = os.lstat(source_path)
        if not stat.S_ISREG(source_stat.st_mode):
            raise DistributionApplyError("provider Current asset is not a regular file")
        fd = os.open(source_path, os.O_RDONLY | nofollow | getattr(os, "O_CLOEXEC", 0))
    except DistributionApplyError:
        raise
    except OSError as exc:
        raise DistributionApplyError("provider Current asset cannot be read safely") from exc
    try:
        opened = os.fstat(fd)
        if not stat.S_ISREG(opened.st_mode):
            raise DistributionApplyError("provider Current asset changed type")
        if _source_snapshot(source_stat) != _source_snapshot(opened):
            raise DistributionApplyError("provider Current asset identity changed before read")
        content = _read_fd_bytes(fd)
        after_read = os.fstat(fd)
        snapshot = _source_snapshot(after_read)
        if snapshot != _source_snapshot(opened):
            raise DistributionApplyError("provider Current asset identity changed during read")
        return content, snapshot
    finally:
        os.close(fd)


def _write_fd_bytes(
    fd: int,
    content: bytes,
    *,
    before_mutation: Callable[[], None] | None = None,
) -> None:
    if before_mutation is not None:
        before_mutation()
    os.ftruncate(fd, 0)
    os.lseek(fd, 0, os.SEEK_SET)
    view = memoryview(content)
    offset = 0
    while offset < len(view):
        if before_mutation is not None:
            before_mutation()
        written = os.write(fd, view[offset:])
        if written <= 0:
            raise DistributionApplyError("managed target write made no progress")
        offset += written
    os.fsync(fd)


def _resolve_distribution_no_replace_rename() -> tuple[Any, int]:
    library = ctypes.CDLL(None, use_errno=True)
    if sys.platform.startswith("linux"):
        rename = getattr(library, "renameat2", None)
        flag = 0x00000001  # RENAME_NOREPLACE
    elif sys.platform == "darwin":
        rename = getattr(library, "renameatx_np", None)
        flag = 0x00000004  # RENAME_EXCL
    else:
        raise DistributionApplyError("platform lacks required no-replace rename support")
    if rename is None:
        raise DistributionApplyError("platform lacks required no-replace rename support")
    rename.argtypes = (
        ctypes.c_int,
        ctypes.c_char_p,
        ctypes.c_int,
        ctypes.c_char_p,
        ctypes.c_uint,
    )
    rename.restype = ctypes.c_int
    return rename, flag


def _rename_distribution_no_replace(
    source_parent_fd: int,
    source_name: str,
    destination_parent_fd: int,
    destination_name: str,
) -> None:
    rename, flag = _resolve_distribution_no_replace_rename()
    result = rename(
        source_parent_fd,
        os.fsencode(source_name),
        destination_parent_fd,
        os.fsencode(destination_name),
        flag,
    )
    if result == 0:
        return
    error_number = ctypes.get_errno()
    if error_number in (errno.EEXIST, errno.ENOTEMPTY):
        raise FileExistsError(error_number, os.strerror(error_number), destination_name)
    raise OSError(error_number, os.strerror(error_number), destination_name)


def _resolve_distribution_swap_rename() -> tuple[Any, int]:
    library = ctypes.CDLL(None, use_errno=True)
    if sys.platform.startswith("linux"):
        rename = getattr(library, "renameat2", None)
        flag = 0x00000002  # RENAME_EXCHANGE
    elif sys.platform == "darwin":
        rename = getattr(library, "renameatx_np", None)
        flag = 0x00000002  # RENAME_SWAP
    else:
        raise DistributionApplyError("platform lacks required atomic replace support")
    if rename is None:
        raise DistributionApplyError("platform lacks required atomic replace support")
    rename.argtypes = (
        ctypes.c_int,
        ctypes.c_char_p,
        ctypes.c_int,
        ctypes.c_char_p,
        ctypes.c_uint,
    )
    rename.restype = ctypes.c_int
    return rename, flag


def _rename_distribution_swap(
    source_parent_fd: int,
    source_name: str,
    destination_parent_fd: int,
    destination_name: str,
) -> None:
    rename, flag = _resolve_distribution_swap_rename()
    result = rename(
        source_parent_fd,
        os.fsencode(source_name),
        destination_parent_fd,
        os.fsencode(destination_name),
        flag,
    )
    if result == 0:
        return
    error_number = ctypes.get_errno()
    raise OSError(error_number, os.strerror(error_number), destination_name)


def _stat_identity_tuple(info: os.stat_result) -> tuple[int, int, int, int, int]:
    return (info.st_dev, info.st_ino, info.st_ctime_ns, info.st_mode, info.st_nlink)


def _stat_optional_no_follow(parent_fd: int, name: str) -> os.stat_result | None:
    try:
        return os.stat(name, dir_fd=parent_fd, follow_symlinks=False)
    except FileNotFoundError:
        return None
    except OSError as exc:
        raise DistributionApplyError("managed staging cleanup failed") from exc


def _distribution_quarantine_backup_name(quarantine_name: str) -> str:
    return f".spec-dock-backup-{hashlib.sha256(quarantine_name.encode()).hexdigest()[:32]}"


def _unlink_distribution_quarantine_with_backup(
    parent_fd: int,
    quarantine_name: str,
    stage_name: str,
    expected: os.stat_result,
    *,
    canonical_validator: Callable[[], None],
    mutation_validator: Callable[[], None] | None,
    post_link_mutation_validator: Callable[[], None] | None = None,
    allow_existing_backup: bool = False,
    backup_recorder: Callable[[DistributionStageOwnership], None] | None = None,
    transition_path: str | None = None,
) -> None:
    """Unlink one exact quarantine while retaining a restorable hardlink."""

    backup_name = _distribution_quarantine_backup_name(quarantine_name)
    created_backup = False
    if mutation_validator is not None:
        mutation_validator()
    try:
        existing_backup = _stat_optional_no_follow(parent_fd, backup_name)
        if existing_backup is not None and not allow_existing_backup:
            raise DistributionApplyError("managed staging cleanup failed")
        if existing_backup is None:
            if backup_recorder is not None:
                if transition_path is None:
                    raise DistributionApplyError("managed staging cleanup failed")
                backup_recorder(
                    _reserved_distribution_stage_ownership(
                        transition_path,
                        backup_name,
                        "regular" if stat.S_ISREG(expected.st_mode) else "symlink",
                        role="backup-reserved",
                    )
                )
            if mutation_validator is not None:
                mutation_validator()
            os.link(
                quarantine_name,
                backup_name,
                src_dir_fd=parent_fd,
                dst_dir_fd=parent_fd,
                follow_symlinks=False,
            )
            created_backup = True
            os.fsync(parent_fd)
        backup = os.stat(backup_name, dir_fd=parent_fd, follow_symlinks=False)
        visible = os.stat(quarantine_name, dir_fd=parent_fd, follow_symlinks=False)
        if (
            visible.st_dev != backup.st_dev
            or visible.st_ino != backup.st_ino
            or _file_type(visible.st_mode) != _file_type(backup.st_mode)
            or backup.st_nlink < 2
            or visible.st_nlink < 2
            or visible.st_dev != expected.st_dev
            or visible.st_ino != expected.st_ino
        ):
            raise DistributionApplyError("managed staging cleanup failed")
        if backup_recorder is not None:
            if transition_path is None:
                raise DistributionApplyError("managed staging cleanup failed")
            backup_recorder(
                DistributionStageOwnership(
                    path=transition_path,
                    stage_name=backup_name,
                    device=visible.st_dev,
                    inode=visible.st_ino,
                    ctime_ns=visible.st_ctime_ns,
                    file_type="regular" if stat.S_ISREG(visible.st_mode) else "symlink",
                    role="backup-dual",
                )
            )
        if post_link_mutation_validator is not None:
            post_link_mutation_validator()
        if mutation_validator is not None:
            mutation_validator()
        canonical_validator()
        # A second no-follow observation closes an interposition after the
        # first final stat.  The backup remains an independent exact reference.
        final_visible = os.stat(quarantine_name, dir_fd=parent_fd, follow_symlinks=False)
        final_backup = os.stat(backup_name, dir_fd=parent_fd, follow_symlinks=False)
        if (
            final_visible.st_dev != final_backup.st_dev
            or final_visible.st_ino != final_backup.st_ino
            or _file_type(final_visible.st_mode) != _file_type(final_backup.st_mode)
            or final_visible.st_nlink < 2
            or final_backup.st_nlink < 2
        ):
            with suppress(OSError):
                _rename_distribution_no_replace(parent_fd, backup_name, parent_fd, stage_name)
                os.fsync(parent_fd)
            raise DistributionApplyError("managed staging cleanup failed")
        if mutation_validator is not None:
            mutation_validator()
        if backup_recorder is not None:
            assert transition_path is not None
            backup_recorder(
                _reserved_distribution_stage_ownership(
                    transition_path,
                    backup_name,
                    "regular" if stat.S_ISREG(expected.st_mode) else "symlink",
                    role="backup-only-reserved",
                )
            )
        if mutation_validator is not None:
            mutation_validator()
        os.unlink(quarantine_name, dir_fd=parent_fd)
        os.fsync(parent_fd)
        try:
            canonical_validator()
        except DistributionApplyError:
            with suppress(OSError):
                os.link(
                    backup_name,
                    quarantine_name,
                    src_dir_fd=parent_fd,
                    dst_dir_fd=parent_fd,
                    follow_symlinks=False,
                )
                os.fsync(parent_fd)
            raise
        final_backup = os.stat(backup_name, dir_fd=parent_fd, follow_symlinks=False)
        if final_backup.st_dev != backup.st_dev or final_backup.st_ino != backup.st_ino:
            raise DistributionApplyError("managed staging cleanup failed")
        if backup_recorder is not None:
            if transition_path is None:
                raise DistributionApplyError("managed staging cleanup failed")
            backup_recorder(
                _distribution_stage_ownership(
                    transition_path,
                    backup_name,
                    final_backup,
                    role="backup-only",
                )
            )
            if mutation_validator is not None:
                mutation_validator()
            return
        if mutation_validator is not None:
            mutation_validator()
        os.unlink(backup_name, dir_fd=parent_fd)
        os.fsync(parent_fd)
        if mutation_validator is not None:
            mutation_validator()
    except (OSError, DistributionApplyError) as exc:
        if isinstance(exc, DistributionApplyError) and exc.recovery_metadata_state is not None:
            raise
        with suppress(OSError):
            visible = os.stat(quarantine_name, dir_fd=parent_fd, follow_symlinks=False)
            retained = os.stat(backup_name, dir_fd=parent_fd, follow_symlinks=False)
            if created_backup and visible.st_dev == retained.st_dev and visible.st_ino == retained.st_ino:
                os.unlink(backup_name, dir_fd=parent_fd)
                os.fsync(parent_fd)
        if str(exc) == "deprovision-parent-namespace-mismatch":
            raise
        raise DistributionApplyError("managed staging cleanup failed") from exc


def _stat_structure_tuple(info: os.stat_result) -> tuple[int, int, str, int, int]:
    return (info.st_dev, info.st_ino, _file_type(info.st_mode), stat.S_IMODE(info.st_mode), info.st_nlink)


def _remove_distribution_directory_if_bound(
    target_root: Path,
    relative_path: Path,
    *,
    expected_root_identity: DistributionRootIdentity,
    expected_root_binding: PathIdentitySnapshot | None = None,
    expected_parent_bindings: tuple[PathIdentitySnapshot, ...] | None = None,
    expected_directory_binding: PathIdentitySnapshot,
    immediate_child_evidence: tuple[DistributionImmediateChildEvidence, ...],
    expected_remaining_child_digest: str,
    before_mutation: Callable[[], None] | None = None,
    final_mutation_validator: Callable[[], None] | None = None,
) -> None:
    """Remove one exact empty directory without reopening removed descendants."""

    try:
        relative = _exact_relative_path(
            relative_path.as_posix(),
            field_name="managed directory path",
        ).as_posix()
    except DistributionManifestError as exc:
        raise DistributionApplyError("managed directory path is unsafe") from exc
    if (
        expected_directory_binding.relative_path != relative
        or not expected_directory_binding.exists
        or expected_directory_binding.file_type != "directory"
        or expected_directory_binding.device is None
        or expected_directory_binding.inode is None
        or expected_directory_binding.mode is None
        or expected_remaining_child_digest != _directory_child_digest(())
    ):
        raise DistributionApplyError(f"managed directory identity changed for '{relative}'")

    parts = PurePosixPath(relative).parts
    if expected_parent_bindings is not None:
        expected_parent_paths = tuple("/".join(parts[:index]) for index in range(1, len(parts)))
        if tuple(binding.relative_path for binding in expected_parent_bindings) != expected_parent_paths or any(
            not binding.exists
            or binding.file_type != "directory"
            or binding.device is None
            or binding.inode is None
            or binding.mode is None
            for binding in expected_parent_bindings
        ):
            raise DistributionApplyError(f"managed directory identity changed for '{relative}'")
    if expected_root_binding is not None and (
        expected_root_binding.relative_path != "."
        or not expected_root_binding.exists
        or expected_root_binding.file_type != "directory"
        or expected_root_binding.device is None
        or expected_root_binding.inode is None
        or expected_root_binding.mode is None
    ):
        raise DistributionApplyError(f"managed directory identity changed for '{relative}'")
    flags = _distribution_directory_flags()
    fds: list[int] = []
    try:
        root_fd = os.open(target_root, flags)
        fds.append(root_fd)
        for component in parts[:-1]:
            visible = os.stat(component, dir_fd=fds[-1], follow_symlinks=False)
            if stat.S_ISLNK(visible.st_mode) or not stat.S_ISDIR(visible.st_mode):
                raise DistributionApplyError(f"managed directory identity changed for '{relative}'")
            child_fd = os.open(component, flags, dir_fd=fds[-1])
            opened = os.fstat(child_fd)
            if _stat_identity_tuple(visible) != _stat_identity_tuple(opened):
                os.close(child_fd)
                raise DistributionApplyError(f"managed directory identity changed for '{relative}'")
            if expected_parent_bindings is not None and not _same_structure_identity(
                _snapshot_from_stat("/".join(parts[: len(fds)]), opened),
                expected_parent_bindings[len(fds) - 1],
            ):
                os.close(child_fd)
                raise DistributionApplyError(f"managed directory identity changed for '{relative}'")
            fds.append(child_fd)

        parent_fd = fds[-1]
        target_name = parts[-1]
        visible_target = os.stat(target_name, dir_fd=parent_fd, follow_symlinks=False)
        target_fd = os.open(target_name, flags, dir_fd=parent_fd)
        fds.append(target_fd)

        def assert_root_and_chain_bound() -> None:
            visible_root = os.lstat(target_root)
            held_root = os.fstat(root_fd)
            if (
                stat.S_ISLNK(visible_root.st_mode)
                or not stat.S_ISDIR(visible_root.st_mode)
                or _stat_identity_tuple(visible_root) != _stat_identity_tuple(held_root)
                or (held_root.st_dev, held_root.st_ino) != (expected_root_identity.device, expected_root_identity.inode)
                or (
                    expected_root_binding is not None
                    and not _same_structure_identity(
                        _snapshot_from_stat(".", held_root),
                        expected_root_binding,
                    )
                )
            ):
                raise DistributionApplyError(f"managed directory identity changed for '{relative}'")
            for index, component in enumerate(parts[:-1]):
                visible_parent = os.stat(component, dir_fd=fds[index], follow_symlinks=False)
                held_parent = os.fstat(fds[index + 1])
                if (
                    stat.S_ISLNK(visible_parent.st_mode)
                    or not stat.S_ISDIR(visible_parent.st_mode)
                    or _stat_identity_tuple(visible_parent) != _stat_identity_tuple(held_parent)
                    or (
                        expected_parent_bindings is not None
                        and not _same_structure_identity(
                            _snapshot_from_stat("/".join(parts[: index + 1]), held_parent),
                            expected_parent_bindings[index],
                        )
                    )
                ):
                    raise DistributionApplyError(f"managed directory identity changed for '{relative}'")
            current_visible = os.stat(target_name, dir_fd=parent_fd, follow_symlinks=False)
            current_held = os.fstat(target_fd)
            if (
                stat.S_ISLNK(current_visible.st_mode)
                or not stat.S_ISDIR(current_visible.st_mode)
                or _stat_identity_tuple(current_visible) != _stat_identity_tuple(current_held)
                or current_held.st_dev != expected_directory_binding.device
                or current_held.st_ino != expected_directory_binding.inode
                or stat.S_IMODE(current_held.st_mode) != expected_directory_binding.mode
            ):
                raise DistributionApplyError(f"managed directory identity changed for '{relative}'")

        def assert_immediate_children_absent() -> None:
            evidence_paths: list[str] = []
            for evidence in immediate_child_evidence:
                if (
                    evidence.required_checkpoint != "published"
                    or evidence.child_path != evidence.action_path
                    or PurePosixPath(evidence.child_path).parent.as_posix() != relative
                    or evidence.expected_postcondition != {"path": evidence.child_path, "exists": False}
                ):
                    raise DistributionApplyError(f"managed directory evidence changed for '{relative}'")
                child_name = PurePosixPath(evidence.child_path).name
                try:
                    os.stat(child_name, dir_fd=target_fd, follow_symlinks=False)
                except FileNotFoundError:
                    pass
                else:
                    raise DistributionApplyError(f"managed directory evidence changed for '{relative}'")
                evidence_paths.append(evidence.child_path)
            if evidence_paths != sorted(evidence_paths, key=os.fsencode) or len(set(evidence_paths)) != len(
                evidence_paths
            ):
                raise DistributionApplyError(f"managed directory evidence changed for '{relative}'")
            before = os.fstat(target_fd)
            names = tuple(
                sorted(
                    os.listdir(target_fd),  # noqa: PTH208 - descriptor-bound listing
                    key=os.fsencode,
                )
            )
            after = os.fstat(target_fd)
            if (
                names
                or _stat_identity_tuple(before) != _stat_identity_tuple(after)
                or _directory_child_digest(()) != expected_remaining_child_digest
            ):
                raise DistributionApplyError(f"managed directory is not exact empty for '{relative}'")

        if _stat_identity_tuple(visible_target) != _stat_identity_tuple(os.fstat(target_fd)):
            raise DistributionApplyError(f"managed directory identity changed for '{relative}'")
        assert_root_and_chain_bound()
        assert_immediate_children_absent()
        if before_mutation is not None:
            before_mutation()
        assert_root_and_chain_bound()
        assert_immediate_children_absent()
        if final_mutation_validator is not None:
            final_mutation_validator()
        os.rmdir(target_name, dir_fd=parent_fd)
        os.fsync(parent_fd)
        try:
            os.stat(target_name, dir_fd=parent_fd, follow_symlinks=False)
        except FileNotFoundError:
            pass
        else:
            raise DistributionApplyError(f"managed directory removal failed for '{relative}'")
        visible_root = os.lstat(target_root)
        held_root = os.fstat(root_fd)
        if (
            stat.S_ISLNK(visible_root.st_mode)
            or not stat.S_ISDIR(visible_root.st_mode)
            or (visible_root.st_dev, visible_root.st_ino) != (held_root.st_dev, held_root.st_ino)
            or (held_root.st_dev, held_root.st_ino) != (expected_root_identity.device, expected_root_identity.inode)
            or (
                expected_root_binding is not None
                and not _same_structure_identity(
                    _snapshot_from_stat(".", held_root),
                    expected_root_binding,
                )
            )
        ):
            raise DistributionApplyError(f"managed directory identity changed for '{relative}'")
        for index, component in enumerate(parts[:-1]):
            visible_parent = os.stat(component, dir_fd=fds[index], follow_symlinks=False)
            held_parent = os.fstat(fds[index + 1])
            if (
                stat.S_ISLNK(visible_parent.st_mode)
                or not stat.S_ISDIR(visible_parent.st_mode)
                or (visible_parent.st_dev, visible_parent.st_ino) != (held_parent.st_dev, held_parent.st_ino)
                or (
                    expected_parent_bindings is not None
                    and not _same_structure_identity(
                        _snapshot_from_stat("/".join(parts[: index + 1]), held_parent),
                        expected_parent_bindings[index],
                    )
                )
            ):
                raise DistributionApplyError(f"managed directory identity changed for '{relative}'")
    except DistributionApplyError:
        raise
    except OSError as exc:
        raise DistributionApplyError(f"managed directory identity changed for '{relative}'") from exc
    finally:
        for fd in reversed(fds):
            with suppress(OSError):
                os.close(fd)


def _restore_distribution_quarantine(
    parent_fd: int,
    quarantine_name: str,
    target_name: str,
    *,
    failure_message: str,
) -> None:
    try:
        _rename_distribution_no_replace(parent_fd, quarantine_name, parent_fd, target_name)
        os.fsync(parent_fd)
    except OSError as exc:
        raise DistributionApplyError(failure_message) from exc


def _remove_distribution_target_if_bound(
    parent_fd: int,
    target_name: str,
    expected: os.stat_result,
    *,
    held_fd: int | None = None,
    identity_message: str,
    transition_path: str | None = None,
    transition_name: str | None = None,
    transition_recorder: Callable[[DistributionStageOwnership], None] | None = None,
    mutation_validator: Callable[[], None] | None = None,
    post_link_mutation_validator: Callable[[], None] | None = None,
    canonical_validator: Callable[[], None] | None = None,
) -> None:
    """Delete only the inode bound before the pathname mutation.

    A nonce quarantine turns a concurrent replacement into a reversible move:
    the moved entry is compared with the held descriptor (or the exact
    no-follow symlink identity) before any unlink is attempted.
    """

    expected_identity = _stat_identity_tuple(expected)
    if held_fd is not None and _stat_identity_tuple(os.fstat(held_fd)) != expected_identity:
        raise DistributionApplyError(identity_message)
    quarantine_name = transition_name or f".{target_name}.{secrets.token_hex(16)}.remove"
    if transition_recorder is not None:
        if transition_path is None:
            raise DistributionApplyError(identity_message)
        file_type = _file_type(expected.st_mode)
        if file_type not in {"regular", "symlink"}:
            raise DistributionApplyError(identity_message)
        transition_recorder(
            _reserved_distribution_stage_ownership(
                transition_path,
                quarantine_name,
                "regular" if file_type == "regular" else "symlink",
                role="predecessor-quarantine",
            )
        )
    if mutation_validator is not None:
        mutation_validator()
    try:
        _rename_distribution_no_replace(parent_fd, target_name, parent_fd, quarantine_name)
    except OSError as exc:
        raise DistributionApplyError(identity_message) from exc
    try:
        moved = os.stat(quarantine_name, dir_fd=parent_fd, follow_symlinks=False)
        moved_matches_bound = (
            _stat_identity_tuple(moved) == _stat_identity_tuple(os.fstat(held_fd))
            if held_fd is not None
            else (
                moved.st_dev == expected.st_dev
                and moved.st_ino == expected.st_ino
                and moved.st_mode == expected.st_mode
                and moved.st_nlink == expected.st_nlink
            )
        )
        if not moved_matches_bound:
            raise DistributionApplyError(identity_message)
        os.fsync(parent_fd)
        if transition_recorder is not None:
            assert transition_path is not None
            transition_recorder(
                _distribution_stage_ownership(
                    transition_path,
                    quarantine_name,
                    moved,
                    role="predecessor-quarantine",
                )
            )
        if mutation_validator is not None:
            mutation_validator()
        try:
            if transition_recorder is None:
                _remove_distribution_stage_if_owned(parent_fd, quarantine_name, moved, strict=True)
            else:

                def assert_pruned_canonical_absent() -> None:
                    if canonical_validator is not None:
                        canonical_validator()
                    elif _stat_optional_no_follow(parent_fd, target_name) is not None:
                        raise DistributionApplyError(identity_message)

                _unlink_distribution_quarantine_with_backup(
                    parent_fd,
                    quarantine_name,
                    target_name,
                    moved,
                    canonical_validator=assert_pruned_canonical_absent,
                    mutation_validator=mutation_validator,
                    post_link_mutation_validator=post_link_mutation_validator,
                    backup_recorder=transition_recorder,
                    transition_path=transition_path,
                )
        except DistributionApplyError as exc:
            if exc.recovery_metadata_state is not None:
                raise
            if str(exc) == "deprovision-parent-namespace-mismatch":
                raise
            raise DistributionApplyError(identity_message) from exc
    except Exception:
        raise


def _swap_regular_distribution_target_if_bound(
    parent_fd: int,
    staging_name: str,
    target_name: str,
    *,
    target_fd: int,
    staging_fd: int,
    expected_target: os.stat_result,
    identity_message: str,
) -> os.stat_result:
    """Exchange two held regular files and roll back a raced pathname."""

    if _stat_identity_tuple(os.fstat(target_fd)) != _stat_identity_tuple(expected_target):
        raise DistributionApplyError(identity_message)
    visible_target = os.stat(target_name, dir_fd=parent_fd, follow_symlinks=False)
    visible_stage = os.stat(staging_name, dir_fd=parent_fd, follow_symlinks=False)
    if _stat_identity_tuple(visible_target) != _stat_identity_tuple(expected_target) or _stat_identity_tuple(
        visible_stage
    ) != _stat_identity_tuple(os.fstat(staging_fd)):
        raise DistributionApplyError(identity_message)
    _rename_distribution_swap(parent_fd, staging_name, parent_fd, target_name)
    os.fsync(parent_fd)
    moved_target = os.stat(staging_name, dir_fd=parent_fd, follow_symlinks=False)
    published = os.stat(target_name, dir_fd=parent_fd, follow_symlinks=False)
    if _stat_identity_tuple(moved_target) != _stat_identity_tuple(os.fstat(target_fd)) or _stat_identity_tuple(
        published
    ) != _stat_identity_tuple(os.fstat(staging_fd)):
        if _stat_identity_tuple(published) == _stat_identity_tuple(os.fstat(staging_fd)):
            # The canonical predecessor changed before the exchange: the
            # exact successor is canonical and the unknown entry is at stage.
            # Re-check that pair and exchange it back so the unknown entry
            # returns to its original canonical name.
            rollback_target = os.stat(target_name, dir_fd=parent_fd, follow_symlinks=False)
            rollback_stage = os.stat(staging_name, dir_fd=parent_fd, follow_symlinks=False)
            if _stat_identity_tuple(rollback_target) != _stat_identity_tuple(published) or _stat_identity_tuple(
                rollback_stage
            ) != _stat_identity_tuple(moved_target):
                raise DistributionApplyError(identity_message)
            _rename_distribution_swap(parent_fd, staging_name, parent_fd, target_name)
            os.fsync(parent_fd)
            restored_target = os.stat(target_name, dir_fd=parent_fd, follow_symlinks=False)
            restored_stage = os.stat(staging_name, dir_fd=parent_fd, follow_symlinks=False)
            if _stat_identity_tuple(restored_target) != _stat_identity_tuple(moved_target) or _stat_identity_tuple(
                restored_stage
            ) != _stat_identity_tuple(published):
                raise DistributionApplyError(identity_message)
        # The exchange already happened.  An unknown canonical entry may have
        # been published after it, so exchanging again would move or delete a
        # third-party entry.  Preserve both names for journaled recovery.
        raise DistributionApplyError(identity_message)
    return moved_target


def _swap_symlink_distribution_target_if_bound(
    parent_fd: int,
    staging_name: str,
    target_name: str,
    *,
    expected_target: PathIdentitySnapshot,
    staging_stat: os.stat_result,
    identity_message: str,
) -> os.stat_result:
    """Exchange symlinks and restore both names when a pathname raced."""

    def read_exact_symlink(name: str) -> tuple[os.stat_result, str]:
        before = os.stat(name, dir_fd=parent_fd, follow_symlinks=False)
        if not stat.S_ISLNK(before.st_mode) or before.st_nlink != 1:
            raise DistributionApplyError(identity_message)
        try:
            link_target = _normalized_link_target_for_path(
                expected_target.relative_path,
                os.readlink(name, dir_fd=parent_fd),
            )
        except OSError as exc:
            raise DistributionApplyError(identity_message) from exc
        after = os.stat(name, dir_fd=parent_fd, follow_symlinks=False)
        if _stat_identity_tuple(after) != _stat_identity_tuple(before):
            raise DistributionApplyError(identity_message)
        if link_target is None:
            raise DistributionApplyError(identity_message)
        return after, link_target

    expected_predecessor_target = (
        expected_target.identity.target
        if expected_target.identity is not None and expected_target.identity.kind == "symlink"
        else None
    )
    if expected_predecessor_target is None:
        raise DistributionApplyError(identity_message)

    visible_target, visible_target_link = read_exact_symlink(target_name)
    visible_stage, visible_stage_link = read_exact_symlink(staging_name)
    staged_target = visible_stage_link
    if (
        not _same_stat_identity(visible_target, expected_target)
        or visible_target_link != expected_predecessor_target
        or _stat_identity_tuple(visible_stage) != _stat_identity_tuple(staging_stat)
        or visible_stage_link != staged_target
    ):
        raise DistributionApplyError(identity_message)
    _rename_distribution_swap(parent_fd, staging_name, parent_fd, target_name)
    os.fsync(parent_fd)
    moved_target, moved_target_link = read_exact_symlink(staging_name)
    published, published_link = read_exact_symlink(target_name)
    if (
        not _same_stat_structure(moved_target, expected_target)
        or moved_target.st_nlink != expected_target.link_count
        or moved_target_link != expected_predecessor_target
        or _stat_structure_tuple(published) != _stat_structure_tuple(staging_stat)
        or published_link != staged_target
    ):
        published_is_exact_successor = (
            _stat_structure_tuple(published) == _stat_structure_tuple(staging_stat) and published_link == staged_target
        )
        if published_is_exact_successor:
            rollback_target, rollback_target_link = read_exact_symlink(target_name)
            rollback_stage, rollback_stage_link = read_exact_symlink(staging_name)
            if (
                _stat_identity_tuple(rollback_target) != _stat_identity_tuple(published)
                or rollback_target_link != published_link
                or _stat_identity_tuple(rollback_stage) != _stat_identity_tuple(moved_target)
                or rollback_stage_link != moved_target_link
            ):
                raise DistributionApplyError(identity_message)
            _rename_distribution_swap(parent_fd, staging_name, parent_fd, target_name)
            os.fsync(parent_fd)
            restored_target, restored_target_link = read_exact_symlink(target_name)
            restored_stage, restored_stage_link = read_exact_symlink(staging_name)
            if (
                _stat_identity_tuple(restored_target) != _stat_identity_tuple(moved_target)
                or restored_target_link != moved_target_link
                or _stat_identity_tuple(restored_stage) != _stat_identity_tuple(published)
                or restored_stage_link != published_link
            ):
                raise DistributionApplyError(identity_message)
        # Never roll an unknown post-exchange canonical entry through the
        # private stage name.  The journal owns recovery; both entries remain.
        raise DistributionApplyError(identity_message)
    return moved_target


def _remove_distribution_stage_if_owned(
    parent_fd: int,
    stage_name: str,
    created: os.stat_result,
    *,
    strict: bool = False,
    transition_path: str | None = None,
    canonical_name: str | None = None,
    canonical_ownership: DistributionStageOwnership | None = None,
    canonical_condition: dict[str, object] | None = None,
    stage_condition: dict[str, object] | None = None,
    recovery_stage_recorder: Callable[[DistributionStageOwnership], None] | None = None,
    transition_name: str | None = None,
    transition_recorder: Callable[[DistributionStageOwnership], None] | None = None,
    mutation_validator: Callable[[], None] | None = None,
    post_link_mutation_validator: Callable[[], None] | None = None,
    gc_path: str | None = None,
    gc_recorder: Callable[[DistributionStageOwnership], None] | None = None,
    gc_name: str | None = None,
    gc_ordinal: int = 1,
    gc_predecessor_name: str | None = None,
) -> str | None:
    try:
        current = os.stat(stage_name, dir_fd=parent_fd, follow_symlinks=False)
    except FileNotFoundError:
        return None
    except OSError as exc:
        if strict:
            raise DistributionApplyError("managed staging cleanup failed") from exc
        return None
    owned = (
        current.st_dev == created.st_dev
        and current.st_ino == created.st_ino
        and current.st_ctime_ns == created.st_ctime_ns
        and _file_type(current.st_mode) == _file_type(created.st_mode)
        and current.st_nlink == created.st_nlink == 1
    )
    if not owned:
        if strict:
            raise DistributionApplyError("managed staging identity changed")
        return None
    if gc_recorder is not None and gc_path is None:
        raise DistributionApplyError("managed staging cleanup failed")
    transition_args = (
        transition_path,
        canonical_name,
        canonical_ownership,
        canonical_condition,
        stage_condition,
    )
    if any(item is not None for item in transition_args):
        if any(item is None for item in transition_args):
            raise DistributionApplyError("managed staging cleanup failed")
        assert transition_path is not None
        assert canonical_name is not None
        assert canonical_ownership is not None
        assert canonical_condition is not None
        assert stage_condition is not None
        try:
            canonical = os.stat(canonical_name, dir_fd=parent_fd, follow_symlinks=False)
            canonical_identity = _distribution_stage_identity(parent_fd, canonical_name, transition_path)
            stage_identity = _distribution_stage_identity(parent_fd, stage_name, transition_path)
        except (FileNotFoundError, OSError, DistributionApplyError) as exc:
            raise DistributionApplyError("managed staging cleanup failed") from exc
        canonical_owned = (
            canonical.st_dev == canonical_ownership.device
            and canonical.st_ino == canonical_ownership.inode
            and canonical.st_ctime_ns == canonical_ownership.ctime_ns
            and _file_type(canonical.st_mode) == canonical_ownership.file_type
            and canonical.st_nlink == 1
            and canonical_condition.get("identity") == _distribution_identity_payload(canonical_identity)
        )
        stage_owned = stage_condition.get("identity") == _distribution_identity_payload(stage_identity)
        stage_owned = stage_owned and all(
            stage_condition.get(field_name) == actual
            for field_name, actual in (
                ("device", current.st_dev),
                ("inode", current.st_ino),
                ("file_type", _file_type(current.st_mode)),
                ("link_count", current.st_nlink),
            )
        )
        if not canonical_owned or not stage_owned:
            raise DistributionApplyError("managed staging cleanup failed")
        quarantine_name = transition_name or f"{stage_name}.{secrets.token_hex(16)}.remove"
        held_fd: int | None = None
        original_link: str | None = None
        try:
            if stat.S_ISREG(current.st_mode):
                nofollow = getattr(os, "O_NOFOLLOW", None)
                if not isinstance(nofollow, int):
                    raise DistributionApplyError("platform lacks required no-follow file support")
                held_fd = os.open(
                    stage_name,
                    os.O_RDONLY | nofollow | getattr(os, "O_CLOEXEC", 0),
                    dir_fd=parent_fd,
                )
                if _stat_identity_tuple(os.fstat(held_fd)) != _stat_identity_tuple(current):
                    raise DistributionApplyError("managed staging cleanup failed")
            elif stat.S_ISLNK(current.st_mode):
                original_link = os.readlink(stage_name, dir_fd=parent_fd)
                if _stat_identity_tuple(
                    os.stat(stage_name, dir_fd=parent_fd, follow_symlinks=False)
                ) != _stat_identity_tuple(current):
                    raise DistributionApplyError("managed staging cleanup failed")
            else:
                raise DistributionApplyError("managed staging cleanup failed")
            if transition_recorder is not None:
                transition_recorder(
                    _reserved_distribution_stage_ownership(
                        transition_path,
                        quarantine_name,
                        "regular" if stat.S_ISREG(current.st_mode) else "symlink",
                        role="predecessor-quarantine",
                    )
                )
            if mutation_validator is not None:
                mutation_validator()
            _rename_distribution_no_replace(parent_fd, stage_name, parent_fd, quarantine_name)
            os.fsync(parent_fd)
            moved = os.stat(quarantine_name, dir_fd=parent_fd, follow_symlinks=False)
            if held_fd is not None:
                if _stat_identity_tuple(moved) != _stat_identity_tuple(os.fstat(held_fd)):
                    raise DistributionApplyError("managed staging cleanup failed")
            elif (
                original_link is None
                or os.readlink(quarantine_name, dir_fd=parent_fd) != original_link
                or _stat_identity_tuple(os.stat(quarantine_name, dir_fd=parent_fd, follow_symlinks=False))
                != _stat_identity_tuple(moved)
            ):
                raise DistributionApplyError("managed staging cleanup failed")
            moved_identity = _distribution_stage_identity(parent_fd, quarantine_name, transition_path)
            if stage_condition.get("identity") != _distribution_identity_payload(moved_identity):
                raise DistributionApplyError("managed staging cleanup failed")
            if transition_recorder is not None:
                transition_recorder(
                    _distribution_stage_ownership(
                        transition_path,
                        quarantine_name,
                        moved,
                        role="predecessor-quarantine",
                    )
                )
            if mutation_validator is not None:
                mutation_validator()

            def assert_canonical_successor() -> None:
                canonical = os.stat(canonical_name, dir_fd=parent_fd, follow_symlinks=False)
                canonical_identity = _distribution_stage_identity(parent_fd, canonical_name, transition_path)
                if (
                    canonical.st_dev != canonical_ownership.device
                    or canonical.st_ino != canonical_ownership.inode
                    or canonical.st_ctime_ns != canonical_ownership.ctime_ns
                    or _file_type(canonical.st_mode) != canonical_ownership.file_type
                    or canonical.st_nlink != 1
                    or canonical_condition.get("identity") != _distribution_identity_payload(canonical_identity)
                ):
                    raise DistributionApplyError("managed staging cleanup failed")

            assert_canonical_successor()
            _unlink_distribution_quarantine_with_backup(
                parent_fd,
                quarantine_name,
                stage_name,
                moved,
                canonical_validator=assert_canonical_successor,
                mutation_validator=mutation_validator,
                backup_recorder=transition_recorder,
                transition_path=transition_path,
            )
            return None
        except (DistributionApplyError, OSError) as exc:
            if isinstance(exc, DistributionApplyError) and exc.recovery_metadata_state is not None:
                raise
            with suppress(DistributionApplyError):
                _restore_distribution_quarantine(
                    parent_fd,
                    quarantine_name,
                    stage_name,
                    failure_message="managed staging cleanup failed",
                )
            if transition_recorder is not None:
                with suppress(Exception):
                    transition_recorder(
                        _reserved_distribution_stage_ownership(
                            transition_path,
                            quarantine_name,
                            "regular" if stat.S_ISREG(current.st_mode) else "symlink",
                            role="predecessor-quarantine",
                        )
                    )
            if recovery_stage_recorder is not None:
                with suppress(Exception):
                    restored = os.stat(stage_name, dir_fd=parent_fd, follow_symlinks=False)
                    restored_identity = _distribution_stage_identity(parent_fd, stage_name, transition_path)
                    if stage_condition.get("identity") == _distribution_identity_payload(restored_identity):
                        recovery_stage_recorder(_distribution_stage_ownership(transition_path, stage_name, restored))
            raise DistributionApplyError("managed staging cleanup failed") from exc
        finally:
            if held_fd is not None:
                os.close(held_fd)
    try:
        quarantine_name = gc_name or f"{stage_name}.{secrets.token_hex(16)}.gc"
        delete_name: str | None = None
        retained_gc_name: str | None = None
        gc_held_fd: int | None = None
        gc_original_link: str | None = None
        if stat.S_ISREG(current.st_mode):
            nofollow = getattr(os, "O_NOFOLLOW", None)
            if not isinstance(nofollow, int):
                raise DistributionApplyError("platform lacks required no-follow file support")
            gc_held_fd = os.open(
                stage_name,
                os.O_RDONLY | nofollow | getattr(os, "O_CLOEXEC", 0),
                dir_fd=parent_fd,
            )
            if _stat_identity_tuple(os.fstat(gc_held_fd)) != _stat_identity_tuple(current):
                raise DistributionApplyError("managed staging identity changed")
        elif stat.S_ISLNK(current.st_mode):
            gc_original_link = os.readlink(stage_name, dir_fd=parent_fd)
            if _stat_identity_tuple(
                os.stat(stage_name, dir_fd=parent_fd, follow_symlinks=False)
            ) != _stat_identity_tuple(current):
                raise DistributionApplyError("managed staging identity changed")
        else:
            raise DistributionApplyError("managed staging identity changed")
        try:
            if gc_recorder is not None:
                if gc_path is None:
                    raise DistributionApplyError("managed staging cleanup failed")
                gc_recorder(
                    _reserved_distribution_stage_ownership(
                        gc_path,
                        quarantine_name,
                        "regular" if stat.S_ISREG(current.st_mode) else "symlink",
                        role="gc-reserved",
                        gc_predecessor_name=gc_predecessor_name or stage_name,
                        gc_ordinal=gc_ordinal,
                    )
                )
            if mutation_validator is not None:
                mutation_validator()
            _rename_distribution_no_replace(parent_fd, stage_name, parent_fd, quarantine_name)
            os.fsync(parent_fd)
            moved = os.stat(quarantine_name, dir_fd=parent_fd, follow_symlinks=False)
            moved_is_exact = (
                _stat_identity_tuple(moved) == _stat_identity_tuple(os.fstat(gc_held_fd))
                if gc_held_fd is not None
                else (
                    gc_original_link is not None
                    and moved.st_dev == current.st_dev
                    and moved.st_ino == current.st_ino
                    and moved.st_mode == current.st_mode
                    and moved.st_nlink == current.st_nlink
                    and os.readlink(quarantine_name, dir_fd=parent_fd) == gc_original_link
                )
            )
            if not moved_is_exact:
                _restore_distribution_quarantine(
                    parent_fd,
                    quarantine_name,
                    stage_name,
                    failure_message="managed staging cleanup failed",
                )
                raise DistributionApplyError("managed staging identity changed")
            if gc_recorder is not None:
                assert gc_path is not None
                gc_recorder(
                    _distribution_stage_ownership(
                        gc_path,
                        quarantine_name,
                        moved,
                        role="gc-exact",
                        gc_predecessor_name=gc_predecessor_name or stage_name,
                        gc_ordinal=gc_ordinal,
                    )
                )
                try:
                    if mutation_validator is not None:
                        mutation_validator()
                except DistributionApplyError as exc:
                    if exc.recovery_metadata_state is not None:
                        raise
                    _restore_distribution_quarantine(
                        parent_fd,
                        quarantine_name,
                        stage_name,
                        failure_message="managed staging cleanup failed",
                    )
                    raise
            # Keep an independent exact link until the moved deletion
            # candidate has been revalidated.  A replacement of the first
            # quarantine name is then moved, inspected, and restored instead
            # of being unlinked as if it were operation-owned.
            retained_name = stage_name
            if gc_recorder is not None:
                assert gc_path is not None
                gc_recorder(
                    _reserved_distribution_stage_ownership(
                        gc_path,
                        retained_name,
                        "regular" if stat.S_ISREG(moved.st_mode) else "symlink",
                        role="backup-reserved",
                    )
                )
            if mutation_validator is not None:
                mutation_validator()
            os.link(
                quarantine_name,
                retained_name,
                src_dir_fd=parent_fd,
                dst_dir_fd=parent_fd,
                follow_symlinks=False,
            )
            os.fsync(parent_fd)
            verified = os.stat(quarantine_name, dir_fd=parent_fd, follow_symlinks=False)
            if (
                verified.st_dev != moved.st_dev
                or verified.st_ino != moved.st_ino
                or verified.st_mode != moved.st_mode
                or verified.st_nlink != 2
                or (stat.S_ISLNK(moved.st_mode) and os.readlink(quarantine_name, dir_fd=parent_fd) != gc_original_link)
            ):
                raise DistributionApplyError("managed staging identity changed")
            if gc_recorder is not None:
                assert gc_path is not None
                retained = os.stat(retained_name, dir_fd=parent_fd, follow_symlinks=False)
                gc_recorder(
                    _distribution_stage_ownership(
                        gc_path,
                        retained_name,
                        retained,
                        role="backup-dual",
                    )
                )
                gc_recorder(
                    DistributionStageOwnership(
                        path=gc_path,
                        stage_name=quarantine_name,
                        device=verified.st_dev,
                        inode=verified.st_ino,
                        ctime_ns=verified.st_ctime_ns,
                        file_type="regular" if stat.S_ISREG(verified.st_mode) else "symlink",
                        role="gc-exact",
                        gc_predecessor_name=gc_predecessor_name or stage_name,
                        gc_ordinal=gc_ordinal,
                    )
                )
            if post_link_mutation_validator is not None:
                post_link_mutation_validator()
            delete_name = f"{stage_name}.{secrets.token_hex(16)}.gc"
            if gc_recorder is not None:
                assert gc_path is not None
                gc_recorder(
                    _reserved_distribution_stage_ownership(
                        gc_path,
                        delete_name,
                        "regular" if stat.S_ISREG(moved.st_mode) else "symlink",
                        role="gc-reserved",
                        gc_predecessor_name=quarantine_name,
                        gc_ordinal=2,
                    )
                )
            if mutation_validator is not None:
                mutation_validator()
            _rename_distribution_no_replace(parent_fd, quarantine_name, parent_fd, delete_name)
            os.fsync(parent_fd)
            deleting = os.stat(delete_name, dir_fd=parent_fd, follow_symlinks=False)
            retained = os.stat(retained_name, dir_fd=parent_fd, follow_symlinks=False)
            if (
                deleting.st_dev != retained.st_dev
                or deleting.st_ino != retained.st_ino
                or _file_type(deleting.st_mode) != _file_type(retained.st_mode)
                or deleting.st_nlink != retained.st_nlink
                or deleting.st_nlink != 2
                or (stat.S_ISLNK(deleting.st_mode) and os.readlink(delete_name, dir_fd=parent_fd) != gc_original_link)
            ):
                _restore_distribution_quarantine(
                    parent_fd,
                    delete_name,
                    quarantine_name,
                    failure_message="managed staging cleanup failed",
                )
                raise DistributionApplyError("managed staging identity changed")
            if gc_recorder is not None:
                assert gc_path is not None
                gc_recorder(
                    DistributionStageOwnership(
                        path=gc_path,
                        stage_name=delete_name,
                        device=deleting.st_dev,
                        inode=deleting.st_ino,
                        ctime_ns=deleting.st_ctime_ns,
                        file_type="regular" if stat.S_ISREG(deleting.st_mode) else "symlink",
                        role="gc-exact",
                        gc_predecessor_name=quarantine_name,
                        gc_ordinal=2,
                    )
                )
            try:
                if mutation_validator is not None:
                    mutation_validator()
            except DistributionApplyError:
                raise
            retained_gc_name = f"{stage_name}.{secrets.token_hex(16)}.gc"
            if gc_recorder is not None:
                assert gc_path is not None
                gc_recorder(
                    _reserved_distribution_stage_ownership(
                        gc_path,
                        retained_gc_name,
                        "regular" if stat.S_ISREG(retained.st_mode) else "symlink",
                        role="gc-reserved",
                        gc_predecessor_name=retained_name,
                        gc_ordinal=3,
                    )
                )
            if mutation_validator is not None:
                mutation_validator()
            _rename_distribution_no_replace(
                parent_fd,
                retained_name,
                parent_fd,
                retained_gc_name,
            )
            os.fsync(parent_fd)
            retained_gc = os.stat(retained_gc_name, dir_fd=parent_fd, follow_symlinks=False)
            deleting = os.stat(delete_name, dir_fd=parent_fd, follow_symlinks=False)
            if (
                retained_gc.st_dev != deleting.st_dev
                or retained_gc.st_ino != deleting.st_ino
                or _file_type(retained_gc.st_mode) != _file_type(deleting.st_mode)
                or retained_gc.st_nlink != deleting.st_nlink
                or retained_gc.st_nlink != 2
                or (
                    stat.S_ISLNK(retained_gc.st_mode)
                    and os.readlink(retained_gc_name, dir_fd=parent_fd) != gc_original_link
                )
            ):
                _restore_distribution_quarantine(
                    parent_fd,
                    retained_gc_name,
                    retained_name,
                    failure_message="managed staging cleanup failed",
                )
                raise DistributionApplyError("managed staging identity changed")
            if gc_recorder is not None:
                assert gc_path is not None
                gc_recorder(
                    DistributionStageOwnership(
                        path=gc_path,
                        stage_name=retained_gc_name,
                        device=retained_gc.st_dev,
                        inode=retained_gc.st_ino,
                        ctime_ns=retained_gc.st_ctime_ns,
                        file_type="regular" if stat.S_ISREG(retained_gc.st_mode) else "symlink",
                        role="gc-exact",
                        gc_predecessor_name=retained_name,
                        gc_ordinal=3,
                    )
                )
            if mutation_validator is not None:
                mutation_validator()
            os.unlink(delete_name, dir_fd=parent_fd)
            os.fsync(parent_fd)
            retained = os.stat(retained_gc_name, dir_fd=parent_fd, follow_symlinks=False)
            if (
                retained.st_dev != moved.st_dev
                or retained.st_ino != moved.st_ino
                or _file_type(retained.st_mode) != _file_type(moved.st_mode)
                or retained.st_nlink != 1
                or (
                    stat.S_ISLNK(retained.st_mode)
                    and os.readlink(retained_gc_name, dir_fd=parent_fd) != gc_original_link
                )
            ):
                raise DistributionApplyError("managed staging identity changed")
            if gc_recorder is not None:
                assert gc_path is not None
                gc_recorder(
                    _distribution_stage_ownership(
                        gc_path,
                        retained_gc_name,
                        retained,
                        role="backup-only",
                        gc_predecessor_name=retained_name,
                        gc_ordinal=3,
                    )
                )
            if post_link_mutation_validator is not None:
                post_link_mutation_validator()
            os.unlink(retained_gc_name, dir_fd=parent_fd)
            os.fsync(parent_fd)
            return retained_gc_name
        except Exception as exc:
            if isinstance(exc, DistributionApplyError) and exc.recovery_metadata_state is not None:
                raise
            if retained_gc_name is not None:
                with suppress(OSError, DistributionApplyError):
                    if (
                        _stat_optional_no_follow(parent_fd, retained_gc_name) is not None
                        and _stat_optional_no_follow(parent_fd, retained_name) is None
                    ):
                        _restore_distribution_quarantine(
                            parent_fd,
                            retained_gc_name,
                            retained_name,
                            failure_message="managed staging cleanup failed",
                        )
            if delete_name is not None:
                with suppress(OSError, DistributionApplyError):
                    deleting = os.stat(delete_name, dir_fd=parent_fd, follow_symlinks=False)
                    retained = os.stat(stage_name, dir_fd=parent_fd, follow_symlinks=False)
                    if (
                        deleting.st_dev == retained.st_dev
                        and deleting.st_ino == retained.st_ino
                        and _file_type(deleting.st_mode) == _file_type(retained.st_mode)
                        and deleting.st_nlink == retained.st_nlink == 2
                    ):
                        os.unlink(delete_name, dir_fd=parent_fd)
                        os.fsync(parent_fd)
                        restored = os.stat(stage_name, dir_fd=parent_fd, follow_symlinks=False)
                        if recovery_stage_recorder is not None and gc_path is not None:
                            recovery_stage_recorder(_distribution_stage_ownership(gc_path, stage_name, restored))
            with suppress(OSError, DistributionApplyError):
                retained = os.stat(quarantine_name, dir_fd=parent_fd, follow_symlinks=False)
                retained_is_exact = (
                    _stat_identity_tuple(retained) == _stat_identity_tuple(os.fstat(gc_held_fd))
                    if gc_held_fd is not None
                    else (
                        gc_original_link is not None
                        and retained.st_dev == current.st_dev
                        and retained.st_ino == current.st_ino
                        and retained.st_mode == current.st_mode
                        and retained.st_nlink == current.st_nlink
                        and os.readlink(quarantine_name, dir_fd=parent_fd) == gc_original_link
                    )
                )
                if retained_is_exact and _stat_optional_no_follow(parent_fd, stage_name) is None:
                    _restore_distribution_quarantine(
                        parent_fd,
                        quarantine_name,
                        stage_name,
                        failure_message="managed staging cleanup failed",
                    )
                    if recovery_stage_recorder is not None and gc_path is not None:
                        restored = os.stat(stage_name, dir_fd=parent_fd, follow_symlinks=False)
                        recovery_stage_recorder(_distribution_stage_ownership(gc_path, stage_name, restored))
            raise
        finally:
            if gc_held_fd is not None:
                os.close(gc_held_fd)
    except FileNotFoundError:
        return None
    except OSError as exc:
        if strict:
            raise DistributionApplyError("managed staging cleanup failed") from exc
        return None


def _distribution_stage_identity(
    parent_fd: int,
    stage_name: str,
    path: str,
    *,
    allow_backup_link: bool = False,
) -> DistributionIdentity | None:
    """Read a private stage identity without following its final path."""
    nofollow = getattr(os, "O_NOFOLLOW", None)
    if not isinstance(nofollow, int):
        raise DistributionApplyError("platform lacks required no-follow file support")
    try:
        info = os.stat(stage_name, dir_fd=parent_fd, follow_symlinks=False)
    except FileNotFoundError:
        return None
    except OSError as exc:
        raise DistributionApplyError("managed staging artifact cannot be inspected safely") from exc
    if info.st_nlink not in ({1, 2} if allow_backup_link else {1}):
        return None
    kind = _file_type(info.st_mode)
    if kind == "regular":
        try:
            fd = os.open(stage_name, os.O_RDONLY | nofollow | getattr(os, "O_CLOEXEC", 0), dir_fd=parent_fd)
        except OSError as exc:
            raise DistributionApplyError("managed staging artifact cannot be opened safely") from exc
        try:
            opened = os.fstat(fd)
            if (
                opened.st_dev != info.st_dev
                or opened.st_ino != info.st_ino
                or opened.st_ctime_ns != info.st_ctime_ns
                or opened.st_nlink != info.st_nlink
                or not stat.S_ISREG(opened.st_mode)
            ):
                raise DistributionApplyError("managed staging identity changed")
            return DistributionIdentity(
                kind="regular",
                sha256=hashlib.sha256(_read_fd_bytes(fd)).hexdigest(),
                mode=stat.S_IMODE(opened.st_mode),
            )
        finally:
            os.close(fd)
    if kind == "symlink":
        try:
            target = os.readlink(stage_name, dir_fd=parent_fd)
        except OSError as exc:
            raise DistributionApplyError("managed staging symlink cannot be read safely") from exc
        normalized = _normalized_link_target_for_path(path, target)
        if normalized is None:
            raise DistributionApplyError("managed staging symlink target is unsafe")
        return DistributionIdentity(kind="symlink", target=normalized)
    return None


def _distribution_stage_ownership(
    path: str,
    stage_name: str,
    info: os.stat_result,
    *,
    role: Literal[
        "stage",
        "predecessor-quarantine",
        "backup-reserved",
        "backup-dual",
        "backup-only-reserved",
        "backup-only",
        "gc-reserved",
        "gc-exact",
    ] = "stage",
    gc_predecessor_name: str | None = None,
    gc_ordinal: int | None = None,
) -> DistributionStageOwnership:
    kind = _file_type(info.st_mode)
    expected_links = 2 if role == "backup-dual" else 1
    if kind not in {"regular", "symlink"} or info.st_nlink != expected_links:
        raise DistributionApplyError("managed staging artifact is not safe to record")
    file_type: Literal["regular", "symlink"] = "regular" if kind == "regular" else "symlink"
    return DistributionStageOwnership(
        path=path,
        stage_name=stage_name,
        device=info.st_dev,
        inode=info.st_ino,
        ctime_ns=info.st_ctime_ns,
        file_type=file_type,
        role=role,
        gc_predecessor_name=gc_predecessor_name,
        gc_ordinal=gc_ordinal,
    )


def _reserved_distribution_stage_ownership(
    path: str,
    stage_name: str,
    file_type: Literal["regular", "symlink"],
    *,
    role: Literal[
        "stage",
        "predecessor-quarantine",
        "backup-reserved",
        "backup-dual",
        "backup-only-reserved",
        "backup-only",
        "gc-reserved",
        "gc-exact",
    ] = "stage",
    gc_predecessor_name: str | None = None,
    gc_ordinal: int | None = None,
) -> DistributionStageOwnership:
    """Persist a private stage name before its namespace entry is created."""

    return DistributionStageOwnership(
        path=path,
        stage_name=stage_name,
        device=0,
        inode=0,
        ctime_ns=0,
        file_type=file_type,
        role=role,
        gc_predecessor_name=gc_predecessor_name,
        gc_ordinal=gc_ordinal,
    )


def _distribution_stage_name(path: str, identity: DistributionIdentity) -> str:
    """Return the stable prefix for private stages owned by one planned target."""
    if identity.kind == "regular":
        identity_key = f"regular:{identity.sha256}"
        prefix = ".spec-dock-file-"
    else:
        identity_key = f"symlink:{identity.target}"
        prefix = ".spec-dock-symlink-"
    digest = hashlib.sha256(f"{path}\0{identity_key}".encode()).hexdigest()[:24]
    return f"{prefix}{digest}"


def _new_distribution_stage_name(path: str, identity: DistributionIdentity) -> str:
    """Return an attempt-unique stage name so an unleased crash cannot reserve the next attempt."""

    return f"{_distribution_stage_name(path, identity)}-{secrets.token_hex(16)}"


def _reusable_predecessor_stage_name(
    operation: DistributionOperation,
    action: DistributionAction,
    stage_ownership: tuple[DistributionStageOwnership, ...],
) -> str | None:
    """Reuse a deprovision prune's exact zero-identity reservation pathname."""

    if operation != "uninstall" or action.action != "prune":
        return None
    path = action.path
    leases = tuple(
        lease
        for lease in stage_ownership
        if lease.path == path
        and lease.role == "predecessor-quarantine"
        and lease.device == lease.inode == lease.ctime_ns == 0
    )
    if len(leases) > 1:
        raise DistributionApplyError("journal-precondition-mismatch")
    return leases[0].stage_name if leases else None


def _matches_distribution_stage_name(name: str, path: str, identity: DistributionIdentity) -> bool:
    prefix = _distribution_stage_name(path, identity)
    return name == prefix or name.startswith(f"{prefix}-")


def _historical_stage_identities(plan: DistributionPlan, path: str) -> tuple[DistributionIdentity, ...]:
    identities: list[DistributionIdentity] = []
    for record in _historical_records(plan.manifest):
        if record["path"] != path:
            continue
        if record["kind"] == "regular":
            identities.append(
                DistributionIdentity(
                    kind="regular",
                    sha256=record["sha256"],
                    mode=record.get("mode"),
                )
            )
        else:
            identities.append(DistributionIdentity(kind="symlink", target=record["target"]))
    return tuple(identities)


def _cleanup_stale_distribution_stages(
    plan: DistributionPlan,
    target_root: Path,
    action: DistributionAction,
    snapshot: DistributionTargetSnapshot,
    stage_ownership: tuple[DistributionStageOwnership, ...],
    mutation_validator: Callable[[tuple[int, ...]], None] | None = None,
    stage_ownership_recorder: Callable[[DistributionStageOwnership], None] | None = None,
    stage_ownership_remover: Callable[[str, tuple[str, ...]], None] | None = None,
) -> None:
    """Retry cleanup of private stages recorded by an earlier failed apply."""
    if action.action not in {"create", "adopt", "upgrade", "prune"}:
        return
    expected = _expected_target_identity(plan, action.path)
    historical = _historical_stage_identities(plan, action.path)
    if expected is None and not historical:
        return
    try:
        parent_chain = _open_distribution_parent_chain(
            target_root,
            action.path,
            create_missing=False,
            expected_snapshot=snapshot,
        )
    except DistributionApplyError as exc:
        if "parent is missing" in str(exc):
            return
        raise
    try:
        parent_fd = parent_chain[-1]

        def validate_cleanup_namespace() -> None:
            if mutation_validator is not None:
                mutation_validator(parent_chain)

        validate_cleanup_namespace()
        try:
            names = os.listdir(parent_fd)  # noqa: PTH208 - descriptor-relative scan is required for no-follow safety
        except OSError as exc:
            raise DistributionApplyError("managed staging directory cannot be listed safely") from exc
        known_identities = tuple(item for item in (expected, *historical) if item is not None)
        mismatch_detected = False
        cleaned = False
        for owned in stage_ownership:
            if owned.path != action.path or owned.stage_name not in names:
                continue
            if not any(
                _matches_distribution_stage_name(owned.stage_name, action.path, identity)
                for identity in known_identities
            ):
                continue
            try:
                current = os.stat(owned.stage_name, dir_fd=parent_fd, follow_symlinks=False)
            except FileNotFoundError:
                continue
            except OSError as exc:
                raise DistributionApplyError("managed staging artifact cannot be inspected safely") from exc
            if owned.role != "stage":
                continue
            if owned.device == owned.inode == owned.ctime_ns == 0:
                if _file_type(current.st_mode) != owned.file_type or current.st_nlink != 1:
                    mismatch_detected = True
                    continue
            elif (
                current.st_dev != owned.device
                or current.st_ino != owned.inode
                or current.st_ctime_ns != owned.ctime_ns
                or _file_type(current.st_mode) != owned.file_type
                or current.st_nlink != 1
            ):
                mismatch_detected = True
                continue
            candidate = _distribution_stage_identity(parent_fd, owned.stage_name, owned.path)
            if candidate is None:
                mismatch_detected = True
                continue
            # The retry marker's exact no-follow device/inode/ctime identity
            # proves ownership of this private stage.  Its payload may be
            # partial after a failed write, so requiring a known package
            # digest here would strand the same-package retry.  Content and
            # ownership checks still apply to ordinary target mutations.
            if stage_ownership_recorder is None or stage_ownership_remover is None:
                _remove_distribution_stage_if_owned(
                    parent_fd,
                    owned.stage_name,
                    current,
                    strict=True,
                    mutation_validator=validate_cleanup_namespace,
                    post_link_mutation_validator=(
                        validate_cleanup_namespace if plan.operation == "uninstall" else None
                    ),
                )
                cleaned = True
                continue
            quarantine_name = f"{owned.stage_name}.{secrets.token_hex(16)}.remove"
            held_fd: int | None = None
            try:
                if stat.S_ISREG(current.st_mode):
                    nofollow = getattr(os, "O_NOFOLLOW", None)
                    if not isinstance(nofollow, int):
                        raise DistributionApplyError("platform lacks required no-follow file support")
                    held_fd = os.open(
                        owned.stage_name,
                        os.O_RDONLY | nofollow | getattr(os, "O_CLOEXEC", 0),
                        dir_fd=parent_fd,
                    )
                _remove_distribution_target_if_bound(
                    parent_fd,
                    owned.stage_name,
                    current,
                    held_fd=held_fd,
                    identity_message="managed staging cleanup failed",
                    transition_path=owned.path,
                    transition_name=quarantine_name,
                    transition_recorder=stage_ownership_recorder,
                    mutation_validator=validate_cleanup_namespace,
                    post_link_mutation_validator=(
                        validate_cleanup_namespace if plan.operation == "uninstall" else None
                    ),
                )
            finally:
                if held_fd is not None:
                    os.close(held_fd)
            backup_name = _distribution_quarantine_backup_name(quarantine_name)
            backup = os.stat(backup_name, dir_fd=parent_fd, follow_symlinks=False)
            validate_cleanup_namespace()
            gc_name = _remove_distribution_stage_if_owned(
                parent_fd,
                backup_name,
                backup,
                strict=True,
                mutation_validator=validate_cleanup_namespace,
                post_link_mutation_validator=(validate_cleanup_namespace if plan.operation == "uninstall" else None),
                gc_path=owned.path,
                gc_recorder=stage_ownership_recorder,
            )
            stage_ownership_remover(
                owned.path,
                tuple(name for name in (owned.stage_name, quarantine_name, backup_name, gc_name) if name is not None),
            )
            cleaned = True
        if mismatch_detected and not cleaned:
            raise DistributionApplyError("managed staging identity changed")
    finally:
        _close_distribution_parent_chain(parent_chain)


def _expected_target_identity(plan: DistributionPlan, path: str) -> DistributionIdentity | None:
    identity = _target_identity_specs(plan.current_assets, plan.scaffold_assets).get(path)
    return identity if identity is not None else _required_directory_identity(plan, path)


def _asset_for_target(plan: DistributionPlan, path: str) -> DistributionAsset | None:
    for asset in (*plan.current_assets, *plan.scaffold_assets):
        target_path = asset.path
        if target_path == path:
            return asset
    return None


def _plan_snapshot_map(plan: DistributionPlan) -> dict[str, DistributionTargetSnapshot]:
    return dict(plan.target_snapshots)


def _assert_plan_target_snapshot(
    target_root: Path,
    path: str,
    expected: DistributionTargetSnapshot,
) -> _TargetObservation:
    observation = _observe_target(target_root, path)
    if observation.snapshot is None:
        raise DistributionApplyError(f"managed target identity changed for '{path}'")
    try:
        _assert_pending_snapshot_stable(
            observation.snapshot,
            expected,
            path,
            {},
        )
    except DistributionApplyError:
        raise DistributionApplyError(f"managed target identity changed for '{path}'") from None
    return observation


def _same_structure_identity(actual: PathIdentitySnapshot, expected: PathIdentitySnapshot) -> bool:
    if not expected.exists or not actual.exists:
        return actual.exists == expected.exists
    return (
        actual.device == expected.device
        and actual.inode == expected.inode
        and actual.file_type == expected.file_type
        and (expected.mode is None or actual.mode is None or actual.mode == expected.mode)
    )


def _assert_pending_snapshot_stable(
    actual: DistributionTargetSnapshot,
    expected: DistributionTargetSnapshot,
    path: str,
    created_parent_bindings: dict[str, PathIdentitySnapshot],
) -> None:
    if not _same_structure_identity(actual.root, expected.root):
        raise DistributionApplyError(f"managed target identity changed for '{path}'")
    actual_parents = {parent.relative_path: parent for parent in actual.parents}
    for expected_parent in expected.parents:
        actual_parent = actual_parents.get(
            expected_parent.relative_path, _missing_snapshot(expected_parent.relative_path)
        )
        if expected_parent.exists:
            if not _same_structure_identity(actual_parent, expected_parent):
                raise DistributionApplyError(f"managed target identity changed for '{path}'")
        elif actual_parent.exists:
            bound_parent = created_parent_bindings.get(expected_parent.relative_path)
            if bound_parent is None or not bound_parent.exists:
                # A parent that was absent during preflight may only become
                # acceptable after this operation creates and binds it through
                # `_bind_created_parent_identities`.  Accepting an unbound
                # inode here would turn a user- or concurrently-created
                # directory into an operation-owned parent after preflight.
                raise DistributionApplyError(f"managed target identity changed for '{path}'")
            if actual_parent.file_type != "directory" or not _same_structure_identity(actual_parent, bound_parent):
                raise DistributionApplyError(f"managed target identity changed for '{path}'")
    target_matches = (
        _same_structure_identity(actual.target, expected.target)
        if expected.target.file_type == "directory"
        else actual.target == expected.target
    )
    if not target_matches:
        raise DistributionApplyError(f"managed target identity changed for '{path}'")


def _assert_action_snapshots_stable(
    target_root: Path,
    actions: tuple[DistributionAction, ...],
    snapshots: dict[str, DistributionTargetSnapshot],
    created_parent_bindings: dict[str, PathIdentitySnapshot],
) -> None:
    """Validate each action once at its phase boundary."""

    for action in actions:
        observation = _observe_target(target_root, action.path)
        if observation.snapshot is None:
            raise DistributionApplyError(f"managed target identity changed for '{action.path}'")
        _assert_pending_snapshot_stable(
            observation.snapshot,
            snapshots[action.path],
            action.path,
            created_parent_bindings,
        )


def _pending_unbound_directory_guards(
    actions: tuple[DistributionAction, ...],
    snapshots: dict[str, DistributionTargetSnapshot],
    created_parent_bindings: dict[str, PathIdentitySnapshot],
    required_directory_paths: set[str],
) -> tuple[str, ...]:
    """Return the first still-unbound missing directory for each pending action."""

    guards: set[str] = set()
    for action in actions:
        snapshot = snapshots[action.path]
        candidates = [
            parent.relative_path
            for parent in snapshot.parents
            if not parent.exists and parent.relative_path in required_directory_paths
        ]
        if action.path in required_directory_paths and not snapshot.target.exists:
            candidates.append(action.path)
        for candidate in candidates:
            binding = created_parent_bindings.get(candidate)
            if binding is None or not binding.exists:
                guards.add(candidate)
                break
    return tuple(sorted(guards))


def _assert_pending_unbound_directories_stable(
    target_root: Path,
    actions: tuple[DistributionAction, ...],
    snapshots: dict[str, DistributionTargetSnapshot],
    created_parent_bindings: dict[str, PathIdentitySnapshot],
    required_directory_paths: set[str],
) -> None:
    """Fail early when an external actor creates a pending operation parent."""

    for path in _pending_unbound_directory_guards(
        actions,
        snapshots,
        created_parent_bindings,
        required_directory_paths,
    ):
        observation = _observe_target(target_root, path)
        if observation.snapshot is None:
            raise DistributionApplyError(f"managed target identity changed for '{path}'")
        _assert_pending_snapshot_stable(
            observation.snapshot,
            snapshots[path],
            path,
            created_parent_bindings,
        )


def _refresh_pending_parent_snapshots(
    actions: tuple[DistributionAction, ...],
    snapshots: dict[str, DistributionTargetSnapshot],
    operation_observation: DistributionTargetSnapshot,
) -> None:
    """Propagate exact parent identities observed after an owned mutation."""

    observed_parents = {parent.relative_path: parent for parent in operation_observation.parents}
    for action in actions:
        snapshot = snapshots[action.path]
        updated_root = snapshot.root
        if _same_structure_identity(operation_observation.root, snapshot.root):
            updated_root = operation_observation.root
        updated_parents: list[PathIdentitySnapshot] = []
        changed = updated_root != snapshot.root
        for parent in snapshot.parents:
            observed = observed_parents.get(parent.relative_path)
            if observed is not None and _same_structure_identity(observed, parent):
                updated_parents.append(observed)
                changed = changed or observed != parent
            else:
                updated_parents.append(parent)
        if changed:
            snapshots[action.path] = replace(snapshot, root=updated_root, parents=tuple(updated_parents))


def _refresh_pending_action_snapshots(
    target_root: Path,
    actions: tuple[DistributionAction, ...],
    snapshots: dict[str, DistributionTargetSnapshot],
    created_parent_bindings: dict[str, PathIdentitySnapshot],
) -> None:
    """Re-observe all pending actions for destructive reconciliation paths."""

    for action in actions:
        snapshot = snapshots[action.path]
        observation = _observe_target(target_root, action.path)
        if observation.snapshot is None:
            raise DistributionApplyError(f"managed target identity changed for '{action.path}'")
        _assert_pending_snapshot_stable(
            observation.snapshot,
            snapshot,
            action.path,
            created_parent_bindings,
        )
        snapshots[action.path] = observation.snapshot


def _bind_created_parent_identities(
    target_rel: str,
    snapshot: DistributionTargetSnapshot,
    parent_chain: tuple[int, ...],
    created_parent_bindings: dict[str, PathIdentitySnapshot],
    created_parent_recorder: Callable[[tuple[PathIdentitySnapshot, ...]], None] | None = None,
) -> None:
    changed = False
    for index, expected_parent in enumerate(snapshot.parents, start=1):
        bound_parent = created_parent_bindings.get(expected_parent.relative_path)
        if index >= len(parent_chain) or (expected_parent.exists and (bound_parent is None or bound_parent.exists)):
            continue
        current = _snapshot_from_stat(
            expected_parent.relative_path,
            os.fstat(parent_chain[index]),
        )
        if bound_parent is None or not bound_parent.exists:
            created_parent_bindings[expected_parent.relative_path] = current
            changed = True
        elif not _same_structure_identity(current, bound_parent):
            raise DistributionApplyError(f"managed target identity changed for '{target_rel}'")
    if changed and created_parent_recorder is not None:
        created_parent_recorder(tuple(created_parent_bindings[path] for path in sorted(created_parent_bindings)))


def _apply_regular_action(
    *,
    target_root: Path,
    action: DistributionAction,
    snapshot: DistributionTargetSnapshot,
    expected: DistributionIdentity,
    source_bytes: bytes | None,
    source_mode: int | None,
    created_parent_bindings: dict[str, PathIdentitySnapshot],
    stage_ownership_recorder: Callable[[DistributionStageOwnership], None] | None,
    created_parent_recorder: Callable[[tuple[PathIdentitySnapshot, ...]], None] | None,
    write_ahead_stage_reservations: bool,
    before_mutation: Callable[[], None] | None,
    held_parent_validator: Callable[[str, tuple[int, ...]], None] | None,
    first_target_mutation_validator: Callable[[], Callable[[], None] | None] | None,
    reusable_predecessor_stage_name: str | None,
    held_parent_checkpoint_recorder: Callable[[str, tuple[int, ...]], None] | None,
    deprovision_post_link_validation: bool,
) -> None:
    path = action.path
    if action.action == "prune" and not snapshot.target.exists:
        return
    if first_target_mutation_validator is None:
        parent_chain = _open_distribution_parent_chain(
            target_root,
            path,
            create_missing=action.action == "create",
            expected_snapshot=snapshot,
            created_parent_bindings=created_parent_bindings,
            created_parent_recorder=created_parent_recorder,
        )
    else:
        parent_chain = _open_distribution_parent_chain(
            target_root,
            path,
            create_missing=action.action == "create",
            expected_snapshot=snapshot,
            created_parent_bindings=created_parent_bindings,
            created_parent_recorder=created_parent_recorder,
            first_target_mutation_validator=first_target_mutation_validator,
        )
    try:
        _assert_distribution_chain_bound(parent_chain, snapshot, path)
        _assert_visible_distribution_chain_bound(target_root, path, parent_chain)
        _bind_created_parent_identities(
            path,
            snapshot,
            parent_chain,
            created_parent_bindings,
            created_parent_recorder,
        )

        def validate_held_namespace() -> None:
            if before_mutation is not None:
                before_mutation()
            if held_parent_validator is not None:
                held_parent_validator(path, parent_chain)

        validate_held_namespace()
        parent_fd = parent_chain[-1]
        target_name = PurePosixPath(path).name
        try:
            target_stat = os.stat(target_name, dir_fd=parent_fd, follow_symlinks=False)
            target_exists = True
        except FileNotFoundError:
            target_stat = None
            target_exists = False

        if action.action == "create":
            if target_exists:
                raise DistributionApplyError(f"managed target identity changed for '{path}'")
            if expected.kind != "regular" or source_bytes is None or source_mode is None:
                raise DistributionApplyError(f"unsupported managed create action for '{path}'")
            _resolve_distribution_no_replace_rename()
            nofollow = getattr(os, "O_NOFOLLOW", None)
            if not isinstance(nofollow, int):
                raise DistributionApplyError("platform lacks required no-follow file support")
            staging_name = _new_distribution_stage_name(path, expected)
            if write_ahead_stage_reservations and stage_ownership_recorder is not None:
                stage_ownership_recorder(_reserved_distribution_stage_ownership(path, staging_name, "regular"))
                validate_held_namespace()
            validate_held_namespace()
            commit_first_mutation = (
                first_target_mutation_validator() if first_target_mutation_validator is not None else None
            )
            fd = os.open(
                staging_name,
                os.O_RDWR | os.O_CREAT | os.O_EXCL | nofollow | getattr(os, "O_CLOEXEC", 0),
                source_mode,
                dir_fd=parent_fd,
            )
            if commit_first_mutation is not None:
                commit_first_mutation()
            created = os.fstat(fd)
            validate_held_namespace()
            stage_identity = created
            try:
                if not stat.S_ISREG(created.st_mode) or created.st_nlink != 1:
                    raise DistributionApplyError(f"managed target is unsafe for '{path}'")
                if stage_ownership_recorder is not None and not write_ahead_stage_reservations:
                    stage_ownership_recorder(_distribution_stage_ownership(path, staging_name, created))
                mutation_phase = "pre"

                def check_before_write() -> None:
                    nonlocal mutation_phase
                    _assert_visible_distribution_chain_bound(target_root, path, parent_chain)
                    current = os.fstat(fd)
                    if not stat.S_ISREG(current.st_mode) or current.st_nlink != 1:
                        raise DistributionApplyError(f"managed target identity changed for '{path}'")
                    mutation_phase = "post"

                _write_fd_bytes(fd, source_bytes, before_mutation=check_before_write)
                _assert_visible_distribution_chain_bound(target_root, path, parent_chain)
                if os.fstat(fd).st_nlink != 1:
                    raise DistributionApplyError(f"managed target identity changed for '{path}'")
                os.fchmod(fd, source_mode)
                verified = os.fstat(fd)
                if (
                    verified.st_nlink != 1
                    or stat.S_IMODE(verified.st_mode) != source_mode
                    or hashlib.sha256(_read_fd_bytes(fd)).hexdigest() != expected.sha256
                ):
                    raise DistributionApplyError(f"managed target verification failed for '{path}'")
                stage_identity = verified
                if write_ahead_stage_reservations and stage_ownership_recorder is not None:
                    stage_ownership_recorder(_distribution_stage_ownership(path, staging_name, verified))
                    validate_held_namespace()
                _assert_visible_distribution_chain_bound(target_root, path, parent_chain)
                validate_held_namespace()
                _rename_distribution_no_replace(parent_fd, staging_name, parent_fd, target_name)
                os.fsync(parent_fd)
            finally:
                with suppress(OSError):
                    stage_identity = os.fstat(fd)
                try:
                    # A failed write may mutate the stage before raising.  The
                    # creation-time stat is then stale (ctime changes), so
                    # refresh and publish the no-follow identity before
                    # attempting ownership-checked cleanup.  The refreshed
                    # marker lets the next same-package retry identify a
                    # partial stage even when cleanup fails here.
                    if stage_ownership_recorder is not None and not write_ahead_stage_reservations:
                        stage_ownership_recorder(_distribution_stage_ownership(path, staging_name, stage_identity))
                finally:
                    try:
                        os.close(fd)
                    finally:
                        _remove_distribution_stage_if_owned(
                            parent_fd,
                            staging_name,
                            stage_identity,
                            strict=True,
                            mutation_validator=validate_held_namespace,
                            post_link_mutation_validator=(
                                validate_held_namespace if deprovision_post_link_validation else None
                            ),
                            gc_path=path,
                            gc_recorder=stage_ownership_recorder,
                            recovery_stage_recorder=stage_ownership_recorder,
                        )
            published_fd = os.open(target_name, os.O_RDONLY | nofollow | getattr(os, "O_CLOEXEC", 0), dir_fd=parent_fd)
            try:
                published = os.fstat(published_fd)
                if (
                    published.st_nlink != 1
                    or stat.S_IMODE(published.st_mode) != source_mode
                    or hashlib.sha256(_read_fd_bytes(published_fd)).hexdigest() != expected.sha256
                ):
                    raise DistributionApplyError(f"managed target verification failed for '{path}'")
            finally:
                os.close(published_fd)
            return

        if not target_exists or target_stat is None:
            if action.action == "prune":
                return
            raise DistributionApplyError(f"managed target identity changed for '{path}'")

        if expected.kind != "regular":
            raise DistributionApplyError(f"unsupported regular managed action for '{path}'")
        nofollow = getattr(os, "O_NOFOLLOW", None)
        if not isinstance(nofollow, int):
            raise DistributionApplyError("platform lacks required no-follow file support")
        flags = os.O_RDONLY | nofollow | getattr(os, "O_CLOEXEC", 0)
        fd = os.open(target_name, flags, dir_fd=parent_fd)
        try:
            opened = os.fstat(fd)
            if not _same_stat_identity(opened, snapshot.target) or opened.st_nlink != 1:
                raise DistributionApplyError(f"managed target identity changed for '{path}'")
            if action.action == "prune":
                target_identity = snapshot.target.identity
                if target_identity is None or target_identity.kind != "regular":
                    raise DistributionApplyError(f"managed target identity changed for '{path}'")
                if hashlib.sha256(_read_fd_bytes(fd)).hexdigest() != target_identity.sha256:
                    raise DistributionApplyError(f"managed target identity changed for '{path}'")
                _assert_visible_distribution_chain_bound(target_root, path, parent_chain)
                _assert_regular_fd_safe(fd, snapshot.target, path, exact=True)
                commit_first_mutation = (
                    first_target_mutation_validator() if first_target_mutation_validator is not None else None
                )
                validate_held_namespace()
                _remove_distribution_target_if_bound(
                    parent_fd,
                    target_name,
                    opened,
                    held_fd=fd,
                    identity_message=f"managed target identity changed for '{path}'",
                    transition_path=path,
                    transition_name=(
                        reusable_predecessor_stage_name or _new_distribution_stage_name(path, target_identity)
                    ),
                    transition_recorder=(stage_ownership_recorder if write_ahead_stage_reservations else None),
                    mutation_validator=validate_held_namespace,
                    post_link_mutation_validator=(
                        validate_held_namespace if deprovision_post_link_validation else None
                    ),
                )
                if held_parent_checkpoint_recorder is not None:
                    held_parent_checkpoint_recorder(path, parent_chain)
                if commit_first_mutation is not None:
                    commit_first_mutation()
                return
            if action.action != "upgrade":
                raise DistributionApplyError(f"unsupported regular action for '{path}'")
            if source_bytes is None or source_mode is None:
                raise DistributionApplyError(f"missing provider bytes for '{path}'")
            _assert_regular_fd_safe(fd, snapshot.target, path, exact=True)
            target_identity = snapshot.target.identity
            if target_identity is None or target_identity.kind != "regular":
                raise DistributionApplyError(f"managed target identity changed for '{path}'")
            if hashlib.sha256(_read_fd_bytes(fd)).hexdigest() != target_identity.sha256:
                raise DistributionApplyError(f"managed target identity changed for '{path}'")

            _resolve_distribution_swap_rename()
            staging_name = _new_distribution_stage_name(path, expected)
            if write_ahead_stage_reservations and stage_ownership_recorder is not None:
                stage_ownership_recorder(_reserved_distribution_stage_ownership(path, staging_name, "regular"))
                validate_held_namespace()
            validate_held_namespace()
            commit_first_mutation = (
                first_target_mutation_validator() if first_target_mutation_validator is not None else None
            )
            staging_fd = os.open(
                staging_name,
                os.O_RDWR | os.O_CREAT | os.O_EXCL | nofollow | getattr(os, "O_CLOEXEC", 0),
                source_mode,
                dir_fd=parent_fd,
            )
            if commit_first_mutation is not None:
                commit_first_mutation()
            staging_stat = os.fstat(staging_fd)
            validate_held_namespace()
            stage_identity = staging_stat
            swapped = False
            try:
                if not stat.S_ISREG(staging_stat.st_mode) or staging_stat.st_nlink != 1:
                    raise DistributionApplyError(f"managed target staging failed for '{path}'")
                if stage_ownership_recorder is not None and not write_ahead_stage_reservations:
                    stage_ownership_recorder(_distribution_stage_ownership(path, staging_name, staging_stat))

                def check_before_stage_write() -> None:
                    _assert_visible_distribution_chain_bound(target_root, path, parent_chain)
                    current = os.fstat(staging_fd)
                    if not stat.S_ISREG(current.st_mode) or current.st_nlink != 1:
                        raise DistributionApplyError(f"managed target staging failed for '{path}'")

                _write_fd_bytes(staging_fd, source_bytes, before_mutation=check_before_stage_write)
                os.fchmod(staging_fd, source_mode)
                staged = os.fstat(staging_fd)
                if (
                    staged.st_nlink != 1
                    or stat.S_IMODE(staged.st_mode) != source_mode
                    or hashlib.sha256(_read_fd_bytes(staging_fd)).hexdigest() != expected.sha256
                ):
                    raise DistributionApplyError(f"managed target staging verification failed for '{path}'")
                stage_identity = staged
                if write_ahead_stage_reservations and stage_ownership_recorder is not None:
                    stage_ownership_recorder(_distribution_stage_ownership(path, staging_name, staged))
                    validate_held_namespace()

                _assert_visible_distribution_chain_bound(target_root, path, parent_chain)
                _assert_regular_fd_safe(fd, snapshot.target, path, exact=True)
                if hashlib.sha256(_read_fd_bytes(fd)).hexdigest() != target_identity.sha256:
                    raise DistributionApplyError(f"managed target identity changed for '{path}'")
                validate_held_namespace()
                _swap_regular_distribution_target_if_bound(
                    parent_fd,
                    staging_name,
                    target_name,
                    target_fd=fd,
                    staging_fd=staging_fd,
                    expected_target=opened,
                    identity_message=f"managed target identity changed for '{path}'",
                )
                swapped = True
                staged_successor = os.fstat(staging_fd)

                published_fd = os.open(
                    target_name, os.O_RDONLY | nofollow | getattr(os, "O_CLOEXEC", 0), dir_fd=parent_fd
                )
                try:
                    published = os.fstat(published_fd)
                    if (
                        _stat_identity_tuple(published) != _stat_identity_tuple(staged_successor)
                        or published.st_nlink != 1
                        or stat.S_IMODE(published.st_mode) != source_mode
                        or hashlib.sha256(_read_fd_bytes(published_fd)).hexdigest() != expected.sha256
                    ):
                        raise DistributionApplyError(f"managed target verification failed for '{path}'")
                finally:
                    os.close(published_fd)
            finally:
                if not swapped:
                    # A failed write may mutate the stage before raising.  The
                    # creation-time stat is then stale (ctime changes), so
                    # refresh and publish the no-follow identity before
                    # attempting ownership-checked cleanup.
                    visible_stage_matches = False
                    with suppress(OSError):
                        stage_identity = os.fstat(staging_fd)
                        visible_stage = os.stat(staging_name, dir_fd=parent_fd, follow_symlinks=False)
                        visible_stage_matches = _stat_identity_tuple(visible_stage) == _stat_identity_tuple(
                            stage_identity
                        )
                    if not visible_stage_matches:
                        os.close(staging_fd)
                        raise DistributionApplyError(f"managed target identity changed for '{path}'")
                    try:
                        if stage_ownership_recorder is not None and not write_ahead_stage_reservations:
                            stage_ownership_recorder(_distribution_stage_ownership(path, staging_name, stage_identity))
                    finally:
                        try:
                            os.close(staging_fd)
                        finally:
                            _remove_distribution_stage_if_owned(
                                parent_fd,
                                staging_name,
                                stage_identity,
                                strict=True,
                                mutation_validator=validate_held_namespace,
                                post_link_mutation_validator=(
                                    validate_held_namespace if deprovision_post_link_validation else None
                                ),
                                gc_path=path,
                                gc_recorder=stage_ownership_recorder,
                                recovery_stage_recorder=stage_ownership_recorder,
                            )
                else:
                    published_successor = staged_successor
                    os.close(staging_fd)
                    try:
                        old_stat = os.stat(staging_name, dir_fd=parent_fd, follow_symlinks=False)
                        old_fd = os.open(
                            staging_name,
                            os.O_RDONLY | nofollow | getattr(os, "O_CLOEXEC", 0),
                            dir_fd=parent_fd,
                        )
                        try:
                            old_digest = hashlib.sha256(_read_fd_bytes(old_fd)).hexdigest()
                        finally:
                            os.close(old_fd)
                        if (
                            _same_stat_structure(old_stat, snapshot.target)
                            and old_stat.st_nlink == 1
                            and old_digest == target_identity.sha256
                        ):
                            successor_ownership = _distribution_stage_ownership(
                                path,
                                staging_name,
                                published_successor,
                            )
                            successor_condition: dict[str, object] = {
                                "identity": _distribution_identity_payload(expected)
                            }
                            predecessor_condition: dict[str, object] = {
                                "device": snapshot.target.device,
                                "inode": snapshot.target.inode,
                                "file_type": snapshot.target.file_type,
                                "link_count": snapshot.target.link_count,
                                "identity": _distribution_identity_payload(snapshot.target.identity),
                            }
                            if stage_ownership_recorder is not None:
                                # Persist the exact canonical successor before
                                # removing the displaced predecessor.  Retry
                                # can then prove both sides of an interrupted
                                # publish/cleanup transition and rebind the
                                # stage lease when needed.
                                try:
                                    stage_ownership_recorder(
                                        _distribution_stage_ownership(
                                            path,
                                            staging_name,
                                            published_successor if write_ahead_stage_reservations else old_stat,
                                        )
                                    )
                                except Exception as record_error:
                                    # The swap has already published the new
                                    # target, so the stage pathname now owns
                                    # the former target inode.  A transient
                                    # marker-write failure must not strand the
                                    # pre-swap identity: retry the recorder
                                    # once before falling back to cleanup.
                                    with suppress(Exception):
                                        stage_ownership_recorder(
                                            _distribution_stage_ownership(
                                                path,
                                                staging_name,
                                                published_successor if write_ahead_stage_reservations else old_stat,
                                            )
                                        )
                                    try:
                                        _remove_distribution_stage_if_owned(
                                            parent_fd,
                                            staging_name,
                                            old_stat,
                                            strict=True,
                                            transition_path=path,
                                            canonical_name=target_name,
                                            canonical_ownership=successor_ownership,
                                            canonical_condition=successor_condition,
                                            stage_condition=predecessor_condition,
                                            recovery_stage_recorder=(
                                                stage_ownership_recorder if not write_ahead_stage_reservations else None
                                            ),
                                            transition_recorder=(
                                                stage_ownership_recorder if write_ahead_stage_reservations else None
                                            ),
                                            mutation_validator=validate_held_namespace,
                                            post_link_mutation_validator=(
                                                validate_held_namespace if deprovision_post_link_validation else None
                                            ),
                                        )
                                    except DistributionApplyError as cleanup_error:
                                        # Quarantine restoration changes ctime.  Do not
                                        # reacquire predecessor authority from a fresh
                                        # stat and retry in-place; the recovery recorder
                                        # above persisted the new exact lease for the
                                        # next normal recovery pass.
                                        raise cleanup_error from record_error
                                    raise
                            current_successor = os.stat(target_name, dir_fd=parent_fd, follow_symlinks=False)
                            if _stat_identity_tuple(current_successor) != _stat_identity_tuple(published_successor):
                                raise DistributionApplyError(f"managed target identity changed for '{path}'")
                            _remove_distribution_stage_if_owned(
                                parent_fd,
                                staging_name,
                                old_stat,
                                strict=True,
                                transition_path=path,
                                canonical_name=target_name,
                                canonical_ownership=successor_ownership,
                                canonical_condition=successor_condition,
                                stage_condition=predecessor_condition,
                                recovery_stage_recorder=(
                                    stage_ownership_recorder if not write_ahead_stage_reservations else None
                                ),
                                transition_recorder=(
                                    stage_ownership_recorder if write_ahead_stage_reservations else None
                                ),
                                mutation_validator=validate_held_namespace,
                                post_link_mutation_validator=(
                                    validate_held_namespace if deprovision_post_link_validation else None
                                ),
                            )
                        else:
                            raise DistributionApplyError("managed staging identity changed")
                    except FileNotFoundError:
                        pass
        finally:
            os.close(fd)
    except FileNotFoundError as exc:
        raise DistributionApplyError(f"managed target identity changed for '{path}'") from exc
    except OSError as exc:
        raise DistributionApplyError(f"managed target apply failed for '{path}'") from exc
    finally:
        _close_distribution_parent_chain(parent_chain)


def _apply_symlink_action(
    *,
    target_root: Path,
    action: DistributionAction,
    snapshot: DistributionTargetSnapshot,
    expected: DistributionIdentity,
    created_parent_bindings: dict[str, PathIdentitySnapshot],
    stage_ownership_recorder: Callable[[DistributionStageOwnership], None] | None,
    created_parent_recorder: Callable[[tuple[PathIdentitySnapshot, ...]], None] | None,
    write_ahead_stage_reservations: bool,
    before_mutation: Callable[[], None] | None,
    held_parent_validator: Callable[[str, tuple[int, ...]], None] | None,
    first_target_mutation_validator: Callable[[], Callable[[], None] | None] | None,
    reusable_predecessor_stage_name: str | None,
    held_parent_checkpoint_recorder: Callable[[str, tuple[int, ...]], None] | None,
    deprovision_post_link_validation: bool,
) -> None:
    if expected.target is None:
        raise DistributionApplyError(f"managed symlink identity has no target for '{action.path}'")
    expected_target = expected.target
    if action.action == "prune" and not snapshot.target.exists:
        return
    if first_target_mutation_validator is None:
        parent_chain = _open_distribution_parent_chain(
            target_root,
            action.path,
            create_missing=action.action == "create",
            expected_snapshot=snapshot,
            created_parent_bindings=created_parent_bindings,
            created_parent_recorder=created_parent_recorder,
        )
    else:
        parent_chain = _open_distribution_parent_chain(
            target_root,
            action.path,
            create_missing=action.action == "create",
            expected_snapshot=snapshot,
            created_parent_bindings=created_parent_bindings,
            created_parent_recorder=created_parent_recorder,
            first_target_mutation_validator=first_target_mutation_validator,
        )
    try:
        _assert_distribution_chain_bound(parent_chain, snapshot, action.path)
        _assert_visible_distribution_chain_bound(target_root, action.path, parent_chain)
        _bind_created_parent_identities(
            action.path,
            snapshot,
            parent_chain,
            created_parent_bindings,
            created_parent_recorder,
        )

        def validate_held_namespace() -> None:
            if before_mutation is not None:
                before_mutation()
            if held_parent_validator is not None:
                held_parent_validator(action.path, parent_chain)

        validate_held_namespace()
        parent_fd = parent_chain[-1]
        target_name = PurePosixPath(action.path).name
        try:
            current_stat = os.stat(target_name, dir_fd=parent_fd, follow_symlinks=False)
            target_exists = True
        except FileNotFoundError:
            current_stat = None
            current_target = None
            target_exists = False
        except OSError as exc:
            raise DistributionApplyError(f"managed target is unsafe for '{action.path}'") from exc
        else:
            assert current_stat is not None
            if stat.S_ISLNK(current_stat.st_mode):
                try:
                    current_target = _normalized_link_target_for_path(
                        action.path,
                        os.readlink(target_name, dir_fd=parent_fd),
                    )
                except OSError as exc:
                    raise DistributionApplyError(f"managed target is unsafe for '{action.path}'") from exc
            else:
                current_target = None

        if action.action == "create":
            if target_exists:
                raise DistributionApplyError(f"managed target identity changed for '{action.path}'")
            _resolve_distribution_no_replace_rename()
            staging_name = _new_distribution_stage_name(action.path, expected)
            if write_ahead_stage_reservations and stage_ownership_recorder is not None:
                stage_ownership_recorder(_reserved_distribution_stage_ownership(action.path, staging_name, "symlink"))
                validate_held_namespace()
            validate_held_namespace()
            commit_first_mutation = (
                first_target_mutation_validator() if first_target_mutation_validator is not None else None
            )
            os.symlink(expected_target, staging_name, dir_fd=parent_fd)
            if commit_first_mutation is not None:
                commit_first_mutation()
            staging_stat = os.stat(staging_name, dir_fd=parent_fd, follow_symlinks=False)
            validate_held_namespace()
            published = False
            try:
                staged_target = _normalized_link_target_for_path(
                    action.path, os.readlink(staging_name, dir_fd=parent_fd)
                )
                if staged_target != expected_target or staging_stat.st_nlink != 1:
                    raise DistributionApplyError(f"managed target staging failed for '{action.path}'")
                if stage_ownership_recorder is not None:
                    stage_ownership_recorder(_distribution_stage_ownership(action.path, staging_name, staging_stat))
                    validate_held_namespace()
                _assert_visible_distribution_chain_bound(target_root, action.path, parent_chain)
                validate_held_namespace()
                _rename_distribution_no_replace(parent_fd, staging_name, parent_fd, target_name)
                os.fsync(parent_fd)
                published = True
            finally:
                if not published:
                    # A recorder failure or publish failure may leave the
                    # symlink stage behind.  Refresh its no-follow identity
                    # before retrying the marker record and use strict,
                    # ownership-checked cleanup so a transient unlink error
                    # remains recoverable by the next same-package retry.
                    with suppress(OSError):
                        staging_stat = os.stat(staging_name, dir_fd=parent_fd, follow_symlinks=False)
                    try:
                        if stage_ownership_recorder is not None:
                            stage_ownership_recorder(
                                _distribution_stage_ownership(action.path, staging_name, staging_stat)
                            )
                    finally:
                        _remove_distribution_stage_if_owned(
                            parent_fd,
                            staging_name,
                            staging_stat,
                            strict=True,
                            mutation_validator=validate_held_namespace,
                            post_link_mutation_validator=(
                                validate_held_namespace if deprovision_post_link_validation else None
                            ),
                            gc_path=action.path,
                            gc_recorder=stage_ownership_recorder,
                            recovery_stage_recorder=stage_ownership_recorder,
                        )
            created_target = _normalized_link_target_for_path(action.path, os.readlink(target_name, dir_fd=parent_fd))
            if created_target != expected_target:
                raise DistributionApplyError(f"managed target verification failed for '{action.path}'")
            return
        if action.action == "prune":
            if not target_exists:
                return
            if snapshot.target.identity is None or current_target != snapshot.target.identity.target:
                raise DistributionApplyError(f"managed target identity changed for '{action.path}'")
            latest_stat = os.stat(target_name, dir_fd=parent_fd, follow_symlinks=False)
            if not _same_stat_identity(latest_stat, snapshot.target) or latest_stat.st_nlink != 1:
                raise DistributionApplyError(f"managed target identity changed for '{action.path}'")
            _assert_visible_distribution_chain_bound(target_root, action.path, parent_chain)
            latest_target = _normalized_link_target_for_path(action.path, os.readlink(target_name, dir_fd=parent_fd))
            if latest_target != snapshot.target.identity.target:
                raise DistributionApplyError(f"managed target identity changed for '{action.path}'")
            commit_first_mutation = (
                first_target_mutation_validator() if first_target_mutation_validator is not None else None
            )
            validate_held_namespace()
            _remove_distribution_target_if_bound(
                parent_fd,
                target_name,
                latest_stat,
                identity_message=f"managed target identity changed for '{action.path}'",
                transition_path=action.path,
                transition_name=(
                    reusable_predecessor_stage_name
                    or _new_distribution_stage_name(action.path, snapshot.target.identity)
                ),
                transition_recorder=(stage_ownership_recorder if write_ahead_stage_reservations else None),
                mutation_validator=validate_held_namespace,
                post_link_mutation_validator=(validate_held_namespace if deprovision_post_link_validation else None),
            )
            if held_parent_checkpoint_recorder is not None:
                held_parent_checkpoint_recorder(action.path, parent_chain)
            if commit_first_mutation is not None:
                commit_first_mutation()
            return
        if action.action == "upgrade":
            if not target_exists or snapshot.target.identity is None:
                raise DistributionApplyError(f"managed target identity changed for '{action.path}'")
            if snapshot.target.identity.kind == "symlink" and current_target != snapshot.target.identity.target:
                raise DistributionApplyError(f"managed target identity changed for '{action.path}'")
            _resolve_distribution_swap_rename()
            staging_name = _new_distribution_stage_name(action.path, expected)
            if write_ahead_stage_reservations and stage_ownership_recorder is not None:
                stage_ownership_recorder(_reserved_distribution_stage_ownership(action.path, staging_name, "symlink"))
                validate_held_namespace()
            validate_held_namespace()
            commit_first_mutation = (
                first_target_mutation_validator() if first_target_mutation_validator is not None else None
            )
            os.symlink(expected_target, staging_name, dir_fd=parent_fd)
            if commit_first_mutation is not None:
                commit_first_mutation()
            staging_stat = os.stat(staging_name, dir_fd=parent_fd, follow_symlinks=False)
            validate_held_namespace()
            cleanup_stage_stat = staging_stat
            swapped = False
            try:
                staged_target = _normalized_link_target_for_path(
                    action.path, os.readlink(staging_name, dir_fd=parent_fd)
                )
                if staged_target != expected_target:
                    raise DistributionApplyError(f"managed target staging failed for '{action.path}'")
                if stage_ownership_recorder is not None:
                    stage_ownership_recorder(_distribution_stage_ownership(action.path, staging_name, staging_stat))
                    validate_held_namespace()
                latest_stat = os.stat(target_name, dir_fd=parent_fd, follow_symlinks=False)
                if not _same_stat_identity(latest_stat, snapshot.target) or latest_stat.st_nlink != 1:
                    raise DistributionApplyError(f"managed target identity changed for '{action.path}'")
                if snapshot.target.identity.kind == "symlink":
                    latest_target = _normalized_link_target_for_path(
                        action.path, os.readlink(target_name, dir_fd=parent_fd)
                    )
                    if latest_target != snapshot.target.identity.target:
                        raise DistributionApplyError(f"managed target identity changed for '{action.path}'")
                _assert_visible_distribution_chain_bound(target_root, action.path, parent_chain)
                validate_held_namespace()
                _swap_symlink_distribution_target_if_bound(
                    parent_fd,
                    staging_name,
                    target_name,
                    expected_target=snapshot.target,
                    staging_stat=staging_stat,
                    identity_message=f"managed target identity changed for '{action.path}'",
                )
                swapped = True
                published_target = _normalized_link_target_for_path(
                    action.path, os.readlink(target_name, dir_fd=parent_fd)
                )
                if published_target != expected_target:
                    raise DistributionApplyError(f"managed target verification failed for '{action.path}'")
            finally:
                if not swapped:
                    # Do not refresh an ambiguous post-exchange pathname into
                    # operation ownership.  Cleanup is authorized only when
                    # the original staged symlink identity and target remain
                    # bound to the staging name.
                    stage_is_original = False
                    try:
                        visible_stage = os.stat(staging_name, dir_fd=parent_fd, follow_symlinks=False)
                        visible_target = _normalized_link_target_for_path(
                            action.path,
                            os.readlink(staging_name, dir_fd=parent_fd),
                        )
                        visible_stage_after = os.stat(staging_name, dir_fd=parent_fd, follow_symlinks=False)
                        stage_is_original = (
                            _stat_structure_tuple(visible_stage) == _stat_structure_tuple(cleanup_stage_stat)
                            and _stat_identity_tuple(visible_stage_after) == _stat_identity_tuple(visible_stage)
                            and visible_target == expected_target
                        )
                    except (FileNotFoundError, OSError, DistributionApplyError):
                        stage_is_original = False
                    if not stage_is_original:
                        raise DistributionApplyError(f"managed target identity changed for '{action.path}'")
                    cleanup_stage_stat = visible_stage
                    try:
                        if stage_ownership_recorder is not None:
                            stage_ownership_recorder(
                                _distribution_stage_ownership(action.path, staging_name, cleanup_stage_stat)
                            )
                    finally:
                        _remove_distribution_stage_if_owned(
                            parent_fd,
                            staging_name,
                            cleanup_stage_stat,
                            strict=True,
                            mutation_validator=validate_held_namespace,
                            post_link_mutation_validator=(
                                validate_held_namespace if deprovision_post_link_validation else None
                            ),
                            gc_path=action.path,
                            gc_recorder=stage_ownership_recorder,
                            recovery_stage_recorder=stage_ownership_recorder,
                        )
                else:
                    current_successor = os.stat(target_name, dir_fd=parent_fd, follow_symlinks=False)
                    current_target = _normalized_link_target_for_path(
                        action.path,
                        os.readlink(target_name, dir_fd=parent_fd),
                    )
                    if (
                        _stat_structure_tuple(current_successor) != _stat_structure_tuple(staging_stat)
                        or current_target != expected_target
                    ):
                        raise DistributionApplyError(f"managed target identity changed for '{action.path}'")
                    published_successor = current_successor
                    try:
                        old_stat = os.stat(staging_name, dir_fd=parent_fd, follow_symlinks=False)
                        old_target = (
                            _normalized_link_target_for_path(action.path, os.readlink(staging_name, dir_fd=parent_fd))
                            if stat.S_ISLNK(old_stat.st_mode)
                            else None
                        )
                        if (
                            snapshot.target.identity is not None
                            and old_target == snapshot.target.identity.target
                            and _same_stat_structure(old_stat, snapshot.target)
                            and old_stat.st_nlink == 1
                        ):
                            successor_ownership = _distribution_stage_ownership(
                                action.path,
                                staging_name,
                                published_successor,
                            )
                            successor_condition: dict[str, object] = {
                                "identity": _distribution_identity_payload(expected)
                            }
                            predecessor_condition: dict[str, object] = {
                                "device": snapshot.target.device,
                                "inode": snapshot.target.inode,
                                "file_type": snapshot.target.file_type,
                                "link_count": snapshot.target.link_count,
                                "identity": _distribution_identity_payload(snapshot.target.identity),
                            }
                            if stage_ownership_recorder is not None:
                                # Bind the exact canonical successor before
                                # removing the displaced predecessor.  Retry
                                # can validate both namespace roles.
                                try:
                                    stage_ownership_recorder(
                                        _distribution_stage_ownership(
                                            action.path,
                                            staging_name,
                                            published_successor if write_ahead_stage_reservations else old_stat,
                                        )
                                    )
                                except Exception as record_error:
                                    # The swap already published the new
                                    # target.  Retry the marker record once,
                                    # then fall back to strict cleanup.
                                    with suppress(Exception):
                                        stage_ownership_recorder(
                                            _distribution_stage_ownership(
                                                action.path,
                                                staging_name,
                                                published_successor if write_ahead_stage_reservations else old_stat,
                                            )
                                        )
                                    try:
                                        _remove_distribution_stage_if_owned(
                                            parent_fd,
                                            staging_name,
                                            old_stat,
                                            strict=True,
                                            transition_path=action.path,
                                            canonical_name=target_name,
                                            canonical_ownership=successor_ownership,
                                            canonical_condition=successor_condition,
                                            stage_condition=predecessor_condition,
                                            recovery_stage_recorder=(
                                                stage_ownership_recorder if not write_ahead_stage_reservations else None
                                            ),
                                            transition_recorder=(
                                                stage_ownership_recorder if write_ahead_stage_reservations else None
                                            ),
                                            mutation_validator=validate_held_namespace,
                                            post_link_mutation_validator=(
                                                validate_held_namespace if deprovision_post_link_validation else None
                                            ),
                                        )
                                    except DistributionApplyError as cleanup_error:
                                        # Restoration changes ctime; only a
                                        # persisted exact recovery lease may
                                        # authorize the next cleanup attempt.
                                        raise cleanup_error from record_error
                                    raise
                            current_successor = os.stat(target_name, dir_fd=parent_fd, follow_symlinks=False)
                            if _stat_identity_tuple(current_successor) != _stat_identity_tuple(published_successor):
                                raise DistributionApplyError(f"managed target identity changed for '{action.path}'")
                            _remove_distribution_stage_if_owned(
                                parent_fd,
                                staging_name,
                                old_stat,
                                strict=True,
                                transition_path=action.path,
                                canonical_name=target_name,
                                canonical_ownership=successor_ownership,
                                canonical_condition=successor_condition,
                                stage_condition=predecessor_condition,
                                recovery_stage_recorder=(
                                    stage_ownership_recorder if not write_ahead_stage_reservations else None
                                ),
                                transition_recorder=(
                                    stage_ownership_recorder if write_ahead_stage_reservations else None
                                ),
                                mutation_validator=validate_held_namespace,
                                post_link_mutation_validator=(
                                    validate_held_namespace if deprovision_post_link_validation else None
                                ),
                            )
                    except FileNotFoundError:
                        pass
            return
        raise DistributionApplyError(f"unsupported symlink action for '{action.path}'")
    except FileNotFoundError as exc:
        raise DistributionApplyError(f"managed target identity changed for '{action.path}'") from exc
    except OSError as exc:
        raise DistributionApplyError(f"managed target apply failed for '{action.path}'") from exc
    finally:
        _close_distribution_parent_chain(parent_chain)


def _apply_distribution_action(
    plan: DistributionPlan,
    target_root: Path,
    action: DistributionAction,
    snapshot: DistributionTargetSnapshot,
    created_parent_bindings: dict[str, PathIdentitySnapshot],
    stage_ownership_recorder: Callable[[DistributionStageOwnership], None] | None = None,
    created_parent_recorder: Callable[[tuple[PathIdentitySnapshot, ...]], None] | None = None,
    write_ahead_stage_reservations: bool = False,
    before_mutation: Callable[[], None] | None = None,
    held_parent_validator: Callable[[str, tuple[int, ...]], None] | None = None,
    first_target_mutation_validator: Callable[[], Callable[[], None] | None] | None = None,
    reusable_predecessor_stage_name: str | None = None,
    held_parent_checkpoint_recorder: Callable[[str, tuple[int, ...]], None] | None = None,
) -> None:
    if action.action in {"adopt", "preserve"}:
        return
    if action.action == "ensure-directory":
        parent_chain = _open_distribution_parent_chain(
            target_root,
            action.path,
            create_missing=False,
            expected_snapshot=snapshot,
            created_parent_bindings=created_parent_bindings,
        )
        try:
            if before_mutation is not None:
                before_mutation()
            if held_parent_validator is not None:
                held_parent_validator(action.path, parent_chain)
            parent_fd = parent_chain[-1]
            name = PurePosixPath(action.path).name
            try:
                existing = os.stat(name, dir_fd=parent_fd, follow_symlinks=False)
            except FileNotFoundError:
                existing = None
            if existing is not None:
                if not stat.S_ISDIR(existing.st_mode) or stat.S_ISLNK(existing.st_mode):
                    raise DistributionApplyError(f"required directory appeared unsafely for '{action.path}'")
                binding = _snapshot_from_stat(action.path, existing)
                previous = created_parent_bindings.get(action.path)
                if previous is None or not _same_stat_structure(existing, previous):
                    raise DistributionApplyError(f"required directory appeared during apply for '{action.path}'")
                return
            commit_first_mutation = (
                first_target_mutation_validator() if first_target_mutation_validator is not None else None
            )
            os.mkdir(name, dir_fd=parent_fd)
            if commit_first_mutation is not None:
                commit_first_mutation()
            os.fsync(parent_fd)
            created = os.stat(name, dir_fd=parent_fd, follow_symlinks=False)
            if not stat.S_ISDIR(created.st_mode) or stat.S_ISLNK(created.st_mode) or created.st_nlink < 1:
                raise DistributionApplyError(f"required directory verification failed for '{action.path}'")
            binding = _snapshot_from_stat(action.path, created)
            created_parent_bindings[action.path] = binding
            if created_parent_recorder is not None:
                created_parent_recorder(
                    tuple(created_parent_bindings[path] for path in sorted(created_parent_bindings))
                )
        except FileExistsError as exc:
            raise DistributionApplyError(f"required directory appeared during apply for '{action.path}'") from exc
        except OSError as exc:
            raise DistributionApplyError(f"required directory apply failed for '{action.path}'") from exc
        finally:
            _close_distribution_parent_chain(parent_chain)
        return
    expected = _expected_target_identity(plan, action.path)
    if expected is None and action.action != "prune":
        raise DistributionApplyError(f"managed action has no Current identity for '{action.path}'")
    if action.action == "create" and expected is not None:
        _resolve_distribution_no_replace_rename()
    elif action.action == "upgrade" and expected is not None:
        _resolve_distribution_swap_rename()

    source_bytes: bytes | None = None
    source_mode: int | None = None
    if action.action in {"create", "upgrade"}:
        if expected is None or expected.kind != "regular":
            source_bytes = None
        else:
            asset = _asset_for_target(plan, action.path)
            if asset is None:
                raise DistributionApplyError(f"distribution plan has no provider source for '{action.path}'")
            if asset.generated_content is not None:
                source_bytes = asset.generated_content
                observed_source_snapshot = None
            else:
                source_root = plan.scaffold_root if asset.source_path is not None else plan.install_root
                if source_root is None:
                    raise DistributionApplyError("distribution plan has no provider source root")
                source_rel = asset.source_path or asset.path
                source_bytes, observed_source_snapshot = _source_asset_bytes(source_root / source_rel)
                if asset.source_snapshot is None or observed_source_snapshot != asset.source_snapshot:
                    raise DistributionApplyError(f"provider Current asset identity changed for '{action.path}'")
            if expected.sha256 is None or hashlib.sha256(source_bytes).hexdigest() != expected.sha256:
                raise DistributionApplyError(f"provider Current asset content changed for '{action.path}'")
            if expected.mode is None:
                raise DistributionApplyError(f"provider Current asset mode changed for '{action.path}'")
            # Bind the mutation to the mode captured in the read-only plan;
            # never publish a mode observed after plan construction.
            source_mode = expected.mode

    target_kind = snapshot.target.file_type
    if expected is not None and expected.kind == "symlink":
        if expected.target is None:
            raise DistributionApplyError(f"managed action has no symlink target for '{action.path}'")
        _apply_symlink_action(
            target_root=target_root,
            action=action,
            snapshot=snapshot,
            expected=expected,
            created_parent_bindings=created_parent_bindings,
            stage_ownership_recorder=stage_ownership_recorder,
            created_parent_recorder=created_parent_recorder,
            write_ahead_stage_reservations=write_ahead_stage_reservations,
            before_mutation=before_mutation,
            held_parent_validator=held_parent_validator,
            first_target_mutation_validator=first_target_mutation_validator,
            reusable_predecessor_stage_name=reusable_predecessor_stage_name,
            held_parent_checkpoint_recorder=held_parent_checkpoint_recorder,
            deprovision_post_link_validation=plan.operation == "uninstall",
        )
        return
    if expected is None and target_kind == "symlink":
        historical_identity = snapshot.target.identity
        if historical_identity is None or historical_identity.kind != "symlink":
            raise DistributionApplyError(f"managed target identity changed for '{action.path}'")
        if historical_identity.target is None:
            raise DistributionApplyError(f"managed target identity changed for '{action.path}'")
        _apply_symlink_action(
            target_root=target_root,
            action=action,
            snapshot=snapshot,
            expected=historical_identity,
            created_parent_bindings=created_parent_bindings,
            stage_ownership_recorder=stage_ownership_recorder,
            created_parent_recorder=created_parent_recorder,
            write_ahead_stage_reservations=write_ahead_stage_reservations,
            before_mutation=before_mutation,
            held_parent_validator=held_parent_validator,
            first_target_mutation_validator=first_target_mutation_validator,
            reusable_predecessor_stage_name=reusable_predecessor_stage_name,
            held_parent_checkpoint_recorder=held_parent_checkpoint_recorder,
            deprovision_post_link_validation=plan.operation == "uninstall",
        )
        return
    if expected is None and target_kind != "regular":
        raise DistributionApplyError(f"managed target identity changed for '{action.path}'")
    _apply_regular_action(
        target_root=target_root,
        action=action,
        snapshot=snapshot,
        expected=expected if expected is not None else snapshot.target.identity,  # type: ignore[arg-type]
        source_bytes=source_bytes,
        source_mode=source_mode,
        created_parent_bindings=created_parent_bindings,
        stage_ownership_recorder=stage_ownership_recorder,
        created_parent_recorder=created_parent_recorder,
        write_ahead_stage_reservations=write_ahead_stage_reservations,
        before_mutation=before_mutation,
        held_parent_validator=held_parent_validator,
        first_target_mutation_validator=first_target_mutation_validator,
        reusable_predecessor_stage_name=reusable_predecessor_stage_name,
        held_parent_checkpoint_recorder=held_parent_checkpoint_recorder,
        deprovision_post_link_validation=plan.operation == "uninstall",
    )


def apply_distribution_plan(
    plan: DistributionPlan,
    *,
    allow_stale_stage_cleanup: bool = False,
    allow_blocked_scaffold_paths: bool = False,
    stage_ownership: tuple[DistributionStageOwnership, ...] = (),
    stage_ownership_recorder: Callable[[DistributionStageOwnership], None] | None = None,
    stage_ownership_remover: Callable[[str, tuple[str, ...]], None] | None = None,
    created_parent_bindings: tuple[PathIdentitySnapshot, ...] = (),
    created_parent_recorder: Callable[[tuple[PathIdentitySnapshot, ...]], None] | None = None,
    write_ahead_stage_reservations: bool = False,
    scaffold_applier: Callable[[], None] | None = None,
    progress_recorder: Callable[[str, tuple[str, ...], tuple[str, ...], bool], None] | None = None,
    before_mutation: Callable[[], None] | None = None,
    held_parent_validator: Callable[[str, tuple[int, ...]], None] | None = None,
    first_target_mutation_validator: Callable[[], Callable[[], None] | None] | None = None,
    held_parent_checkpoint_recorder: Callable[[str, tuple[int, ...]], None] | None = None,
) -> DistributionResult:
    """Apply a validated plan with no-follow identity checks at every action.

    This S30 seam intentionally does not perform CLI admission, version-marker
    handling, retry persistence, or recursive cleanup.  Stale private-stage
    cleanup is opt-in for a validated same-package retry and only removes
    stage entries whose no-follow identity was recorded immediately after
    creation by that retry marker; ordinary runs leave unknown stage-like
    siblings untouched.  Any preflight or identity mismatch raises before the
    corresponding action writes or removes a target path.
    """

    if any(not _intent_allows_distribution_action(plan.operation, action.action) for action in plan.actions):
        raise DistributionApplyError("distribution plan action is not allowed for its intent")

    target_root = plan.target_root
    if target_root is None or plan.install_root is None:
        raise DistributionApplyError("distribution plan is missing target or provider roots")
    permitted_scaffold_paths = (
        plan.scaffold_paths if scaffold_applier is not None and allow_blocked_scaffold_paths else frozenset()
    )
    blocked_actions = [
        action for action in plan.actions if action.blocked and action.path not in permitted_scaffold_paths
    ]
    if blocked_actions:
        raise DistributionApplyError("distribution plan is blocked")
    try:
        root_stat = os.lstat(target_root)
    except OSError as exc:
        raise DistributionApplyError("managed target root cannot be opened safely") from exc
    if not stat.S_ISDIR(root_stat.st_mode) or stat.S_ISLNK(root_stat.st_mode):
        raise DistributionApplyError("managed target root is not a real directory")

    snapshots = _plan_snapshot_map(plan)
    created_parent_bindings_by_path = {binding.relative_path: binding for binding in created_parent_bindings}
    scaffold_paths = plan.scaffold_paths if scaffold_applier is not None else frozenset()
    for action in plan.actions:
        snapshot = snapshots.get(action.path)
        if snapshot is None:
            raise DistributionApplyError("distribution plan is missing a target identity snapshot")
        _assert_plan_target_snapshot(target_root, action.path, snapshot)

    applied_paths: list[str] = []
    pending_paths = [action.path for action in plan.actions]

    if scaffold_applier is not None and scaffold_paths:
        if progress_recorder is not None:
            progress_recorder("managed-scaffold-refresh", tuple(applied_paths), tuple(pending_paths), False)
        try:
            if before_mutation is not None:
                before_mutation()
            commit_first_mutation = (
                first_target_mutation_validator() if first_target_mutation_validator is not None else None
            )
            scaffold_applier()
            if commit_first_mutation is not None:
                commit_first_mutation()
            for action in plan.actions:
                if action.path not in scaffold_paths:
                    continue
                refreshed = _observe_target(target_root, action.path)
                if refreshed.snapshot is None:
                    raise DistributionApplyError(f"managed scaffold post-apply path is missing for '{action.path}'")
                expected = _expected_target_identity(plan, action.path)
                if expected is None or refreshed.identity != expected:
                    raise DistributionApplyError(f"managed scaffold post-apply verification failed for '{action.path}'")
                snapshots[action.path] = refreshed.snapshot
                applied_paths.append(action.path)
                pending_paths.remove(action.path)
            for action in plan.actions:
                if action.path in scaffold_paths:
                    continue
                refreshed = _observe_target(target_root, action.path)
                if refreshed.snapshot is None:
                    raise DistributionApplyError(f"managed target identity changed for '{action.path}'")
                scaffold_owned_obsolete = (
                    action.action == "prune"
                    and any(action.path.startswith(f"spec-dock/{root}/") for root in _SCAFFOLD_MANAGED_ROOTS)
                    and refreshed.state == "missing"
                )
                if not scaffold_owned_obsolete:
                    _assert_pending_snapshot_stable(
                        refreshed.snapshot,
                        snapshots[action.path],
                        action.path,
                        created_parent_bindings_by_path,
                    )
                snapshots[action.path] = refreshed.snapshot
        except Exception as exc:
            if isinstance(exc, DistributionApplyError) and exc.phase is not None:
                raise
            raise DistributionApplyError(
                str(exc),
                phase="managed-scaffold-refresh",
                applied_paths=tuple(applied_paths),
                pending_paths=tuple(pending_paths),
                recovery_metadata_state=(
                    exc.recovery_metadata_state if isinstance(exc, DistributionApplyError) else None
                ),
            ) from exc
        if progress_recorder is not None:
            progress_recorder("managed-scaffold-refresh", tuple(applied_paths), tuple(pending_paths), True)

    current_paths = {asset.path for asset in plan.current_assets} | set(_CURRENT_SHORTCUTS)
    required_directory_paths = {item.path for item in plan.required_directories}
    external_actions = tuple(action for action in plan.actions if action.path not in scaffold_paths)
    directory_actions = tuple(action for action in external_actions if action.path in required_directory_paths)
    action_groups = (
        ("ensure-directory", directory_actions),
        ("current-external-materialize", tuple(action for action in external_actions if action.path in current_paths)),
        (
            "obsolete-prune",
            tuple(
                action
                for action in external_actions
                if action.path not in current_paths
                and action.path not in required_directory_paths
                and action.action != "ensure-directory"
            ),
        ),
    )
    actions_to_apply = tuple(action for _, actions in action_groups for action in actions)
    action_index = {id(action): index for index, action in enumerate(actions_to_apply)}
    for phase, actions in action_groups:
        if not actions:
            if progress_recorder is not None:
                progress_recorder(phase, tuple(applied_paths), tuple(pending_paths), True)
            continue
        if progress_recorder is not None:
            progress_recorder(phase, tuple(applied_paths), tuple(pending_paths), False)
        _assert_action_snapshots_stable(
            target_root,
            actions,
            snapshots,
            created_parent_bindings_by_path,
        )
        for action in actions:
            index = action_index[id(action)]
            try:
                snapshot = snapshots[action.path]
                if before_mutation is not None:
                    before_mutation()
                if allow_stale_stage_cleanup:

                    def validate_stale_cleanup(
                        parent_chain: tuple[int, ...],
                        path: str = action.path,
                    ) -> None:
                        if before_mutation is not None:
                            before_mutation()
                        if held_parent_validator is not None:
                            held_parent_validator(path, parent_chain)

                    _cleanup_stale_distribution_stages(
                        plan,
                        target_root,
                        action,
                        snapshot,
                        stage_ownership,
                        mutation_validator=validate_stale_cleanup,
                        stage_ownership_recorder=stage_ownership_recorder,
                        stage_ownership_remover=stage_ownership_remover,
                    )
                # A known stale-stage cleanup may mutate the current parent ctime.
                # Propagate only that operation-observed parent identity to pending
                # siblings; do not re-observe every pending target.
                refreshed = _observe_target(target_root, action.path)
                if refreshed.snapshot is None:
                    raise DistributionApplyError(f"managed target identity changed for '{action.path}'")
                _assert_pending_snapshot_stable(
                    refreshed.snapshot,
                    snapshot,
                    action.path,
                    created_parent_bindings_by_path,
                )
                snapshot = refreshed.snapshot
                snapshots[action.path] = snapshot
                if plan.operation == "fresh":
                    _refresh_pending_parent_snapshots(
                        actions_to_apply[index + 1 :],
                        snapshots,
                        refreshed.snapshot,
                    )
                else:
                    _refresh_pending_action_snapshots(
                        target_root,
                        actions_to_apply[index + 1 :],
                        snapshots,
                        created_parent_bindings_by_path,
                    )
                if action.action not in {"adopt", "preserve"}:
                    reusable_stage_name = _reusable_predecessor_stage_name(
                        plan.operation,
                        action,
                        stage_ownership,
                    )
                    if reusable_stage_name is None:
                        invoke_distribution_action = _apply_distribution_action
                    else:
                        invoke_distribution_action = partial(
                            _apply_distribution_action,
                            reusable_predecessor_stage_name=reusable_stage_name,
                        )
                    if held_parent_checkpoint_recorder is not None:
                        invoke_distribution_action = partial(
                            invoke_distribution_action,
                            held_parent_checkpoint_recorder=held_parent_checkpoint_recorder,
                        )
                    if before_mutation is not None:
                        before_mutation()
                    if stage_ownership_recorder is None and created_parent_recorder is None:
                        if before_mutation is None:
                            invoke_distribution_action(
                                plan,
                                target_root,
                                action,
                                snapshot,
                                created_parent_bindings_by_path,
                            )
                        else:
                            invoke_distribution_action(
                                plan,
                                target_root,
                                action,
                                snapshot,
                                created_parent_bindings_by_path,
                                before_mutation=before_mutation,
                                held_parent_validator=held_parent_validator,
                                first_target_mutation_validator=first_target_mutation_validator,
                            )
                    elif stage_ownership_recorder is None:
                        if before_mutation is None:
                            invoke_distribution_action(
                                plan,
                                target_root,
                                action,
                                snapshot,
                                created_parent_bindings_by_path,
                                created_parent_recorder=created_parent_recorder,
                            )
                        else:
                            invoke_distribution_action(
                                plan,
                                target_root,
                                action,
                                snapshot,
                                created_parent_bindings_by_path,
                                created_parent_recorder=created_parent_recorder,
                                before_mutation=before_mutation,
                                held_parent_validator=held_parent_validator,
                                first_target_mutation_validator=first_target_mutation_validator,
                            )
                    elif before_mutation is None:
                        invoke_distribution_action(
                            plan,
                            target_root,
                            action,
                            snapshot,
                            created_parent_bindings_by_path,
                            stage_ownership_recorder,
                            created_parent_recorder,
                            write_ahead_stage_reservations,
                        )
                    else:
                        invoke_distribution_action(
                            plan,
                            target_root,
                            action,
                            snapshot,
                            created_parent_bindings_by_path,
                            stage_ownership_recorder,
                            created_parent_recorder,
                            write_ahead_stage_reservations,
                            before_mutation,
                            held_parent_validator,
                            first_target_mutation_validator,
                        )
                    post_observation = _observe_target(target_root, action.path)
                    if post_observation.snapshot is None:
                        raise DistributionApplyError(f"managed target identity changed for '{action.path}'")
                    _refresh_pending_parent_snapshots(
                        actions_to_apply[index + 1 :],
                        snapshots,
                        post_observation.snapshot,
                    )
                applied_paths.append(action.path)
                pending_paths.remove(action.path)
                if progress_recorder is not None:
                    progress_recorder(phase, tuple(applied_paths), tuple(pending_paths), False)
                if plan.operation == "fresh":
                    _assert_pending_unbound_directories_stable(
                        target_root,
                        actions_to_apply[index + 1 :],
                        snapshots,
                        created_parent_bindings_by_path,
                        required_directory_paths,
                    )
                else:
                    _refresh_pending_action_snapshots(
                        target_root,
                        actions_to_apply[index + 1 :],
                        snapshots,
                        created_parent_bindings_by_path,
                    )
            except Exception as exc:
                if isinstance(exc, DistributionApplyError) and exc.phase is not None:
                    raise
                raise DistributionApplyError(
                    str(exc),
                    phase=phase,
                    applied_paths=tuple(applied_paths),
                    pending_paths=tuple(pending_paths),
                    failed_paths=(exc.failed_paths if isinstance(exc, DistributionApplyError) else ()),
                    recovery_metadata_state=(
                        exc.recovery_metadata_state if isinstance(exc, DistributionApplyError) else None
                    ),
                ) from exc
        if progress_recorder is not None:
            progress_recorder(phase, tuple(applied_paths), tuple(pending_paths), True)

    return DistributionResult(status="complete", actions=plan.actions)


